    // ============================================
    //  Tracks which encyclopedia object is currently being viewed
    // ============================================
    public static class EncyclopediaPageTracker
    {
        public static string CurrentObjectId { get; set; }
        public static string CurrentDescription { get; set; }
        public static string OriginalDescription { get; set; }
        public static Action CurrentRefreshAction { get; set; }
        public static Action<string> CurrentSetTextAction { get; set; }
        // Name/Title editing support (heroes only)
        public static Hero CurrentHero { get; set; }
        public static string CurrentPageType { get; set; }
        public static Action<string> CurrentSetNameAction { get; set; }
        public static Action<string> CurrentSetTitleAction { get; set; }
        public static string CurrentName { get; set; }
        public static string CurrentTitle { get; set; }

        // Action to refresh the "last edited" timestamp on the current page (set by each page Postfix)
        public static Action CurrentUpdateTimestampAction { get; set; }

        // Reference to the current encyclopedia ViewModel (used for banner visual refresh via reflection)
        public static object CurrentViewModel { get; set; }

        public static string UndoObjectId { get; set; }
        public static string UndoPreviousDescription { get; set; }
        public static bool HasUndo => _undoStack.Count > 0;

        private const int MaxUndoLevels = 10;
        private static readonly List<UndoEntry> _undoStack = new List<UndoEntry>();

        internal class UndoEntry
        {
            public string ObjectId;
            public string PreviousDescription;
        }

        public static void PushUndo(string objectId, string previousDescription)
        {
            _undoStack.Add(new UndoEntry { ObjectId = objectId, PreviousDescription = previousDescription });
            if (_undoStack.Count > MaxUndoLevels)
                _undoStack.RemoveAt(0);

            // Keep legacy properties in sync for hint text
            UndoObjectId = objectId;
            UndoPreviousDescription = previousDescription;
        }

        internal static UndoEntry PopUndo()
        {
            if (_undoStack.Count == 0) return null;
            int last = _undoStack.Count - 1;
            var entry = _undoStack[last];
            _undoStack.RemoveAt(last);

            // Update legacy properties
            if (_undoStack.Count > 0)
            {
                var prev = _undoStack[_undoStack.Count - 1];
                UndoObjectId = prev.ObjectId;
                UndoPreviousDescription = prev.PreviousDescription;
            }
            else
            {
                UndoObjectId = null;
                UndoPreviousDescription = null;
            }
            return entry;
        }

        public static void ClearUndo()
        {
            _undoStack.Clear();
            UndoObjectId = null;
            UndoPreviousDescription = null;
        }

        public static int UndoCount => _undoStack.Count;

        // Layer count when encyclopedia was first opened in this session (fallback only)
        public static int LayerCountOnOpen { get; set; } = -1;

        // Reference to the encyclopedia screen manager (GauntletMapEncyclopediaView).
        // Used to read its IsEncyclopediaOpen property and Layer reference for close detection.
        public static object EncyclopediaManagerRef { get; set; }

        // Cached FieldInfo for <IsEncyclopediaOpen>k__BackingField on the manager
        public static System.Reflection.FieldInfo EncyclopediaOpenField { get; set; }

        // Direct reference to the encyclopedia's Layer (ScreenLayer) for layer-ref-based detection
        public static object EncyclopediaLayerRef { get; set; }

        // Reference to the TopScreen instance when EncyclopediaManagerRef was cached.
        // Used to detect when the screen has been recreated (e.g., after save/load)
        // so we can invalidate the stale manager cache and re-discover.
        public static object CachedScreenRef { get; set; }

        // Set true during ExecuteLink page transitions to suppress false close detection.
        // The IsEncyclopediaOpen field briefly returns false during page navigation, which
        // would otherwise trigger the close detection debounce and eventually close the UI.
        private static readonly object _transitionLock = new object();
        private static bool _inPageTransition;
        private static DateTime _transitionStartTime;
        private const double MaxTransitionSeconds = 3.0;

        public static void BeginPageTransition()
        {
            lock (_transitionLock)
            {
                _inPageTransition = true;
                _transitionStartTime = DateTime.UtcNow;
            }
        }

        public static void EndPageTransition()
        {
            lock (_transitionLock)
            {
                _inPageTransition = false;
            }
        }

        public static bool IsInPageTransition
        {
            get
            {
                lock (_transitionLock)
                {
                    if (!_inPageTransition) return false;
                    if ((DateTime.UtcNow - _transitionStartTime).TotalSeconds > MaxTransitionSeconds)
                    {
                        _inPageTransition = false;
                        return false;
                    }
                    return true;
                }
            }
        }

        public static bool IsEncyclopediaOpen()
        {
            try
            {
                // During page transitions (ExecuteLink), the field briefly toggles false.
                // If we're in a known transition, report open to prevent false close detection.
                if (IsInPageTransition) return true;

                bool fieldSaysOpen = false;
                bool fieldChecked = false;

                // Primary: read IsEncyclopediaOpen directly from the encyclopedia manager.
                if (EncyclopediaManagerRef != null && EncyclopediaOpenField != null)
                {
                    try
                    {
                        var isOpen = EncyclopediaOpenField.GetValue(EncyclopediaManagerRef);
                        if (isOpen is bool bVal)
                        {
                            fieldChecked = true;
                            fieldSaysOpen = bVal;
                            if (bVal) return true; // Field says open — definitely open
                        }
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: reflection GetValue failed: " + ex.ToString()); }
                }

                // If the field says closed (or unavailable), also check the layer reference.
                // During page transitions (e.g., search → detail page), the field may briefly
                // return false while the encyclopedia layer is still present on the screen.
                var topScreen = ScreenManager.TopScreen;
                if (topScreen == null) return false;

                if (EncyclopediaLayerRef != null)
                {
                    foreach (var layer in topScreen.Layers)
                    {
                        if (object.ReferenceEquals(layer, EncyclopediaLayerRef))
                            return true; // Layer still exists — encyclopedia is open
                    }
                    // Layer is gone — encyclopedia truly closed
                    return false;
                }

                // Field says closed and no layer ref to verify — trust the field
                if (fieldChecked) return false;

                // Fallback: use layer count (only before we've found the manager/layer ref)
                if (LayerCountOnOpen < 0) return false;
                return topScreen.Layers.Count >= LayerCountOnOpen;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: operation failed: " + ex.ToString()); }
            return false;
        }

        public static void Clear()
        {
            CurrentObjectId = null;
            CurrentDescription = null;
            OriginalDescription = null;
            CurrentRefreshAction = null;
            CurrentSetTextAction = null;
            CurrentHero = null;
            CurrentPageType = null;
            CurrentSetNameAction = null;
            CurrentSetTitleAction = null;
            CurrentName = null;
            CurrentTitle = null;
            CurrentUpdateTimestampAction = null;
            CurrentViewModel = null;
            LayerCountOnOpen = -1;
            _inPageTransition = false;
            // Keep EncyclopediaManagerRef and EncyclopediaOpenField cached — they survive across
            // encyclopedia sessions (the manager object persists on the MapScreen).
            // CachedScreenRef is kept so we can detect save/load (screen recreation) and re-discover.

            // Only clear EncyclopediaLayerRef if the layer is actually gone from the screen.
            // During false close detection (e.g. ExecuteLink reentrancy), the layer may still
            // be present — clearing it would remove our safety net for subsequent checks.
            if (EncyclopediaLayerRef != null)
            {
                bool layerStillPresent = false;
                try
                {
                    var topScreen = ScreenManager.TopScreen;
                    if (topScreen != null)
                    {
                        foreach (var layer in topScreen.Layers)
                        {
                            if (object.ReferenceEquals(layer, EncyclopediaLayerRef))
                            {
                                layerStillPresent = true;
                                break;
                            }
                        }
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation failed: " + ex.ToString()); }

                if (layerStillPresent)
                {
                    MCMSettings.DebugLog("Clear: EncyclopediaLayerRef still on screen — keeping reference (false close?)");
                }
                else
                {
                    EncyclopediaLayerRef = null;
                }
            }
        }

        /// <summary>
        /// Sets Hero name via reflection on both _name and _firstName backing fields.
        /// _name controls the detail page/breadcrumb, _firstName controls the Heroes list.
        /// </summary>
        public static void SetHeroName(Hero hero, string name)
        {
            try
            {
                var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Public;
                bool anySet = false;

                // Set both _name and _firstName so the name updates everywhere
                foreach (var fieldName in new[] { "_name", "_firstName" })
                {
                    var field = typeof(Hero).GetField(fieldName, flags);
                    if (field != null)
                    {
                        field.SetValue(hero, new TextObject(name));
                        MCMSettings.DebugLog("Set Hero '" + fieldName + "' = " + name);
                        anySet = true;
                    }
                }

                if (!anySet)
                    MCMSettings.DebugLog("WARNING: Could not find _name or _firstName fields on Hero");

                // Also update the MobileParty name so the map tooltip reflects the new name
                try
                {
                    if (hero.PartyBelongedTo != null)
                    {
                        var party = hero.PartyBelongedTo;
                        bool nameSet = false;

                        // Search all methods for anything that sets a custom/override name
                        foreach (var method in typeof(MobileParty).GetMethods(flags))
                        {
                            if (method.Name.ToLower().Contains("customname") || method.Name.ToLower().Contains("setname"))
                            {
                                var parms = method.GetParameters();
                                if (parms.Length == 1 && parms[0].ParameterType == typeof(TextObject))
                                {
                                    method.Invoke(party, new object[] { new TextObject(name + "'s Party") });
                                    MCMSettings.DebugLog("Set MobileParty name via " + method.Name + ": " + name + "'s Party");
                                    nameSet = true;
                                    break;
                                }
                            }
                        }

                        // Search all fields with TextObject type that contain "name" or "custom"
                        if (!nameSet)
                        {
                            // Search up the type hierarchy
                            var searchType = typeof(MobileParty);
                            while (searchType != null && searchType != typeof(object) && !nameSet)
                            {
                                foreach (var f in searchType.GetFields(flags | System.Reflection.BindingFlags.DeclaredOnly))
                                {
                                    if (f.FieldType == typeof(TextObject) &&
                                        (f.Name.ToLower().Contains("name") || f.Name.ToLower().Contains("custom")))
                                    {
                                        f.SetValue(party, new TextObject(name + "'s Party"));
                                        MCMSettings.DebugLog("Set MobileParty field " + f.Name + " on " + searchType.Name + ": " + name + "'s Party");
                                        nameSet = true;
                                        break;
                                    }
                                }
                                searchType = searchType.BaseType;
                            }
                        }

                        // Last resort: try the Name property setter directly
                        if (!nameSet)
                        {
                            var nameProp = typeof(MobileParty).GetProperty("Name", flags);
                            if (nameProp != null && nameProp.CanWrite)
                            {
                                nameProp.SetValue(party, new TextObject(name + "'s Party"));
                                MCMSettings.DebugLog("Set MobileParty Name property: " + name + "'s Party");
                                nameSet = true;
                            }
                        }

                        // Also update PartyBase.Name — the tooltip title reads from here
                        try
                        {
                            var partyBase = party.Party;
                            if (partyBase != null)
                            {
                                bool pbSet = false;
                                // Search PartyBase type hierarchy for TextObject name fields
                                var pbType = partyBase.GetType();
                                while (pbType != null && pbType != typeof(object) && !pbSet)
                                {
                                    foreach (var f in pbType.GetFields(flags | System.Reflection.BindingFlags.DeclaredOnly))
                                    {
                                        if (f.FieldType == typeof(TextObject) &&
                                            (f.Name.ToLower().Contains("name") || f.Name.ToLower().Contains("custom")))
                                        {
                                            f.SetValue(partyBase, new TextObject(name + "'s Party"));
                                            MCMSettings.DebugLog("Set PartyBase field " + f.Name + " on " + pbType.Name + ": " + name + "'s Party");
                                            pbSet = true;
                                            break;
                                        }
                                    }
                                    pbType = pbType.BaseType;
                                }

                                // Try Name property setter
                                if (!pbSet)
                                {
                                    var pbNameProp = partyBase.GetType().GetProperty("Name", flags);
                                    if (pbNameProp != null && pbNameProp.CanWrite)
                                    {
                                        pbNameProp.SetValue(partyBase, new TextObject(name + "'s Party"));
                                        MCMSettings.DebugLog("Set PartyBase.Name property: " + name + "'s Party");
                                        pbSet = true;
                                    }
                                }

                                if (!pbSet)
                                {
                                    MCMSettings.DebugLog("Could not set PartyBase name. Dumping PartyBase type info:");
                                    var dumpPb = partyBase.GetType();
                                    while (dumpPb != null && dumpPb != typeof(object))
                                    {
                                        foreach (var f in dumpPb.GetFields(flags | System.Reflection.BindingFlags.DeclaredOnly))
                                        {
                                            if (f.FieldType == typeof(TextObject) || f.Name.ToLower().Contains("name"))
                                                MCMSettings.DebugLog("  " + dumpPb.Name + " field: " + f.Name + " (" + f.FieldType.Name + ")");
                                        }
                                        dumpPb = dumpPb.BaseType;
                                    }
                                }
                            }
                        }
                        catch (Exception ex)
                        {
                            MCMSettings.DebugLog("SetHeroName: PartyBase name update failed: " + ex.ToString());
                        }

                        // Also try to refresh the party visual so the nameplate updates on the map
                        try
                        {
                            var partyBase2 = party.Party;
                            if (partyBase2 != null)
                            {
                                var setDirtyMethod = partyBase2.GetType().GetMethod("SetVisualAsDirty", flags);
                                if (setDirtyMethod != null)
                                {
                                    setDirtyMethod.Invoke(partyBase2, null);
                                    MCMSettings.DebugLog("Called PartyBase.SetVisualAsDirty()");
                                }
                            }
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("SetHeroName: SetVisualAsDirty failed: " + ex.ToString()); }

                        if (!nameSet)
                        {
                            // Dump all fields and methods for diagnosis
                            MCMSettings.DebugLog("Could not set MobileParty name. Dumping type info:");
                            var dumpType = typeof(MobileParty);
                            while (dumpType != null && dumpType != typeof(object))
                            {
                                foreach (var f in dumpType.GetFields(flags | System.Reflection.BindingFlags.DeclaredOnly))
                                {
                                    if (f.FieldType == typeof(TextObject) || f.Name.ToLower().Contains("name"))
                                        MCMSettings.DebugLog("  " + dumpType.Name + " field: " + f.Name + " (" + f.FieldType.Name + ")");
                                }
                                foreach (var m in dumpType.GetMethods(flags | System.Reflection.BindingFlags.DeclaredOnly))
                                {
                                    if (m.Name.ToLower().Contains("name"))
                                        MCMSettings.DebugLog("  " + dumpType.Name + " method: " + m.Name + "(" + string.Join(", ", Array.ConvertAll(m.GetParameters(), p => p.ParameterType.Name)) + ")");
                                }
                                dumpType = dumpType.BaseType;
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    MCMSettings.DebugLog("SetHeroName: MobileParty name update failed: " + ex.ToString());
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("SetHeroName exception: " + ex.ToString());
            }
        }

        /// <summary>
        /// Sets the Name on a Kingdom, Clan, or Settlement game object via reflection.
        /// Searches the type hierarchy for _name field or Name property with TextObject type.
        /// </summary>
        public static void SetGameObjectName(object gameObject, string name)
        {
            if (gameObject == null) return;
            try
            {
                var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Public;
                var declaredFlags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.DeclaredOnly;
                var type = gameObject.GetType();
                bool set = false;

                // Walk the type hierarchy looking for name backing fields
                var current = type;
                while (current != null && current != typeof(object) && !set)
                {
                    // Try common field names: _name, <Name>k__BackingField
                    foreach (var fieldName in new[] { "_name", "<Name>k__BackingField" })
                    {
                        var field = current.GetField(fieldName, declaredFlags);
                        if (field != null && (field.FieldType == typeof(TextObject) || field.FieldType.Name == "TextObject"))
                        {
                            // Try to modify the EXISTING TextObject in-place so references stay valid.
                            // The nameplate renderer holds the old TextObject ref and calls .ToString() on it.
                            var existingTO = field.GetValue(gameObject) as TextObject;
                            if (existingTO != null)
                            {
                                try
                                {
                                    // Dump TextObject fields once for diagnosis
                                    var toFlags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Public;
                                    var toFields = typeof(TextObject).GetFields(toFlags);
                                    bool dumped = false;
                                    System.Reflection.FieldInfo targetField = null;
                                    foreach (var f in toFields)
                                    {
                                        if (!dumped)
                                        {
                                            MCMSettings.DebugLog("TextObject field: " + f.Name + " (" + f.FieldType.Name + ")");
                                        }
                                        if (f.FieldType == typeof(string))
                                            targetField = f; // grab the first string field
                                    }
                                    dumped = true;

                                    if (targetField != null)
                                    {
                                        targetField.SetValue(existingTO, name);
                                        // Invalidate TextObject cache so ToString() re-evaluates
                                        try
                                        {
                                            var cachedTokens = typeof(TextObject).GetField("cachedTokens", toFlags);
                                            if (cachedTokens != null) cachedTokens.SetValue(existingTO, null);
                                            var cachedLangId = typeof(TextObject).GetField("cachedTextLanguageId", toFlags);
                                            if (cachedLangId != null) cachedLangId.SetValue(existingTO, -1);
                                        }
                                        catch { }
                                        MCMSettings.DebugLog("Set " + type.Name + "." + fieldName + " in-place via " + targetField.Name + " = " + name + " (cache cleared)");
                                        set = true;
                                        break;
                                    }
                                }
                                catch { }
                            }
                            // Fallback: replace the TextObject entirely
                            field.SetValue(gameObject, new TextObject(name));
                            MCMSettings.DebugLog("Set " + type.Name + "." + fieldName + " (replaced) = " + name);
                            set = true;
                            break;
                        }
                    }
                    current = current.BaseType;
                }

                // Fallback: try Name property setter
                if (!set)
                {
                    var nameProp = type.GetProperty("Name", flags);
                    if (nameProp != null && nameProp.CanWrite)
                    {
                        nameProp.SetValue(gameObject, new TextObject(name));
                        MCMSettings.DebugLog("Set " + type.Name + ".Name (property) = " + name);
                        set = true;
                    }
                }

                // Last resort: scan all TextObject fields on each type looking for one containing the current name
                if (!set)
                {
                    current = type;
                    while (current != null && current != typeof(object) && !set)
                    {
                        foreach (var field in current.GetFields(declaredFlags))
                        {
                            if (field.FieldType != typeof(TextObject) && field.FieldType.Name != "TextObject") continue;
                            var val = field.GetValue(gameObject);
                            if (val == null) continue;
                            string valStr = val.ToString();
                            // This field holds a TextObject that matches the entity's current display name
                            if (!string.IsNullOrEmpty(valStr) && valStr.Length > 0)
                            {
                                // Only set fields whose name suggests they're the primary name
                                string fn = field.Name.ToLowerInvariant();
                                if (fn.Contains("name") || fn.Contains("title") || fn.Contains("label"))
                                {
                                    field.SetValue(gameObject, new TextObject(name));
                                    MCMSettings.DebugLog("Set " + type.Name + "." + field.Name + " (scan) = " + name);
                                    set = true;
                                    break;
                                }
                            }
                        }
                        current = current.BaseType;
                    }
                }

                if (!set)
                    MCMSettings.DebugLog("WARNING: Could not set name on " + type.Name);

                // Also try to set InformalName for kingdoms (shown in lists)
                if (type.Name == "Kingdom")
                {
                    try
                    {
                        current = type;
                        while (current != null && current != typeof(object))
                        {
                            foreach (var fieldName in new[] { "_informalName", "<InformalName>k__BackingField" })
                            {
                                var field = current.GetField(fieldName, declaredFlags);
                                if (field != null && (field.FieldType == typeof(TextObject) || field.FieldType.Name == "TextObject"))
                                {
                                    field.SetValue(gameObject, new TextObject(name));
                                    MCMSettings.DebugLog("Set Kingdom." + fieldName + " = " + name);
                                }
                            }
                            current = current.BaseType;
                        }
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: operation failed: " + ex.ToString()); }
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("SetGameObjectName exception: " + ex.ToString());
            }
        }
    }

    // ============================================
    //  Input blocker: disables encyclopedia interaction while popups are open
    // ============================================
    /// <summary>
    /// Blocks/unblocks keyboard and mouse input on the encyclopedia layer while
    /// edit popups (Ctrl+E/N/U/O) are open. Prevents accidental navigation,
    /// text deletion, and other unintended interactions while the user is editing.
    /// </summary>
    public static class EncyclopediaInputBlocker
    {
        // Instead of finding and modifying the encyclopedia's own layer (which
        // GauntletMapEncyclopediaView doesn't expose as a field), we add our own
        // transparent GauntletLayer to the screen with InputRestrictions enabled.
        // This layer sits above the encyclopedia and absorbs all input, preventing
        // navigation (Home, search, back, etc.) from firing while a popup is open.
        // The popup itself is added after this layer, so it sits on top and still
        // receives input normally.
        private const int BlockingLayerOrder = 9998;
        private static TaleWorlds.Engine.GauntletUI.GauntletLayer _blockingLayer;
        private static int _blockRefCount;

        // Post-unblock cooldown: after removing the blocking layer, keep forcing
        // IsEncyclopediaOpen = true for several ticks. The game's focus system
        // processes IsFocusLayer changes asynchronously (on subsequent ticks),
        // so it may set IsEncyclopediaOpen = false AFTER DoRemoveLayer() already
        // forced it true. This cooldown counteracts that delayed reset.
        private const int PostUnblockCooldownTickCount = 30;
        private static int _postUnblockCooldownTicks;

        /// <summary>
        /// True when the blocking layer is active (a popup or picker is open).
        /// Used by GoToLinkPrefix to block encyclopedia navigation.
        /// </summary>
        public static bool IsBlocking => _blockingLayer != null;

        /// <summary>
        /// Adds a transparent input-blocking GauntletLayer to the current screen.
        /// Uses a reference counter — each Block() must be paired with an Unblock().
        /// The layer is only added on the first Block() call.
        /// </summary>
        public static void Block()
        {
            try
            {
                _blockRefCount++;
                if (_blockingLayer != null)
                {
                    MCMSettings.DebugLog("EncyclopediaInputBlocker: already blocking (refCount=" + _blockRefCount + ")");
                    return;
                }

                var topScreen = ScreenManager.TopScreen;
                if (topScreen == null)
                {
                    MCMSettings.DebugLog("EncyclopediaInputBlocker: TopScreen is null");
                    return;
                }

                // Use a high localOrder so the layer sits above encyclopedia layers
                // but the popup (created after this) will be added on top.
                _blockingLayer = new TaleWorlds.Engine.GauntletUI.GauntletLayer("EditEncyclopediaBlocker", BlockingLayerOrder, false);
                _blockingLayer.InputRestrictions.SetInputRestrictions(true);
                // IsFocusLayer is intentionally NOT set. Setting it causes
                // GauntletMapEncyclopediaView to navigate to the Home page
                // through an internal mechanism that bypasses all ViewModel
                // commands and GoToLink. Instead, we rely on Harmony patches
                // on ExecuteBack/ExecuteLink/GoToLink to block any navigation
                // that the user triggers by clicking through this layer.

                topScreen.AddLayer(_blockingLayer);

                MCMSettings.DebugLog("EncyclopediaInputBlocker: added blocking layer to screen (layers="
                    + topScreen.Layers.Count + ")");
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("EncyclopediaInputBlocker.Block error: " + ex.ToString());
            }
        }

        /// <summary>
        /// Decrements the block reference counter. Only actually removes the
        /// blocking layer when the counter reaches zero.
        /// </summary>
        public static void Unblock()
        {
            if (_blockingLayer == null)
            {
                _blockRefCount = 0;
                return;
            }

            _blockRefCount--;
            if (_blockRefCount > 0)
            {
                MCMSettings.DebugLog("EncyclopediaInputBlocker: Unblock deferred (refCount=" + _blockRefCount + ")");
                return;
            }
            _blockRefCount = 0;

            // Safety: don't actually remove the layer if any popup is still open.
            // This prevents unpaired Unblock() calls (e.g., from other popup's
            // ReleasePopup) from removing the layer while the journal popup is active.
            if (AnyPopupOpen())
            {
                MCMSettings.DebugLog("EncyclopediaInputBlocker: Unblock skipped (popup still open)");
                return;
            }

            DoRemoveLayer();
        }

        /// <summary>
        /// Returns true if any edit popup is currently open.
        /// </summary>
        private static bool AnyPopupOpen()
        {
            return EncyclopediaEditPopup.IsPopupOpen
                || EncyclopediaNameEditPopup.IsPopupOpen
                || EncyclopediaCultureEditPopup.IsPopupOpen
                || EncyclopediaOccupationEditPopup.IsPopupOpen
                || EncyclopediaBannerEditPopup.IsPopupOpen
                || EncyclopediaResetPopup.IsPopupOpen
                || EncyclopediaTagEditPopup.IsPopupOpen
                || EncyclopediaJournalPopup.IsPopupOpen
                || RelationNotesInjector.IsPopupOpen
                || EditPopupInjector.IsOpen
                || LoreEditorPopup.IsOpen
                || SelectionPopupHelper.IsOpen;
        }

        private static void DoRemoveLayer()
        {
            if (_blockingLayer == null) return;
            try
            {
                var topScreen = ScreenManager.TopScreen;
                if (topScreen != null)
                {
                    _blockingLayer.InputRestrictions.ResetInputRestrictions();
                    topScreen.RemoveLayer(_blockingLayer);
                }
                MCMSettings.DebugLog("EncyclopediaInputBlocker: removed blocking layer");
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("EncyclopediaInputBlocker.Unblock error: " + ex.ToString());
            }
            _blockingLayer = null;
            _forceOpenLogged = false;

            // Force IsEncyclopediaOpen = true one last time after removing the blocking layer.
            // While the blocking layer was active, TickForceEncyclopediaOpen() kept this true.
            // Now that the layer is gone, TickForceEncyclopediaOpen() stops running, but the
            // game may have already set IsEncyclopediaOpen = false due to focus changes caused
            // by popup layers. Without this final force, the encyclopedia remains "closed"/inactive.
            try
            {
                var mgr = EncyclopediaPageTracker.EncyclopediaManagerRef;
                var field = EncyclopediaPageTracker.EncyclopediaOpenField;
                if (mgr != null && field != null)
                {
                    field.SetValue(mgr, true);
                    MCMSettings.DebugLog("EncyclopediaInputBlocker: forced IsEncyclopediaOpen = true after unblock");
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: force encyclopedia open failed: " + ex.ToString()); }

            // Start post-unblock cooldown: the game's focus system processes
            // IsFocusLayer changes asynchronously across multiple ticks. Keep
            // forcing IsEncyclopediaOpen = true for 30 ticks (~500ms at 60fps)
            // to counteract any delayed reset by the game engine. Must outlast
            // the key poller's CloseConfirmationThreshold (6 polls × 50ms = 300ms).
            _postUnblockCooldownTicks = PostUnblockCooldownTickCount;
        }

        /// <summary>
        /// Force-removes the blocking layer regardless of reference count.
        /// Used by TickAutoUnblock when no popup is open (safety net).
        /// </summary>
        public static void ForceUnblock()
        {
            _blockRefCount = 0;
            DoRemoveLayer();
        }

        /// <summary>
        /// Called from OnApplicationTick. Automatically unblocks when no edit popup is open.
        /// </summary>
        public static void TickAutoUnblock()
        {
            if (_blockingLayer == null) return;
            if (AnyPopupOpen()) return;

            // No popup open — force unblock (resets refcount)
            ForceUnblock();
        }

        /// <summary>
        /// Called from OnApplicationTick. While the blocking layer is active,
        /// forces the encyclopedia's IsEncyclopediaOpen field to stay true.
        /// The IsFocusLayer on our blocking layer causes GauntletMapEncyclopediaView
        /// to set this field to false (thinking the encyclopedia is closing),
        /// which triggers internal Home/close navigation. By keeping it true,
        /// the encyclopedia thinks it's still active and doesn't navigate away.
        /// </summary>
        public static void TickForceEncyclopediaOpen()
        {
            // Post-unblock cooldown: keep forcing IsEncyclopediaOpen = true
            // for several ticks after the blocking layer was removed, because
            // the game's focus system processes IsFocusLayer changes on
            // subsequent ticks and may reset IsEncyclopediaOpen = false.
            if (_postUnblockCooldownTicks > 0)
            {
                _postUnblockCooldownTicks--;
                var cooldownMgr = EncyclopediaPageTracker.EncyclopediaManagerRef;
                var cooldownField = EncyclopediaPageTracker.EncyclopediaOpenField;
                if (cooldownMgr != null && cooldownField != null)
                {
                    try
                    {
                        var v = cooldownField.GetValue(cooldownMgr);
                        if (v is bool b && !b)
                        {
                            cooldownField.SetValue(cooldownMgr, true);
                            MCMSettings.DebugLog("EncyclopediaInputBlocker: post-unblock cooldown forced IsEncyclopediaOpen = true (tick " + _postUnblockCooldownTicks + ")");
                        }
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: reflection GetValue failed: " + ex.ToString()); }
                }
            }

            if (_blockingLayer == null) return;

            var mgr = EncyclopediaPageTracker.EncyclopediaManagerRef;
            var field = EncyclopediaPageTracker.EncyclopediaOpenField;
            if (mgr == null || field == null) return;

            try
            {
                var val = field.GetValue(mgr);
                if (val is bool bVal && !bVal)
                {
                    field.SetValue(mgr, true);
                    // Only log once to avoid spam
                    if (!_forceOpenLogged)
                    {
                        MCMSettings.DebugLog("NavBlocker: forced IsEncyclopediaOpen = true (was reset by focus change)");
                        _forceOpenLogged = true;
                    }
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: reflection GetValue failed: " + ex.ToString()); }
        }
        private static bool _forceOpenLogged;
    }

    /// <summary>
    /// Counters the encyclopedia's automatic navigation to its Home page that occurs
    /// when MBInformationManager.ShowMultiSelectionInquiry() or ShowTextInquiry() is
    /// called while the encyclopedia is open. The game resets the encyclopedia to Home
    /// as a side effect of showing global inquiry popups. This helper re-navigates to
    /// the page the user was viewing before the popup was shown.
    ///
    /// Uses a tick-deferred mechanism: the navigation is scheduled and executed on the
    /// next OnApplicationTick call, ensuring the popup has fully rendered first.
    /// </summary>
    /// <summary>
    /// Harmony prefix patches on EncyclopediaVM navigation commands (ExecuteGoToHome,
    /// ExecuteBack, ExecuteLink) and EncyclopediaManager.GoToLink that block encyclopedia
    /// navigation while any edit popup or picker is open.
    ///
    /// The encyclopedia's internal navigation bypasses EncyclopediaManager.GoToLink —
    /// clicking Home/Back or pressing Backspace triggers ExecuteGoToHome()/ExecuteBack()
    /// on the EncyclopediaNavigatorVM, which swaps the ActivePage directly within
    /// the ViewModelCollection. We must patch at this ViewModel level.
    /// </summary>
    internal static class EncyclopediaNavigationGuard
    {
        private static bool _patched;

        /// <summary>
        /// Kept as a no-op for existing call sites.
        /// </summary>
        public static void ScheduleNavigateBack() { }

        /// <summary>
        /// Called from OnApplicationTick. On the first tick where Campaign.Current
        /// is available, applies all Harmony navigation-blocking patches.
        /// </summary>
        public static void Tick()
        {
            if (_patched) return;
            TryPatchDeferred();
        }

        private static void TryPatchDeferred()
        {
            try
            {
                var campaign = Campaign.Current;
                if (campaign == null) return;

                var harmony = new HarmonyLib.Harmony("com.editableencyclopedia.patch");
                var flags = System.Reflection.BindingFlags.Instance
                          | System.Reflection.BindingFlags.Public
                          | System.Reflection.BindingFlags.NonPublic;

                var prefix = typeof(EncyclopediaNavigationGuard).GetMethod("BlockNavigationPrefix",
                    System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public);

                // 1. Patch EncyclopediaManager.GoToLink (external navigation)
                var encMgr = campaign.EncyclopediaManager;
                if (encMgr != null)
                {
                    var goToLink = encMgr.GetType().GetMethod("GoToLink", flags, null, new[] { typeof(string) }, null);
                    if (goToLink != null)
                    {
                        harmony.Patch(goToLink, prefix: new HarmonyLib.HarmonyMethod(prefix));
                        MCMSettings.DebugLog("NavBlocker: patched " + encMgr.GetType().FullName + ".GoToLink()");
                    }
                }

                // 2. Find and patch EncyclopediaNavigatorVM (or EncyclopediaVM) commands
                //    Search the ViewModelCollection assembly for the navigator type
                var vmAssembly = typeof(EncyclopediaHeroPageVM).Assembly;
                int vmPatched = 0;

                // Search for types with ExecuteGoToHome or ExecuteBack methods.
                // Use DeclaredOnly to avoid inherited methods that Harmony can't patch
                // through subclasses (e.g., EncyclopediaFamilyMemberVM inherits HeroVM.ExecuteLink).
                var declaredFlags = flags | System.Reflection.BindingFlags.DeclaredOnly;
                foreach (var type in vmAssembly.GetTypes())
                {
                    if (!type.Name.Contains("Encyclopedia")) continue;

                    var methods = new List<System.Reflection.MethodInfo>();

                    var goHome = type.GetMethod("ExecuteGoToHome", declaredFlags);
                    if (goHome != null) methods.Add(goHome);

                    var goBack = type.GetMethod("ExecuteBack", declaredFlags);
                    if (goBack != null) methods.Add(goBack);

                    var execLink = type.GetMethod("ExecuteLink", declaredFlags);
                    if (execLink != null) methods.Add(execLink);

                    // Also try ExecuteGoBack, ExecuteHome, ExecuteClose variants
                    var goBack2 = type.GetMethod("ExecuteGoBack", declaredFlags);
                    if (goBack2 != null) methods.Add(goBack2);

                    var execClose = type.GetMethod("ExecuteClose", declaredFlags);
                    if (execClose != null) methods.Add(execClose);

                    foreach (var method in methods)
                    {
                        try
                        {
                            harmony.Patch(method, prefix: new HarmonyLib.HarmonyMethod(prefix));
                            MCMSettings.DebugLog("NavBlocker: patched " + type.Name + "." + method.Name + "()");
                            vmPatched++;
                        }
                        catch (Exception ex)
                        {
                            MCMSettings.DebugLog("NavBlocker: failed to patch " + type.Name + "." + method.Name + ": " + ex.ToString());
                        }
                    }
                }

                // 2b. Patch HeroVM.ExecuteLink and similar non-Encyclopedia VMs
                //     Portrait clicks in Friends/Enemies grids fire ExecuteLink on HeroVM,
                //     which doesn't contain "Encyclopedia" in its name.
                string[] extraVmNames = { "HeroVM", "ClanVM", "KingdomVM", "SettlementVM" };
                foreach (string vmName in extraVmNames)
                {
                    foreach (var type in vmAssembly.GetTypes())
                    {
                        if (type.Name != vmName) continue;
                        var execLink2 = type.GetMethod("ExecuteLink", declaredFlags);
                        if (execLink2 != null)
                        {
                            try
                            {
                                harmony.Patch(execLink2, prefix: new HarmonyLib.HarmonyMethod(prefix));
                                MCMSettings.DebugLog("NavBlocker: patched " + type.Name + ".ExecuteLink()");
                                vmPatched++;
                            }
                            catch (Exception ex)
                            {
                                MCMSettings.DebugLog("NavBlocker: failed " + type.Name + ".ExecuteLink: " + ex.ToString());
                            }
                        }
                        break;
                    }
                }

                // 3. Also scan GauntletMapEncyclopediaView (the view class) for
                //    Close/Navigate/Home methods that bypass the ViewModel layer
                var encManagerRef = EncyclopediaPageTracker.EncyclopediaManagerRef;
                if (encManagerRef != null)
                {
                    var viewType = encManagerRef.GetType();
                    var searchType = viewType;
                    while (searchType != null && searchType != typeof(object))
                    {
                        foreach (var method in searchType.GetMethods(flags | System.Reflection.BindingFlags.DeclaredOnly))
                        {
                            string name = method.Name;
                            bool isTarget = name.Contains("Close") || name.Contains("Home")
                                || name.Contains("Navigate") || name.Contains("Deactivate")
                                || name.Contains("OnFinalize");
                            if (!isTarget) continue;
                            // Skip property getters/setters
                            if (method.IsSpecialName) continue;

                            try
                            {
                                harmony.Patch(method, prefix: new HarmonyLib.HarmonyMethod(prefix));
                                MCMSettings.DebugLog("NavBlocker: patched View." + viewType.Name + "." + name + "()");
                                vmPatched++;
                            }
                            catch (Exception ex)
                            {
                                MCMSettings.DebugLog("NavBlocker: failed View." + name + ": " + ex.ToString());
                            }
                        }
                        searchType = searchType.BaseType;
                    }
                }

                // 4. Patch non-editable page VMs (Home page) to clear the tracker
                //    so hotkeys don't fire on pages without an editable object.
                var clearPrefix = typeof(EncyclopediaNavigationGuard).GetMethod("ClearTrackerPrefix",
                    System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public);

                string[] homeTypeNames = new[]
                {
                    "TaleWorlds.CampaignSystem.ViewModelCollection.Encyclopedia.EncyclopediaHomeVM",
                    "TaleWorlds.CampaignSystem.ViewModelCollection.Encyclopedia.Pages.EncyclopediaHomePageVM",
                    "TaleWorlds.CampaignSystem.ViewModelCollection.Encyclopedia.EncyclopediaSearchResultsVM",
                };

                foreach (var typeName in homeTypeNames)
                {
                    var homeType = vmAssembly.GetType(typeName);
                    if (homeType == null) continue;

                    var refresh = homeType.GetMethod("Refresh", flags);
                    if (refresh != null)
                    {
                        try
                        {
                            harmony.Patch(refresh, prefix: new HarmonyLib.HarmonyMethod(clearPrefix));
                            MCMSettings.DebugLog("NavBlocker: patched " + homeType.Name + ".Refresh() (clears tracker)");
                        }
                        catch (Exception ex)
                        {
                            MCMSettings.DebugLog("NavBlocker: failed " + homeType.Name + ".Refresh: " + ex.ToString());
                        }
                    }
                }

                // Also search for any type named "*HomeVM" or "*HomePageVM" we might have missed
                foreach (var type in vmAssembly.GetTypes())
                {
                    if (!type.Name.Contains("EncyclopediaHome")) continue;
                    var refresh = type.GetMethod("Refresh", flags);
                    if (refresh == null) continue;
                    try
                    {
                        harmony.Patch(refresh, prefix: new HarmonyLib.HarmonyMethod(clearPrefix));
                        MCMSettings.DebugLog("NavBlocker: patched " + type.Name + ".Refresh() (clears tracker, discovered)");
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: Harmony patch failed: " + ex.ToString()); } // might already be patched
                }

                MCMSettings.DebugLog("NavBlocker: patched " + vmPatched + " total navigation methods");
                _patched = true;
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("NavBlocker: patch error - " + ex.ToString());
                _patched = true;
            }
        }

        /// <summary>
        /// Harmony prefix for non-editable page Refresh methods (Home, search results).
        /// Clears the page tracker so hotkeys won't fire on these pages.
        /// Returns true to allow Refresh to proceed normally.
        /// </summary>
        public static bool ClearTrackerPrefix()
        {
            EncyclopediaPageTracker.CurrentObjectId = null;
            EncyclopediaPageTracker.CurrentPageType = null;
            EncyclopediaPageTracker.CurrentHero = null;
            return true; // let the original Refresh run
        }

        /// <summary>
        /// Harmony prefix shared by all patched navigation methods.
        /// Returns false (skip original) when any edit popup or picker is open.
        /// </summary>
        public static bool BlockNavigationPrefix(System.Reflection.MethodBase __originalMethod, object __instance)
        {
            if (IsAnyEditPopupOpen())
            {
                MCMSettings.DebugLog("NavBlocker: blocked " + __originalMethod.DeclaringType.Name
                    + "." + __originalMethod.Name + "() (popup open)");
                return false;
            }

            return true;
        }

        private static bool IsAnyEditPopupOpen()
        {
            return EncyclopediaInputBlocker.IsBlocking
                || EncyclopediaEditPopup.IsPopupOpen
                || EncyclopediaNameEditPopup.IsPopupOpen
                || EncyclopediaCultureEditPopup.IsPopupOpen
                || EncyclopediaOccupationEditPopup.IsPopupOpen
                || EncyclopediaBannerEditPopup.IsPopupOpen
                || EncyclopediaResetPopup.IsPopupOpen
                || EncyclopediaTagEditPopup.IsPopupOpen
                || EncyclopediaJournalPopup.IsPopupOpen
                || RelationNotesInjector.IsPopupOpen
                || EditPopupInjector.IsOpen
                || LoreEditorPopup.IsOpen
                || SelectionPopupHelper.IsOpen;
        }
    }

    // ============================================
    //  Ctrl+E / Ctrl+R / Ctrl+Z key polling timer
    // ============================================
    public static class EncyclopediaKeyPoller
    {
        private static System.Threading.Timer _timer;
        private static bool _running = false;
        private static readonly object _lock = new object();

        // Debounce: require multiple consecutive "closed" readings before confirming close.
        // This prevents false close detection during page transitions (e.g., search -> detail page)
        // where IsEncyclopediaOpen briefly becomes false.
        private static int _closeDetectionCount = 0;
        private const int CloseConfirmationThreshold = 6; // 6 polls × 50ms = 300ms of confirmed closed

        [System.Runtime.InteropServices.DllImport("user32.dll")]
        private static extern short GetAsyncKeyState(int vKey);

        /// <summary>Exposes GetAsyncKeyState for other classes (e.g. RelationNotesInjector).</summary>
        public static short GetKeyState(int vKey) => GetAsyncKeyState(vKey);

        private const int VK_B = 0x42;
        private const int VK_E = 0x45;
        private const int VK_F = 0x46;
        private const int VK_G = 0x47;
        private const int VK_J = 0x4A;
        private const int VK_N = 0x4E;
        private const int VK_O = 0x4F;

        private const int VK_R = 0x52;
        private const int VK_U = 0x55;
        private const int VK_Z = 0x5A;
        private const int VK_LCONTROL = 0xA2;
        private const int VK_RCONTROL = 0xA3;

        private static bool _comboWasDown = false;
        private static bool _resetComboWasDown = false;
        private static bool _undoComboWasDown = false;
        private static bool _nameComboWasDown = false;
        private static bool _bannerComboWasDown = false;
        private static bool _cultureComboWasDown = false;
        private static bool _occupationComboWasDown = false;
        private static bool _tagComboWasDown = false;
        private static bool _friendNoteComboWasDown = false;
        private static bool _journalComboWasDown = false;



        public static void EnsureRunning()
        {
            lock (_lock)
            {
                if (_running) return;
                _running = true;
                _comboWasDown = false;
                _resetComboWasDown = false;
                _undoComboWasDown = false;
                _nameComboWasDown = false;
                _bannerComboWasDown = false;
                _cultureComboWasDown = false;
                _occupationComboWasDown = false;
                _tagComboWasDown = false;
                _journalComboWasDown = false;
                _friendNoteComboWasDown = false;
                _closeDetectionCount = 0;

                int delayMs = 500;
                int intervalMs = 50;
                try
                {
                    var settings = MCMSettings.Instance;
                    if (settings != null)
                    {
                        delayMs = settings.InitialKeyPollDelayMs;
                        intervalMs = settings.KeyPollIntervalMs;
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: settings access failed: " + ex.ToString()); }

                MCMSettings.DebugLog("Key poller started (delay=" + delayMs + "ms, interval=" + intervalMs + "ms)");
                _timer = new System.Threading.Timer(PollKey, null, delayMs, intervalMs);
            }
        }

        private static void Stop()
        {
            lock (_lock)
            {
                _running = false;
                _timer?.Dispose();
                _timer = null;
                MCMSettings.DebugLog("Key poller stopped (encyclopedia inactive)");
            }
        }

        private static void PollKey(object state)
        {
            try
            {
                if (Campaign.Current == null)
                {
                    Stop();
                    return;
                }

                if (string.IsNullOrEmpty(EncyclopediaPageTracker.CurrentObjectId))
                    return;

                // Check if the encyclopedia is still open (layer ref or layer count).
                // Use debounce: require multiple consecutive "closed" readings to confirm close.
                // This prevents false positives during page transitions (search -> detail page)
                // where IsEncyclopediaOpen can briefly return false.
                if (!EncyclopediaPageTracker.IsEncyclopediaOpen())
                {
                    _closeDetectionCount++;
                    if (_closeDetectionCount < CloseConfirmationThreshold)
                    {
                        if (_closeDetectionCount == 1)
                        {
                            string method = EncyclopediaPageTracker.EncyclopediaOpenField != null ? "IsEncyclopediaOpen-field"
                                : EncyclopediaPageTracker.EncyclopediaLayerRef != null ? "layer-ref" : "layer-count";
                            MCMSettings.DebugLog("Encyclopedia close tentative (method=" + method + ", confirming " + CloseConfirmationThreshold + " polls)");
                        }
                        return; // wait for more confirmations
                    }

                    string detectionMethod = EncyclopediaPageTracker.EncyclopediaOpenField != null ? "IsEncyclopediaOpen-field"
                        : EncyclopediaPageTracker.EncyclopediaLayerRef != null ? "layer-ref" : "layer-count";
                    MCMSettings.DebugLog("Encyclopedia closed confirmed after " + _closeDetectionCount + " polls (method=" + detectionMethod + ")");

                    // Schedule deferred banner visual refresh on the MAIN game thread.
                    // We're on a timer thread here — game engine visual operations need the main thread.
                    try
                    {
                        EncyclopediaBannerEditPopup.ScheduleMainThreadRefresh();
                    }
                    catch (Exception ex)
                    {
                        MCMSettings.DebugLog("Schedule visual refresh error: " + ex.ToString());
                    }

                    // Use ScheduleClear (not Clear) because we're on a timer thread —
                    // Gauntlet widget removal must happen on the main game thread.
                    TimestampWidgetInjector.ScheduleClear();
                    TagWidgetInjector.ScheduleClear();
                    JournalSectionInjector.ScheduleClear();
                    LoreSectionInjector.ScheduleClear();
                    RelationNotesSectionInjector.ScheduleClear();
                    HeroTimelineSectionInjector.ScheduleClear();
                    SelectionPopupHelper.ScheduleClose();
                    EncyclopediaTagEditPopup.ScheduleClose();
                    LoreEditorPopup.ScheduleClose();
                    EncyclopediaPageTracker.Clear();
                    // Clear the corrupted flag so the next encyclopedia open can tick normally.
                    // Without this, OnTick stays blocked after a failed page load (e.g. ListPage skip).
                    JournalSectionInjector._encyclopediaCorrupted = false;
                    JournalSectionInjector._encyclopediaHasPage = false;
                    // Stop the timer so EnsureRunning() creates a fresh one on next open
                    Stop();
                    return;
                }

                // Encyclopedia is open — reset close detection counter
                _closeDetectionCount = 0;

                bool ctrlDown = (GetAsyncKeyState(VK_LCONTROL) & 0x8000) != 0
                             || (GetAsyncKeyState(VK_RCONTROL) & 0x8000) != 0;
                bool eIsDown = (GetAsyncKeyState(VK_E) & 0x8000) != 0;
                bool fIsDown = (GetAsyncKeyState(VK_F) & 0x8000) != 0;
                bool gIsDown = (GetAsyncKeyState(VK_G) & 0x8000) != 0;
                bool jIsDown = (GetAsyncKeyState(VK_J) & 0x8000) != 0;
                bool rIsDown = (GetAsyncKeyState(VK_R) & 0x8000) != 0;
                bool zIsDown = (GetAsyncKeyState(VK_Z) & 0x8000) != 0;
                bool nIsDown = (GetAsyncKeyState(VK_N) & 0x8000) != 0;
                bool bIsDown = (GetAsyncKeyState(VK_B) & 0x8000) != 0;
                bool uIsDown = (GetAsyncKeyState(VK_U) & 0x8000) != 0;
                bool oIsDown = (GetAsyncKeyState(VK_O) & 0x8000) != 0;

                bool comboDown = ctrlDown && eIsDown;
                bool justPressed = comboDown && !_comboWasDown;
                _comboWasDown = comboDown;

                bool resetComboDown = ctrlDown && rIsDown;
                bool resetJustPressed = resetComboDown && !_resetComboWasDown;
                _resetComboWasDown = resetComboDown;

                bool undoComboDown = ctrlDown && zIsDown;
                bool undoJustPressed = undoComboDown && !_undoComboWasDown;
                _undoComboWasDown = undoComboDown;

                bool nameComboDown = ctrlDown && nIsDown;
                bool nameJustPressed = nameComboDown && !_nameComboWasDown;
                _nameComboWasDown = nameComboDown;

                bool bannerComboDown = ctrlDown && bIsDown;
                bool bannerJustPressed = bannerComboDown && !_bannerComboWasDown;
                _bannerComboWasDown = bannerComboDown;

                bool cultureComboDown = ctrlDown && uIsDown;
                bool cultureJustPressed = cultureComboDown && !_cultureComboWasDown;
                _cultureComboWasDown = cultureComboDown;

                bool occupationComboDown = ctrlDown && oIsDown;
                bool occupationJustPressed = occupationComboDown && !_occupationComboWasDown;
                _occupationComboWasDown = occupationComboDown;

                bool tagComboDown = ctrlDown && gIsDown;
                bool tagJustPressed = tagComboDown && !_tagComboWasDown;
                _tagComboWasDown = tagComboDown;

                bool journalComboDown = ctrlDown && jIsDown;
                bool journalJustPressed = journalComboDown && !_journalComboWasDown;
                _journalComboWasDown = journalComboDown;

                bool friendNoteComboDown = ctrlDown && fIsDown;
                bool friendNoteJustPressed = friendNoteComboDown && !_friendNoteComboWasDown;
                _friendNoteComboWasDown = friendNoteComboDown;

                // Block all shortcut processing when any edit popup is open.
                // This prevents Ctrl+E, Ctrl+G, Backspace etc. from triggering
                // while the tag menu or other popups are active.
                if (EncyclopediaInputBlocker.IsBlocking
                    || EncyclopediaEditPopup.IsPopupOpen
                    || EncyclopediaNameEditPopup.IsPopupOpen
                    || EncyclopediaCultureEditPopup.IsPopupOpen
                    || EncyclopediaOccupationEditPopup.IsPopupOpen
                    || EncyclopediaBannerEditPopup.IsPopupOpen
                    || EncyclopediaResetPopup.IsPopupOpen
                    || EncyclopediaTagEditPopup.IsPopupOpen
                    || EncyclopediaJournalPopup.IsPopupOpen
                    || RelationNotesInjector.IsPopupOpen
                    || EditPopupInjector.IsOpen
                    || LoreEditorPopup.IsOpen
                    || SelectionPopupHelper.IsOpen
)
                {
                    return;
                }

                if (friendNoteJustPressed
                    && EncyclopediaPageTracker.CurrentPageType == "Hero"
                    && !string.IsNullOrEmpty(EncyclopediaPageTracker.CurrentObjectId)
                    && !EditPopupInjector.IsOpen
                    && !SelectionPopupHelper.IsOpen
                    && (MCMSettings.Instance?.EnableRelationNotes ?? true))
                {
                    MCMSettings.DebugLog("Ctrl+F detected! Opening relation notes for: " + EncyclopediaPageTracker.CurrentObjectId);
                    RelationNotesInjector.ScheduleHeroPicker(EncyclopediaPageTracker.CurrentObjectId);
                }
                else if (justPressed)
                {
                    MCMSettings.DebugLog("Ctrl+E detected! Opening edit popup for: " + EncyclopediaPageTracker.CurrentObjectId);
                    EncyclopediaEditPopup.TryOpen();
                }
                else if (nameJustPressed)
                {
                    MCMSettings.DebugLog("Ctrl+N detected! Opening name edit for: " + EncyclopediaPageTracker.CurrentObjectId);
                    EncyclopediaNameEditPopup.TryOpen();
                }
                else if (resetJustPressed)
                {
                    MCMSettings.DebugLog("Ctrl+R detected! Opening reset confirmation for: " + EncyclopediaPageTracker.CurrentObjectId);
                    EncyclopediaResetPopup.TryOpen();
                }
                else if (bannerJustPressed)
                {
                    MCMSettings.DebugLog("Ctrl+B detected! Opening banner edit for: " + EncyclopediaPageTracker.CurrentObjectId);
                    EncyclopediaBannerEditPopup.TryOpen();
                }
                else if (cultureJustPressed)
                {
                    MCMSettings.DebugLog("Ctrl+U detected! Opening culture edit for: " + EncyclopediaPageTracker.CurrentObjectId);
                    EncyclopediaCultureEditPopup.TryOpen();
                }
                else if (occupationJustPressed)
                {
                    MCMSettings.DebugLog("Ctrl+O detected! Opening occupation edit for: " + EncyclopediaPageTracker.CurrentObjectId);
                    EncyclopediaOccupationEditPopup.TryOpen();
                }
                else if (tagJustPressed)
                {
                    MCMSettings.DebugLog("Ctrl+G detected! Opening tag edit for: " + EncyclopediaPageTracker.CurrentObjectId);
                    EncyclopediaTagEditPopup.TryOpen();
                }
                else if (journalJustPressed && EncyclopediaPageTracker.CurrentPageType != "Hero")
                {
                    MCMSettings.DebugLog("Ctrl+J detected! Opening journal popup for: " + EncyclopediaPageTracker.CurrentObjectId);
                    EncyclopediaJournalPopup.TryOpen();
                }
                else if (undoJustPressed)
                {
                    MCMSettings.DebugLog("Ctrl+Z detected! Attempting undo");
                    EncyclopediaUndoHandler.TryUndo();
                }

            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: operation failed: " + ex.ToString()); }
        }
    }

    // ============================================
    //  Stats Widget Injector: injects Info panels for Settlement/Kingdom pages
    // ============================================
    public static class StatsWidgetInjector
    {
        private const float StatPairWidth = 280f;

        private static readonly System.Reflection.BindingFlags AllFlags =
            System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public
            | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static;

        private static string _pendingObjectId;
        private static List<KeyValuePair<string, string>> _pendingStats;
        private const int MaxRetryCount = 20;
        private static int _retryCount;
        private static string _injectedObjectId;

        public static void ScheduleInjection(string objectId, List<KeyValuePair<string, string>> stats)
        {
            _pendingObjectId = objectId;
            _pendingStats = stats;
            _retryCount = 0;
        }

        public static void TickMainThread()
        {
            if (_pendingStats == null || _pendingObjectId == null) return;
            if (_pendingObjectId == _injectedObjectId)
            {
                _pendingStats = null;
                return;
            }

            _retryCount++;
            if (_retryCount > MaxRetryCount)
            {
                MCMSettings.DebugLog("StatsWidget: gave up after " + MaxRetryCount + " retries for " + _pendingObjectId);
                _pendingStats = null;
                return;
            }

            try
            {
                if (DoInject(_pendingObjectId, _pendingStats))
                {
                    _injectedObjectId = _pendingObjectId;
                    _pendingStats = null;
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("StatsWidget: tick error: " + ex.ToString());
            }
        }

        public static void ClearInjected()
        {
            _injectedObjectId = null;
        }

        private static bool DoInject(string objectId, List<KeyValuePair<string, string>> stats)
        {
            var topScreen = ScreenManager.TopScreen;
            if (topScreen == null) return false;

            GauntletLayer encLayer = FindEncyclopediaLayer(topScreen);
            if (encLayer == null) return false;

            Widget layerRoot = GetLayerRootWidget(encLayer);
            if (layerRoot == null) return false;

            UIContext uiContext = layerRoot.EventManager?.Context as UIContext;
            if (uiContext == null) return false;

            Widget encWindow = FindLargestChild(layerRoot);
            if (encWindow == null) return false;

            // Find the main content panel
            Widget mainPanel = FindMainContentPanel(encWindow);
            if (mainPanel == null) return false;

            // Remove old stats widgets
            RemoveOldWidgets(mainPanel);

            // Find brushes from existing text widgets
            Brush textBrush = FindBrushByName(encWindow, "Encyclopedia.SubPage.Info.Text")
                              ?? FindAnyTextBrush(encWindow);
            Brush labelBrush = null;
            if (textBrush != null)
            {
                labelBrush = textBrush.Clone();
                // Make label slightly brighter/bolder for contrast
            }

            // Find native section parts for collapsible header
            var native = LoreSectionInjector.ExtractNativeSectionParts(mainPanel);
            if (native.ReferenceHeader == null)
                native = LoreSectionInjector.ExtractNativeSectionParts(encWindow);

            // === Build the Info section ===

            // 1. Header (collapsible "Info" divider matching native style)
            Widget headerWrapper = null;
            if (native.ReferenceHeader != null)
            {
                Type t = native.ReferenceHeader.GetType();
                while (t != null && t != typeof(Widget))
                {
                    if (t.Name == "ButtonWidget")
                    {
                        var ctor = t.GetConstructor(new[] { typeof(UIContext) });
                        if (ctor != null)
                            headerWrapper = ctor.Invoke(new object[] { uiContext }) as Widget;
                        break;
                    }
                    t = t.BaseType;
                }
            }
            if (headerWrapper == null)
                headerWrapper = LoreSectionInjector.TryCreateWidgetByType(uiContext, "ButtonWidget");
            if (headerWrapper == null)
                headerWrapper = new Widget(uiContext);

            headerWrapper.Id = "EditableEncyclopediaStatsDivider";
            headerWrapper.WidthSizePolicy = SizePolicy.StretchToParent;
            headerWrapper.HeightSizePolicy = SizePolicy.CoverChildren;
            headerWrapper.ClipContents = true;
            if (native.ReferenceHeader != null)
            {
                headerWrapper.MarginTop = native.ReferenceHeader.MarginTop;
                headerWrapper.MarginBottom = native.ReferenceHeader.MarginBottom;
                headerWrapper.MarginLeft = native.ReferenceHeader.MarginLeft;
                headerWrapper.MarginRight = native.ReferenceHeader.MarginRight;
            }
            else
            {
                headerWrapper.MarginTop = 15f;
            }
            headerWrapper.DoNotAcceptEvents = false;
            headerWrapper.DoNotPassEventsToChildren = true;

            // Header bar (horizontal: arrow + title + line)
            Widget headerBar = LoreSectionInjector.TryCreateWidgetByType(uiContext, "ListPanel");
            if (headerBar == null) headerBar = new Widget(uiContext);
            headerBar.Id = "EditableEncyclopediaStatsPlacement";

            if (native.ReferencePlacement != null)
            {
                LoreSectionInjector.CopyLayoutProperties(native.ReferencePlacement, headerBar);
                LoreSectionInjector.CopyOrSetHorizontalLayout(native.ReferencePlacement, headerBar);
            }
            else
            {
                headerBar.WidthSizePolicy = SizePolicy.StretchToParent;
                headerBar.HeightSizePolicy = SizePolicy.CoverChildren;
                LoreSectionInjector.CopyOrSetHorizontalLayout(null, headerBar);
            }

            // Collapse arrow
            if (native.NativeIndicator != null)
            {
                var arrow = new BrushWidget(uiContext);
                arrow.Id = "EditableEncyclopediaStatsIndicator";
                LoreSectionInjector.CopyLayoutProperties(native.NativeIndicator, arrow);
                if (native.IndicatorBrush != null)
                    arrow.Brush = native.IndicatorBrush;
                LoreSectionInjector.ForceWidgetBrushState(arrow, native.NativeIndicator);
                headerBar.AddChild(arrow);
            }

            // Title "Info"
            var titleText = new TextWidget(uiContext);
            titleText.Id = "EditableEncyclopediaStatsTitle";
            titleText.Text = Localization.L("ui_info");
            if (native.NativeTitle != null)
            {
                titleText.WidthSizePolicy = native.NativeTitle.WidthSizePolicy;
                titleText.HeightSizePolicy = native.NativeTitle.HeightSizePolicy;
                titleText.MarginLeft = native.NativeTitle.MarginLeft;
                titleText.MarginRight = native.NativeTitle.MarginRight;
                titleText.VerticalAlignment = native.NativeTitle.VerticalAlignment;
                if (native.NativeTitle is TextWidget nativeTitleTW && nativeTitleTW.Brush != null)
                    titleText.Brush = nativeTitleTW.Brush.Clone();
            }
            else
            {
                titleText.WidthSizePolicy = SizePolicy.CoverChildren;
                titleText.HeightSizePolicy = SizePolicy.CoverChildren;
                titleText.MarginLeft = 5f;
                titleText.VerticalAlignment = VerticalAlignment.Center;
                if (textBrush != null) titleText.Brush = textBrush.Clone();
            }
            headerBar.AddChild(titleText);

            // Divider line
            if (native.NativeLine != null)
            {
                var line = new BrushWidget(uiContext);
                LoreSectionInjector.CopyLayoutProperties(native.NativeLine, line);
                if (native.NativeLine is BrushWidget nlBW && nlBW.Brush != null)
                    line.Brush = nlBW.Brush.Clone();
                headerBar.AddChild(line);
            }

            headerWrapper.AddChild(headerBar);

            // 2. Content container (vertical list of stat rows)
            Widget contentContainer = LoreSectionInjector.TryCreateWidgetByType(uiContext, "ListPanel");
            if (contentContainer == null) contentContainer = new Widget(uiContext);
            contentContainer.Id = "EditableEncyclopediaStatsContent";
            contentContainer.WidthSizePolicy = SizePolicy.StretchToParent;
            contentContainer.HeightSizePolicy = SizePolicy.CoverChildren;
            contentContainer.MarginLeft = 20f;
            contentContainer.MarginTop = 5f;
            contentContainer.MarginBottom = 10f;
            LoreSectionInjector.SetVerticalLayoutTopToBottom(contentContainer);

            // 3. Create stat rows (two-column layout matching native ClanInfo style)
            // Try to get the native brushes used by the Clan Info section
            var defBrush = EncyclopediaPatchHelper.TryGetBrushByNamePublic(uiContext, "Encyclopedia.Stat.DefinitionText");
            var valBrush = EncyclopediaPatchHelper.TryGetBrushByNamePublic(uiContext, "Encyclopedia.Stat.ValueText");

            const int statsPerRow = 2;
            for (int i = 0; i < stats.Count; i += statsPerRow)
            {
                Widget row = LoreSectionInjector.TryCreateWidgetByType(uiContext, "ListPanel");
                if (row == null) row = new Widget(uiContext);
                row.Id = "EditableEncyclopediaStatsRow_" + i;
                row.WidthSizePolicy = SizePolicy.StretchToParent;
                row.HeightSizePolicy = SizePolicy.CoverChildren;
                row.MarginBottom = 3f; // vertical spacing between rows
                LoreSectionInjector.CopyOrSetHorizontalLayout(null, row);

                for (int j = 0; j < statsPerRow && (i + j) < stats.Count; j++)
                {
                    var stat = stats[i + j];

                    // Stat pair container (fixed width for column alignment)
                    Widget pairWidget = LoreSectionInjector.TryCreateWidgetByType(uiContext, "ListPanel");
                    if (pairWidget == null) pairWidget = new Widget(uiContext);
                    pairWidget.WidthSizePolicy = SizePolicy.Fixed;
                    pairWidget.SuggestedWidth = StatPairWidth;
                    pairWidget.HeightSizePolicy = SizePolicy.CoverChildren;
                    LoreSectionInjector.CopyOrSetHorizontalLayout(null, pairWidget);

                    // Label — use native Encyclopedia.Stat.DefinitionText brush (with colon like native ClanInfo)
                    var lbl = new TextWidget(uiContext);
                    lbl.Text = stat.Key + ":";
                    lbl.WidthSizePolicy = SizePolicy.CoverChildren;
                    lbl.HeightSizePolicy = SizePolicy.CoverChildren;
                    if (defBrush != null)
                        lbl.Brush = defBrush.Clone();
                    else if (textBrush != null)
                    {
                        var lblBrush = textBrush.Clone();
                        try { LoreSectionHelpers.SetBrushColor(lblBrush, 0.9f, 0.85f, 0.75f, 1f); } catch (Exception ex) { MCMSettings.DebugLog("Patches: brush color set failed: " + ex.ToString()); }
                        lbl.Brush = lblBrush;
                    }
                    pairWidget.AddChild(lbl);

                    // Value — use native Encyclopedia.Stat.ValueText brush
                    var valWidget = new TextWidget(uiContext);
                    valWidget.Text = " " + stat.Value;
                    valWidget.WidthSizePolicy = SizePolicy.CoverChildren;
                    valWidget.HeightSizePolicy = SizePolicy.CoverChildren;
                    if (valBrush != null)
                        valWidget.Brush = valBrush.Clone();
                    else if (textBrush != null)
                    {
                        var vBrush = textBrush.Clone();
                        try { LoreSectionHelpers.SetBrushColor(vBrush, 0.82f, 0.65f, 0.35f, 1f); } catch (Exception ex) { MCMSettings.DebugLog("Patches: brush color set failed: " + ex.ToString()); }
                        valWidget.Brush = vBrush;
                    }
                    pairWidget.AddChild(valWidget);

                    row.AddChild(pairWidget);
                }

                contentContainer.AddChild(row);
            }

            // Collapse toggle support
            bool isExpanded = true;
            LoreSectionHelpers.HookWidgetClick(headerWrapper, () =>
            {
                isExpanded = !isExpanded;
                contentContainer.IsVisible = isExpanded;
            });

            // 4. Insert into main panel (after description, before first native section)
            // Find insert position — look for the first native section header (Owner/Leader/Clans/etc.)
            int insertIndex = 0;
            for (int i = 0; i < mainPanel.ChildCount; i++)
            {
                insertIndex = i;
                var child = mainPanel.GetChild(i);
                // Native section headers are typically ButtonWidget/Widget with specific patterns
                // We want to insert AFTER the description text
                if (child.ChildCount > 0)
                {
                    // This is likely a section header (Owner, Clans, etc.) — insert before it
                    break;
                }
            }

            // Insert header + content
            mainPanel.AddChildAtIndex(headerWrapper, insertIndex);
            mainPanel.AddChildAtIndex(contentContainer, insertIndex + 1);

            MCMSettings.DebugLog("StatsWidget: injected " + stats.Count + " stats for " + objectId + " at index " + insertIndex);
            return true;
        }

        private static void RemoveOldWidgets(Widget parent)
        {
            if (parent == null) return;
            for (int i = parent.ChildCount - 1; i >= 0; i--)
            {
                var child = parent.GetChild(i);
                if (child.Id != null && child.Id.StartsWith("EditableEncyclopediaStats"))
                    parent.RemoveChild(child);
            }
        }

        private static Brush FindBrushByName(Widget root, string brushName, int depth = 0)
        {
            if (root == null || depth > 15) return null;
            try
            {
                if (root is BrushWidget bw && bw.Brush?.Name != null && bw.Brush.Name.Contains(brushName))
                    return bw.Brush.Clone();
                if (root is TextWidget tw && tw.Brush?.Name != null && tw.Brush.Name.Contains(brushName))
                    return tw.Brush.Clone();
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: brush search failed: " + ex.ToString()); }
            for (int i = 0; i < root.ChildCount; i++)
            {
                var result = FindBrushByName(root.GetChild(i), brushName, depth + 1);
                if (result != null) return result;
            }
            return null;
        }

        private static Brush FindAnyTextBrush(Widget root, int depth = 0)
        {
            if (root == null || depth > 15) return null;
            try
            {
                if (root is TextWidget tw && tw.Brush != null) return tw.Brush.Clone();
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: text brush search failed: " + ex.ToString()); }
            for (int i = 0; i < root.ChildCount; i++)
            {
                var result = FindAnyTextBrush(root.GetChild(i), depth + 1);
                if (result != null) return result;
            }
            return null;
        }

        private static GauntletLayer FindEncyclopediaLayer(ScreenBase topScreen)
        {
            object encManager = EncyclopediaPageTracker.EncyclopediaManagerRef;
            if (encManager != null)
            {
                var encType = encManager.GetType();
                while (encType != null && encType != typeof(object))
                {
                    var layerField = encType.GetField("<Layer>k__BackingField", AllFlags);
                    if (layerField != null)
                    {
                        var layerVal = layerField.GetValue(encManager);
                        if (layerVal is GauntletLayer gl) return gl;
                        break;
                    }
                    encType = encType.BaseType;
                }
            }

            GauntletLayer bestLayer = null;
            int bestDesc = 0;
            var layers = topScreen.Layers;
            for (int i = 0; i < layers.Count; i++)
            {
                if (!(layers[i] is GauntletLayer gl2)) continue;
                Widget root = GetLayerRootWidget(gl2);
                if (root == null) continue;
                int desc = CountDescendants(root);
                if (desc < 10 || desc > 2000) continue;
                // Only consider layers with EncyclopediaDividerButtonWidget — prevents
                // picking Clan/Party/Inventory screen panels instead of the encyclopedia.
                if (!LoreSectionInjector.ContainsWidgetType(root, "EncyclopediaDividerButtonWidget")) continue;
                if (desc > bestDesc) { bestDesc = desc; bestLayer = gl2; }
            }
            return bestLayer;
        }

        private static Widget GetLayerRootWidget(GauntletLayer layer)
        {
            try
            {
                var type = typeof(GauntletLayer);
                foreach (var fieldName in new[] { "_gauntletUIContext", "_uiContext", "_context" })
                {
                    var field = type.GetField(fieldName, AllFlags);
                    if (field != null)
                    {
                        var uiCtx = field.GetValue(layer) as UIContext;
                        if (uiCtx?.EventManager?.Root != null) return uiCtx.EventManager.Root;
                    }
                }
                foreach (var propName in new[] { "UIContext", "_gauntletUIContext" })
                {
                    var prop = type.GetProperty(propName, AllFlags);
                    if (prop != null)
                    {
                        var uiCtx = prop.GetValue(layer) as UIContext;
                        if (uiCtx?.EventManager?.Root != null) return uiCtx.EventManager.Root;
                    }
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: layer root widget access failed: " + ex.ToString()); }
            return null;
        }

        private static Widget FindLargestChild(Widget parent)
        {
            if (parent == null) return null;
            Widget best = null;
            int bestDesc = 0;
            for (int i = 0; i < parent.ChildCount; i++)
            {
                int desc = CountDescendants(parent.GetChild(i));
                if (desc > bestDesc) { bestDesc = desc; best = parent.GetChild(i); }
            }
            return best ?? parent;
        }

        private static Widget FindMainContentPanel(Widget root)
        {
            Widget rightSideList = FindWidgetById(root, "RightSideList", 0);
            if (rightSideList != null && rightSideList.ChildCount >= 1)
            {
                Widget wrapper = rightSideList.GetChild(0);
                for (int i = 0; i < wrapper.ChildCount; i++)
                {
                    Widget child = wrapper.GetChild(i);
                    string typeName = child.GetType().Name;
                    if (typeName == "ListPanel" || typeName == "NavigatableListPanel")
                        return child;
                }
                return wrapper;
            }
            return null;
        }

        private static Widget FindWidgetById(Widget root, string id, int depth)
        {
            if (root == null || depth > 20) return null;
            if (root.Id == id) return root;
            for (int i = 0; i < root.ChildCount; i++)
            {
                var result = FindWidgetById(root.GetChild(i), id, depth + 1);
                if (result != null) return result;
            }
            return null;
        }

        private static int CountDescendants(Widget w)
        {
            if (w == null) return 0;
            int count = 1;
            for (int i = 0; i < w.ChildCount; i++)
                count += CountDescendants(w.GetChild(i));
            return count;
        }
    }

    // ============================================
    //  Helper: shared logic for all encyclopedia page patches
    // ============================================
    public static class EncyclopediaPatchHelper
    {
        // Round 4 finding P-C1 / P-I4: identical inline `new[] { ... }` arrays were allocated
        // on every Refresh postfix at 5+ sites. Hoisted to static readonly so they share storage.
        internal static readonly string[] StatsListNamesFull =
            { "Stats", "HeroInfo", "Information", "LeftSideProperties", "RightSideProperties" };
        internal static readonly string[] StatsListNamesCommon =
            { "Stats", "HeroInfo", "Information" };

        // ── Fog-of-war consistency for injected Info/Stats rows ──
        // Vanilla masks unknown heroes' stats with "???" (std_common_strings id keqS2dGa,
        // literally "???" in all 12 shipped languages). The gate is
        // EncyclopediaHeroPageVM.IsInformationHidden — a public bool on the very VM we patch,
        // driven by CampaignUIHelper.IsHeroInformationHidden.
        // Our rows are appended in a Refresh POSTFIX, i.e. after vanilla's own gating has run,
        // so without re-applying the check here the panel leaks gold/troops/holdings/location
        // for heroes the player has never met, while Age/Occupation still read "???".
        internal const string HiddenInfoPlaceholder = "???";

        private static readonly Dictionary<Type, System.Reflection.PropertyInfo> _infoHiddenPropCache =
            new Dictionary<Type, System.Reflection.PropertyInfo>();

        /// <summary>
        /// True when the game considers this page's subject unknown to the player.
        /// Primary source is the VM's own vanilla flag; falls back to detecting a row the
        /// game itself already masked, so engine builds without the property still behave
        /// correctly instead of silently un-masking everything.
        /// </summary>
        internal static bool IsInfoHidden(object pageVm, System.Collections.IEnumerable existingStats)
        {
            const System.Reflection.BindingFlags flags =
                  System.Reflection.BindingFlags.Instance
                | System.Reflection.BindingFlags.Public
                | System.Reflection.BindingFlags.NonPublic;

            // 1) Authoritative: vanilla's own flag on the VM.
            if (pageVm != null)
            {
                try
                {
                    var vmType = pageVm.GetType();
                    System.Reflection.PropertyInfo prop;
                    lock (_infoHiddenPropCache)
                    {
                        if (!_infoHiddenPropCache.TryGetValue(vmType, out prop))
                        {
                            prop = vmType.GetProperty("IsInformationHidden", flags);
                            _infoHiddenPropCache[vmType] = prop;
                        }
                    }
                    if (prop != null && prop.PropertyType == typeof(bool))
                    {
                        object v = prop.GetValue(pageVm);
                        if (v is bool) return (bool)v;
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("IsInfoHidden: VM flag read failed: " + ex.Message); }
            }

            // 2) Fallback: the game already rendered a masked row (e.g. Age = "???").
            if (existingStats != null)
            {
                try
                {
                    foreach (var item in existingStats)
                    {
                        if (item == null) continue;
                        var vp = item.GetType().GetProperty("Value", flags);
                        if (vp == null) continue;
                        var raw = vp.GetValue(item);
                        if (raw != null && IsMaskedValue(raw.ToString())) return true;
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("IsInfoHidden: row scan failed: " + ex.Message); }
            }

            return false;
        }

        /// <summary>True if the string is nothing but question marks, i.e. a vanilla mask.</summary>
        private static bool IsMaskedValue(string s)
        {
            if (string.IsNullOrEmpty(s)) return false;
            s = s.Trim();
            if (s.Length == 0) return false;
            for (int i = 0; i < s.Length; i++)
                if (s[i] != '?') return false;
            return true;
        }

        /// <summary>
        /// Emits an "At War" entry as one row per faction.
        /// The vanilla stats grid uses a fixed DefaultCellWidth="275" with a CoverChildren,
        /// non-clipping row template (SandBox EncyclopediaHeroPage.xml), so a comma-joined
        /// list of war targets renders straight over the neighbouring column instead of
        /// wrapping. One row per faction is the same approach the clan page already uses.
        /// </summary>
        internal static void AddWarRows(Action<string, string> addRow, List<string> warFactions, bool infoHidden)
        {
            if (addRow == null) return;
            if (infoHidden) { addRow("At War", HiddenInfoPlaceholder); return; }
            if (warFactions == null || warFactions.Count == 0) { addRow("At War", "Peace"); return; }

            addRow("At War", warFactions[0]);
            for (int i = 1; i < warFactions.Count; i++)
                addRow("", warFactions[i]);
        }

        // v2.5.2 fix: deferred post-apply refresh.
        // Calling EncyclopediaPageTracker.CurrentRefreshAction() synchronously from a popup-confirm
        // click handler triggers a "Collection was modified during enumeration" crash inside
        // GauntletGamepadNavigationManager.Update — the click handler runs inside OnApplicationTick's
        // input phase, so the synchronous Refresh mutates widgets while the gamepad-nav dict is
        // mid-iteration on the same thread. Scheduling the refresh + confirmation message for the
        // NEXT tick breaks the reentrance.
        private static volatile Action _pendingPostApplyRefresh;
        private static volatile string _pendingPostApplyMessage;
        private static volatile bool _pendingPostApplyFlag;

        internal static void SchedulePostApplyRefresh(Action refresh, string message)
        {
            _pendingPostApplyRefresh = refresh;
            _pendingPostApplyMessage = message;
            _pendingPostApplyFlag = true;
        }

        /// <summary>
        /// MUST be called from OnApplicationTick on the main thread. Drains the deferred
        /// post-apply refresh + confirmation-message queue. Runs AFTER the previous tick's
        /// GauntletUI iteration has completed, so widget mutations are safe here.
        /// </summary>
        public static void TickMainThread()
        {
            if (!_pendingPostApplyFlag) return;
            _pendingPostApplyFlag = false;

            var refresh = _pendingPostApplyRefresh;
            var message = _pendingPostApplyMessage;
            _pendingPostApplyRefresh = null;
            _pendingPostApplyMessage = null;

            if (refresh != null)
            {
                try { refresh(); }
                catch (Exception ex) { MCMSettings.DebugLog("EncyclopediaPatchHelper.TickMainThread: deferred refresh failed: " + ex.ToString()); }
            }

            if (!string.IsNullOrEmpty(message))
            {
                try { InformationManager.DisplayMessage(new InformationMessage(message, Colors.Green)); }
                catch (Exception ex) { MCMSettings.DebugLog("EncyclopediaPatchHelper.TickMainThread: deferred message failed: " + ex.ToString()); }
            }
        }

        /// <summary>
        /// Resolves the display name for a hero's custom culture.
        /// Checks custom display name first, then looks up the culture object by ID.
        /// Returns null if no custom culture is assigned.
        /// </summary>
        public static string ResolveCustomCultureDisplay(string heroId)
        {
            if (EncyclopediaEditBehavior.Instance == null || string.IsNullOrEmpty(heroId)) return null;
            string display = EncyclopediaEditBehavior.Instance.GetCustomCultureDisplayName(heroId);
            if (!string.IsNullOrEmpty(display)) return display;
            string cultureId = EncyclopediaEditBehavior.Instance.GetCustomCulture(heroId);
            if (string.IsNullOrEmpty(cultureId)) return null;
            try
            {
                foreach (var c in TaleWorlds.ObjectSystem.MBObjectManager.Instance.GetObjectTypeList<CultureObject>())
                {
                    if (c != null && string.Equals(c.StringId, cultureId, StringComparison.OrdinalIgnoreCase))
                        return c.Name?.ToString() ?? cultureId;
                }
            }
            catch { }
            return cultureId;
        }

        /// <summary>
        /// Overrides the "Culture" entry in a ViewModel's stats list with a custom display name.
        /// Works for Hero, Clan, Kingdom, and Settlement page VMs.
        /// </summary>
        public static void OverrideCultureInStats(object viewModel, string cultureDisplay, string debugPrefix)
        {
            if (viewModel == null || string.IsNullOrEmpty(cultureDisplay)) return;
            var infoFlags = System.Reflection.BindingFlags.Instance
                          | System.Reflection.BindingFlags.Public
                          | System.Reflection.BindingFlags.NonPublic;
            try
            {
                // Try CultureText property (NavalDLC VMs)
                var cultureTextProp = viewModel.GetType().GetProperty("CultureText", infoFlags);
                if (cultureTextProp != null && cultureTextProp.CanWrite && cultureTextProp.PropertyType == typeof(string))
                {
                    cultureTextProp.SetValue(viewModel, cultureDisplay);
                    MCMSettings.DebugLog(debugPrefix + " CultureText overridden to: " + cultureDisplay);
                    return;
                }

                // Search stats lists (Stats, HeroInfo, Information, LeftSideProperties, RightSideProperties)
                foreach (var listPropName in EncyclopediaPatchHelper.StatsListNamesFull)
                {
                    var listProp = viewModel.GetType().GetProperty(listPropName, infoFlags);
                    if (listProp == null) continue;
                    var list = listProp.GetValue(viewModel) as System.Collections.IEnumerable;
                    if (list == null) continue;
                    foreach (var item in list)
                    {
                        if (item == null) continue;
                        var defProp = item.GetType().GetProperty("Definition", infoFlags)
                                   ?? item.GetType().GetProperty("Type", infoFlags)
                                   ?? item.GetType().GetProperty("Name", infoFlags);
                        if (defProp == null) continue;
                        string def = defProp.GetValue(item)?.ToString();
                        if (string.IsNullOrEmpty(def)) continue;
                        if (def.IndexOf("Culture", StringComparison.OrdinalIgnoreCase) >= 0)
                        {
                            var valProp = item.GetType().GetProperty("Value", infoFlags);
                            if (valProp != null && valProp.CanWrite)
                            {
                                valProp.SetValue(item, cultureDisplay);
                                MCMSettings.DebugLog(debugPrefix + " culture overridden in stats list: " + cultureDisplay);
                                return;
                            }
                        }
                    }
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog(debugPrefix + " OverrideCultureInStats failed: " + ex.ToString()); }

            // Schedule a deferred widget-tree override as well, since the native Info section
            // renders its own Culture row that isn't in the ViewModel stats list
            _pendingCultureOverride = cultureDisplay;
            _pendingCultureOverrideRetries = 10;
        }

        // Volatile so the consumer (TickCultureWidgetOverride on main thread)
        // sees the latest value written by the Harmony postfix on its background thread
        // (Theme 1: round 1 finding W-1 / W-6).
        private static volatile string _pendingCultureOverride;
        private static volatile int _pendingCultureOverrideRetries;

        /// <summary>
        /// Called from OnApplicationTick — scans the native Info widget tree for "Culture" label
        /// and replaces the adjacent value text with the custom culture display name.
        /// </summary>
        public static void TickCultureWidgetOverride()
        {
            if (_pendingCultureOverride == null || _pendingCultureOverrideRetries <= 0) return;
            _pendingCultureOverrideRetries--;

            try
            {
                var topScreen = TaleWorlds.ScreenSystem.ScreenManager.TopScreen;
                if (topScreen == null) return;

                // Walk all layers looking for TextWidgets with "Culture" text
                foreach (var layer in topScreen.Layers)
                {
                    if (layer == null) continue;
                    var gauntletLayer = layer as GauntletLayer;
                    if (gauntletLayer == null) continue;

                    try
                    {
                        var root = gauntletLayer.UIContext?.Root;
                        if (root == null) continue;
                        if (TryOverrideCultureInWidgetTree(root, _pendingCultureOverride))
                        {
                            MCMSettings.DebugLog("Widget tree: overrode Culture text to: " + _pendingCultureOverride);
                            _pendingCultureOverride = null;
                            return;
                        }
                    }
                    catch { }
                }
            }
            catch { }

            if (_pendingCultureOverrideRetries <= 0)
                _pendingCultureOverride = null;
        }

        private static bool TryOverrideCultureInWidgetTree(Widget widget, string newCulture)
        {
            if (widget == null) return false;

            // Look for a TextWidget with text "Culture" or "Culture:" — the next sibling should be the value
            if (widget is TextWidget tw)
            {
                string text = tw.Text;
                if (text != null && text.Trim().StartsWith("Culture", StringComparison.OrdinalIgnoreCase))
                {
                    // Check if this is a label (Definition) and the value is in a sibling
                    var parent = widget.ParentWidget;
                    if (parent != null)
                    {
                        bool foundLabel = false;
                        for (int ci = 0; ci < parent.ChildCount; ci++)
                        {
                            var child = parent.GetChild(ci);
                            if (child == widget) { foundLabel = true; continue; }
                            if (foundLabel && child is TextWidget valueTw)
                            {
                                valueTw.Text = newCulture;
                                return true;
                            }
                        }
                    }
                }
            }

            // Recurse into children
            for (int i = 0; i < widget.ChildCount; i++)
            {
                if (TryOverrideCultureInWidgetTree(widget.GetChild(i), newCulture))
                    return true;
            }
            return false;
        }

        // Round 4 finding P-C2: cache the discovered (PropertyInfo, ConstructorInfo, MethodInfo, ParameterInfo[])
        // per VM type. Skips the expensive full GetProperties() + GetConstructors() scan on cache hit.
        private class StatsAdderTypeInfo
        {
            public System.Reflection.PropertyInfo StatsListProp;
            public System.Reflection.ConstructorInfo Ctor;
            public System.Reflection.MethodInfo AddMethod;
            public System.Reflection.ParameterInfo[] CtorParams;
        }
        private static readonly System.Collections.Concurrent.ConcurrentDictionary<Type, StatsAdderTypeInfo> _statsAdderTypeCache
            = new System.Collections.Concurrent.ConcurrentDictionary<Type, StatsAdderTypeInfo>();
        private static readonly System.Collections.Concurrent.ConcurrentDictionary<Type, bool> _statsAdderTypeCacheNegative
            = new System.Collections.Concurrent.ConcurrentDictionary<Type, bool>();

        /// <summary>
        /// Discovers the native stats list on a ViewModel (StringPairItemVM-based BindingList)
        /// and returns an addStatItem action that appends label/value pairs to it.
        /// Returns null if the list cannot be found. Round 4 finding P-C2: caches the
        /// discovery per VM type so the expensive GetProperties+GetConstructors scan
        /// only happens on first encounter; subsequent calls do a single dictionary lookup.
        /// </summary>
        public static Action<string, string> TryGetNativeStatsAdder(object viewModel, string debugPrefix)
        {
            if (viewModel == null) return null;
            var vmType = viewModel.GetType();

            // Cache hit (positive)
            if (_statsAdderTypeCache.TryGetValue(vmType, out var cachedInfo))
            {
                var cachedStatsList = cachedInfo.StatsListProp.GetValue(viewModel) as System.Collections.IEnumerable;
                if (cachedStatsList == null) return null;
                var cCtor = cachedInfo.Ctor;
                var cAdd = cachedInfo.AddMethod;
                var cCtorParams = cachedInfo.CtorParams;
                return (label, value) =>
                {
                    if (string.IsNullOrEmpty(value)) return;
                    object[] args = new object[cCtorParams.Length];
                    args[0] = label;
                    args[1] = value;
                    for (int ai = 2; ai < cCtorParams.Length; ai++)
                        args[ai] = cCtorParams[ai].ParameterType.IsValueType
                            ? Activator.CreateInstance(cCtorParams[ai].ParameterType) : null;
                    var newItem = cCtor.Invoke(args);
                    cAdd.Invoke(cachedStatsList, new[] { newItem });
                };
            }

            // Cache hit (negative: previously failed for this type — skip rediscovery)
            if (_statsAdderTypeCacheNegative.ContainsKey(vmType)) return null;

            var infoFlags = System.Reflection.BindingFlags.Instance
                          | System.Reflection.BindingFlags.Public
                          | System.Reflection.BindingFlags.NonPublic;
            System.Collections.IEnumerable statsList = null;
            Type statsItemType = null;
            System.Reflection.PropertyInfo discoveredProp = null;

            foreach (var prop in vmType.GetProperties(infoFlags))
            {
                if (statsList != null && statsItemType != null) break;
                try
                {
                    var val = prop.GetValue(viewModel) as System.Collections.IEnumerable;
                    if (val == null || val is string) continue;
                    foreach (var item in val)
                    {
                        if (item == null) continue;
                        var itemType = item.GetType();
                        foreach (var c in itemType.GetConstructors())
                        {
                            var ps = c.GetParameters();
                            if (ps.Length >= 2 && ps[0].ParameterType == typeof(string) && ps[1].ParameterType == typeof(string))
                            {
                                statsList = val;
                                statsItemType = itemType;
                                discoveredProp = prop;
                                MCMSettings.DebugLog(debugPrefix + " stats: found list via property '" + prop.Name + "' itemType=" + itemType.Name);
                                break;
                            }
                        }
                        break;
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation failed: " + ex.ToString()); }
            }

            // Second pass: look for named properties like LeftSideProperties/RightSideProperties
            // which use EncyclopediaSettlementPageStatItemVM (not StringPairItemVM)
            if (statsList == null || statsItemType == null)
            {
                string[] namedProps = { "LeftSideProperties", "RightSideProperties", "ClanInfo", "FactionInfo", "KingdomInfo", "Stats" };
                foreach (var propName in namedProps)
                {
                    if (statsList != null) break;
                    try
                    {
                        var prop = vmType.GetProperty(propName, infoFlags);
                        if (prop == null) continue;
                        var val = prop.GetValue(viewModel) as System.Collections.IEnumerable;
                        if (val == null) continue;

                        // Find the item type and a suitable constructor
                        var listType = prop.PropertyType;
                        if (listType.IsGenericType)
                        {
                            var itemType = listType.GetGenericArguments()[0];
                            foreach (var c in itemType.GetConstructors())
                            {
                                var ps = c.GetParameters();
                                if (ps.Length >= 2 && ps[0].ParameterType == typeof(string) && ps[1].ParameterType == typeof(string))
                                {
                                    statsList = val;
                                    statsItemType = itemType;
                                    discoveredProp = prop;
                                    MCMSettings.DebugLog(debugPrefix + " stats: found list via named property '" + propName + "' itemType=" + itemType.Name);
                                    break;
                                }
                            }
                            // If no (string, string) ctor, try (string, string, int) or similar
                            if (statsItemType == null)
                            {
                                foreach (var c in itemType.GetConstructors())
                                {
                                    var ps = c.GetParameters();
                                    if (ps.Length >= 2)
                                    {
                                        bool firstIsString = ps[0].ParameterType == typeof(string);
                                        bool secondIsString = ps[1].ParameterType == typeof(string);
                                        if (firstIsString && secondIsString)
                                        {
                                            statsList = val;
                                            statsItemType = itemType;
                                            discoveredProp = prop;
                                            MCMSettings.DebugLog(debugPrefix + " stats: found via named '" + propName + "' ctor(" + ps.Length + ") itemType=" + itemType.Name);
                                            break;
                                        }
                                    }
                                }
                            }
                        }
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: operation failed: " + ex.ToString()); }
                }
            }

            if (statsList == null || statsItemType == null || discoveredProp == null)
            {
                _statsAdderTypeCacheNegative.TryAdd(vmType, true);
                MCMSettings.DebugLog(debugPrefix + " stats: no suitable list found. VM type=" + vmType.Name);
                return null;
            }

            System.Reflection.ConstructorInfo ctor = null;
            foreach (var c in statsItemType.GetConstructors())
            {
                var ps = c.GetParameters();
                if (ps.Length >= 2 && ps[0].ParameterType == typeof(string) && ps[1].ParameterType == typeof(string))
                { ctor = c; break; }
            }
            if (ctor == null)
            {
                _statsAdderTypeCacheNegative.TryAdd(vmType, true);
                return null;
            }

            var addMethod = statsList.GetType().GetMethod("Add");
            if (addMethod == null)
            {
                _statsAdderTypeCacheNegative.TryAdd(vmType, true);
                return null;
            }

            var ctorParams = ctor.GetParameters();

            // Populate cache so subsequent calls skip discovery.
            _statsAdderTypeCache.TryAdd(vmType, new StatsAdderTypeInfo
            {
                StatsListProp = discoveredProp,
                Ctor = ctor,
                AddMethod = addMethod,
                CtorParams = ctorParams,
            });

            return (label, value) =>
            {
                if (string.IsNullOrEmpty(value)) return;
                object[] args = new object[ctorParams.Length];
                args[0] = label;
                args[1] = value;
                for (int ai = 2; ai < ctorParams.Length; ai++)
                    args[ai] = ctorParams[ai].ParameterType.IsValueType
                        ? Activator.CreateInstance(ctorParams[ai].ParameterType) : null;
                var newItem = ctor.Invoke(args);
                addMethod.Invoke(statsList, new[] { newItem });
            };
        }

        /// <summary>
        /// Public wrapper for TryGetBrushByName, used by StatsWidgetInjector.
        /// </summary>
        public static Brush TryGetBrushByNamePublic(UIContext uiContext, string brushName)
        {
            if (uiContext == null || string.IsNullOrEmpty(brushName)) return null;
            try
            {
                var flags = System.Reflection.BindingFlags.Instance
                          | System.Reflection.BindingFlags.Public
                          | System.Reflection.BindingFlags.NonPublic;
                var factoryProp = uiContext.GetType().GetProperty("BrushFactory", flags)
                    ?? uiContext.GetType().GetProperty("Brushes", flags);
                if (factoryProp == null) return null;
                var factory = factoryProp.GetValue(uiContext);
                if (factory == null) return null;
                var getBrush = factory.GetType().GetMethod("GetBrush",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public,
                    null, new[] { typeof(string) }, null);
                if (getBrush != null)
                    return getBrush.Invoke(factory, new object[] { brushName }) as Brush;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: operation failed: " + ex.ToString()); }
            return null;
        }

        public static void HandlePageRefresh(string objectId, string informationText, Action refreshAction, Action<string> setInformationText, string pageType)
        {
            if (string.IsNullOrEmpty(objectId) || EncyclopediaEditBehavior.Instance == null)
                return;

            MCMSettings.DebugLog(pageType + " page refresh: objectId=" + objectId);

            EncyclopediaPageTracker.CurrentObjectId = objectId;
            EncyclopediaPageTracker.CurrentDescription = informationText;
            EncyclopediaPageTracker.OriginalDescription = informationText;
            EncyclopediaPageTracker.CurrentRefreshAction = refreshAction;
            EncyclopediaPageTracker.CurrentSetTextAction = setInformationText;

            // Record the layer count and cache the encyclopedia's GauntletLayer reference
            // ONLY on first open (not on subsequent Refresh calls triggered by edit/reset/undo)
            try
            {
                var topScreen = ScreenManager.TopScreen;
                if (topScreen != null && EncyclopediaPageTracker.LayerCountOnOpen < 0)
                {
                    EncyclopediaPageTracker.LayerCountOnOpen = topScreen.Layers.Count;
                    MCMSettings.DebugLog("Encyclopedia opened - screen type: " + topScreen.GetType().Name
                        + ", layer count: " + topScreen.Layers.Count);
                    foreach (var layer in topScreen.Layers)
                    {
                        if (layer == null) continue;
                        MCMSettings.DebugLog("  Layer: type=" + layer.GetType().Name
                            + ", IsActive=" + layer.IsActive);
                    }

                    // Cache the encyclopedia manager and its IsEncyclopediaOpen/Layer fields
                    // for reliable close detection. Layer counting fails when right-clicking
                    // settlements/villages (layer count on open == layer count on close).
                    // Also invalidate the cache if the screen instance changed (save/load
                    // recreates the MapScreen, making the old manager reference stale).
                    if (EncyclopediaPageTracker.EncyclopediaManagerRef != null
                        && !object.ReferenceEquals(EncyclopediaPageTracker.CachedScreenRef, topScreen))
                    {
                        MCMSettings.DebugLog("Screen instance changed (save/load?) — invalidating encyclopedia manager cache");
                        EncyclopediaPageTracker.EncyclopediaManagerRef = null;
                        EncyclopediaPageTracker.EncyclopediaOpenField = null;
                        EncyclopediaPageTracker.EncyclopediaLayerRef = null;
                        EncyclopediaPageTracker.CachedScreenRef = null;
                    }
                    if (EncyclopediaPageTracker.EncyclopediaManagerRef == null)
                    {
                        try
                        {
                            var reflFlags = System.Reflection.BindingFlags.Instance
                                          | System.Reflection.BindingFlags.Public
                                          | System.Reflection.BindingFlags.NonPublic;

                            // Find EncyclopediaScreenManager on the screen
                            // (GauntletMapEncyclopediaView on NavalDLC MapScreen)
                            // Search by field name first, then by type name as fallback
                            // (different screen types may store it under different field names).
                            object encManager = null;
                            var screenType = topScreen.GetType();

                            // Pass 1: search by field name containing "EncyclopediaScreenManager"
                            var searchType = screenType;
                            while (searchType != null && searchType != typeof(object))
                            {
                                foreach (var field in searchType.GetFields(reflFlags | System.Reflection.BindingFlags.DeclaredOnly))
                                {
                                    if (field.Name.Contains("EncyclopediaScreenManager"))
                                    {
                                        try { encManager = field.GetValue(topScreen); } catch (Exception ex) { MCMSettings.DebugLog("Patches: reflection GetValue failed: " + ex.ToString()); }
                                        if (encManager != null) break;
                                    }
                                }
                                if (encManager != null) break;
                                searchType = searchType.BaseType;
                            }

                            // Pass 2: search by field type name containing "Encyclopedia"
                            // (e.g., GauntletMapEncyclopediaView stored under a different name)
                            if (encManager == null)
                            {
                                searchType = screenType;
                                while (searchType != null && searchType != typeof(object))
                                {
                                    foreach (var field in searchType.GetFields(reflFlags | System.Reflection.BindingFlags.DeclaredOnly))
                                    {
                                        if (field.FieldType.Name.Contains("Encyclopedia")
                                            || field.FieldType.FullName?.Contains("Encyclopedia") == true)
                                        {
                                            try
                                            {
                                                var val = field.GetValue(topScreen);
                                                if (val != null)
                                                {
                                                    // Verify it has IsEncyclopediaOpen or a Layer field
                                                    var valType = val.GetType();
                                                    var hasOpenField = valType.GetField("<IsEncyclopediaOpen>k__BackingField", reflFlags) != null;
                                                    var hasLayerField = valType.GetField("<Layer>k__BackingField", reflFlags) != null;
                                                    if (hasOpenField || hasLayerField)
                                                    {
                                                        encManager = val;
                                                        MCMSettings.DebugLog("Found encyclopedia manager by type scan: " + field.Name + " (" + val.GetType().Name + ")");
                                                        break;
                                                    }
                                                }
                                            }
                                            catch (Exception ex) { MCMSettings.DebugLog("Patches: operation failed: " + ex.ToString()); }
                                        }
                                    }
                                    if (encManager != null) break;
                                    searchType = searchType.BaseType;
                                }
                            }

                            // Pass 3: search through layers for encyclopedia-related fields
                            if (encManager == null)
                            {
                                foreach (var layer in topScreen.Layers)
                                {
                                    if (layer == null) continue;
                                    var layerType = layer.GetType();
                                    while (layerType != null && layerType != typeof(object))
                                    {
                                        foreach (var field in layerType.GetFields(reflFlags | System.Reflection.BindingFlags.DeclaredOnly))
                                        {
                                            if (field.FieldType.Name.Contains("Encyclopedia")
                                                || field.FieldType.FullName?.Contains("Encyclopedia") == true
                                                || field.Name.Contains("Encyclopedia"))
                                            {
                                                try
                                                {
                                                    var val = field.GetValue(layer);
                                                    if (val != null)
                                                    {
                                                        var valType = val.GetType();
                                                        var hasOpenField = valType.GetField("<IsEncyclopediaOpen>k__BackingField", reflFlags) != null;
                                                        if (hasOpenField)
                                                        {
                                                            encManager = val;
                                                            MCMSettings.DebugLog("Found encyclopedia manager on layer: "
                                                                + field.Name + " (" + val.GetType().Name + ")");
                                                            break;
                                                        }
                                                    }
                                                }
                                                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation failed: " + ex.ToString()); }
                                            }
                                        }
                                        if (encManager != null) break;
                                        layerType = layerType.BaseType;
                                    }
                                    if (encManager != null) break;
                                }
                            }

                            if (encManager != null)
                            {
                                MCMSettings.DebugLog("Found EncyclopediaScreenManager: " + encManager.GetType().FullName);
                                EncyclopediaPageTracker.EncyclopediaManagerRef = encManager;
                                EncyclopediaPageTracker.CachedScreenRef = topScreen;

                                // Primary: cache <IsEncyclopediaOpen>k__BackingField (Boolean)
                                // This is the game's own open/close state — most reliable
                                var encType = encManager.GetType();
                                while (encType != null && encType != typeof(object))
                                {
                                    var openField = encType.GetField("<IsEncyclopediaOpen>k__BackingField", reflFlags);
                                    if (openField != null && openField.FieldType == typeof(bool))
                                    {
                                        EncyclopediaPageTracker.EncyclopediaOpenField = openField;
                                        MCMSettings.DebugLog("Cached IsEncyclopediaOpen field (primary close detection)");
                                        break;
                                    }
                                    encType = encType.BaseType;
                                }

                                if (EncyclopediaPageTracker.EncyclopediaOpenField == null)
                                {
                                    MCMSettings.DebugLog("WARNING: Could not find IsEncyclopediaOpen field — falling back to layer count");
                                }

                                // Patch GauntletMapEncyclopediaView to capture the GauntletLayer
                                // when the encyclopedia opens. This eliminates fragile text-matching
                                // and retry loops in LoreSection/TagWidget/TimestampOverlay.
                                EncyclopediaLayerCapturePatch.TryPatch(encManager);
                            }
                            else
                            {
                                MCMSettings.DebugLog("WARNING: EncyclopediaScreenManager not found on screen — "
                                    + "resetting LayerCountOnOpen (screen may not host encyclopedia)");
                                // Reset LayerCountOnOpen so that the next time a hero page
                                // refreshes (possibly with the encyclopedia now open) we
                                // re-attempt the manager search instead of skipping it.
                                EncyclopediaPageTracker.LayerCountOnOpen = -1;
                            }
                        }
                        catch (Exception ex)
                        {
                            MCMSettings.DebugLog("Failed to cache encyclopedia manager: " + ex.ToString());
                        }
                    }
                    else
                    {
                        // Manager already cached — nothing else to update.
                        // GauntletMapEncyclopediaView doesn't expose its layer as a field,
                        // so input blocking uses a separate overlay layer approach instead.
                    }
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: operation failed: " + ex.ToString()); }

            // If hero has a custom name but no custom description, replace the original name
            // in the game-generated description text so it matches the displayed name
            if (pageType == "Hero" && string.IsNullOrEmpty(EncyclopediaEditBehavior.Instance.GetDescription(objectId)))
            {
                try
                {
                    string customName = EncyclopediaEditBehavior.Instance.GetCustomName(objectId);
                    string originalName = EncyclopediaEditBehavior.Instance.GetOriginalName(objectId);
                    if (!string.IsNullOrEmpty(customName) && !string.IsNullOrEmpty(originalName)
                        && customName != originalName && informationText.Contains(originalName))
                    {
                        informationText = informationText.Replace(originalName, customName);
                        setInformationText(informationText);
                        EncyclopediaPageTracker.CurrentDescription = informationText;
                        EncyclopediaPageTracker.OriginalDescription = informationText;
                        MCMSettings.DebugLog("Replaced original name '" + originalName + "' with '" + customName + "' in auto-generated description");
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: name replacement in description failed: " + ex.ToString()); }
            }

            string custom = EncyclopediaEditBehavior.Instance.GetDescription(objectId);
            if (!string.IsNullOrEmpty(custom))
            {
                MCMSettings.DebugLog("Loaded custom description for " + objectId + " (" + custom.Length + " chars)");

                bool showIndicator = false;
                try
                {
                    var s = MCMSettings.Instance;
                    if (s != null) showIndicator = s.ShowEditedIndicator;
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: settings access failed: " + ex.ToString()); }

                string displayCustom = showIndicator ? Localization.L("edited_prefix") + custom : custom;

                // Strip markers for the VM text (clean plain text for the native widget)
                string cleanDisplay = MarkdownFormatter.HasFormatting(displayCustom)
                    ? MarkdownFormatter.StripMarkers(displayCustom) : displayCustom;
                setInformationText(cleanDisplay);
                EncyclopediaPageTracker.CurrentDescription = custom;
                informationText = cleanDisplay;

                // Schedule deferred widget replacement if text has formatting
                if (MarkdownFormatter.HasFormatting(custom))
                    DescriptionFormatter.ScheduleFormat(custom, showIndicator);
            }

            bool showHint = true;
            try
            {
                var settings = MCMSettings.Instance;
                if (settings != null)
                    showHint = settings.ShowEditHint;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: settings access failed: " + ex.ToString()); }

            if (showHint && !informationText.Contains("[E ") && !informationText.Contains("[Ctrl+E") && !informationText.Contains("[Strg+E"))
            {
                bool hasCustom = EncyclopediaEditBehavior.Instance.HasCustomDescription(objectId);
                bool hasUndo = EncyclopediaPageTracker.HasUndo;

                // Build a single compact hint line: [E Edit | R Reset | Z Undo | N Name | B Banner | U Culture | O Occupation]
                var parts = new System.Collections.Generic.List<string>();

                parts.Add(Localization.L("hint_key_edit"));
                if (hasCustom)
                    parts.Add(Localization.L("hint_key_reset"));
                if (hasUndo)
                    parts.Add(Localization.L("hint_key_undo"));

                try
                {
                    var s = MCMSettings.Instance;
                    var behavior = EncyclopediaEditBehavior.Instance;

                    if (s == null || (s.EnableHeroNameEditing && s.ShowNameEditHint))
                        parts.Add(Localization.L("hint_key_name"));

                    if (s == null || (s.EnableBannerEditing && s.ShowBannerEditHint))
                        parts.Add(Localization.L("hint_key_banner"));

                    // Show culture/occupation hints when the feature is enabled
                    if (pageType == "Hero" && (s == null || (s.EnableCultureEditing && s.ShowCultureEditHint)))
                        parts.Add(Localization.L("hint_key_culture"));

                    if (pageType == "Hero" && (s == null || (s.EnableOccupationEditing && s.ShowOccupationEditHint)))
                        parts.Add(Localization.L("hint_key_occupation"));

                    if (s == null || (s.EnableTagEditing && s.ShowTagEditHint))
                        parts.Add(Localization.L("hint_key_tags"));

                    if (pageType != "Hero" && (s == null || (s.EnableJournal && s.ShowJournalHint)))
                        parts.Add(Localization.L("hint_key_journal"));

                    if (pageType == "Hero" && (s == null || (s.EnableRelationNotes && s.ShowRelationNoteHint)))
                        parts.Add(Localization.L("hint_key_friend"));
                }
                catch
                {
                    parts.Add(Localization.L("hint_key_name"));
                    parts.Add(Localization.L("hint_key_banner"));
                    parts.Add(Localization.L("hint_key_tags"));
                    if (pageType != "Hero")
                        parts.Add(Localization.L("hint_key_journal"));
                }

                // Tags are shown as a styled widget in the portrait panel for all page types,
                // so we no longer append them to the informationText.
                string tagLine = "";

                string hint = "\n[" + string.Join(" | ", parts) + "]";
                setInformationText(informationText + tagLine + hint);
            }

            EncyclopediaKeyPoller.EnsureRunning();
        }

        /// <summary>
        /// Appends the "last edited" timestamp to a VM string property (e.g., LastSeenText)
        /// so the timestamp appears in the page's info panel rather than inline with the description.
        /// </summary>
        /// <summary>
        /// Updates a VM string property to show (or remove) the "last edited" timestamp.
        /// Safe to call multiple times — strips any existing timestamp line before appending.
        /// </summary>
        public static void AppendEditTimestamp(object viewModel, string objectId, string propertyName)
        {
            if (viewModel == null || EncyclopediaEditBehavior.Instance == null)
                return;

            try
            {
                var prop = viewModel.GetType().GetProperty(propertyName,
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public);
                if (prop == null) return;

                string current = prop.GetValue(viewModel)?.ToString() ?? "";

                // Strip any previously appended timestamp line
                // The timestamp format is: "\n" + Localization.L("edited_timestamp", ...)
                // which produces something like "\nEdited: Day 1 of Summer, 1084"
                string tsMarker = Localization.L("edited_timestamp", "").TrimEnd();
                int markerIdx = current.IndexOf(tsMarker);
                if (markerIdx > 0)
                {
                    // Remove from the newline before the marker to end of that line
                    int nlIdx = current.LastIndexOf('\n', markerIdx);
                    if (nlIdx >= 0)
                    {
                        int endIdx = current.IndexOf('\n', markerIdx);
                        current = endIdx >= 0
                            ? current.Substring(0, nlIdx) + current.Substring(endIdx)
                            : current.Substring(0, nlIdx);
                    }
                }

                // Append the new timestamp if applicable
                bool hasCustom = EncyclopediaEditBehavior.Instance.HasCustomDescription(objectId);
                if (!hasCustom)
                {
                    prop.SetValue(viewModel, current);
                    return;
                }

                bool showTimestamp = true;
                try
                {
                    var s = MCMSettings.Instance;
                    if (s != null) showTimestamp = s.ShowEditTimestamp;
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: settings access failed: " + ex.ToString()); }

                string timestamp = EncyclopediaEditBehavior.Instance.GetEditTimestamp(objectId);
                if (showTimestamp && !string.IsNullOrEmpty(timestamp))
                {
                    string line = Localization.L("edited_timestamp", timestamp);
                    prop.SetValue(viewModel, current + "\n" + line);
                }
                else
                {
                    prop.SetValue(viewModel, current);
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: operation failed: " + ex.ToString()); }
        }

        /// <summary>
        /// Injects a right-aligned timestamp widget into the encyclopedia page via TimestampWidgetInjector.
        /// Shared by all page types (Hero, Settlement, etc.).
        /// </summary>
        public static void InjectTimestampWidget(string objectId)
        {
            try
            {
                var behavior = EncyclopediaEditBehavior.Instance;
                if (behavior == null) return;

                bool showTimestamp = true;
                try
                {
                    var s = MCMSettings.Instance;
                    if (s != null) showTimestamp = s.ShowEditTimestamp;
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: settings access failed: " + ex.ToString()); }

                if (showTimestamp && behavior.HasCustomDescription(objectId))
                {
                    string ts = behavior.GetEditTimestamp(objectId);
                    if (!string.IsNullOrEmpty(ts))
                    {
                        string line = Localization.L("edited_timestamp", ts);
                        TimestampWidgetInjector.InjectOrUpdate(line, true);
                        return;
                    }
                }

                TimestampWidgetInjector.InjectOrUpdate("", false);
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("InjectTimestampWidget error: " + ex.ToString());
            }
        }

        /// <summary>
        /// Prepends the "last edited" timestamp as the FIRST line of a VM string property
        /// so it appears at the top of the text area (used for settlement/castle/village pages).
        /// </summary>
        public static void PrependEditTimestamp(object viewModel, string objectId, string propertyName)
        {
            if (viewModel == null || EncyclopediaEditBehavior.Instance == null)
                return;

            try
            {
                var prop = viewModel.GetType().GetProperty(propertyName,
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public);
                if (prop == null) return;

                string current = prop.GetValue(viewModel)?.ToString() ?? "";

                // Strip any previously prepended/appended timestamp line
                string tsMarker = Localization.L("edited_timestamp", "").TrimEnd();
                int markerIdx = current.IndexOf(tsMarker);
                if (markerIdx >= 0)
                {
                    // Find the end of the timestamp line
                    int endIdx = current.IndexOf('\n', markerIdx);
                    if (endIdx >= 0)
                    {
                        // Remove from start of line to end of line (including newline)
                        int lineStart = (markerIdx > 0) ? current.LastIndexOf('\n', markerIdx) : 0;
                        if (lineStart < 0) lineStart = 0;
                        current = current.Substring(0, lineStart) + current.Substring(endIdx + 1);
                    }
                    else
                    {
                        // Timestamp is at the end — remove from start of line to end of string
                        int lineStart = (markerIdx > 0) ? current.LastIndexOf('\n', markerIdx) : 0;
                        if (lineStart < 0) lineStart = 0;
                        current = current.Substring(0, lineStart);
                    }
                    current = current.Trim('\n');
                }

                bool hasCustom = EncyclopediaEditBehavior.Instance.HasCustomDescription(objectId);
                if (!hasCustom)
                {
                    prop.SetValue(viewModel, current);
                    return;
                }

                bool showTimestamp = true;
                try
                {
                    var s = MCMSettings.Instance;
                    if (s != null) showTimestamp = s.ShowEditTimestamp;
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: settings access failed: " + ex.ToString()); }

                string timestamp = EncyclopediaEditBehavior.Instance.GetEditTimestamp(objectId);
                if (showTimestamp && !string.IsNullOrEmpty(timestamp))
                {
                    string line = Localization.L("edited_timestamp", timestamp);
                    // Prepend at the top so it appears first
                    prop.SetValue(viewModel, line + "\n" + current);
                }
                else
                {
                    prop.SetValue(viewModel, current);
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: operation failed: " + ex.ToString()); }
        }

        /// <summary>
        /// Applies a custom banner code (if stored) to the game object on page load.
        /// Guarded against recursion: Refresh() callback triggers the Harmony postfix
        /// <summary>
        /// Tries to set the display name on a page VM by probing multiple property names.
        /// Returns true if the name was successfully set. On first call for a given VM type,
        /// dumps all string properties for diagnostic purposes.
        /// </summary>
        private static HashSet<string> _dumpedVmTypes = new HashSet<string>();

        public static bool TrySetVMName(object vm, string name)
        {
            if (vm == null) return false;
            var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public;
            var vmType = vm.GetType();
            bool set = false;

            // Set ALL matching name properties — different VMs use different property names.
            // Settlement uses SettlementName for the big title, NameText for breadcrumb.
            // Kingdom/Clan use NameText for the title.
            foreach (var propName in new[] { "NameText", "SettlementName", "ClanName", "FactionName",
                                             "KingdomName", "Name", "TitleText", "PageHeaderText" })
            {
                var prop = vmType.GetProperty(propName, flags);
                if (prop != null && prop.CanWrite && prop.PropertyType == typeof(string))
                {
                    prop.SetValue(vm, name);
                    MCMSettings.DebugLog("Set VM." + propName + " = " + name);
                    set = true;
                    // Don't break — set ALL matching properties
                }
            }

            return set;
        }

        /// again, which would re-apply the banner in an infinite loop.
        /// </summary>
        internal static bool _isApplyingBanner = false;

        public static void ApplyCustomBanner(string objectId, string pageType)
        {
            if (_isApplyingBanner) return;
            if (EncyclopediaEditBehavior.Instance == null) return;

            try
            {
                var settings = MCMSettings.Instance;
                if (settings != null && !settings.EnableBannerEditing) return;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: settings access failed: " + ex.ToString()); }

            string bannerCode = EncyclopediaEditBehavior.Instance.GetCustomBannerCode(objectId);

            // For settlements: if no banner code stored for the settlement itself,
            // check the owner clan and its heroes. Banner edits are stored by hero/clan
            // StringId (e.g. "lord_7_1"), not by settlement StringId (e.g. "town_N3").
            if (string.IsNullOrEmpty(bannerCode) && pageType == "Settlement")
            {
                try
                {
                    var settlement = Settlement.Find(objectId);
                    if (settlement?.OwnerClan != null)
                    {
                        // Check clan itself
                        bannerCode = EncyclopediaEditBehavior.Instance.GetCustomBannerCode(settlement.OwnerClan.StringId);

                        // Check clan leader and heroes
                        if (string.IsNullOrEmpty(bannerCode))
                        {
                            foreach (var hero in settlement.OwnerClan.Heroes)
                            {
                                if (hero == null) continue;
                                bannerCode = EncyclopediaEditBehavior.Instance.GetCustomBannerCode(hero.StringId);
                                if (!string.IsNullOrEmpty(bannerCode))
                                {
                                    MCMSettings.DebugLog("Settlement " + objectId + ": found banner code via hero " + hero.StringId);
                                    break;
                                }
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    MCMSettings.DebugLog("Settlement banner lookup error: " + ex.ToString());
                }
            }

            if (string.IsNullOrEmpty(bannerCode)) return;

            _isApplyingBanner = true;
            try
            {
                EncyclopediaBannerEditPopup.ApplyBannerCode(objectId, pageType, bannerCode);
            }
            finally
            {
                _isApplyingBanner = false;
            }
        }
    }

    // ============================================
    //  Hero Encyclopedia Page
    // ============================================
    [HarmonyPatch(typeof(EncyclopediaHeroPageVM), "Refresh")]
    public static class HeroPageRefreshPatch
    {
        /// <summary>
        /// Updates the last breadcrumb item to show the custom hero name.
        /// The breadcrumb lives on the encyclopedia navigator/screen VM (a GauntletLayer DataSource),
        /// not on the hero page VM itself.
        /// </summary>
        static bool _breadcrumbSearchLogged = false;

        // Deferred retry: when Refresh() fires on a non-map screen (e.g. Clan),
        // we schedule retries to check if the game transitions to a MapScreen
        // (opening the encyclopedia).  If so, we re-run the Postfix.
        static EncyclopediaHeroPageVM _deferredInstance;
        static int _deferredRetryCount;
        static System.Threading.Timer _deferredTimer;
        const int DeferredMaxRetries = 10;
        const int DeferredRetryMs = 200;
        static bool _deferredPending;

        private static void ScheduleDeferredRetry()
        {
            var t = _deferredTimer;
            _deferredTimer = null;
            if (t != null) try { t.Dispose(); } catch (Exception ex) { MCMSettings.DebugLog("Patches: Dispose failed: " + ex.ToString()); }
            _deferredTimer = new System.Threading.Timer(_ =>
            {
                _deferredPending = true;
            }, null, DeferredRetryMs, System.Threading.Timeout.Infinite);
        }

        /// <summary>
        /// Called from the key poller or main thread tick to check deferred retries.
        /// </summary>
        internal static void TickDeferredRetry()
        {
            if (!_deferredPending) return;
            _deferredPending = false;
            var inst = _deferredInstance;
            if (inst == null) return;

            _deferredRetryCount++;
            var topScreen = ScreenManager.TopScreen;
            if (topScreen == null)
            {
                if (_deferredRetryCount < DeferredMaxRetries) ScheduleDeferredRetry();
                return;
            }

            string screenName = topScreen.GetType().Name;
            bool isMapScreen = screenName.Contains("Map") || screenName.Contains("map");
            // The encyclopedia may open as layers on the SAME screen (e.g. Clan screen)
            // without switching to MapScreen.  Check both conditions:
            bool hasMultipleLayers = topScreen.Layers.Count > 1;

            if (isMapScreen || hasMultipleLayers)
            {
                MCMSettings.DebugLog("HeroPageRefreshPatch: deferred retry #" + _deferredRetryCount
                    + " — screen=" + screenName + " layers=" + topScreen.Layers.Count
                    + ", running Postfix now");
                _deferredInstance = null;
                Postfix(inst);
            }
            else if (_deferredRetryCount < DeferredMaxRetries)
            {
                ScheduleDeferredRetry();
            }
            else
            {
                MCMSettings.DebugLog("HeroPageRefreshPatch: deferred retry exhausted ("
                    + DeferredMaxRetries + "), screen=" + screenName
                    + " layers=" + topScreen.Layers.Count);
                _deferredInstance = null;
            }
        }

        /// <summary>
        /// Tries to extract the DataSource (ViewModel) from a GauntletLayer using multiple reflection paths.
        /// Different game modes (MapScreen vs NavalMapScreen) may store the VM in different locations.
        /// </summary>
        static object TryGetLayerDataSource(object layer, System.Reflection.BindingFlags flags)
        {
            object dataSource = null;

            // 1. Try public property DataSource
            var dsProp = layer.GetType().GetProperty("DataSource", flags);
            if (dsProp != null)
                dataSource = dsProp.GetValue(layer);

            // 2. Try private field _dataSource
            if (dataSource == null)
            {
                var dsField = layer.GetType().GetField("_dataSource", flags);
                if (dsField != null)
                    dataSource = dsField.GetValue(layer);
            }

            // 3. Try finding the movie object (could be _movie or _gauntletMovie)
            object movie = null;
            foreach (var movieFieldName in new[] { "_movie", "_gauntletMovie" })
            {
                var movieField = layer.GetType().GetField(movieFieldName, flags);
                if (movieField != null)
                {
                    movie = movieField.GetValue(layer);
                    if (movie != null) break;
                }
            }

            if (movie != null && dataSource == null)
            {
                // 3a. Try movie.RootView.Target
                var rootProp = movie.GetType().GetProperty("RootView", flags);
                if (rootProp != null)
                {
                    var rootView = rootProp.GetValue(movie);
                    if (rootView != null)
                    {
                        var targetProp = rootView.GetType().GetProperty("Target", flags);
                        if (targetProp != null)
                            dataSource = targetProp.GetValue(rootView);
                    }
                }

                // 3b. Try movie.DataSource directly
                if (dataSource == null)
                {
                    var movieDsProp = movie.GetType().GetProperty("DataSource", flags);
                    if (movieDsProp != null)
                        dataSource = movieDsProp.GetValue(movie);
                }

                // 3c. Try movie.RootNode / _movieRootNode path
                if (dataSource == null)
                {
                    foreach (var nodeName in new[] { "_movieRootNode", "RootNode" })
                    {
                        var nodeField = movie.GetType().GetField(nodeName, flags);
                        object rootNode = null;
                        if (nodeField != null)
                            rootNode = nodeField.GetValue(movie);
                        if (rootNode == null)
                        {
                            var nodeProp = movie.GetType().GetProperty(nodeName, flags);
                            if (nodeProp != null)
                                rootNode = nodeProp.GetValue(movie);
                        }
                        if (rootNode != null)
                        {
                            var dcProp = rootNode.GetType().GetProperty("DataContext", flags);
                            if (dcProp != null)
                                dataSource = dcProp.GetValue(rootNode);
                            if (dataSource != null) break;
                        }
                    }
                }
            }

            // 4. Brute-force: scan all fields for ViewModel-like objects with list properties
            if (dataSource == null)
            {
                foreach (var field in layer.GetType().GetFields(flags))
                {
                    if (field.FieldType.Name.Contains("ViewModel") || field.FieldType.Name.Contains("VM"))
                    {
                        dataSource = field.GetValue(layer);
                        if (dataSource != null) break;
                    }
                }
            }

            return dataSource;
        }

        /// <summary>
        /// Recursively searches an object's fields for breadcrumb-like list properties.
        /// Follows fields whose type or name looks encyclopedia/navigator-related, up to 3 levels deep.
        /// Also iterates collection fields to find objects stored in lists (e.g., _mapViews).
        /// </summary>
        static bool TryUpdateBreadcrumbFromObject(object obj, string customName, string originalName, System.Reflection.BindingFlags flags, int depth, object skipVm)
        {
            if (obj == null || depth > 3) return false;
            var objType = obj.GetType();

            // Skip the hero page VM itself (already handled separately)
            if (!ReferenceEquals(obj, skipVm))
            {
                if (TryUpdateBreadcrumbOnVM(obj, objType, customName, originalName, flags))
                    return true;
            }

            // Walk the ENTIRE type hierarchy to find fields — GetFields(NonPublic) only returns
            // private fields declared on the exact type, NOT inherited private fields from base classes.
            // The encyclopedia manager is likely a private field on MapScreen (base of NavalMapScreen).
            var searchType = objType;
            while (searchType != null && searchType != typeof(object))
            {
                foreach (var field in searchType.GetFields(flags | System.Reflection.BindingFlags.DeclaredOnly))
                {
                    if (field.FieldType.IsPrimitive || field.FieldType == typeof(string) || field.FieldType.IsEnum)
                        continue;

                    var fieldTypeName = field.FieldType.Name;
                    var fieldFullName = field.FieldType.FullName ?? fieldTypeName;
                    bool isPromising = fieldTypeName.Contains("Encyclopedia") || fieldTypeName.Contains("Navigator") ||
                        fieldTypeName.Contains("ViewModel") || field.Name.Contains("Encyclopedia") ||
                        field.Name.Contains("encyclopedia") || field.Name.Contains("Navigator") ||
                        field.Name.Contains("navigator");

                    object val = null;
                    if (isPromising)
                    {
                        try { val = field.GetValue(obj); } catch { continue; }
                        if (val != null && !ReferenceEquals(val, obj))
                        {
                            if (TryUpdateBreadcrumbFromObject(val, customName, originalName, flags, depth + 1, skipVm))
                                return true;
                        }
                    }

                    // Also check list/collection fields — the breadcrumb VM may be on an object stored
                    // in a collection (e.g., MapScreen._mapViews contains GauntletEncyclopediaScreenManager)
                    if (typeof(System.Collections.IList).IsAssignableFrom(field.FieldType))
                    {
                        if (val == null)
                        {
                            try { val = field.GetValue(obj); } catch { continue; }
                        }
                        if (val is System.Collections.IList list)
                        {
                            for (int i = 0; i < list.Count; i++)
                            {
                                var element = list[i];
                                if (element == null) continue;
                                var elementTypeName = element.GetType().Name;
                                if (elementTypeName.Contains("Encyclopedia") || elementTypeName.Contains("Navigator") ||
                                    elementTypeName.Contains("ViewModel"))
                                {
                                    if (TryUpdateBreadcrumbFromObject(element, customName, originalName, flags, depth + 1, skipVm))
                                        return true;
                                }
                            }
                        }
                    }
                }
                searchType = searchType.BaseType;
            }

            return false;
        }

        /// <summary>
        /// Deep-searches ALL fields on an object (no keyword filter) for breadcrumb lists.
        /// Used after finding the EncyclopediaScreenManager to explore its internal structure.
        /// </summary>
        static bool DeepSearchForBreadcrumb(object obj, string customName, string originalName, System.Reflection.BindingFlags flags, int depth, object skipVm, System.Collections.Generic.List<object> visited)
        {
            if (obj == null || depth > 4) return false;

            // Cycle detection using reference equality
            if (visited == null) visited = new System.Collections.Generic.List<object>();
            for (int i = 0; i < visited.Count; i++)
                if (ReferenceEquals(visited[i], obj)) return false;
            visited.Add(obj);

            // Try this object for breadcrumb lists
            if (!ReferenceEquals(obj, skipVm))
            {
                try
                {
                    if (TryUpdateBreadcrumbOnVM(obj, obj.GetType(), customName, originalName, flags))
                        return true;
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: breadcrumb update failed: " + ex.ToString()); }
            }

            // Search ALL reference-type fields (walking the type hierarchy)
            var searchType = obj.GetType();
            while (searchType != null && searchType != typeof(object))
            {
                foreach (var field in searchType.GetFields(flags | System.Reflection.BindingFlags.DeclaredOnly))
                {
                    if (field.FieldType.IsPrimitive || field.FieldType == typeof(string) || field.FieldType.IsEnum)
                        continue;
                    if (field.FieldType.IsValueType) continue; // skip structs

                    object val = null;
                    try { val = field.GetValue(obj); } catch { continue; }
                    if (val == null || ReferenceEquals(val, obj) || ReferenceEquals(val, skipVm)) continue;

                    try
                    {
                        if (DeepSearchForBreadcrumb(val, customName, originalName, flags, depth + 1, skipVm, visited))
                            return true;
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: deep search failed: " + ex.ToString()); }
                }
                searchType = searchType.BaseType;
            }

            return false;
        }

        /// <summary>
        /// Logs all fields on the EncyclopediaScreenManager and its type hierarchy for diagnostics.
        /// </summary>
        static void LogEncyclopediaManagerFields(object encManager, System.Reflection.BindingFlags flags)
        {
            var encType = encManager.GetType();
            while (encType != null && encType != typeof(object))
            {
                MCMSettings.DebugLog("  === EncyclopediaManager: " + encType.FullName + " fields ===");
                foreach (var field in encType.GetFields(flags | System.Reflection.BindingFlags.DeclaredOnly))
                {
                    object val = null;
                    try { val = field.GetValue(encManager); } catch (Exception ex) { MCMSettings.DebugLog("Patches: reflection GetValue failed: " + ex.ToString()); }
                    string valStr = val != null ? val.GetType().FullName : "(null)";
                    MCMSettings.DebugLog("    Field: " + field.Name + " (" + field.FieldType.Name + ") = " + valStr);
                }
                encType = encType.BaseType;
            }
        }

        static void UpdateBreadcrumb(EncyclopediaHeroPageVM vm, string customName, string originalName)
        {
            var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic;
            var topScreen = ScreenManager.TopScreen;
            if (topScreen == null) return;

            // Strategy 0 (targeted): Get _navigatorDatasource directly from EncyclopediaScreenManager
            // and update the breadcrumb list on it.
            try
            {
                object encManager = null;
                var screenType = topScreen.GetType();
                while (screenType != null && screenType != typeof(object))
                {
                    foreach (var field in screenType.GetFields(flags | System.Reflection.BindingFlags.DeclaredOnly))
                    {
                        if (field.Name.Contains("EncyclopediaScreenManager"))
                        {
                            try { encManager = field.GetValue(topScreen); } catch (Exception ex) { MCMSettings.DebugLog("Patches: reflection GetValue failed: " + ex.ToString()); }
                            if (encManager != null) break;
                        }
                    }
                    if (encManager != null) break;
                    screenType = screenType.BaseType;
                }

                if (encManager != null)
                {
                    MCMSettings.DebugLog("Found EncyclopediaScreenManager: " + encManager.GetType().FullName);

                    // Get _navigatorDatasource directly
                    object navigatorVM = null;
                    var encType = encManager.GetType();
                    while (encType != null && encType != typeof(object))
                    {
                        var navField = encType.GetField("_navigatorDatasource", flags);
                        if (navField != null)
                        {
                            try { navigatorVM = navField.GetValue(encManager); } catch (Exception ex) { MCMSettings.DebugLog("Patches: reflection GetValue failed: " + ex.ToString()); }
                            break;
                        }
                        encType = encType.BaseType;
                    }

                    if (navigatorVM != null)
                    {
                        MCMSettings.DebugLog("Found _navigatorDatasource: " + navigatorVM.GetType().FullName);

                        // Diagnostic: dump ALL properties and fields on the navigator VM
                        if (!_breadcrumbSearchLogged)
                        {
                            var navType = navigatorVM.GetType();
                            while (navType != null && navType != typeof(object))
                            {
                                MCMSettings.DebugLog("  === NavigatorVM: " + navType.FullName + " properties ===");
                                foreach (var prop in navType.GetProperties(flags | System.Reflection.BindingFlags.DeclaredOnly))
                                {
                                    object val = null;
                                    try { val = prop.GetValue(navigatorVM); } catch (Exception ex) { MCMSettings.DebugLog("Patches: reflection GetValue failed: " + ex.ToString()); }
                                    string valStr = val != null ? val.GetType().Name : "(null)";
                                    MCMSettings.DebugLog("    Prop: " + prop.Name + " (" + prop.PropertyType.Name + ") = " + valStr);
                                    // If it's a list, show items
                                    if (val is System.Collections.IList plist && plist.Count > 0 && plist.Count <= 20)
                                    {
                                        for (int i = 0; i < plist.Count; i++)
                                        {
                                            var el = plist[i];
                                            string elStr = el != null ? (el.GetType().Name + ": " + el.ToString()) : "(null)";
                                            MCMSettings.DebugLog("      [" + i + "] = " + elStr);
                                        }
                                    }
                                }
                                MCMSettings.DebugLog("  === NavigatorVM: " + navType.FullName + " fields ===");
                                foreach (var fld in navType.GetFields(flags | System.Reflection.BindingFlags.DeclaredOnly))
                                {
                                    object val = null;
                                    try { val = fld.GetValue(navigatorVM); } catch (Exception ex) { MCMSettings.DebugLog("Patches: reflection GetValue failed: " + ex.ToString()); }
                                    string valStr = val != null ? val.GetType().Name : "(null)";
                                    MCMSettings.DebugLog("    Field: " + fld.Name + " (" + fld.FieldType.Name + ") = " + valStr);
                                    // If it's a list, show items
                                    if (val is System.Collections.IList flist && flist.Count > 0 && flist.Count <= 20)
                                    {
                                        for (int i = 0; i < flist.Count; i++)
                                        {
                                            var el = flist[i];
                                            string elStr = el != null ? (el.GetType().Name + ": " + el.ToString()) : "(null)";
                                            MCMSettings.DebugLog("      [" + i + "] = " + elStr);
                                        }
                                    }
                                }
                                navType = navType.BaseType;
                            }
                        }

                        // The breadcrumb is displayed via string properties on the navigator VM,
                        // NOT as a list of breadcrumb item VMs. Update PageName and NavBarString directly.
                        bool updated = false;

                        // Update PageName property (the page title in the breadcrumb bar)
                        updated |= TryReplaceStringProperty(navigatorVM, "PageName", originalName, customName, flags);

                        // Update NavBarString property (the full navigation bar text)
                        updated |= TryReplaceStringProperty(navigatorVM, "NavBarString", originalName, customName, flags);

                        if (updated)
                            return;
                    }
                    else
                    {
                        MCMSettings.DebugLog("_navigatorDatasource not found or null on EncyclopediaScreenManager");
                        if (!_breadcrumbSearchLogged)
                            LogEncyclopediaManagerFields(encManager, flags);
                    }
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Strategy 0 exception: " + ex.GetType().Name + ": " + ex.ToString());
            }

            // Strategy 1: Search the TopScreen object graph recursively (keyword-filtered).
            try
            {
                if (TryUpdateBreadcrumbFromObject(topScreen, customName, originalName, flags, 0, vm))
                    return;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: breadcrumb update failed: " + ex.ToString()); }

            // Strategy 2 (fallback): Search all layers for VMs that have breadcrumb-like list properties
            foreach (var layer in topScreen.Layers)
            {
                if (layer == null) continue;

                object dataSource = null;
                try
                {
                    dataSource = TryGetLayerDataSource(layer, flags);
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: breadcrumb update failed: " + ex.ToString()); }

                if (dataSource == null) continue;

                // Skip if this is the hero page VM itself (we already checked that)
                if (dataSource == vm) continue;

                // Search this VM for list properties that could be the breadcrumb
                var dsType = dataSource.GetType();
                if (TryUpdateBreadcrumbOnVM(dataSource, dsType, customName, originalName, flags))
                    return;
            }

            // Log diagnostics once if not found — dump fields to discover the correct path
            if (!_breadcrumbSearchLogged)
            {
                _breadcrumbSearchLogged = true;
                MCMSettings.DebugLog("Breadcrumb not found. Screen type: " + topScreen.GetType().Name);

                // Dump TopScreen fields across the ENTIRE type hierarchy (base classes too).
                // GetFields(NonPublic) only returns private fields from the declaring type,
                // so we must walk the chain to see private fields on MapScreen, ScreenBase, etc.
                var diagType = topScreen.GetType();
                while (diagType != null && diagType != typeof(object))
                {
                    MCMSettings.DebugLog("  === " + diagType.FullName + " fields ===");
                    foreach (var field in diagType.GetFields(flags | System.Reflection.BindingFlags.DeclaredOnly))
                    {
                        object val = null;
                        try { val = field.GetValue(topScreen); } catch (Exception ex) { MCMSettings.DebugLog("Patches: reflection GetValue failed: " + ex.ToString()); }
                        string valStr = val != null ? val.GetType().Name : "(null)";
                        MCMSettings.DebugLog("    Field: " + field.Name + " (" + field.FieldType.Name + ") = " + valStr);

                        // If it's a list, also log its element types
                        if (val is System.Collections.IList screenList && screenList.Count > 0)
                        {
                            for (int i = 0; i < screenList.Count && i < 20; i++)
                            {
                                var el = screenList[i];
                                if (el != null)
                                    MCMSettings.DebugLog("      [" + i + "] = " + el.GetType().FullName);
                            }
                        }
                    }
                    diagType = diagType.BaseType;
                }

                MCMSettings.DebugLog("  === Layer diagnostics ===");
                foreach (var layer in topScreen.Layers)
                {
                    if (layer == null) continue;
                    string layerTypeName = layer.GetType().Name;

                    // Dump fields on GauntletLayers to discover the correct VM path
                    if (layerTypeName.Contains("Gauntlet"))
                    {
                        MCMSettings.DebugLog("  === " + layerTypeName + " fields ===");
                        foreach (var field in layer.GetType().GetFields(flags))
                        {
                            object val = null;
                            try { val = field.GetValue(layer); } catch (Exception ex) { MCMSettings.DebugLog("Patches: reflection GetValue failed: " + ex.ToString()); }
                            string valStr = val != null ? val.GetType().Name : "(null)";
                            MCMSettings.DebugLog("    Field: " + field.Name + " (" + field.FieldType.Name + ") = " + valStr);
                        }
                        MCMSettings.DebugLog("  === " + layerTypeName + " properties ===");
                        foreach (var prop in layer.GetType().GetProperties(flags))
                        {
                            object val = null;
                            try { val = prop.GetValue(layer); } catch (Exception ex) { MCMSettings.DebugLog("Patches: reflection GetValue failed: " + ex.ToString()); }
                            string valStr = val != null ? val.GetType().Name : "(null)";
                            MCMSettings.DebugLog("    Prop: " + prop.Name + " (" + prop.PropertyType.Name + ") = " + valStr);
                        }
                    }
                    else
                    {
                        MCMSettings.DebugLog("  Layer " + layerTypeName + " (skipped - not GauntletLayer)");
                    }
                }
            }
        }

        /// <summary>
        /// Directly sets the breadcrumb name on the navigator VM by reading the History list
        /// and rebuilding PageName. Used for the reset case where we don't know the stale name.
        /// </summary>
        internal static void SetBreadcrumbName(string correctName)
        {
            var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic;
            var topScreen = ScreenManager.TopScreen;
            if (topScreen == null) return;

            try
            {
                // Find EncyclopediaScreenManager
                object encManager = null;
                var screenType = topScreen.GetType();
                while (screenType != null && screenType != typeof(object))
                {
                    var field = screenType.GetField("<EncyclopediaScreenManager>k__BackingField", flags);
                    if (field != null)
                    {
                        try { encManager = field.GetValue(topScreen); } catch (Exception ex) { MCMSettings.DebugLog("Patches: reflection GetValue failed: " + ex.ToString()); }
                        break;
                    }
                    screenType = screenType.BaseType;
                }
                if (encManager == null) return;

                // Get _navigatorDatasource
                object navigatorVM = null;
                var encType = encManager.GetType();
                while (encType != null && encType != typeof(object))
                {
                    var navField = encType.GetField("_navigatorDatasource", flags);
                    if (navField != null)
                    {
                        try { navigatorVM = navField.GetValue(encManager); } catch (Exception ex) { MCMSettings.DebugLog("Patches: reflection GetValue failed: " + ex.ToString()); }
                        break;
                    }
                    encType = encType.BaseType;
                }
                if (navigatorVM == null) return;

                // Read PageName and replace the last breadcrumb segment if it doesn't match
                var pageNameProp = navigatorVM.GetType().GetProperty("PageName", flags);
                if (pageNameProp != null && pageNameProp.CanRead && pageNameProp.CanWrite)
                {
                    string pageName = pageNameProp.GetValue(navigatorVM) as string;
                    if (!string.IsNullOrEmpty(pageName) && pageName != correctName)
                    {
                        pageNameProp.SetValue(navigatorVM, correctName);
                        MCMSettings.DebugLog("SetBreadcrumbName: PageName \"" + pageName + "\" -> \"" + correctName + "\"");
                    }
                }

                // Read NavBarString and replace the last segment
                var navBarProp = navigatorVM.GetType().GetProperty("NavBarString", flags);
                if (navBarProp != null && navBarProp.CanRead && navBarProp.CanWrite)
                {
                    string navBar = navBarProp.GetValue(navigatorVM) as string;
                    if (!string.IsNullOrEmpty(navBar) && !navBar.EndsWith(correctName))
                    {
                        // Find the last separator and replace everything after it
                        // Common separators: " - ", " > ", " \ ", " / "
                        string[] separators = new[] { " - ", " > ", " \\ ", " / " };
                        foreach (var sep in separators)
                        {
                            int lastSepIdx = navBar.LastIndexOf(sep);
                            if (lastSepIdx >= 0)
                            {
                                string newNavBar = navBar.Substring(0, lastSepIdx + sep.Length) + correctName;
                                navBarProp.SetValue(navigatorVM, newNavBar);
                                MCMSettings.DebugLog("SetBreadcrumbName: NavBarString \"" + navBar + "\" -> \"" + newNavBar + "\"");
                                break;
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("SetBreadcrumbName error: " + ex.ToString());
            }
        }

        /// <summary>
        /// Replaces the original hero name in a string property with the custom name.
        /// Returns true if the property was found and updated.
        /// </summary>
        static bool TryReplaceStringProperty(object obj, string propertyName, string originalName, string customName, System.Reflection.BindingFlags flags)
        {
            try
            {
                var prop = obj.GetType().GetProperty(propertyName, flags);
                if (prop == null || !prop.CanRead || !prop.CanWrite) return false;

                if (prop.PropertyType == typeof(string))
                {
                    string val = prop.GetValue(obj) as string;
                    MCMSettings.DebugLog("  Breadcrumb " + propertyName + " = \"" + (val ?? "(null)") + "\"");
                    if (string.IsNullOrEmpty(val)) return false;

                    // Replace the original name with custom name in the string
                    if (!string.IsNullOrEmpty(originalName) && val.Contains(originalName))
                    {
                        string newVal = val.Replace(originalName, customName);
                        prop.SetValue(obj, newVal);
                        MCMSettings.DebugLog("  Updated " + propertyName + ": \"" + val + "\" -> \"" + newVal + "\"");
                        return true;
                    }
                    return false;
                }
                return false;
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("  TryReplaceStringProperty(" + propertyName + ") error: " + ex.ToString());
                return false;
            }
        }

        /// <summary>
        /// Like TryUpdateBreadcrumbOnVM but searches fields instead of properties for the breadcrumb list.
        /// This handles VMs where the breadcrumb list is stored as a field rather than a property.
        /// </summary>
        static bool TryUpdateBreadcrumbViaFields(object dataSource, string customName, string originalName, System.Reflection.BindingFlags flags)
        {
            bool logDiag = !_breadcrumbSearchLogged;
            var dsType = dataSource.GetType();
            string dsTypeName = dsType.Name;

            while (dsType != null && dsType != typeof(object))
            {
                foreach (var field in dsType.GetFields(flags | System.Reflection.BindingFlags.DeclaredOnly))
                {
                    var fieldTypeName = field.FieldType.Name;
                    if (!fieldTypeName.Contains("MBBindingList") && !fieldTypeName.Contains("List") && !fieldTypeName.Contains("Collection"))
                        continue;

                    System.Collections.IList list = null;
                    try { list = field.GetValue(dataSource) as System.Collections.IList; } catch { continue; }
                    if (list == null || list.Count < 2) continue;
                    if (list.Count > 6) continue;

                    var lastItem = list[list.Count - 1];
                    if (lastItem == null) continue;

                    var itemType = lastItem.GetType();
                    if (logDiag)
                        MCMSettings.DebugLog("  [BreadcrumbFieldCheck] " + dsTypeName + "." + field.Name + " count=" + list.Count + " lastItemType=" + itemType.Name);

                    // Try common name properties on the last breadcrumb item
                    foreach (var nameProp in new[] { "Name", "Text", "Title", "NameText", "PageName" })
                    {
                        var np = itemType.GetProperty(nameProp, System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public);
                        if (np == null || !np.CanWrite) continue;

                        bool isString = np.PropertyType == typeof(string);
                        bool isTextObject = !isString && np.PropertyType.Name.Contains("TextObject");
                        if (!isString && !isTextObject)
                        {
                            if (logDiag)
                                MCMSettings.DebugLog("    -> " + nameProp + " type=" + np.PropertyType.Name + " (skipped)");
                            continue;
                        }

                        string oldVal = "";
                        try { oldVal = np.GetValue(lastItem)?.ToString() ?? ""; } catch { continue; }
                        if (logDiag)
                            MCMSettings.DebugLog("    -> " + nameProp + " type=" + np.PropertyType.Name + " val=\"" + oldVal + "\"");
                        if (string.IsNullOrEmpty(oldVal)) continue;
                        if (!string.IsNullOrEmpty(originalName) && oldVal != originalName && oldVal != customName)
                            continue;

                        if (isString)
                        {
                            np.SetValue(lastItem, customName);
                        }
                        else
                        {
                            try
                            {
                                var newTextObj = Activator.CreateInstance(np.PropertyType, new object[] { customName });
                                np.SetValue(lastItem, newTextObj);
                            }
                            catch
                            {
                                try
                                {
                                    var existingTextObj = np.GetValue(lastItem);
                                    if (existingTextObj != null)
                                    {
                                        var valueProp = existingTextObj.GetType().GetProperty("Value", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public);
                                        if (valueProp != null && valueProp.CanWrite && valueProp.PropertyType == typeof(string))
                                            valueProp.SetValue(existingTextObj, customName);
                                    }
                                }
                                catch { continue; }
                            }
                        }
                        MCMSettings.DebugLog("Updated breadcrumb via field: " + field.Name + "[" + (list.Count - 1) + "]." + nameProp + ": " + oldVal + " -> " + customName);
                        return true;
                    }
                }
                dsType = dsType.BaseType;
            }
            return false;
        }

        static bool TryUpdateBreadcrumbOnVM(object dataSource, Type dsType, string customName, string originalName, System.Reflection.BindingFlags flags)
        {
            bool logDiag = !_breadcrumbSearchLogged;
            string dsTypeName = dsType?.Name ?? "null";

            // Search all properties for list-type properties that might be the breadcrumb
            while (dsType != null && dsType != typeof(object))
            {
                foreach (var prop in dsType.GetProperties(flags))
                {
                    var propTypeName = prop.PropertyType.Name;
                    if (!propTypeName.Contains("MBBindingList") && !propTypeName.Contains("List"))
                        continue;

                    System.Collections.IList list = null;
                    try { list = prop.GetValue(dataSource) as System.Collections.IList; } catch { continue; }
                    if (list == null || list.Count < 2) continue; // breadcrumb has at least 2 items (Home, Heroes, Name)

                    // Skip large lists — breadcrumbs are small (typically 3-5 items).
                    // Category lists like "Lists" can have 7+ items.
                    if (list.Count > 6) continue;

                    var lastItem = list[list.Count - 1];
                    if (lastItem == null) continue;

                    var itemType = lastItem.GetType();
                    if (logDiag)
                        MCMSettings.DebugLog("  [BreadcrumbCheck] " + dsTypeName + "." + prop.Name + " count=" + list.Count + " lastItemType=" + itemType.Name);

                    // Try common name properties on the last breadcrumb item
                    foreach (var nameProp in new[] { "Name", "Text", "Title", "NameText", "PageName" })
                    {
                        var np = itemType.GetProperty(nameProp, System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public);
                        if (np == null || !np.CanWrite) continue;

                        bool isString = np.PropertyType == typeof(string);
                        bool isTextObject = !isString && np.PropertyType.Name.Contains("TextObject");

                        if (!isString && !isTextObject) {
                            if (logDiag)
                                MCMSettings.DebugLog("    -> " + nameProp + " type=" + np.PropertyType.Name + " (skipped: not string/TextObject)");
                            continue;
                        }

                        string oldVal = "";
                        try { oldVal = np.GetValue(lastItem)?.ToString() ?? ""; } catch { continue; }
                        if (logDiag)
                            MCMSettings.DebugLog("    -> " + nameProp + " type=" + np.PropertyType.Name + " val=\"" + oldVal + "\"");
                        // Sanity check: the old value should look like a hero name (non-empty, not a category)
                        if (string.IsNullOrEmpty(oldVal)) continue;

                        // Validate: the current value should match the hero's original or custom name.
                        // This prevents accidentally modifying unrelated lists.
                        if (!string.IsNullOrEmpty(originalName) && oldVal != originalName && oldVal != customName)
                            continue;

                        if (isString)
                        {
                            np.SetValue(lastItem, customName);
                        }
                        else
                        {
                            // TextObject: create a new instance with the custom name string
                            try
                            {
                                var newTextObj = Activator.CreateInstance(np.PropertyType, new object[] { customName });
                                np.SetValue(lastItem, newTextObj);
                            }
                            catch (Exception texEx)
                            {
                                MCMSettings.DebugLog("    TextObject set failed: " + texEx.Message);
                                // Fallback: try setting the string directly via ToString-based approach
                                // Look for a StringValue or Value property on the existing TextObject
                                try
                                {
                                    var existingTextObj = np.GetValue(lastItem);
                                    if (existingTextObj != null)
                                    {
                                        var valueProp = existingTextObj.GetType().GetProperty("Value", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public);
                                        if (valueProp != null && valueProp.CanWrite && valueProp.PropertyType == typeof(string))
                                        {
                                            valueProp.SetValue(existingTextObj, customName);
                                        }
                                    }
                                }
                                catch { continue; }
                            }
                        }
                        MCMSettings.DebugLog("Updated breadcrumb: " + prop.Name + "[" + (list.Count - 1) + "]." + nameProp + ": " + oldVal + " -> " + customName);
                        return true;
                    }
                }
                dsType = dsType.BaseType;
            }
            return false;
        }

        static void Postfix(EncyclopediaHeroPageVM __instance)
        {
            try
            {
                try
                {
                    var settings = MCMSettings.Instance;
                    if (settings != null && !settings.EnableHeroEditing) return;
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: settings access failed: " + ex.ToString()); }

                var hero = __instance.Obj as Hero;
                if (hero == null) return;

                EncyclopediaPatchHelper.HandlePageRefresh(
                    hero.StringId, __instance.InformationText,
                    () => __instance.Refresh(), text => __instance.InformationText = text, "Hero");

                // Guard: skip widget injection on non-map screens with a single layer.
                // The Clan/Party/Inventory screens reuse EncyclopediaHeroPageVM for their
                // own hero panels.  With only 1 layer the encyclopedia overlay is NOT open.
                // Schedule a deferred retry — the game may switch to the MapScreen shortly
                // after this Refresh() fires (opening the encyclopedia from the Clan screen).
                {
                    var topScreen2 = ScreenManager.TopScreen;
                    if (topScreen2 != null)
                    {
                        string screenName = topScreen2.GetType().Name;
                        bool isMapScreen = screenName.Contains("Map") || screenName.Contains("map");
                        if (!isMapScreen && topScreen2.Layers.Count <= 1)
                        {
                            MCMSettings.DebugLog("HeroPageRefreshPatch: non-map screen (" + screenName
                                + ") with " + topScreen2.Layers.Count + " layer(s) — skipping widget injection, scheduling deferred retry");
                            // Save context for deferred retry
                            _deferredInstance = __instance;
                            _deferredRetryCount = 0;
                            ScheduleDeferredRetry();
                            return;
                        }
                    }
                }

                EncyclopediaPageTracker.CurrentViewModel = __instance;

                // Track name/title for Ctrl+N editing (must be set BEFORE TagWidgetInjector)
                EncyclopediaPageTracker.CurrentHero = hero;
                EncyclopediaPageTracker.CurrentPageType = "Hero";
                EncyclopediaPageTracker.CurrentName = hero.Name?.ToString() ?? "";

                // Show edit timestamp as a right-aligned overlay
                EncyclopediaPatchHelper.InjectTimestampWidget(hero.StringId);

                // Show tags as a styled widget at the bottom of the character portrait panel
                try
                {
                    string heroTags = EncyclopediaEditBehavior.Instance?.GetTagsWithAuto(hero.StringId);
                    TagWidgetInjector.InjectOrUpdate(heroTags);
                }
                catch (Exception ex)
                {
                    MCMSettings.DebugLog("TagWidget hero inject error: " + ex.ToString());
                }

                // Chronicle Notes are NOT shown on hero pages — Timeline covers hero biography.
                // Chronicle is for world history (kingdoms, clans, settlements).

                // Annotate friend/enemy entries with inline relation score and note text
                try { RelationNotesInjector.AnnotateFriendEnemyNames(__instance, hero.StringId); }
                catch (Exception ex) { MCMSettings.DebugLog("RelationNotes annotate error: " + ex.ToString()); }

                // Relation Notes section is injected later (after Lore) to ensure
                // correct order: Info → Lore → Relation Notes → Friends → Enemies.
                // See LoreSectionInjector.InjectLoreSection call below.

                // Show collapsible Timeline section (personal chronicle)
                // 2026-05-28: Timeline owned by EE-ChronicleNoters across ALL entity pages
                // including Hero (per user direction). Disappears when ChronicleNoters disabled.
                if (HeroTimelineSectionInjector.IsEnabled() && PeerRegistry.Has("EE-ChronicleNoters"))
                {
                    try { HeroTimelineSectionInjector.InjectTimelineSection(hero.StringId); }
                    catch (Exception ex) { MCMSettings.DebugLog("HeroTimeline hero inject error: " + ex.ToString()); }
                }

                // Inventory Lore (main module) — gated only by its own MCM toggle inside DoInject.
                try { InventoryLoreSectionInjector.InjectInventorySection(hero.StringId); }
                catch (Exception ex) { MCMSettings.DebugLog("InventoryLore hero inject error: " + ex.ToString()); }

                // Store action so the edit popup can refresh the timestamp immediately after saving
                EncyclopediaPageTracker.CurrentUpdateTimestampAction = () =>
                    EncyclopediaPatchHelper.InjectTimestampWidget(hero.StringId);

                // Apply custom banner if set
                EncyclopediaPatchHelper.ApplyCustomBanner(hero.StringId, "Hero");

                // Store original firstName for reset support.
                // This runs BEFORE we apply custom name below, so hero.FirstName is still the game original.
                // StoreOriginalName is a no-op if already stored, so safe to call every time.
                if (EncyclopediaEditBehavior.Instance != null)
                {
                    try
                    {
                        string origFirst = hero.FirstName?.ToString() ?? "";
                        EncyclopediaEditBehavior.Instance.StoreOriginalName(hero.StringId, origFirst);
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: banner apply failed: " + ex.ToString()); }
                }

                // Get the hero's title/rank (e.g., "Vassal of the Khuzaits")
                // This reads KingdomRankText AFTER game's Refresh(), before we apply custom title.
                string heroTitle = "";
                try
                {
                    var titleProp = __instance.GetType().GetProperty("KingdomRankText",
                        System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public);
                    if (titleProp != null)
                        heroTitle = titleProp.GetValue(__instance)?.ToString() ?? "";
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: title read failed: " + ex.ToString()); }
                EncyclopediaPageTracker.CurrentTitle = heroTitle;

                // Store original title once (before any custom title is applied)
                if (EncyclopediaEditBehavior.Instance != null)
                {
                    try { EncyclopediaEditBehavior.Instance.StoreOriginalTitle(hero.StringId, heroTitle); }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: operation failed: " + ex.ToString()); }
                }

                EncyclopediaPageTracker.CurrentSetNameAction = text =>
                {
                    try
                    {
                        __instance.NameText = text;
                        // Also set on the Hero game object so it shows in lists/breadcrumb
                        EncyclopediaPageTracker.SetHeroName(hero, text);
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: operation failed: " + ex.ToString()); }
                };
                EncyclopediaPageTracker.CurrentSetTitleAction = text =>
                {
                    try
                    {
                        var tp = __instance.GetType().GetProperty("KingdomRankText",
                            System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public);
                        if (tp != null) tp.SetValue(__instance, text);
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: title read failed: " + ex.ToString()); }
                };

                // Apply custom name/title if set, or restore original if previously customized
                try
                {
                    if (EncyclopediaEditBehavior.Instance != null)
                    {
                        string customName = EncyclopediaEditBehavior.Instance.GetCustomName(hero.StringId);
                        if (!string.IsNullOrEmpty(customName))
                        {
                            __instance.NameText = customName;
                            EncyclopediaPageTracker.SetHeroName(hero, customName);
                            MCMSettings.DebugLog("Applied custom name for " + hero.StringId + ": " + customName);

                            // Update breadcrumb — the last breadcrumb item shows the hero name
                            try
                            {
                                string origName = EncyclopediaEditBehavior.Instance.GetOriginalName(hero.StringId) ?? "";
                                UpdateBreadcrumb(__instance, customName, origName);
                            }
                            catch (Exception ex) { MCMSettings.DebugLog("Patches: breadcrumb update failed: " + ex.ToString()); }
                        }
                        else
                        {
                            // No custom name — ensure NameText reflects the hero's current name.
                            // This is needed because the game's Refresh() may not re-set NameText,
                            // so after a custom name is cleared, NameText would show the stale custom value.
                            string heroName = hero.Name?.ToString() ?? "";
                            if (!string.IsNullOrEmpty(heroName))
                            {
                                __instance.NameText = heroName;
                            }

                            // Also update breadcrumb — after a reset, the breadcrumb may still
                            // show the stale custom name. Use direct set approach since we don't
                            // know what the previous custom name was.
                            try
                            {
                                string correctName = heroName;
                                if (!string.IsNullOrEmpty(correctName))
                                    SetBreadcrumbName(correctName);
                            }
                            catch (Exception ex) { MCMSettings.DebugLog("Patches: breadcrumb update failed: " + ex.ToString()); }
                        }

                        string customTitle = EncyclopediaEditBehavior.Instance.GetCustomTitle(hero.StringId);
                        if (!string.IsNullOrEmpty(customTitle))
                        {
                            var tp = __instance.GetType().GetProperty("KingdomRankText",
                                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public);
                            if (tp != null)
                            {
                                tp.SetValue(__instance, customTitle);
                                MCMSettings.DebugLog("Applied custom title for " + hero.StringId + ": " + customTitle);
                            }
                        }
                        else
                        {
                            // No custom title — restore the persistently stored original title
                            // so stale custom titles don't persist after reset.
                            // heroTitle from KingdomRankText may be stale if game's Refresh()
                            // didn't reset it, so prefer the stored original.
                            string origTitle = EncyclopediaEditBehavior.Instance.GetOriginalTitle(hero.StringId)
                                               ?? heroTitle;
                            var tp = __instance.GetType().GetProperty("KingdomRankText",
                                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public);
                            if (tp != null)
                                tp.SetValue(__instance, origTitle);
                        }

                        // NOTE: We intentionally do NOT re-apply custom culture/occupation
                        // to actual hero properties (CharacterObject.Occupation, Hero.Culture, etc.).
                        // Changing these causes GetListItems() to exclude heroes with non-standard
                        // values from the encyclopedia list. Custom values are persisted in the
                        // behavior and displayed via the Stats panel overrides below.

                        // Read custom values from behavior for Stats display override
                        int customOccupation = EncyclopediaEditBehavior.Instance.GetCustomOccupation(hero.StringId);

                        // Override the Culture and Occupation display labels in the Info/Stats panel
                        // The EncyclopediaHeroPageVM has a Stats property (MBBindingList<StringPairItemVM>)
                        // Each item has Definition (label) and Value (display text)
                        try
                        {
                            string customCultureDisplay = EncyclopediaEditBehavior.Instance.GetCustomCultureDisplayName(hero.StringId);
                            // If no display name override but a custom culture IS assigned, get the culture's name
                            if (string.IsNullOrEmpty(customCultureDisplay))
                            {
                                string customCultureId = EncyclopediaEditBehavior.Instance.GetCustomCulture(hero.StringId);
                                if (!string.IsNullOrEmpty(customCultureId))
                                {
                                    try
                                    {
                                        foreach (var c in TaleWorlds.ObjectSystem.MBObjectManager.Instance.GetObjectTypeList<CultureObject>())
                                        {
                                            if (c != null && string.Equals(c.StringId, customCultureId, StringComparison.OrdinalIgnoreCase))
                                            {
                                                customCultureDisplay = c.Name?.ToString() ?? customCultureId;
                                                break;
                                            }
                                        }
                                        if (string.IsNullOrEmpty(customCultureDisplay))
                                            customCultureDisplay = customCultureId; // fallback to raw ID
                                    }
                                    catch (Exception ex) { MCMSettings.DebugLog("Patches: culture name lookup failed: " + ex.ToString()); }
                                }
                            }
                            string occDisplayOverride = (customOccupation >= 0) ? EncyclopediaOccupationEditPopup.GetFriendlyName(customOccupation) : null;

                            if (!string.IsNullOrEmpty(customCultureDisplay) || !string.IsNullOrEmpty(occDisplayOverride))
                            {
                                var infoFlags = System.Reflection.BindingFlags.Instance
                                              | System.Reflection.BindingFlags.Public
                                              | System.Reflection.BindingFlags.NonPublic;
                                // Try to find the Stats/HeroInfo list on the VM
                                System.Collections.IEnumerable statsList = null;
                                foreach (var propName in EncyclopediaPatchHelper.StatsListNamesCommon)
                                {
                                    var sProp = __instance.GetType().GetProperty(propName, infoFlags);
                                    if (sProp != null)
                                    {
                                        statsList = sProp.GetValue(__instance) as System.Collections.IEnumerable;
                                        if (statsList != null)
                                        {
                                            MCMSettings.DebugLog("Found hero info list via '" + propName + "'");
                                            break;
                                        }
                                    }
                                }

                                if (statsList != null)
                                {
                                    bool foundOccEntry = false;
                                    Type statsItemType = null;

                                    foreach (var item in statsList)
                                    {
                                        if (item == null) continue;
                                        var itemType = item.GetType();
                                        if (statsItemType == null) statsItemType = itemType;

                                        // Read the Definition (label) property
                                        string definition = null;
                                        var defProp = itemType.GetProperty("Definition", infoFlags)
                                                   ?? itemType.GetProperty("Type", infoFlags)
                                                   ?? itemType.GetProperty("Name", infoFlags);
                                        if (defProp != null)
                                            definition = defProp.GetValue(item)?.ToString();

                                        if (string.IsNullOrEmpty(definition)) continue;

                                        // Find the Value property
                                        var valProp = itemType.GetProperty("Value", infoFlags);
                                        if (valProp == null || !valProp.CanWrite) continue;

                                        // Override Culture display
                                        if (!string.IsNullOrEmpty(customCultureDisplay)
                                            && definition.IndexOf("Culture", StringComparison.OrdinalIgnoreCase) >= 0)
                                        {
                                            valProp.SetValue(item, customCultureDisplay);
                                            MCMSettings.DebugLog("Overrode Culture display to: " + customCultureDisplay);
                                        }

                                        // Override Occupation display
                                        if (!string.IsNullOrEmpty(occDisplayOverride)
                                            && definition.IndexOf("Occupation", StringComparison.OrdinalIgnoreCase) >= 0)
                                        {
                                            valProp.SetValue(item, occDisplayOverride);
                                            foundOccEntry = true;
                                            MCMSettings.DebugLog("Overrode Occupation display to: " + occDisplayOverride);
                                        }
                                    }

                                    // If the game didn't create an Occupation entry (common for Lords/player heroes),
                                    // inject one so the custom occupation is visible in the Stats panel.
                                    if (!foundOccEntry && !string.IsNullOrEmpty(occDisplayOverride) && statsItemType != null)
                                    {
                                        try
                                        {
                                            // Find ctor where first two params are strings (may be 2 or 3+ params)
                                            System.Reflection.ConstructorInfo ctor = null;
                                            foreach (var c in statsItemType.GetConstructors())
                                            {
                                                var ps = c.GetParameters();
                                                if (ps.Length >= 2 && ps[0].ParameterType == typeof(string) && ps[1].ParameterType == typeof(string))
                                                { ctor = c; break; }
                                            }
                                            if (ctor != null)
                                            {
                                                var ctorParams = ctor.GetParameters();
                                                object[] args = new object[ctorParams.Length];
                                                args[0] = "Occupation";
                                                args[1] = occDisplayOverride;
                                                for (int ai = 2; ai < ctorParams.Length; ai++)
                                                    args[ai] = ctorParams[ai].ParameterType.IsValueType ? Activator.CreateInstance(ctorParams[ai].ParameterType) : null;

                                                var newItem = ctor.Invoke(args);
                                                var addMethod = statsList.GetType().GetMethod("Add");
                                                if (addMethod != null)
                                                {
                                                    addMethod.Invoke(statsList, new[] { newItem });
                                                    MCMSettings.DebugLog("Injected Occupation entry into Stats: " + occDisplayOverride);
                                                }
                                            }
                                            else
                                            {
                                                MCMSettings.DebugLog("No suitable ctor on " + statsItemType.Name);
                                            }
                                        }
                                        catch (Exception injectEx)
                                        {
                                            MCMSettings.DebugLog("Occupation Stats injection failed: " + injectEx.Message);
                                        }
                                    }
                                }
                                else
                                {
                                    MCMSettings.DebugLog("Could not find hero info/stats list on VM type: " + __instance.GetType().Name);
                                    // Fallback: dump all properties to debug log so we can identify the right one
                                    foreach (var prop in __instance.GetType().GetProperties(infoFlags))
                                    {
                                        if (prop.PropertyType.Name.Contains("List") || prop.PropertyType.Name.Contains("Binding")
                                            || prop.PropertyType.Name.Contains("Collection"))
                                        {
                                            MCMSettings.DebugLog("  Candidate list property: " + prop.Name + " (" + prop.PropertyType.Name + ")");
                                        }
                                    }
                                }
                            }
                        }
                        catch (Exception infoEx)
                        {
                            MCMSettings.DebugLog("Info panel override failed: " + infoEx.Message);
                        }

                        // ── Inject additional game-data fields into the Info/Stats panel ──
                        // Kingdom, Location, Status, Traits, Wealth/Influence
                        if (MCMSettings.Instance == null || MCMSettings.Instance.EnableInfoStats)
                        try
                        {
                            var infoFlags3 = System.Reflection.BindingFlags.Instance
                                          | System.Reflection.BindingFlags.Public
                                          | System.Reflection.BindingFlags.NonPublic;
                            System.Collections.IEnumerable statsList3 = null;
                            Type statsItemType3 = null;

                            foreach (var propName in EncyclopediaPatchHelper.StatsListNamesCommon)
                            {
                                var sProp = __instance.GetType().GetProperty(propName, infoFlags3);
                                if (sProp != null)
                                {
                                    statsList3 = sProp.GetValue(__instance) as System.Collections.IEnumerable;
                                    if (statsList3 != null) break;
                                }
                            }

                            if (statsList3 != null)
                            {
                                foreach (var item in statsList3)
                                {
                                    if (item != null) { statsItemType3 = item.GetType(); break; }
                                }
                            }

                            if (statsList3 != null && statsItemType3 != null)
                            {
                                System.Reflection.ConstructorInfo ctor3 = null;
                                foreach (var c in statsItemType3.GetConstructors())
                                {
                                    var ps = c.GetParameters();
                                    if (ps.Length >= 2 && ps[0].ParameterType == typeof(string) && ps[1].ParameterType == typeof(string))
                                    { ctor3 = c; break; }
                                }

                                if (ctor3 != null)
                                {
                                    var addMethod3 = statsList3.GetType().GetMethod("Add");
                                    if (addMethod3 != null)
                                    {
                                        var ctorParams3 = ctor3.GetParameters();

                                        // Fog of war: mirror vanilla's masking. Computed BEFORE any of our
                                        // rows are appended, so the fallback row-scan only ever sees the
                                        // game's own entries (Age/Occupation = "???").
                                        bool infoHidden = EncyclopediaPatchHelper.IsInfoHidden(__instance, statsList3);
                                        if (infoHidden)
                                            MCMSettings.DebugLog("Hero info hidden — masking injected stats for " + hero.StringId);

                                        // Helper to create and add a stats item
                                        Action<string, string> addStatItem = (label, value) =>
                                        {
                                            if (string.IsNullOrEmpty(value)) return;
                                            // Mask every injected value while the hero is unknown to the player,
                                            // so our rows stay consistent with vanilla's "???" Age/Occupation.
                                            // Redundant for rows coming from HeroInfoStats — which already
                                            // skipped empties and applied the mask — but kept deliberately so
                                            // this lambda stays safe for any caller that adds a row directly.
                                            // Re-masking is idempotent: "???" masked again is still "???".
                                            if (infoHidden) value = EncyclopediaPatchHelper.HiddenInfoPlaceholder;
                                            object[] args = new object[ctorParams3.Length];
                                            args[0] = label;
                                            args[1] = value;
                                            for (int ai = 2; ai < ctorParams3.Length; ai++)
                                                args[ai] = ctorParams3[ai].ParameterType.IsValueType
                                                    ? Activator.CreateInstance(ctorParams3[ai].ParameterType) : null;
                                            var newItem = ctor3.Invoke(args);
                                            addMethod3.Invoke(statsList3, new[] { newItem });
                                        };

                                        // Stat rows come from the shared HeroInfoStats set so the
                                        // encyclopedia page and EE-ChronicleNoters cannot drift apart —
                                        // and so the fog-of-war mask is applied in exactly one place.
                                        foreach (var row in HeroInfoStats.Build(hero, infoHidden))
                                            addStatItem(row.Key, row.Value);
                                    }
                                }
                            }
                        }
                        catch (Exception extraInfoEx)
                        {
                            MCMSettings.DebugLog("Extra info panel injection failed: " + extraInfoEx.Message);
                        }

                        // Inject short info fields (Personality, Goals, Relationships, Rumors) into Stats panel
                        try
                        {
                            if (EncyclopediaEditBehavior.Instance.HasAnyHeroInfoField(hero.StringId))
                            {
                                var infoFlags2 = System.Reflection.BindingFlags.Instance
                                              | System.Reflection.BindingFlags.Public
                                              | System.Reflection.BindingFlags.NonPublic;
                                System.Collections.IEnumerable statsList2 = null;
                                Type statsItemType2 = null;

                                foreach (var propName in EncyclopediaPatchHelper.StatsListNamesCommon)
                                {
                                    var sProp = __instance.GetType().GetProperty(propName, infoFlags2);
                                    if (sProp != null)
                                    {
                                        statsList2 = sProp.GetValue(__instance) as System.Collections.IEnumerable;
                                        if (statsList2 != null) break;
                                    }
                                }

                                // Get the item type from the first existing item
                                if (statsList2 != null)
                                {
                                    foreach (var item in statsList2)
                                    {
                                        if (item != null) { statsItemType2 = item.GetType(); break; }
                                    }
                                }

                                if (statsList2 != null && statsItemType2 != null)
                                {
                                    // Find a ctor with at least 2 string params
                                    System.Reflection.ConstructorInfo ctor2 = null;
                                    foreach (var c in statsItemType2.GetConstructors())
                                    {
                                        var ps = c.GetParameters();
                                        if (ps.Length >= 2 && ps[0].ParameterType == typeof(string) && ps[1].ParameterType == typeof(string))
                                        { ctor2 = c; break; }
                                    }

                                    if (ctor2 != null)
                                    {
                                        var addMethod = statsList2.GetType().GetMethod("Add");
                                        if (addMethod != null)
                                        {
                                            // Inject short trait fields (Personality, Goals, etc.) into Stats panel
                                            foreach (string fieldKey in EncyclopediaEditBehavior.StatsFieldKeys)
                                            {
                                                string fieldValue = EncyclopediaEditBehavior.Instance.GetHeroInfoField(fieldKey, hero.StringId);
                                                if (string.IsNullOrEmpty(fieldValue)) continue;

                                                string fieldLabel = Localization.L("info_field_" + fieldKey);
                                                var ctorParams = ctor2.GetParameters();
                                                object[] args = new object[ctorParams.Length];
                                                args[0] = fieldLabel;
                                                args[1] = fieldValue;
                                                for (int ai = 2; ai < ctorParams.Length; ai++)
                                                    args[ai] = ctorParams[ai].ParameterType.IsValueType
                                                        ? Activator.CreateInstance(ctorParams[ai].ParameterType) : null;

                                                var newItem = ctor2.Invoke(args);
                                                addMethod.Invoke(statsList2, new[] { newItem });
                                                MCMSettings.DebugLog("Injected info field '" + fieldKey + "' into Stats panel");
                                            }

                                            // Narrative fields (Backstory, Rumors, etc.) are injected
                                            // separately via LoreSectionInjector into the widget tree.
                                        }
                                    }
                                }
                            }
                        }
                        catch (Exception infoFieldEx)
                        {
                            MCMSettings.DebugLog("Hero info field injection failed: " + infoFieldEx.Message);
                        }

                        // Inject (or remove) narrative fields (Backstory, Rumors, etc.) as a Lore section.
                        // Always call InjectLoreSection — it removes old widgets first, then only
                        // re-injects if there are fields. This ensures reset-to-default clears the UI.
                        try
                        {
                            if (EncyclopediaEditBehavior.Instance != null
                                && MCMSettings.Instance != null && MCMSettings.Instance.EnableLoreSection)
                            {
                                LoreSectionInjector.InjectLoreSection(hero.StringId);
                            }
                        }
                        catch (Exception loreEx)
                        {
                            MCMSettings.DebugLog("Lore section injection failed: " + loreEx.Message);
                        }

                        // Inject Relation Notes AFTER Lore so order is: Info → Lore → Relation Notes → Friends → Enemies
                        if (MCMSettings.Instance?.EnableRelationNotes ?? true)
                        {
                            try { RelationNotesSectionInjector.InjectRelationNotesSection(hero.StringId); }
                            catch (Exception ex2) { MCMSettings.DebugLog("RelationNotesSection hero inject error: " + ex2.Message); }
                        }
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation failed: " + ex.ToString()); }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Hero patch exception: " + ex.ToString());
                InformationManager.DisplayMessage(
                    new InformationMessage("[EditableEncyclopedia] Hero Error: " + ex.Message, Colors.Red));
            }
        }
    }

    // ============================================
    //  Clan Encyclopedia Page
    // ============================================
    [HarmonyPatch(typeof(EncyclopediaClanPageVM), "Refresh")]
    public static class ClanPageRefreshPatch
    {
        static void Postfix(EncyclopediaClanPageVM __instance)
        {
            try
            {
                try
                {
                    var settings = MCMSettings.Instance;
                    if (settings != null && !settings.EnableClanEditing) return;
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: settings access failed: " + ex.ToString()); }

                var clan = __instance.Obj as Clan;
                if (clan == null) return;

                EncyclopediaPatchHelper.HandlePageRefresh(
                    clan.StringId, __instance.InformationText,
                    () => __instance.Refresh(), text => __instance.InformationText = text, "Clan");

                EncyclopediaPageTracker.CurrentPageType = "Clan";
                EncyclopediaPageTracker.CurrentViewModel = __instance;
                EncyclopediaPageTracker.CurrentName = clan.Name?.ToString() ?? "";

                EncyclopediaPatchHelper.InjectTimestampWidget(clan.StringId);

                // Show tags as a styled widget
                try
                {
                    string clanTags = EncyclopediaEditBehavior.Instance?.GetTags(clan.StringId);
                    TagWidgetInjector.InjectOrUpdate(clanTags);
                }
                catch (Exception ex)
                {
                    MCMSettings.DebugLog("TagWidget clan inject error: " + ex.ToString());
                }

                if (MCMSettings.Instance?.EnableLoreSection ?? true)
                {
                    try { LoreSectionInjector.InjectLoreSection(clan.StringId); }
                    catch (Exception ex) { MCMSettings.DebugLog("LoreSection clan inject error: " + ex.ToString()); }
                }

                // 2026-05-28: chronicle on entity pages now owned by EE-ChronicleNoters.
                // Gate via PeerRegistry (EE-Core) so chronicle disappears when ChronicleNoters disabled.
                if ((MCMSettings.Instance?.EnableJournal ?? true) && PeerRegistry.Has("EE-ChronicleNoters"))
                {
                    try { JournalSectionInjector.InjectJournalSection(clan.StringId); }
                    catch (Exception ex) { MCMSettings.DebugLog("JournalSection clan inject error: " + ex.ToString()); }
                }

                // 2026-05-28: Timeline on Clan/Faction/Settlement entity pages is owned by
                // EE-ChronicleNoters going forward (same scope as Chronicle section). Gate so
                // it disappears when ChronicleNoters is disabled. Hero-page Timeline is NOT
                // gated — that's an EditableEncyclopedia core feature.
                if (HeroTimelineSectionInjector.IsEnabled() && PeerRegistry.Has("EE-ChronicleNoters"))
                {
                    try { HeroTimelineSectionInjector.InjectTimelineSection(clan.StringId); }
                    catch (Exception ex) { MCMSettings.DebugLog("Timeline clan inject error: " + ex.ToString()); }
                }

                EncyclopediaPageTracker.CurrentUpdateTimestampAction = () =>
                    EncyclopediaPatchHelper.InjectTimestampWidget(clan.StringId);
                EncyclopediaPatchHelper.ApplyCustomBanner(clan.StringId, "Clan");

                // Store original name once (before applying custom below)
                if (EncyclopediaEditBehavior.Instance != null)
                {
                    try { EncyclopediaEditBehavior.Instance.StoreOriginalName(clan.StringId, clan.Name?.ToString() ?? ""); }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: banner apply failed: " + ex.ToString()); }
                }

                // Setup name setter (VM + game object)
                EncyclopediaPageTracker.CurrentSetNameAction = text =>
                {
                    try
                    {
                        EncyclopediaPatchHelper.TrySetVMName(__instance, text);
                        EncyclopediaPageTracker.SetGameObjectName(clan, text);
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: VM name set failed: " + ex.ToString()); }
                };

                // Apply custom name if stored, or ensure original is shown
                try
                {
                    if (EncyclopediaEditBehavior.Instance != null)
                    {
                        string customName = EncyclopediaEditBehavior.Instance.GetCustomName(clan.StringId);
                        if (!string.IsNullOrEmpty(customName))
                        {
                            EncyclopediaPatchHelper.TrySetVMName(__instance, customName);
                            EncyclopediaPageTracker.SetGameObjectName(clan, customName);
                            // Update breadcrumb to show custom name
                            try { HeroPageRefreshPatch.SetBreadcrumbName(customName); } catch (Exception ex) { MCMSettings.DebugLog("Patches: refresh callback failed: " + ex.ToString()); }
                            MCMSettings.DebugLog("Applied custom name for clan " + clan.StringId + ": " + customName);
                        }
                        else
                        {
                            // No custom name — restore original name on the breadcrumb
                            string clanName = clan.Name?.ToString() ?? "";
                            if (!string.IsNullOrEmpty(clanName))
                                try { HeroPageRefreshPatch.SetBreadcrumbName(clanName); } catch (Exception ex) { MCMSettings.DebugLog("Patches: refresh callback failed: " + ex.ToString()); }
                        }
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation failed: " + ex.ToString()); }

                // --- Override Culture display for clan leader's custom culture ---
                try
                {
                    if (EncyclopediaEditBehavior.Instance != null && clan.Leader != null)
                    {
                        string clanCultureDisplay = EncyclopediaPatchHelper.ResolveCustomCultureDisplay(clan.Leader.StringId);
                        if (!string.IsNullOrEmpty(clanCultureDisplay))
                            EncyclopediaPatchHelper.OverrideCultureInStats(__instance, clanCultureDisplay, "Clan");
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("Clan culture override failed: " + ex.ToString()); }

                // ── Inject additional game-data fields into the Clan Info/Stats panel ──
                if (MCMSettings.Instance == null || MCMSettings.Instance.EnableInfoStats)
                try
                {
                    var addStatItem = EncyclopediaPatchHelper.TryGetNativeStatsAdder(__instance, "Clan");
                    if (addStatItem != null)
                    {
                                // NOTE: Clan Tier and Clan Strength are shown natively by the game
                                // so we skip injecting them to avoid duplicates

                                // Kingdom
                                try
                                {
                                    string kingdomName = clan.Kingdom?.Name?.ToString();
                                    if (clan.IsMinorFaction)
                                        addStatItem("Type", "Minor Faction");
                                    else
                                        addStatItem("Kingdom", !string.IsNullOrEmpty(kingdomName) ? kingdomName : "None");
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }

                                // Leader
                                try
                                {
                                    string leaderName = clan.Leader?.Name?.ToString();
                                    addStatItem("Leader", !string.IsNullOrEmpty(leaderName) ? leaderName : "None");
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }

                                // Culture — use leader's custom culture if set
                                try
                                {
                                    string cultureName = null;
                                    if (clan.Leader != null)
                                        cultureName = EncyclopediaPatchHelper.ResolveCustomCultureDisplay(clan.Leader.StringId);
                                    if (string.IsNullOrEmpty(cultureName))
                                        cultureName = clan.Culture?.Name?.ToString();
                                    addStatItem("Culture", !string.IsNullOrEmpty(cultureName) ? cultureName : "Unknown");
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }

                                // Renown
                                try
                                {
                                    float renown = clan.Renown;
                                    string renownStr;
                                    if (renown >= 1000) renownStr = (renown / 1000f).ToString("F1") + "K";
                                    else renownStr = ((int)renown).ToString();
                                    addStatItem("Renown", renownStr);
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }

                                // Lords
                                try
                                {
                                    int lordCount = 0;
                                    if (clan.Heroes != null)
                                        foreach (var h in clan.Heroes)
                                            if (h != null && h.IsAlive && h.IsLord) lordCount++;
                                    addStatItem("Lords", lordCount.ToString());
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }

                                // Companions
                                try
                                {
                                    int companionCount = 0;
                                    if (clan.Companions != null)
                                        foreach (var c in clan.Companions)
                                            if (c != null && c.IsAlive) companionCount++;
                                    addStatItem("Companions", companionCount.ToString());
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }

                                // Influence
                                try
                                {
                                    float influence = clan.Influence;
                                    string infStr;
                                    if (influence >= 1000) infStr = (influence / 1000f).ToString("F1") + "K";
                                    else infStr = ((int)influence).ToString();
                                    addStatItem("Influence", infStr);
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }

                                // NOTE: Clan Strength is shown natively, skip to avoid duplicate

                                // Total Troops
                                try
                                {
                                    int totalTroops = 0;
                                    if (clan.WarPartyComponents != null)
                                    {
                                        foreach (var wp in clan.WarPartyComponents)
                                        {
                                            try { totalTroops += wp.MobileParty?.MemberRoster?.TotalManCount ?? 0; } catch (Exception ex) { MCMSettings.DebugLog("Patches: troop count access failed: " + ex.ToString()); }
                                        }
                                    }
                                    addStatItem("Troops", totalTroops.ToString());
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }

                                // Parties
                                try
                                {
                                    int partyCount = clan.WarPartyComponents?.Count ?? 0;
                                    addStatItem("Parties", partyCount.ToString());
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }

                                // Garrison troops
                                try
                                {
                                    int totalGarrison = 0;
                                    if (clan.Fiefs != null)
                                    {
                                        foreach (var fief in clan.Fiefs)
                                        {
                                            try { totalGarrison += fief.GarrisonParty?.MemberRoster?.TotalManCount ?? 0; } catch (Exception ex) { MCMSettings.DebugLog("Patches: troop count access failed: " + ex.ToString()); }
                                        }
                                    }
                                    addStatItem("Garrisons", totalGarrison.ToString());
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }

                                // Holdings (Towns + Castles + Villages)
                                try
                                {
                                    int towns = 0, castles = 0, villages = 0;
                                    if (clan.Fiefs != null)
                                    {
                                        foreach (var fief in clan.Fiefs)
                                        {
                                            if (fief?.Settlement == null) continue;
                                            if (fief.Settlement.IsTown) towns++;
                                            else if (fief.Settlement.IsCastle) castles++;
                                        }
                                    }
                                    if (clan.Villages != null) villages = clan.Villages.Count;
                                    if (towns > 0) addStatItem("Towns", towns.ToString());
                                    if (castles > 0) addStatItem("Castles", castles.ToString());
                                    if (villages > 0) addStatItem("Villages", villages.ToString());
                                    if (towns == 0 && castles == 0 && villages == 0)
                                        addStatItem("Holdings", "None");
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }

                                // Caravans
                                try
                                {
                                    int caravans = 0;
                                    if (clan.Heroes != null)
                                    {
                                        foreach (var h in clan.Heroes)
                                        {
                                            if (h != null && h.IsAlive)
                                                try { caravans += h.OwnedCaravans?.Count ?? 0; } catch (Exception ex) { MCMSettings.DebugLog("Patches: caravan access failed: " + ex.ToString()); }
                                        }
                                    }
                                    addStatItem("Caravans", caravans.ToString());
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }

                                // Workshops
                                try
                                {
                                    int workshops = 0;
                                    if (clan.Heroes != null)
                                    {
                                        foreach (var h in clan.Heroes)
                                        {
                                            if (h == null || !h.IsAlive) continue;
                                            try
                                            {
                                                if (h.OwnedWorkshops != null)
                                                {
                                                    foreach (var ws in h.OwnedWorkshops)
                                                        if (ws != null && !ws.WorkshopType.IsHidden) workshops++;
                                                }
                                            }
                                            catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }
                                        }
                                    }
                                    addStatItem("Workshops", workshops.ToString());
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }

                                // At War
                                try
                                {
                                    var warFactions = new System.Collections.Generic.List<string>();
                                    IFaction clanFaction = (IFaction)clan.Kingdom ?? clan;
                                    foreach (var faction in Campaign.Current.Factions)
                                    {
                                        if (faction != null && faction != clanFaction && clanFaction.IsAtWarWith(faction))
                                        {
                                            if (faction is Kingdom)
                                                warFactions.Add(faction.Name?.ToString() ?? "Unknown");
                                        }
                                    }
                                    if (warFactions.Count > 0)
                                    {
                                        addStatItem("At War", warFactions[0]);
                                        for (int wi = 1; wi < warFactions.Count; wi++)
                                            addStatItem("", warFactions[wi]);
                                    }
                                    else
                                        addStatItem("At War", "Peace");
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: war faction check failed: " + ex.ToString()); }

                                MCMSettings.DebugLog("Clan stats injected for " + clan.StringId);
                    }
                }
                catch (Exception statsEx)
                {
                    MCMSettings.DebugLog("Clan stats injection failed: " + statsEx.Message);
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Clan patch exception: " + ex.ToString());
                InformationManager.DisplayMessage(
                    new InformationMessage("[EditableEncyclopedia] Clan Error: " + ex.Message, Colors.Red));
            }
        }
    }

    // ============================================
    //  Kingdom/Faction Encyclopedia Page
    // ============================================
    [HarmonyPatch(typeof(EncyclopediaFactionPageVM), "Refresh")]
    public static class FactionPageRefreshPatch
    {
        static void Postfix(EncyclopediaFactionPageVM __instance)
        {
            try
            {
                try
                {
                    var settings = MCMSettings.Instance;
                    if (settings != null && !settings.EnableKingdomEditing) return;
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: settings access failed: " + ex.ToString()); }

                var kingdom = __instance.Obj as Kingdom;
                if (kingdom == null) return;

                EncyclopediaPatchHelper.HandlePageRefresh(
                    kingdom.StringId, __instance.InformationText,
                    () => __instance.Refresh(), text => __instance.InformationText = text, "Kingdom");

                EncyclopediaPageTracker.CurrentPageType = "Kingdom";
                EncyclopediaPageTracker.CurrentViewModel = __instance;
                EncyclopediaPageTracker.CurrentName = kingdom.Name?.ToString() ?? "";

                EncyclopediaPatchHelper.InjectTimestampWidget(kingdom.StringId);

                // Show tags as a styled widget
                try
                {
                    string kingdomTags = EncyclopediaEditBehavior.Instance?.GetTags(kingdom.StringId);
                    TagWidgetInjector.InjectOrUpdate(kingdomTags);
                }
                catch (Exception ex)
                {
                    MCMSettings.DebugLog("TagWidget kingdom inject error: " + ex.ToString());
                }

                if (MCMSettings.Instance?.EnableLoreSection ?? true)
                {
                    try { LoreSectionInjector.InjectLoreSection(kingdom.StringId); }
                    catch (Exception ex) { MCMSettings.DebugLog("LoreSection kingdom inject error: " + ex.ToString()); }
                }

                // 2026-05-28: chronicle on entity pages now owned by EE-ChronicleNoters.
                if ((MCMSettings.Instance?.EnableJournal ?? true) && PeerRegistry.Has("EE-ChronicleNoters"))
                {
                    try { JournalSectionInjector.InjectJournalSection(kingdom.StringId); }
                    catch (Exception ex) { MCMSettings.DebugLog("JournalSection kingdom inject error: " + ex.ToString()); }
                }

                // 2026-05-28: Timeline on Clan/Faction/Settlement entity pages owned by EE-ChronicleNoters.
                if (HeroTimelineSectionInjector.IsEnabled() && PeerRegistry.Has("EE-ChronicleNoters"))
                {
                    try { HeroTimelineSectionInjector.InjectTimelineSection(kingdom.StringId); }
                    catch (Exception ex) { MCMSettings.DebugLog("Timeline kingdom inject error: " + ex.ToString()); }
                }

                EncyclopediaPageTracker.CurrentUpdateTimestampAction = () =>
                    EncyclopediaPatchHelper.InjectTimestampWidget(kingdom.StringId);
                EncyclopediaPatchHelper.ApplyCustomBanner(kingdom.StringId, "Kingdom");

                if (EncyclopediaEditBehavior.Instance != null)
                {
                    try { EncyclopediaEditBehavior.Instance.StoreOriginalName(kingdom.StringId, kingdom.Name?.ToString() ?? ""); }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: banner apply failed: " + ex.ToString()); }
                }

                EncyclopediaPageTracker.CurrentSetNameAction = text =>
                {
                    try
                    {
                        EncyclopediaPatchHelper.TrySetVMName(__instance, text);
                        EncyclopediaPageTracker.SetGameObjectName(kingdom, text);
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: VM name set failed: " + ex.ToString()); }
                };

                try
                {
                    if (EncyclopediaEditBehavior.Instance != null)
                    {
                        string customName = EncyclopediaEditBehavior.Instance.GetCustomName(kingdom.StringId);
                        if (!string.IsNullOrEmpty(customName))
                        {
                            EncyclopediaPatchHelper.TrySetVMName(__instance, customName);
                            EncyclopediaPageTracker.SetGameObjectName(kingdom, customName);
                            try { HeroPageRefreshPatch.SetBreadcrumbName(customName); } catch (Exception ex) { MCMSettings.DebugLog("Patches: refresh callback failed: " + ex.ToString()); }
                            MCMSettings.DebugLog("Applied custom name for kingdom " + kingdom.StringId + ": " + customName);
                        }
                        else
                        {
                            string kingdomName = kingdom.Name?.ToString() ?? "";
                            if (!string.IsNullOrEmpty(kingdomName))
                                try { HeroPageRefreshPatch.SetBreadcrumbName(kingdomName); } catch (Exception ex) { MCMSettings.DebugLog("Patches: refresh callback failed: " + ex.ToString()); }
                        }
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation failed: " + ex.ToString()); }

                // --- Override Culture display for kingdom ruler's custom culture ---
                try
                {
                    if (EncyclopediaEditBehavior.Instance != null && kingdom.Leader != null)
                    {
                        string kingdomCultureDisplay = EncyclopediaPatchHelper.ResolveCustomCultureDisplay(kingdom.Leader.StringId);
                        if (!string.IsNullOrEmpty(kingdomCultureDisplay))
                            EncyclopediaPatchHelper.OverrideCultureInStats(__instance, kingdomCultureDisplay, "Kingdom");
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("Kingdom culture override failed: " + ex.ToString()); }

                // ── Inject additional game-data fields into native Stats panel ──
                if (MCMSettings.Instance == null || MCMSettings.Instance.EnableInfoStats)
                try
                {
                    var addStat = EncyclopediaPatchHelper.TryGetNativeStatsAdder(__instance, "Kingdom");
                    if (addStat != null)
                    {
                        try { addStat("Ruler", kingdom.Leader?.Name?.ToString() ?? "None"); } catch (Exception ex) { MCMSettings.DebugLog("Patches: stat injection failed: " + ex.ToString()); }
                        try {
                            string kCultureDisplay = null;
                            if (kingdom.Leader != null)
                                kCultureDisplay = EncyclopediaPatchHelper.ResolveCustomCultureDisplay(kingdom.Leader.StringId);
                            if (string.IsNullOrEmpty(kCultureDisplay))
                                kCultureDisplay = kingdom.Culture?.Name?.ToString() ?? "Unknown";
                            addStat("Culture", kCultureDisplay);
                        } catch (Exception ex) { MCMSettings.DebugLog("Patches: stat injection failed: " + ex.ToString()); }
                        try { addStat("Clans", (kingdom.Clans?.Count ?? 0).ToString()); } catch (Exception ex) { MCMSettings.DebugLog("Patches: stat injection failed: " + ex.ToString()); }

                        try
                        {
                            int lordCount = 0;
                            if (kingdom.Clans != null)
                                foreach (var kc in kingdom.Clans)
                                    if (kc?.Heroes != null)
                                        foreach (var h in kc.Heroes)
                                            if (h != null && h.IsAlive && h.IsLord) lordCount++;
                            addStat("Lords", lordCount.ToString());
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }

                        try
                        {
                            int towns = 0, castles = 0, villages = 0;
                            if (kingdom.Fiefs != null)
                                foreach (var fief in kingdom.Fiefs)
                                {
                                    if (fief?.Settlement == null) continue;
                                    if (fief.Settlement.IsTown) towns++;
                                    else if (fief.Settlement.IsCastle) castles++;
                                }
                            if (kingdom.Villages != null) villages = kingdom.Villages.Count;
                            addStat("Towns", towns.ToString());
                            addStat("Castles", castles.ToString());
                            addStat("Villages", villages.ToString());
                            addStat("Total Fiefs", (towns + castles).ToString());
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }

                        // Total field strength
                        try
                        {
                            int totalTroops = 0;
                            if (kingdom.Clans != null)
                                foreach (var kc in kingdom.Clans)
                                    if (kc?.WarPartyComponents != null)
                                        foreach (var wp in kc.WarPartyComponents)
                                            try { totalTroops += wp.MobileParty?.MemberRoster?.TotalManCount ?? 0; } catch (Exception ex) { MCMSettings.DebugLog("Patches: troop count access failed: " + ex.ToString()); }
                            string strStr = totalTroops >= 1000 ? (totalTroops / 1000f).ToString("F1") + "K" : totalTroops.ToString();
                            addStat("Strength", strStr);
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }

                        // Total garrisons
                        try
                        {
                            int totalGarrison = 0;
                            if (kingdom.Fiefs != null)
                                foreach (var fief in kingdom.Fiefs)
                                    try { totalGarrison += fief.GarrisonParty?.MemberRoster?.TotalManCount ?? 0; } catch (Exception ex) { MCMSettings.DebugLog("Patches: troop count access failed: " + ex.ToString()); }
                            string garStr = totalGarrison >= 1000 ? (totalGarrison / 1000f).ToString("F1") + "K" : totalGarrison.ToString();
                            addStat("Garrisons", garStr);
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }

                        // Total influence
                        try
                        {
                            float totalInfluence = 0;
                            if (kingdom.Clans != null)
                                foreach (var kc in kingdom.Clans)
                                    try { totalInfluence += kc.Influence; } catch (Exception ex) { MCMSettings.DebugLog("Patches: influence access failed: " + ex.ToString()); }
                            string infStr = totalInfluence >= 1000 ? (totalInfluence / 1000f).ToString("F1") + "K" : ((int)totalInfluence).ToString();
                            addStat("Influence", infStr);
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }

                        // Mercenary clans
                        try
                        {
                            int mercCount = 0;
                            if (kingdom.Clans != null)
                                foreach (var kc in kingdom.Clans)
                                    if (kc != null && kc.IsMinorFaction) mercCount++;
                            if (mercCount > 0)
                                addStat("Mercenaries", mercCount.ToString());
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }

                        // At War
                        try
                        {
                            var wars = new List<string>();
                            foreach (var faction in Campaign.Current.Factions)
                                if (faction != null && faction != kingdom && kingdom.IsAtWarWith(faction) && faction is Kingdom)
                                    wars.Add(faction.Name?.ToString() ?? "Unknown");
                            // One row per faction — see AddWarRows. Kingdoms have no vanilla
                            // fog-of-war gate (only heroes and settlements do), so never masked.
                            EncyclopediaPatchHelper.AddWarRows(addStat, wars, false);
                            if (wars.Count > 0)
                                addStat("Wars", wars.Count.ToString());
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }

                        MCMSettings.DebugLog("Kingdom stats injected via native VM for " + kingdom.StringId);
                    }
                    else
                    {
                        MCMSettings.DebugLog("Kingdom stats: falling back to widget injection");
                        var fallbackStats = new List<KeyValuePair<string, string>>();
                        Action<string, string> addFb = (l, v) => { if (!string.IsNullOrEmpty(v)) fallbackStats.Add(new KeyValuePair<string, string>(l, v)); };

                        try { addFb("Ruler", kingdom.Leader?.Name?.ToString() ?? "None"); } catch (Exception ex) { MCMSettings.DebugLog("Patches: stat injection failed: " + ex.ToString()); }
                        try {
                            string kfbCulture = null;
                            if (kingdom.Leader != null)
                                kfbCulture = EncyclopediaPatchHelper.ResolveCustomCultureDisplay(kingdom.Leader.StringId);
                            if (string.IsNullOrEmpty(kfbCulture))
                                kfbCulture = kingdom.Culture?.Name?.ToString() ?? "Unknown";
                            addFb("Culture", kfbCulture);
                        } catch (Exception ex) { MCMSettings.DebugLog("Patches: stat injection failed: " + ex.ToString()); }
                        try { addFb("Clans", (kingdom.Clans?.Count ?? 0).ToString()); } catch (Exception ex) { MCMSettings.DebugLog("Patches: stat injection failed: " + ex.ToString()); }
                        try
                        {
                            int lordCount = 0;
                            if (kingdom.Clans != null) foreach (var kc in kingdom.Clans) if (kc?.Heroes != null) foreach (var h in kc.Heroes) if (h != null && h.IsAlive && h.IsLord) lordCount++;
                            addFb("Lords", lordCount.ToString());
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }
                        try
                        {
                            int towns = 0, castles = 0, villages = 0;
                            if (kingdom.Fiefs != null) foreach (var fief in kingdom.Fiefs) { if (fief?.Settlement == null) continue; if (fief.Settlement.IsTown) towns++; else if (fief.Settlement.IsCastle) castles++; }
                            if (kingdom.Villages != null) villages = kingdom.Villages.Count;
                            addFb("Towns", towns.ToString()); addFb("Castles", castles.ToString()); addFb("Villages", villages.ToString()); addFb("Total Fiefs", (towns + castles).ToString());
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }
                        try
                        {
                            int totalTroops = 0;
                            if (kingdom.Clans != null) foreach (var kc in kingdom.Clans) if (kc?.WarPartyComponents != null) foreach (var wp in kc.WarPartyComponents) try { totalTroops += wp.MobileParty?.MemberRoster?.TotalManCount ?? 0; } catch (Exception ex) { MCMSettings.DebugLog("Patches: troop count access failed: " + ex.ToString()); }
                            addFb("Strength", totalTroops >= 1000 ? (totalTroops / 1000f).ToString("F1") + "K" : totalTroops.ToString());
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: operation failed: " + ex.ToString()); }
                        try
                        {
                            int totalGarrison = 0;
                            if (kingdom.Fiefs != null) foreach (var fief in kingdom.Fiefs) try { totalGarrison += fief.GarrisonParty?.MemberRoster?.TotalManCount ?? 0; } catch (Exception ex) { MCMSettings.DebugLog("Patches: troop count access failed: " + ex.ToString()); }
                            addFb("Garrisons", totalGarrison >= 1000 ? (totalGarrison / 1000f).ToString("F1") + "K" : totalGarrison.ToString());
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: operation failed: " + ex.ToString()); }
                        try
                        {
                            float totalInfluence = 0;
                            if (kingdom.Clans != null) foreach (var kc in kingdom.Clans) try { totalInfluence += kc.Influence; } catch (Exception ex) { MCMSettings.DebugLog("Patches: influence access failed: " + ex.ToString()); }
                            addFb("Influence", totalInfluence >= 1000 ? (totalInfluence / 1000f).ToString("F1") + "K" : ((int)totalInfluence).ToString());
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: operation failed: " + ex.ToString()); }
                        try
                        {
                            var wars = new List<string>();
                            foreach (var faction in Campaign.Current.Factions) if (faction != null && faction != kingdom && kingdom.IsAtWarWith(faction) && faction is Kingdom) wars.Add(faction.Name?.ToString() ?? "Unknown");
                            EncyclopediaPatchHelper.AddWarRows(addFb, wars, false);
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: war faction check failed: " + ex.ToString()); }

                        if (fallbackStats.Count > 0)
                        {
                            StatsWidgetInjector.ClearInjected();
                            StatsWidgetInjector.ScheduleInjection(kingdom.StringId, fallbackStats);
                        }
                    }
                }
                catch (Exception statsEx)
                {
                    MCMSettings.DebugLog("Kingdom stats injection failed: " + statsEx.Message);
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Kingdom patch exception: " + ex.ToString());
                InformationManager.DisplayMessage(
                    new InformationMessage("[EditableEncyclopedia] Kingdom Error: " + ex.Message, Colors.Red));
            }
        }
    }

    // ============================================
    //  Settlement Encyclopedia Page
    // ============================================
    [HarmonyPatch(typeof(EncyclopediaSettlementPageVM), "Refresh")]
    public static class SettlementPageRefreshPatch
    {
        /// <summary>
        /// Tracks the settlement + custom culture that was swapped out during Prefix.
        /// </summary>
        [System.ThreadStatic]
        private static Settlement _swappedSettlement;
        [System.ThreadStatic]
        private static CultureObject _swappedCustomCulture;

        /// <summary>
        /// Before Refresh(), swap the settlement's culture back to vanilla
        /// so the game's internal ViewModel code doesn't crash on the custom culture.
        /// </summary>
        static void Prefix(EncyclopediaSettlementPageVM __instance)
        {
            _swappedSettlement = null;
            _swappedCustomCulture = null;
            try
            {
                var settlement = __instance.Obj as Settlement;
                if (settlement == null) return;

                if (SaveSanitizerPatch.OriginalSettlementCultures.TryGetValue(settlement, out var original))
                {
                    _swappedCustomCulture = settlement.Culture;
                    _swappedSettlement = settlement;
                    settlement.Culture = original;
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: settlement page postfix failed: " + ex.ToString()); }
        }

        /// <summary>
        /// After Refresh(), restore the custom culture. Finalizer ensures this
        /// runs even if Refresh() throws.
        /// </summary>
        static Exception Finalizer(Exception __exception)
        {
            try
            {
                if (_swappedSettlement != null && _swappedCustomCulture != null)
                    _swappedSettlement.Culture = _swappedCustomCulture;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: operation failed: " + ex.ToString()); }
            _swappedSettlement = null;
            _swappedCustomCulture = null;
            return __exception;
        }

        static void Postfix(EncyclopediaSettlementPageVM __instance)
        {
            try
            {
                try
                {
                    var settings = MCMSettings.Instance;
                    if (settings != null && !settings.EnableSettlementEditing) return;
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: settings access failed: " + ex.ToString()); }

                // Skip injection entirely when a conflicting layout mod (e.g. Realm of Thrones)
                // is loaded. EE's anchor-walking assumes the vanilla settlement page widget
                // tree; mods that replace that prefab cause the Lore / Journal / Timeline
                // injections to wrap into their own column. User can force-enable via MCM
                // (Override Layout Mod Compat). Bug 2026-05-25, image S987QOQ.
                if (ModCompatHelper.ShouldSkipSettlementInjection())
                {
                    MCMSettings.DebugLog("[ModCompat] Skipping settlement injection (conflicting mod loaded: "
                        + ModCompatHelper.DetectedModuleId + "). Toggle 'Override Layout Mod Compat' in MCM to force on.");
                    return;
                }

                var settlement = __instance.Obj as Settlement;
                if (settlement == null) return;

                EncyclopediaPatchHelper.HandlePageRefresh(
                    settlement.StringId, __instance.InformationText,
                    () => __instance.Refresh(), text => __instance.InformationText = text, "Settlement");

                EncyclopediaPageTracker.CurrentPageType = "Settlement";
                EncyclopediaPageTracker.CurrentViewModel = __instance;
                EncyclopediaPageTracker.CurrentName = settlement.Name?.ToString() ?? "";

                // Show edit timestamp as a right-aligned overlay
                EncyclopediaPatchHelper.InjectTimestampWidget(settlement.StringId);

                // Show tags as a styled widget
                try
                {
                    string settlementTags = EncyclopediaEditBehavior.Instance?.GetTags(settlement.StringId);
                    TagWidgetInjector.InjectOrUpdate(settlementTags);
                }
                catch (Exception ex)
                {
                    MCMSettings.DebugLog("TagWidget settlement inject error: " + ex.ToString());
                }

                if (MCMSettings.Instance?.EnableLoreSection ?? true)
                {
                    try { LoreSectionInjector.InjectLoreSection(settlement.StringId); }
                    catch (Exception ex) { MCMSettings.DebugLog("LoreSection settlement inject error: " + ex.ToString()); }
                }

                // 2026-05-28: chronicle on entity pages now owned by EE-ChronicleNoters.
                if ((MCMSettings.Instance?.EnableJournal ?? true) && PeerRegistry.Has("EE-ChronicleNoters"))
                {
                    try { JournalSectionInjector.InjectJournalSection(settlement.StringId); }
                    catch (Exception ex) { MCMSettings.DebugLog("JournalSection settlement inject error: " + ex.ToString()); }
                }

                // 2026-05-28: Timeline on Clan/Faction/Settlement entity pages owned by EE-ChronicleNoters.
                if (HeroTimelineSectionInjector.IsEnabled() && PeerRegistry.Has("EE-ChronicleNoters"))
                {
                    try { HeroTimelineSectionInjector.InjectTimelineSection(settlement.StringId); }
                    catch (Exception ex) { MCMSettings.DebugLog("Timeline settlement inject error: " + ex.ToString()); }
                }

                // Inventory Lore (main module) — settlement stash items.
                try { InventoryLoreSectionInjector.InjectInventorySection(settlement.StringId); }
                catch (Exception ex) { MCMSettings.DebugLog("InventoryLore settlement inject error: " + ex.ToString()); }

                EncyclopediaPageTracker.CurrentUpdateTimestampAction = () =>
                    EncyclopediaPatchHelper.InjectTimestampWidget(settlement.StringId);
                EncyclopediaPatchHelper.ApplyCustomBanner(settlement.StringId, "Settlement");

                if (EncyclopediaEditBehavior.Instance != null)
                {
                    try { EncyclopediaEditBehavior.Instance.StoreOriginalName(settlement.StringId, settlement.Name?.ToString() ?? ""); }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: banner apply failed: " + ex.ToString()); }
                }

                EncyclopediaPageTracker.CurrentSetNameAction = text =>
                {
                    try
                    {
                        EncyclopediaPatchHelper.TrySetVMName(__instance, text);
                        EncyclopediaPageTracker.SetGameObjectName(settlement, text);
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: VM name set failed: " + ex.ToString()); }
                };

                try
                {
                    if (EncyclopediaEditBehavior.Instance != null)
                    {
                        string customName = EncyclopediaEditBehavior.Instance.GetCustomName(settlement.StringId);
                        if (!string.IsNullOrEmpty(customName))
                        {
                            EncyclopediaPatchHelper.TrySetVMName(__instance, customName);
                            EncyclopediaPageTracker.SetGameObjectName(settlement, customName);
                            try { HeroPageRefreshPatch.SetBreadcrumbName(customName); } catch (Exception ex) { MCMSettings.DebugLog("Patches: refresh callback failed: " + ex.ToString()); }
                            // Refresh the map nameplate for this settlement
                            try { SettlementNameplateMixin.RefreshNameForSettlement(settlement); } catch (Exception ex) { MCMSettings.DebugLog("Patches: refresh callback failed: " + ex.ToString()); }
                            MCMSettings.DebugLog("Applied custom name for settlement " + settlement.StringId + ": " + customName);
                        }
                        else
                        {
                            string settlementName = settlement.Name?.ToString() ?? "";
                            if (!string.IsNullOrEmpty(settlementName))
                                try { HeroPageRefreshPatch.SetBreadcrumbName(settlementName); } catch (Exception ex) { MCMSettings.DebugLog("Patches: refresh callback failed: " + ex.ToString()); }
                        }
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation failed: " + ex.ToString()); }

                // --- Override Culture display to match owner hero's custom culture ---
                try
                {
                    if (EncyclopediaEditBehavior.Instance != null)
                    {
                        // Find the owner hero (clan leader of the owning clan)
                        Hero ownerHero = settlement.OwnerClan?.Leader;
                        if (ownerHero != null)
                        {
                            string customCultureDisplay = EncyclopediaEditBehavior.Instance.GetCustomCultureDisplayName(ownerHero.StringId);
                            // Fallback: look up culture name from persisted culture ID
                            if (string.IsNullOrEmpty(customCultureDisplay))
                            {
                                string cId = EncyclopediaEditBehavior.Instance.GetCustomCulture(ownerHero.StringId);
                                if (!string.IsNullOrEmpty(cId))
                                {
                                    try
                                    {
                                        foreach (var c in TaleWorlds.ObjectSystem.MBObjectManager.Instance.GetObjectTypeList<CultureObject>())
                                        {
                                            if (c != null && string.Equals(c.StringId, cId, StringComparison.OrdinalIgnoreCase))
                                            { customCultureDisplay = c.Name?.ToString() ?? cId; break; }
                                        }
                                        if (string.IsNullOrEmpty(customCultureDisplay)) customCultureDisplay = cId;
                                    }
                                    catch { }
                                }
                            }
                            if (!string.IsNullOrEmpty(customCultureDisplay))
                            {
                                var infoFlags = System.Reflection.BindingFlags.Instance
                                              | System.Reflection.BindingFlags.Public
                                              | System.Reflection.BindingFlags.NonPublic;
                                bool overridden = false;

                                // Primary: set CultureText property directly (used by NavalEncyclopediaSettlementPageVM and similar)
                                var cultureTextProp = __instance.GetType().GetProperty("CultureText", infoFlags);
                                if (cultureTextProp != null && cultureTextProp.CanWrite && cultureTextProp.PropertyType == typeof(string))
                                {
                                    cultureTextProp.SetValue(__instance, customCultureDisplay);
                                    overridden = true;
                                    MCMSettings.DebugLog("Settlement CultureText overridden to owner's culture: " + customCultureDisplay);
                                }

                                // Also check LeftSideProperties / RightSideProperties for Culture entries (StringPairItemVM lists)
                                foreach (var listPropName in new[] { "LeftSideProperties", "RightSideProperties" })
                                {
                                    var listProp = __instance.GetType().GetProperty(listPropName, infoFlags);
                                    if (listProp == null) continue;
                                    var list = listProp.GetValue(__instance) as System.Collections.IEnumerable;
                                    if (list == null) continue;
                                    foreach (var item in list)
                                    {
                                        if (item == null) continue;
                                        var itemType = item.GetType();
                                        var defProp = itemType.GetProperty("Definition", infoFlags)
                                                   ?? itemType.GetProperty("Type", infoFlags)
                                                   ?? itemType.GetProperty("Name", infoFlags);
                                        if (defProp == null) continue;
                                        string definition = defProp.GetValue(item)?.ToString();
                                        if (string.IsNullOrEmpty(definition)) continue;

                                        if (definition.IndexOf("Culture", StringComparison.OrdinalIgnoreCase) >= 0)
                                        {
                                            var valProp = itemType.GetProperty("Value", infoFlags);
                                            if (valProp != null && valProp.CanWrite)
                                            {
                                                valProp.SetValue(item, customCultureDisplay);
                                                overridden = true;
                                                MCMSettings.DebugLog("Settlement " + listPropName + " Culture overridden to: " + customCultureDisplay);
                                            }
                                        }
                                    }
                                }

                                if (!overridden)
                                    MCMSettings.DebugLog("Settlement culture override: no writable CultureText or list Culture entry found on " + __instance.GetType().Name);
                            }
                        }
                    }
                }
                catch (Exception cultureEx)
                {
                    MCMSettings.DebugLog("Settlement culture override failed: " + cultureEx.Message);
                }

                // ── Inject additional game-data fields into native Stats panel ──
                if (MCMSettings.Instance == null || MCMSettings.Instance.EnableInfoStats)
                try
                {
                    var addStat = EncyclopediaPatchHelper.TryGetNativeStatsAdder(__instance, "Settlement");
                    if (addStat != null)
                    {
                        try { addStat("Owner", settlement.OwnerClan?.Leader?.Name?.ToString() ?? "None"); } catch (Exception ex) { MCMSettings.DebugLog("Patches: stat injection failed: " + ex.ToString()); }
                        try { addStat("Clan", settlement.OwnerClan?.Name?.ToString() ?? "None"); } catch (Exception ex) { MCMSettings.DebugLog("Patches: stat injection failed: " + ex.ToString()); }
                        try { addStat("Kingdom", settlement.OwnerClan?.Kingdom?.Name?.ToString() ?? "None"); } catch (Exception ex) { MCMSettings.DebugLog("Patches: stat injection failed: " + ex.ToString()); }
                        try {
                            // Use custom culture from owner hero if set, else settlement's native culture
                            string cultureDisplay = null;
                            if (settlement.OwnerClan?.Leader != null)
                                cultureDisplay = EncyclopediaPatchHelper.ResolveCustomCultureDisplay(settlement.OwnerClan.Leader.StringId);
                            if (string.IsNullOrEmpty(cultureDisplay))
                                cultureDisplay = settlement.Culture?.Name?.ToString() ?? "Unknown";
                            addStat("Culture", cultureDisplay);
                        } catch (Exception ex) { MCMSettings.DebugLog("Patches: stat injection failed: " + ex.ToString()); }

                        if (settlement.IsTown || settlement.IsCastle)
                        {
                            var town = settlement.Town;
                            if (town != null)
                            {
                                try { addStat("Prosperity", ((int)town.Prosperity).ToString()); } catch (Exception ex) { MCMSettings.DebugLog("Patches: stat injection failed: " + ex.ToString()); }
                                try { addStat("Loyalty", ((int)town.Loyalty).ToString()); } catch (Exception ex) { MCMSettings.DebugLog("Patches: stat injection failed: " + ex.ToString()); }
                                try { addStat("Security", ((int)town.Security).ToString()); } catch (Exception ex) { MCMSettings.DebugLog("Patches: stat injection failed: " + ex.ToString()); }
                                try { addStat("Food", ((int)town.FoodStocks).ToString()); } catch (Exception ex) { MCMSettings.DebugLog("Patches: stat injection failed: " + ex.ToString()); }
                                try { addStat("Garrison", (town.GarrisonParty?.MemberRoster?.TotalManCount ?? 0).ToString()); } catch (Exception ex) { MCMSettings.DebugLog("Patches: troop count access failed: " + ex.ToString()); }
                                try { addStat("Militia", ((int)settlement.Militia).ToString()); } catch (Exception ex) { MCMSettings.DebugLog("Patches: stat injection failed: " + ex.ToString()); }

                                // Governor
                                try
                                {
                                    string govName = town.Governor?.Name?.ToString();
                                    addStat("Governor", !string.IsNullOrEmpty(govName) ? govName : "None");
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }

                                // Wall Level
                                try
                                {
                                    var wallProp = town.GetType().GetProperty("WallLevel",
                                        System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public);
                                    if (wallProp != null)
                                    {
                                        int wallLevel = (int)wallProp.GetValue(town);
                                        addStat("Wall Level", wallLevel.ToString());
                                    }
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }

                                if (settlement.IsTown)
                                {
                                    try
                                    {
                                        var wsNames = new System.Text.StringBuilder();
                                        int wc = 0;
                                        if (town.Workshops != null)
                                        {
                                            foreach (var ws in town.Workshops)
                                            {
                                                if (ws == null) continue;
                                                if (ws.WorkshopType == null) continue;
                                                bool isHidden = false;
                                                try { isHidden = ws.WorkshopType.IsHidden; } catch { }
                                                if (isHidden) continue;
                                                string wsName = null;
                                                try { wsName = ws.WorkshopType.Name?.ToString(); } catch { }
                                                if (string.IsNullOrEmpty(wsName)) try { wsName = ws.WorkshopType.StringId; } catch { }
                                                if (string.IsNullOrEmpty(wsName)) try { wsName = ws.WorkshopType.ToString(); } catch { }
                                                // Clean up internal IDs: "linen_weavery" → "Linen Weavery"
                                                if (!string.IsNullOrEmpty(wsName) && wsName.Contains("_"))
                                                    wsName = System.Globalization.CultureInfo.InvariantCulture.TextInfo.ToTitleCase(wsName.Replace("_", " "));
                                                if (!string.IsNullOrEmpty(wsName))
                                                {
                                                    if (wc > 0) wsNames.Append(", ");
                                                    wsNames.Append(wsName);
                                                }
                                                wc++;
                                            }
                                        }
                                        addStat("Workshops", wc > 0 ? wc + " (" + wsNames.ToString() + ")" : "0");
                                    }
                                    catch (Exception ex) { MCMSettings.DebugLog("Patches: workshops stat failed: " + ex.ToString()); }
                                    try { addStat("Trade Tax", ((int)town.TradeTaxAccumulated) > 0 ? ((int)town.TradeTaxAccumulated).ToString("N0") + " denars" : "0"); } catch (Exception ex) { MCMSettings.DebugLog("Patches: trade tax stat failed: " + ex.ToString()); }
                                }

                                // Castle trade tax
                                if (settlement.IsCastle)
                                {
                                    try { addStat("Trade Tax", ((int)town.TradeTaxAccumulated) > 0 ? ((int)town.TradeTaxAccumulated).ToString("N0") + " denars" : "0"); } catch (Exception ex) { MCMSettings.DebugLog("Patches: castle trade tax failed: " + ex.ToString()); }
                                }

                                // Notables
                                try
                                {
                                    int notables = 0;
                                    if (settlement.Notables != null)
                                        foreach (var n in settlement.Notables)
                                            if (n != null && n.IsAlive) notables++;
                                    addStat("Notables", notables.ToString());
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }
                            }
                            try { addStat("Villages", (settlement.BoundVillages?.Count ?? 0).ToString()); } catch (Exception ex) { MCMSettings.DebugLog("Patches: stat injection failed: " + ex.ToString()); }

                            // Bound village produces
                            try
                            {
                                if (settlement.BoundVillages != null && settlement.BoundVillages.Count > 0)
                                {
                                    var prods = new HashSet<string>();
                                    foreach (var bv in settlement.BoundVillages)
                                    {
                                        if (bv?.Settlement?.Village?.VillageType == null) continue;
                                        string prodName = null;
                                        var bvt = bv.Settlement.Village.VillageType;
                                        try { prodName = bvt.PrimaryProduction?.Name?.ToString(); } catch { }
                                        if (string.IsNullOrEmpty(prodName))
                                            try { prodName = bvt.PrimaryProduction?.StringId; } catch { }
                                        if (string.IsNullOrEmpty(prodName))
                                            try { prodName = bvt.ShortName?.ToString(); } catch { }
                                        if (string.IsNullOrEmpty(prodName))
                                            try { prodName = bvt.StringId; } catch { }
                                        if (string.IsNullOrEmpty(prodName))
                                            try { prodName = bvt.ToString(); } catch { }
                                        if (!string.IsNullOrEmpty(prodName) && prodName.Contains("_"))
                                            prodName = System.Globalization.CultureInfo.InvariantCulture.TextInfo.ToTitleCase(prodName.Replace("_", " "));
                                        if (!string.IsNullOrEmpty(prodName)) prods.Add(prodName);
                                    }
                                    if (prods.Count > 0)
                                        addStat("Village Produces", string.Join(", ", prods));
                                }
                            }
                            catch (Exception ex) { MCMSettings.DebugLog("Patches: village produces aggregation failed: " + ex.ToString()); }
                        }

                        if (settlement.IsVillage && settlement.Village != null)
                        {
                            try { addStat("Hearths", ((int)settlement.Village.Hearth).ToString()); } catch (Exception ex) { MCMSettings.DebugLog("Patches: stat injection failed: " + ex.ToString()); }
                            try { var bt = settlement.Village.Bound?.Name?.ToString(); if (!string.IsNullOrEmpty(bt)) addStat("Bound To", bt); } catch (Exception ex) { MCMSettings.DebugLog("Patches: stat injection failed: " + ex.ToString()); }
                            try { addStat("Militia", ((int)settlement.Militia).ToString()); } catch (Exception ex) { MCMSettings.DebugLog("Patches: stat injection failed: " + ex.ToString()); }

                            // Village production
                            try
                            {
                                var vt = settlement.Village.VillageType;
                                MCMSettings.DebugLog("Village VillageType: " + (vt != null ? vt.GetType().Name + " = " + vt.ToString() : "null"));
                                if (vt != null)
                                {
                                    string prodName = null;
                                    try { prodName = vt.PrimaryProduction?.Name?.ToString(); } catch { }
                                    if (string.IsNullOrEmpty(prodName))
                                        try { prodName = vt.PrimaryProduction?.StringId; } catch { }
                                    if (string.IsNullOrEmpty(prodName))
                                        try { prodName = vt.ShortName?.ToString(); } catch { }
                                    if (string.IsNullOrEmpty(prodName))
                                        try { prodName = vt.StringId; } catch { }
                                    if (string.IsNullOrEmpty(prodName))
                                        try { prodName = vt.ToString(); } catch { }
                                    // Clean up internal IDs
                                    if (!string.IsNullOrEmpty(prodName) && prodName.Contains("_"))
                                        prodName = System.Globalization.CultureInfo.InvariantCulture.TextInfo.ToTitleCase(prodName.Replace("_", " "));
                                    if (!string.IsNullOrEmpty(prodName))
                                        addStat("Produces", prodName);
                                    else
                                        MCMSettings.DebugLog("Village produces: all lookups returned null/empty");
                                }
                            }
                            catch (Exception ex) { MCMSettings.DebugLog("Patches: village produces failed: " + ex.ToString()); }

                            // Village notables
                            try
                            {
                                int notables = 0;
                                if (settlement.Notables != null)
                                    foreach (var n in settlement.Notables)
                                        if (n != null && n.IsAlive) notables++;
                                addStat("Notables", notables.ToString());
                            }
                            catch (Exception ex) { MCMSettings.DebugLog("Patches: stat item injection failed: " + ex.ToString()); }
                        }

                        MCMSettings.DebugLog("Settlement stats injected via native VM for " + settlement.StringId);
                    }
                    else
                    {
                        MCMSettings.DebugLog("Settlement stats: falling back to widget injection");
                        var fallbackStats = new List<KeyValuePair<string, string>>();
                        Action<string, string> addFb = (l, v) => { if (!string.IsNullOrEmpty(v)) fallbackStats.Add(new KeyValuePair<string, string>(l, v)); };

                        try { addFb("Owner", settlement.OwnerClan?.Leader?.Name?.ToString() ?? "None"); } catch (Exception ex) { MCMSettings.DebugLog("Patches: fallback Owner stat failed: " + ex.ToString()); }
                        try { addFb("Clan", settlement.OwnerClan?.Name?.ToString() ?? "None"); } catch (Exception ex) { MCMSettings.DebugLog("Patches: fallback Clan stat failed: " + ex.ToString()); }
                        try { addFb("Kingdom", settlement.OwnerClan?.Kingdom?.Name?.ToString() ?? "None"); } catch (Exception ex) { MCMSettings.DebugLog("Patches: fallback Kingdom stat failed: " + ex.ToString()); }
                        try {
                            string fbCulture = null;
                            if (settlement.OwnerClan?.Leader != null)
                                fbCulture = EncyclopediaPatchHelper.ResolveCustomCultureDisplay(settlement.OwnerClan.Leader.StringId);
                            if (string.IsNullOrEmpty(fbCulture))
                                fbCulture = settlement.Culture?.Name?.ToString() ?? "Unknown";
                            addFb("Culture", fbCulture);
                        } catch (Exception ex) { MCMSettings.DebugLog("Patches: fallback Culture stat failed: " + ex.ToString()); }

                        if (settlement.IsTown || settlement.IsCastle)
                        {
                            var town = settlement.Town;
                            if (town != null)
                            {
                                try { addFb("Prosperity", ((int)town.Prosperity).ToString()); } catch (Exception ex) { MCMSettings.DebugLog("Patches: fallback Prosperity stat failed: " + ex.ToString()); }
                                try { addFb("Loyalty", ((int)town.Loyalty).ToString()); } catch (Exception ex) { MCMSettings.DebugLog("Patches: fallback Loyalty stat failed: " + ex.ToString()); }
                                try { addFb("Security", ((int)town.Security).ToString()); } catch (Exception ex) { MCMSettings.DebugLog("Patches: fallback Security stat failed: " + ex.ToString()); }
                                try { addFb("Food", ((int)town.FoodStocks).ToString()); } catch (Exception ex) { MCMSettings.DebugLog("Patches: fallback Food stat failed: " + ex.ToString()); }
                                try { addFb("Garrison", (town.GarrisonParty?.MemberRoster?.TotalManCount ?? 0).ToString()); } catch (Exception ex) { MCMSettings.DebugLog("Patches: fallback Garrison stat failed: " + ex.ToString()); }
                                try { addFb("Militia", ((int)settlement.Militia).ToString()); } catch (Exception ex) { MCMSettings.DebugLog("Patches: fallback Militia stat failed: " + ex.ToString()); }
                                try { string govName = town.Governor?.Name?.ToString(); addFb("Governor", !string.IsNullOrEmpty(govName) ? govName : "None"); } catch (Exception ex) { MCMSettings.DebugLog("Patches: fallback Governor stat failed: " + ex.ToString()); }
                                if (settlement.IsTown)
                                {
                                    try
                                    {
                                        var wsNames = new System.Text.StringBuilder();
                                        int wc = 0;
                                        if (town.Workshops != null)
                                            foreach (var ws in town.Workshops)
                                            {
                                                if (ws == null || ws.WorkshopType == null) continue;
                                                bool isHidden = false;
                                                try { isHidden = ws.WorkshopType.IsHidden; } catch { }
                                                if (isHidden) continue;
                                                string wsName = null;
                                                try { wsName = ws.WorkshopType.Name?.ToString(); } catch { }
                                                if (string.IsNullOrEmpty(wsName)) try { wsName = ws.WorkshopType.StringId; } catch { }
                                                if (string.IsNullOrEmpty(wsName)) try { wsName = ws.WorkshopType.ToString(); } catch { }
                                                if (!string.IsNullOrEmpty(wsName) && wsName.Contains("_"))
                                                    wsName = System.Globalization.CultureInfo.InvariantCulture.TextInfo.ToTitleCase(wsName.Replace("_", " "));
                                                if (!string.IsNullOrEmpty(wsName)) { if (wc > 0) wsNames.Append(", "); wsNames.Append(wsName); }
                                                wc++;
                                            }
                                        addFb("Workshops", wc > 0 ? wc + " (" + wsNames.ToString() + ")" : "0");
                                    }
                                    catch (Exception ex) { MCMSettings.DebugLog("Patches: fallback Workshops stat failed: " + ex.ToString()); }
                                }
                                try { addFb("Trade Tax", ((int)town.TradeTaxAccumulated) > 0 ? ((int)town.TradeTaxAccumulated).ToString("N0") + " denars" : "0"); } catch (Exception ex) { MCMSettings.DebugLog("Patches: fallback Trade Tax stat failed: " + ex.ToString()); }
                                try { int notables = 0; if (settlement.Notables != null) foreach (var n in settlement.Notables) if (n != null && n.IsAlive) notables++; addFb("Notables", notables.ToString()); } catch (Exception ex) { MCMSettings.DebugLog("Patches: fallback Notables stat failed: " + ex.ToString()); }
                            }
                            try { addFb("Villages", (settlement.BoundVillages?.Count ?? 0).ToString()); } catch (Exception ex) { MCMSettings.DebugLog("Patches: fallback Villages stat failed: " + ex.ToString()); }
                            try
                            {
                                if (settlement.BoundVillages != null && settlement.BoundVillages.Count > 0)
                                {
                                    var prods = new HashSet<string>();
                                    foreach (var bv in settlement.BoundVillages)
                                    {
                                        if (bv?.Settlement?.Village?.VillageType == null) continue;
                                        string prodName = null;
                                        var bvt = bv.Settlement.Village.VillageType;
                                        try { prodName = bvt.PrimaryProduction?.Name?.ToString(); } catch { }
                                        if (string.IsNullOrEmpty(prodName)) try { prodName = bvt.PrimaryProduction?.StringId; } catch { }
                                        if (string.IsNullOrEmpty(prodName)) try { prodName = bvt.ShortName?.ToString(); } catch { }
                                        if (string.IsNullOrEmpty(prodName)) try { prodName = bvt.StringId; } catch { }
                                        if (!string.IsNullOrEmpty(prodName) && prodName.Contains("_"))
                                            prodName = System.Globalization.CultureInfo.InvariantCulture.TextInfo.ToTitleCase(prodName.Replace("_", " "));
                                        if (!string.IsNullOrEmpty(prodName)) prods.Add(prodName);
                                    }
                                    if (prods.Count > 0) addFb("Village Produces", string.Join(", ", prods));
                                }
                            }
                            catch (Exception ex) { MCMSettings.DebugLog("Patches: fallback Village Produces failed: " + ex.ToString()); }
                        }

                        if (settlement.IsVillage && settlement.Village != null)
                        {
                            try { addFb("Hearths", ((int)settlement.Village.Hearth).ToString()); } catch (Exception ex) { MCMSettings.DebugLog("Patches: fallback Hearths stat failed: " + ex.ToString()); }
                            try { var bt = settlement.Village.Bound?.Name?.ToString(); if (!string.IsNullOrEmpty(bt)) addFb("Bound To", bt); } catch (Exception ex) { MCMSettings.DebugLog("Patches: fallback Bound To stat failed: " + ex.ToString()); }
                            try { addFb("Militia", ((int)settlement.Militia).ToString()); } catch (Exception ex) { MCMSettings.DebugLog("Patches: fallback Militia stat failed: " + ex.ToString()); }
                            try
                            {
                                var vt = settlement.Village.VillageType;
                                if (vt != null)
                                {
                                    string prodName = null;
                                    try { prodName = vt.PrimaryProduction?.Name?.ToString(); } catch { }
                                    if (string.IsNullOrEmpty(prodName)) try { prodName = vt.PrimaryProduction?.StringId; } catch { }
                                    if (string.IsNullOrEmpty(prodName)) try { prodName = vt.ShortName?.ToString(); } catch { }
                                    if (string.IsNullOrEmpty(prodName)) try { prodName = vt.StringId; } catch { }
                                    if (!string.IsNullOrEmpty(prodName) && prodName.Contains("_"))
                                        prodName = System.Globalization.CultureInfo.InvariantCulture.TextInfo.ToTitleCase(prodName.Replace("_", " "));
                                    if (!string.IsNullOrEmpty(prodName)) addFb("Produces", prodName);
                                }
                            }
                            catch (Exception ex) { MCMSettings.DebugLog("Patches: fallback Produces stat failed: " + ex.ToString()); }
                            try { int notables = 0; if (settlement.Notables != null) foreach (var n in settlement.Notables) if (n != null && n.IsAlive) notables++; addFb("Notables", notables.ToString()); } catch (Exception ex) { MCMSettings.DebugLog("Patches: fallback Notables stat failed: " + ex.ToString()); }
                        }

                        if (fallbackStats.Count > 0)
                        {
                            StatsWidgetInjector.ClearInjected();
                            StatsWidgetInjector.ScheduleInjection(settlement.StringId, fallbackStats);
                        }
                    }
                }
                catch (Exception statsEx)
                {
                    MCMSettings.DebugLog("Settlement stats injection failed: " + statsEx.Message);
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Settlement patch exception: " + ex.ToString());
                InformationManager.DisplayMessage(
                    new InformationMessage("[EditableEncyclopedia] Settlement Error: " + ex.Message, Colors.Red));
            }
        }

    }

    // ============================================
    //  Edit popup logic
    // ============================================
    public static class EncyclopediaEditPopup
    {
        private static volatile bool _popupOpen = false;

        /// <summary>
        /// Generation counter to invalidate stale closure callbacks.
        /// Incremented each time a popup opens; callbacks compare their captured
        /// generation against the current value and skip refresh if stale.
        /// </summary>
        private static volatile int _popupGeneration = 0;

        /// <summary>
        /// Custom tip text for the next popup. When set, overrides the default edit_tips text.
        /// Cleared after use by TryInjectEditingTips.
        /// </summary>
        internal static string PendingCustomTipText;

        /// <summary>
        /// Whether the edit popup is currently open.
        /// </summary>
        public static bool IsPopupOpen => _popupOpen;

        /// <summary>
        /// Releases the popup state and unblocks encyclopedia input.
        /// </summary>
        private static void ReleasePopup()
        {
            _popupOpen = false;
            // Stop any pending char-limit / preview timers so they don't keep
            // searching for an EditableTextWidget that no longer exists.
            DisposeCharLimitTimer();
            DisposePreviewConstrainTimer();
            EncyclopediaInputBlocker.Unblock();
        }

        /// <summary>
        /// Reads the current text from the EditableTextWidget in the active TextInquiry popup.
        /// Returns null if the widget is not found or the text cannot be read.
        /// Called from the onConfirm delegate to get the authoritative user-typed text,
        /// because the game's VM may return stale text when the widget was set via reflection.
        /// </summary>
        internal static string ReadEditableWidgetText()
        {
            try
            {
                var flags = System.Reflection.BindingFlags.Instance
                          | System.Reflection.BindingFlags.Public
                          | System.Reflection.BindingFlags.NonPublic;

                var topScreen = TaleWorlds.ScreenSystem.ScreenManager.TopScreen;
                if (topScreen == null) return null;

                foreach (var layer in topScreen.Layers)
                {
                    if (!(layer is TaleWorlds.Engine.GauntletUI.GauntletLayer gl)) continue;
                    Widget root = GetLayerRootWidget(gl);
                    if (root == null) continue;
                    var editWidget = FindEditableTextWidget(root);
                    if (editWidget == null || editWidget.Id == "SearchInputWidget") continue;

                    // Try RealText first (the internal backing text), then Text
                    foreach (var propName in new[] { "RealText", "Text" })
                    {
                        var prop = editWidget.GetType().GetProperty(propName, flags);
                        if (prop != null && prop.PropertyType == typeof(string))
                        {
                            string val = prop.GetValue(editWidget) as string;
                            if (val != null) return val;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("ReadEditableWidgetText: " + ex.ToString());
            }
            return null;
        }

        /// <summary>
        /// Shows the native TextInquiry dialog with game styling.
        /// Template/existing text is shown as the description (above input) for reference,
        /// and also injected into the input field via deferred reflection.
        /// </summary>
        internal static void ShowNativeTextInquiry(string title, string currentText, int maxLength,
            Action<string> onConfirm, Action onCancel)
        {
            string defaultText = currentText ?? "";

            // Use the standard constructor. The 2nd param (description) shows as
            // non-editable text above the input field — useful as a template reference.
            // We also inject the text into the input field via deferred reflection.
            var inquiryData = new TextInquiryData(
                title, defaultText, true, true,
                Localization.L("edit_done"), Localization.L("edit_cancel"),
                delegate (string newText) { onConfirm?.Invoke(newText); },
                delegate { onCancel?.Invoke(); },
                false, null);

            EEInquiry.Show(inquiryData, false, false);
            // Set char limit and inject existing text into the input field so the user
            // can edit their existing description rather than retyping from scratch.
            ScheduleCharLimitOverride(maxLength > 0 ? maxLength : 10000, defaultText);
            SchedulePreviewConstrain();
            SchedulePortraitInjection();

            // ShowTextInquiry causes the encyclopedia to navigate to Home as a side effect.
            // Re-navigate back to the page the user was viewing.
            EncyclopediaNavigationGuard.ScheduleNavigateBack();

            MCMSettings.DebugLog("Showed native TextInquiry: " + title);
        }

        // Deferred character limit override — the EditableTextWidget in the text
        // inquiry dialog needs to be patched after the dialog is shown.
        private static volatile int _pendingCharLimit;
        private static string _pendingDefaultText;
        private static int _charLimitRetries;
        private static System.Threading.Timer _charLimitTimer;
        private const int CharLimitRetryDelayMs = 100;
        private const int CharLimitMaxRetries = 15;

        // Deferred preview text constraining — on first open, the preview
        // RichTextWidget may not be populated yet. Retry independently.
        private static volatile bool _previewConstrainPending;
        private static int _previewConstrainRetries;
        private static System.Threading.Timer _previewConstrainTimer;
        private const int PreviewConstrainMaxRetries = 20;
        private const int PreviewConstrainRetryDelayMs = 80;
        private static volatile bool _charLimitPending;

        /// <summary>
        /// Schedules a deferred character limit override on the text inquiry dialog's
        /// EditableTextWidget. Must call after ShowTextInquiry() since the widget is
        /// created asynchronously.
        /// </summary>
        internal static void ScheduleCharLimitOverride(int limit, string defaultText = null)
        {
            DisposeCharLimitTimer();
            _pendingCharLimit = limit;
            _pendingDefaultText = defaultText;
            _charLimitRetries = 0;
            _charLimitPending = true;
        }

        /// <summary>
        /// Must be called from OnApplicationTick to process deferred char limit overrides.
        /// </summary>
        public static void TickCharLimitOverride()
        {
            // Process deferred preview constraining (independent of char limit)
            TickPreviewConstrain();

            if (!_charLimitPending) return;
            _charLimitPending = false;

            if (TryApplyCharLimitToWidget(_pendingCharLimit))
            {
                // Schedule a few more re-applications to catch the game resetting the limit.
                // Some game versions re-validate widget properties after a few frames.
                _charLimitRetries++;
                if (_charLimitRetries < 5)
                {
                    _charLimitTimer = new System.Threading.Timer(_ =>
                    {
                        _charLimitPending = true;
                    }, null, 300, System.Threading.Timeout.Infinite);
                }
                else
                {
                    DisposeCharLimitTimer();
                }
                return;
            }

            _charLimitRetries++;
            if (_charLimitRetries < CharLimitMaxRetries)
            {
                MCMSettings.DebugLog("TextInquiry: widget not found yet, retry #" + _charLimitRetries);
                _charLimitTimer = new System.Threading.Timer(_ =>
                {
                    _charLimitPending = true;
                }, null, CharLimitRetryDelayMs, System.Threading.Timeout.Infinite);
            }
            else
            {
                MCMSettings.DebugLog("TextInquiry: gave up finding EditableTextWidget after " + CharLimitMaxRetries + " retries");
                DisposeCharLimitTimer();
            }
        }

        private static void DisposeCharLimitTimer()
        {
            var t = _charLimitTimer;
            _charLimitTimer = null;
            if (t != null)
                try { t.Dispose(); } catch (Exception ex) { MCMSettings.DebugLog("Patches: timer dispose failed: " + ex.ToString()); }
        }

        /// <summary>
        /// Schedules deferred preview text constraining. Called after the TextInquiry
        /// is shown so the preview widget can be found once the dialog is built.
        /// </summary>
        internal static void SchedulePreviewConstrain()
        {
            DisposePreviewConstrainTimer();
            _previewConstrainRetries = 0;
            _previewConstrainPending = true;
        }

        /// <summary>
        /// Must be called from OnApplicationTick (via TickCharLimitOverride) to process
        /// deferred preview constraining.
        /// </summary>
        private static void TickPreviewConstrain()
        {
            // Also tick portrait injection (runs independently)
            TickPortraitInjection();

            if (!_previewConstrainPending) return;
            _previewConstrainPending = false;

            if (TryFindAndConstrainPreview())
            {
                MCMSettings.DebugLog("TextInquiry: deferred preview constrain succeeded on retry #" + _previewConstrainRetries);
                DisposePreviewConstrainTimer();
                // Schedule portrait injection now that the dialog is ready
                SchedulePortraitInjection();
                return;
            }

            _previewConstrainRetries++;
            if (_previewConstrainRetries < PreviewConstrainMaxRetries)
            {
                MCMSettings.DebugLog("TextInquiry: preview not ready yet, scheduling retry #" + _previewConstrainRetries);
                _previewConstrainTimer = new System.Threading.Timer(_ =>
                {
                    _previewConstrainPending = true;
                }, null, PreviewConstrainRetryDelayMs, System.Threading.Timeout.Infinite);
            }
            else
            {
                MCMSettings.DebugLog("TextInquiry: gave up finding preview after " + PreviewConstrainMaxRetries + " retries");
                DisposePreviewConstrainTimer();
            }
        }

        private static void DisposePreviewConstrainTimer()
        {
            var t = _previewConstrainTimer;
            _previewConstrainTimer = null;
            if (t != null)
                try { t.Dispose(); } catch (Exception ex) { MCMSettings.DebugLog("Patches: timer dispose failed: " + ex.ToString()); }
        }

        // ─────────── Deferred Portrait Injection ───────────

        private static volatile bool _portraitPending;
        private static int _portraitRetries;
        private static System.Threading.Timer _portraitTimer;
        // Deferred positioning: portrait is created hidden, then positioned on next tick
        private static volatile bool _portraitPositionPending;
        private static Widget _portraitWidget;
        private static Widget _portraitTargetPanel;
        private const int PortraitMaxRetries = 10;
        private const int PortraitRetryDelayMs = 150;
        private const string PortraitMarkerId = "__EE_Portrait";
        private static bool _useBannerColors = false;
        private static uint _bannerColor1 = 0;
        private static uint _bannerColor2 = 0;
        private static Clan _bannerClan = null;

        /// <summary>
        /// Schedules deferred portrait injection into the native TextInquiry header.
        /// </summary>
        internal static void SchedulePortraitInjection()
        {
            if (MCMSettings.Instance != null && !MCMSettings.Instance.ShowEditPopupPortrait)
                return; // Portrait disabled via MCM
            DisposePortraitTimer();
            _portraitRetries = 0;
            _portraitPending = true;
        }

        private static void TickPortraitInjection()
        {
            // Phase 2: Deferred positioning (runs after layout is calculated)
            if (_portraitPositionPending)
            {
                _portraitPositionPending = false;
                TryPositionPortrait();
            }

            if (!_portraitPending) return;
            _portraitPending = false;

            if (TryInjectPortrait())
            {
                MCMSettings.DebugLog("TextInquiry: portrait injection succeeded on retry #" + _portraitRetries);
                DisposePortraitTimer();
                return;
            }

            _portraitRetries++;
            if (_portraitRetries < PortraitMaxRetries)
            {
                _portraitTimer = new System.Threading.Timer(_ =>
                {
                    _portraitPending = true;
                }, null, PortraitRetryDelayMs, System.Threading.Timeout.Infinite);
            }
            else
            {
                MCMSettings.DebugLog("TextInquiry: gave up portrait injection after " + PortraitMaxRetries + " retries");
                DisposePortraitTimer();
            }
        }

        /// <summary>
        /// Phase 2: Position the portrait using the dialog's GlobalPosition (available after layout).
        /// The portrait was created hidden on the layer root in Phase 1.
        /// </summary>
        private static void TryPositionPortrait()
        {
            try
            {
                var portrait = _portraitWidget;
                var panel = _portraitTargetPanel;
                if (portrait == null || panel == null) return;

                var flags = System.Reflection.BindingFlags.Instance
                    | System.Reflection.BindingFlags.Public
                    | System.Reflection.BindingFlags.NonPublic;

                // Read GlobalPosition of both panel and root via reflection
                // GlobalPosition is in screen coords; MarginLeft is root-relative.
                // Must subtract root's GlobalPosition to convert.
                float panelX = 0, panelY = 0, rootX = 0, rootY = 0;
                var gp = panel.GetType().GetProperty("GlobalPosition", flags);
                if (gp != null)
                {
                    var pos = gp.GetValue(panel);
                    if (pos != null)
                    {
                        var xField = pos.GetType().GetField("X");
                        var yField = pos.GetType().GetField("Y");
                        if (xField != null) panelX = (float)xField.GetValue(pos);
                        if (yField != null) panelY = (float)yField.GetValue(pos);
                    }
                    // Read root's GlobalPosition
                    var rootWidget = portrait.ParentWidget;
                    if (rootWidget != null)
                    {
                        var rootPos = gp.GetValue(rootWidget);
                        if (rootPos != null)
                        {
                            var xField = rootPos.GetType().GetField("X");
                            var yField = rootPos.GetType().GetField("Y");
                            if (xField != null) rootX = (float)xField.GetValue(rootPos);
                            if (yField != null) rootY = (float)yField.GetValue(rootPos);
                        }
                    }
                }

                MCMSettings.DebugLog("TextInquiry: deferred position — panel=("
                    + panelX + "," + panelY + ") root=(" + rootX + "," + rootY + ") panelW=" + panel.SuggestedWidth);

                if (panelX <= 0 && panelY <= 0)
                {
                    MCMSettings.DebugLog("TextInquiry: GlobalPosition still (0,0), scheduling retry");
                    new System.Threading.Timer(_ => { _portraitPositionPending = true; }, null, 200, System.Threading.Timeout.Infinite);
                    return;
                }

                // Use PositionXOffset/PositionYOffset — these bypass the layout engine
                // and set absolute pixel position directly
                float relX = panelX - rootX;
                float relY = panelY - rootY;
                portrait.PositionXOffset = relX + 8;
                portrait.PositionYOffset = relY + 4;
                // Clear any margins that might interfere
                portrait.MarginLeft = 0;
                portrait.MarginTop = 0;
                portrait.IsVisible = true;

                MCMSettings.DebugLog("TextInquiry: portrait positioned at ("
                    + portrait.MarginLeft + "," + portrait.MarginTop + ") — visible");

                // Clear refs
                _portraitWidget = null;
                _portraitTargetPanel = null;
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TextInquiry: TryPositionPortrait error: " + ex.ToString());
                // Show anyway at fallback position
                if (_portraitWidget != null)
                {
                    _portraitWidget.IsVisible = true;
                    _portraitWidget = null;
                    _portraitTargetPanel = null;
                }
            }
        }

        private static void DisposePortraitTimer()
        {
            var t = _portraitTimer;
            _portraitTimer = null;
            if (t != null)
                try { t.Dispose(); } catch (Exception ex) { MCMSettings.DebugLog("Patches: timer dispose failed: " + ex.ToString()); }
        }

        /// <summary>
        /// Finds the native TextInquiry dialog and injects a portrait row with the
        /// current hero's face at the top, next to the title text.
        /// The title lives in a parent container ABOVE the popupBody (ListPanel),
        /// so we walk up to find the popup panel and search there.
        /// </summary>
        private static bool TryInjectPortrait()
        {
            try
            {
                var hero = EncyclopediaPageTracker.CurrentHero;

                // Reset banner state — ensures no leak from previous popup
                _useBannerColors = false;
                _bannerClan = null;

                // For non-hero pages, try to find a representative hero for the portrait
                if (hero == null)
                {
                    string pageType = EncyclopediaPageTracker.CurrentPageType;
                    string objectId = EncyclopediaPageTracker.CurrentObjectId;

                    if (pageType == "Settlement" && !string.IsNullOrEmpty(objectId))
                    {
                        try
                        {
                            if (Settlement.All != null)
                                foreach (var s in Settlement.All)
                                    if (s != null && s.StringId == objectId) { hero = s.OwnerClan?.Leader; break; }
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: settlement lookup failed: " + ex.ToString()); }
                    }

                    // For Clan/Kingdom pages, use banner colors instead of hero portrait
                    if ((pageType == "Clan" || pageType == "Kingdom") && !string.IsNullOrEmpty(objectId))
                    {
                        _useBannerColors = true;
                        try
                        {
                            Clan bannerClan = null;
                            if (pageType == "Clan")
                            {
                                if (Clan.All != null)
                                    foreach (var c in Clan.All)
                                        if (c != null && c.StringId == objectId) { bannerClan = c; break; }
                            }
                            else if (pageType == "Kingdom")
                            {
                                if (Kingdom.All != null)
                                    foreach (var k in Kingdom.All)
                                        if (k != null && k.StringId == objectId) { bannerClan = k.RulingClan; break; }
                            }

                            if (bannerClan != null)
                            {
                                _bannerClan = bannerClan;
                                _bannerColor1 = bannerClan.Color;
                                _bannerColor2 = bannerClan.Color2;
                                hero = bannerClan.Leader; // use leader for portrait fallback
                            }
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: unexpected error: " + ex.ToString()); }
                    }
                }

                if (hero == null && !_useBannerColors) return true; // no portrait source found, skip silently

                var flags = System.Reflection.BindingFlags.Instance
                          | System.Reflection.BindingFlags.Public
                          | System.Reflection.BindingFlags.NonPublic
                          | System.Reflection.BindingFlags.Static;

                // Find the popup body using the same pattern as TryFindAndConstrainPreview
                var layersToSearch = new List<TaleWorlds.Engine.GauntletUI.GauntletLayer>();
                var topScreen = TaleWorlds.ScreenSystem.ScreenManager.TopScreen;
                if (topScreen != null)
                {
                    foreach (var layer in topScreen.Layers)
                    {
                        if (layer is TaleWorlds.Engine.GauntletUI.GauntletLayer gl)
                            layersToSearch.Add(gl);
                    }
                }

                var smType = typeof(TaleWorlds.ScreenSystem.ScreenManager);
                foreach (var fieldName in new[] { "_globalLayers", "GlobalLayers", "_activeGlobalLayers" })
                {
                    var field = smType.GetField(fieldName, flags);
                    if (field != null)
                    {
                        var globalLayers = field.GetValue(null) as System.Collections.IEnumerable;
                        if (globalLayers != null)
                        {
                            foreach (var obj in globalLayers)
                            {
                                if (obj is TaleWorlds.Engine.GauntletUI.GauntletLayer ggl)
                                    layersToSearch.Add(ggl);
                                else if (obj != null)
                                {
                                    var layerProp = obj.GetType().GetProperty("Layer", flags);
                                    var inner = layerProp?.GetValue(obj) as TaleWorlds.Engine.GauntletUI.GauntletLayer;
                                    if (inner != null) layersToSearch.Add(inner);
                                }
                            }
                        }
                        break;
                    }
                }

                foreach (var gl in layersToSearch)
                {
                    Widget root = GetLayerRootWidget(gl);
                    if (root == null) continue;

                    var editWidget = FindEditableTextWidget(root);
                    if (editWidget == null || editWidget.Id == "SearchInputWidget") continue;

                    Widget directParent = editWidget.ParentWidget;
                    if (directParent == null) continue;

                    Widget popupBody = directParent.ParentWidget;
                    if (popupBody == null || popupBody.ChildCount < 3) continue;

                    // Check if already injected anywhere in the popup tree
                    Widget popupPanel = popupBody.ParentWidget; // DimensionSyncWidget or similar
                    if (popupPanel == null) continue;

                    if (FindWidgetByIdInTree(root, PortraitMarkerId) != null)
                    {
                        MCMSettings.DebugLog("TextInquiry: portrait already injected");
                        return true;
                    }

                    UIContext uiContext = root.EventManager?.Context as UIContext;
                    if (uiContext == null) continue;

                    // CONSTRAINTS LEARNED (Bannerlord 1.3.13):
                    // - DimensionSyncWidget: NEVER add children (breaks background sync)
                    // - popupBody (ListPanel): NEVER add/remove children (crashes GamepadNavigationScope
                    //   in CollectNavigatableChildrenOfWidget — NullReferenceException)
                    // - TextQueryParentWidget: invisible (W=0, H=0)
                    // - Existing widgets: NEVER reparent (crashes gamepad navigation)
                    //
                    // SAFE: Add portrait to the GauntletLayer's ROOT widget, completely outside
                    // the dialog's widget tree and navigation scopes. Use absolute positioning
                    // to overlay it on top of the dialog.

                    // STRATEGY: Use an EXISTING empty child of the DimensionSyncWidget as
                    // the portrait container. The dialog has empty placeholder widgets at
                    // indices [2] and [3]. Modifying PROPERTIES of existing widgets is safe
                    // (proven by TryEnlargeTextInquiryPopup). This avoids adding new children
                    // to DimensionSyncWidget (breaks background) or to popupBody (crashes
                    // GamepadNavigationScope).
                    //
                    // Find an empty widget (ChildCount=0) that isn't popupBody or the header
                    Widget emptySlot = null;
                    for (int ci = popupPanel.ChildCount - 1; ci >= 0; ci--)
                    {
                        var ch = popupPanel.GetChild(ci);
                        if (ch.ChildCount == 0 && ch != popupBody)
                        {
                            emptySlot = ch;
                            MCMSettings.DebugLog("TextInquiry: found empty slot at index " + ci
                                + " type=" + ch.GetType().Name);
                            break;
                        }
                    }

                    if (emptySlot == null)
                    {
                        MCMSettings.DebugLog("TextInquiry: no empty slot found in popupPanel, skipping portrait");
                        return false;
                    }

                    // Keep the empty slot at its ORIGINAL size (0x0) to avoid breaking
                    // DimensionSyncWidget's dimension sync. Instead, add the portrait as a
                    // child that overflows the slot bounds.
                    emptySlot.Id = PortraitMarkerId;
                    emptySlot.ClipContents = false;
                    // DO NOT set margins on emptySlot — the DimensionSyncWidget syncs its
                    // border to include all children's positions. Moving the slot causes
                    // the dialog border to extend around the portrait.
                    // Keep slot at original position; move the portrait CHILD instead.

                    // STRATEGY: Add portrait as a child of the TITLE widget inside popupBody.
                    // This makes portrait + title one unit — when the portrait is bigger,
                    // the title widget grows, popupBody grows, DimensionSyncWidget grows,
                    // and the frame background grows automatically. No separate positioning.
                    Widget titleWidget = null;
                    for (int ti = 0; ti < popupBody.ChildCount; ti++)
                    {
                        Widget candidate = popupBody.GetChild(ti);
                        string tcType = candidate.GetType().Name;
                        if (tcType.Contains("Text"))
                        {
                            titleWidget = candidate;
                            break;
                        }
                    }

                    if (titleWidget != null)
                    {
                        // Mark as injected using the empty slot (don't add children to it)
                        emptySlot.Id = PortraitMarkerId;

                        float portraitSize = 130f;
                        float indent = portraitSize + 16f;

                        // Indent the title text to the right to make room
                        titleWidget.MarginLeft = indent;

                        // Build portrait and position it in the left corner.
                        // Since the title has MarginLeft, use negative margin to push
                        // the portrait back to the popup's left edge.
                        Widget portraitFrame = BuildPortraitFrame(uiContext, hero, flags);
                        portraitFrame.HorizontalAlignment = HorizontalAlignment.Left;
                        portraitFrame.VerticalAlignment = VerticalAlignment.Top;
                        portraitFrame.MarginLeft = -indent + 20f;
                        portraitFrame.MarginTop = 4;
                        titleWidget.AddChild(portraitFrame);

                        // Make title tall enough for portrait
                        float minTitleH = portraitSize + 12f;
                        if (titleWidget.SuggestedHeight < minTitleH)
                        {
                            titleWidget.HeightSizePolicy = SizePolicy.Fixed;
                            titleWidget.SuggestedHeight = minTitleH;
                            titleWidget.ScaledSuggestedHeight = minTitleH;
                        }

                        MCMSettings.DebugLog("TextInquiry: portrait in title left corner, indent=" + indent);

                        // Add a divider line between the title and the description text,
                        // matching the reference popup's horizontal separator.
                        try
                        {
                            var divider = new BrushWidget(uiContext);
                            divider.WidthSizePolicy = SizePolicy.StretchToParent;
                            divider.HeightSizePolicy = SizePolicy.Fixed;
                            divider.SuggestedHeight = 16;
                            divider.ScaledSuggestedHeight = 16;
                            divider.MarginTop = 6;
                            divider.MarginBottom = 6;
                            // Try native encyclopedia-style divider brush first
                            var dividerBrush = TryGetBrushByName(uiContext, "SPOptions.CollapserLine", flags)
                                            ?? TryGetBrushByName(uiContext, "Tooltip.Frame", flags);
                            if (dividerBrush != null)
                                divider.Brush = dividerBrush;
                            // Insert after the title widget in popupBody
                            int titleIdx = -1;
                            for (int di = 0; di < popupBody.ChildCount; di++)
                            {
                                if (popupBody.GetChild(di) == titleWidget) { titleIdx = di; break; }
                            }
                            if (titleIdx >= 0 && titleIdx + 1 < popupBody.ChildCount)
                            {
                                popupBody.AddChildAtIndex(divider, titleIdx + 1);
                                MCMSettings.DebugLog("TextInquiry: divider inserted after title at index " + (titleIdx + 1));
                            }
                        }
                        catch (Exception divEx)
                        {
                            MCMSettings.DebugLog("TextInquiry: divider error: " + divEx.Message);
                        }
                    }
                    else
                    {
                        // Fallback: use the empty slot as before
                        emptySlot.Id = PortraitMarkerId;
                        emptySlot.ClipContents = false;
                        Widget portraitFrame = BuildPortraitFrame(uiContext, hero, flags);
                        portraitFrame.MarginLeft = 14;
                        portraitFrame.MarginTop = 10;
                        emptySlot.AddChild(portraitFrame);
                        MCMSettings.DebugLog("TextInquiry: portrait fallback — injected into empty slot");
                    }
                    return true;
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TextInquiry: TryInjectPortrait error: " + ex.ToString());
            }
            return false;
        }

        // FindTitleWidget and InjectPortraitFrameIntoBody removed —
        // portrait now injected into popupBody via horizontal wrapper strategy,
        // avoiding the DimensionSyncWidget entirely.

        /// <summary>
        /// Builds the portrait frame widget matching the native Bannerlord dialog style:
        /// outer border (3px) + dark inset (2px) + hero face.
        /// Reference: native TextInquiry "Your message to X:" dialog portrait.
        /// Size: 78x78 outer for a 68x68 inner portrait area.
        /// </summary>
        internal static Widget BuildPortraitFrame(UIContext uiContext, Hero hero,
            System.Reflection.BindingFlags flags)
        {
            float portraitSize = 130f; // match native dialog portrait size
            var portraitFrame = new Widget(uiContext);
            portraitFrame.WidthSizePolicy = SizePolicy.Fixed;
            portraitFrame.HeightSizePolicy = SizePolicy.Fixed;
            portraitFrame.SuggestedWidth = portraitSize;
            portraitFrame.SuggestedHeight = portraitSize;
            portraitFrame.ScaledSuggestedWidth = portraitSize;
            portraitFrame.ScaledSuggestedHeight = portraitSize;
            portraitFrame.VerticalAlignment = VerticalAlignment.Top;

            // Outer border — try native dark sprite for textured look
            var portraitBorder = new ImageWidget(uiContext);
            portraitBorder.WidthSizePolicy = SizePolicy.StretchToParent;
            portraitBorder.HeightSizePolicy = SizePolicy.StretchToParent;
            try
            {
                var sdProp = uiContext.GetType().GetProperty("SpriteData", flags);
                var sd = sdProp?.GetValue(uiContext);
                var gs = sd?.GetType().GetMethod("GetSprite", flags);
                var spProp = typeof(ImageWidget).GetProperty("Sprite",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public);
                // Try canvas_dark, then BlankWhiteSquare_9 as fallback
                object sprite = null;
                foreach (string name in new[] { "canvas_dark", "Frame1_canvas", "BlankWhiteSquare_9" })
                {
                    try { sprite = gs?.Invoke(sd, new object[] { name }); } catch (Exception ex) { MCMSettings.DebugLog("Patches: sprite lookup failed: " + ex.ToString()); }
                    if (sprite != null)
                    {
                        spProp?.SetValue(portraitBorder, sprite);
                        MCMSettings.DebugLog("TextInquiry: portrait border sprite = " + name);
                        break;
                    }
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: unexpected error: " + ex.ToString()); }
            portraitBorder.Color = new Color(0.45f, 0.40f, 0.30f, 1f);

            // Dark inner background for the portrait
            var portraitInner = new Widget(uiContext);
            portraitInner.WidthSizePolicy = SizePolicy.StretchToParent;
            portraitInner.HeightSizePolicy = SizePolicy.StretchToParent;
            portraitInner.MarginLeft = 6;
            portraitInner.MarginRight = 6;
            portraitInner.MarginTop = 6;
            portraitInner.MarginBottom = 4;
            portraitInner.Color = new Color(0.06f, 0.05f, 0.03f, 1f);

            // For Clan/Kingdom pages, render banner image
            if (_useBannerColors)
            {
                bool bannerRendered = false;
                try
                {
                    // Try to render actual banner using ImageTypeCode=3
                    bannerRendered = TryCreateBannerImage(uiContext, portraitInner, flags);
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: banner image creation failed: " + ex.ToString()); }

                if (!bannerRendered)
                {
                    // Fallback: use banner colors
                    try
                    {
                        uint c1 = _bannerColor1;
                        float r1 = ((c1 >> 16) & 0xFF) / 255f;
                        float g1 = ((c1 >> 8) & 0xFF) / 255f;
                        float b1 = (c1 & 0xFF) / 255f;
                        portraitInner.Color = new Color(r1, g1, b1, 1f);

                        uint c2 = _bannerColor2;
                        float r2 = ((c2 >> 16) & 0xFF) / 255f;
                        float g2 = ((c2 >> 8) & 0xFF) / 255f;
                        float b2 = (c2 & 0xFF) / 255f;
                        var stripe = new Widget(uiContext);
                        stripe.WidthSizePolicy = SizePolicy.StretchToParent;
                        stripe.HeightSizePolicy = SizePolicy.Fixed;
                        stripe.SuggestedHeight = 40f;
                        stripe.ScaledSuggestedHeight = 40f;
                        stripe.VerticalAlignment = VerticalAlignment.Center;
                        stripe.Color = new Color(r2, g2, b2, 1f);
                        portraitInner.AddChild(stripe);
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: banner color fallback failed: " + ex.ToString()); }
                }
                _useBannerColors = false;
            }
            else
            {
                // Try to create hero face portrait
                bool portraitRendered = TryCreateHeroPortrait(uiContext, hero, portraitInner, flags);
                if (!portraitRendered)
                {
                    // Fallback: clan banner color
                    try
                    {
                        var clanColor = hero.Clan?.Color ?? 0xFF3A2A1A;
                        float r = ((clanColor >> 16) & 0xFF) / 255f;
                        float g = ((clanColor >> 8) & 0xFF) / 255f;
                        float b = (clanColor & 0xFF) / 255f;
                        portraitInner.Color = new Color(r * 0.5f, g * 0.5f, b * 0.5f, 1f);
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: portrait color fallback failed: " + ex.ToString()); }
                }
            }

            portraitBorder.AddChild(portraitInner);
            portraitFrame.AddChild(portraitBorder);
            return portraitFrame;
        }

        /// <summary>
        /// Gets a named brush from the UIContext's BrushFactory.
        /// Same pattern as TagWidgetInjector.TryGetBrushFromFactory.
        /// </summary>
        private static Brush TryGetBrushByName(UIContext uiContext, string brushName,
            System.Reflection.BindingFlags flags)
        {
            if (uiContext == null || string.IsNullOrEmpty(brushName)) return null;
            try
            {
                var factoryProp = uiContext.GetType().GetProperty("BrushFactory", flags)
                    ?? uiContext.GetType().GetProperty("Brushes", flags);
                if (factoryProp == null) return null;

                var factory = factoryProp.GetValue(uiContext);
                if (factory == null) return null;

                var getBrush = factory.GetType().GetMethod("GetBrush",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public,
                    null, new[] { typeof(string) }, null);
                if (getBrush != null)
                    return getBrush.Invoke(factory, new object[] { brushName }) as Brush;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: unexpected error: " + ex.ToString()); }
            return null;
        }

        /// <summary>
        /// Sets a ListPanel to horizontal layout using the correct enum value.
        /// Mirrors the pattern from GlobalChroniclePanel.SetHorizontalLayout.
        /// </summary>
        private static void SetHorizontalLayout(Widget panel, System.Reflection.BindingFlags flags)
        {
            try
            {
                var layoutProp = panel.GetType().GetProperty("StackLayout", flags);
                if (layoutProp == null) return;
                var layout = layoutProp.GetValue(panel);
                if (layout == null) return;
                var methodProp = layout.GetType().GetProperty("LayoutMethod", flags);
                if (methodProp == null || !methodProp.CanWrite) return;
                var enumType = methodProp.PropertyType;
                foreach (var ev in Enum.GetValues(enumType))
                {
                    if (ev.ToString().Contains("HorizontalLeft"))
                    {
                        methodProp.SetValue(layout, ev);
                        MCMSettings.DebugLog("TextInquiry: set horizontal layout = " + ev);
                        return;
                    }
                }
                MCMSettings.DebugLog("TextInquiry: HorizontalLeft enum value not found in " + enumType.Name);
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TextInquiry: SetHorizontalLayout error: " + ex.ToString());
            }
        }

        private static Widget FindWidgetByIdInTree(Widget parent, string id, int depth = 0)
        {
            if (parent == null || depth > 15) return null;
            if (parent.Id == id) return parent;
            for (int i = 0; i < parent.ChildCount; i++)
            {
                var result = FindWidgetByIdInTree(parent.GetChild(i), id, depth + 1);
                if (result != null) return result;
            }
            return null;
        }

        private static Widget FindWidgetByType(Widget root, string typeName, int depth)
        {
            if (root == null || depth > 20) return null;
            if (root.GetType().Name == typeName) return root;
            for (int i = 0; i < root.ChildCount; i++)
            {
                var result = FindWidgetByType(root.GetChild(i), typeName, depth + 1);
                if (result != null) return result;
            }
            return null;
        }

        /// <summary>
        /// Creates a hero face portrait using ImageIdentifierWidget + CharacterImageTextureProvider.
        /// Proven pipeline: resolve types -> create CharacterCode -> get imageId from VM ->
        /// create widget + set provider properties -> create concrete provider + assign.
        /// </summary>
        private static bool TryCreateHeroPortrait(UIContext uiContext, Hero hero, Widget container,
            System.Reflection.BindingFlags flags)
        {
            try
            {
                // Step 1: Resolve required types from loaded assemblies
                Type imgWidgetType = null, charCodeType = null, charImgIdType = null;
                Type charImgIdVMType = null;
                foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                {
                    imgWidgetType = imgWidgetType ?? asm.GetType("TaleWorlds.MountAndBlade.GauntletUI.Widgets.ImageIdentifierWidget");
                    charCodeType = charCodeType ?? asm.GetType("TaleWorlds.Core.CharacterCode");
                    charImgIdType = charImgIdType ?? asm.GetType("TaleWorlds.Core.ImageIdentifiers.CharacterImageIdentifier");
                    charImgIdVMType = charImgIdVMType ?? asm.GetType("TaleWorlds.Core.ViewModelCollection.ImageIdentifiers.CharacterImageIdentifierVM");
                }

                MCMSettings.DebugLog("TextInquiry: portrait types — Widget=" + (imgWidgetType != null)
                    + " CharCode=" + (charCodeType != null) + " CharImgId=" + (charImgIdType != null)
                    + " CharImgIdVM=" + (charImgIdVMType != null));

                if (imgWidgetType == null || charCodeType == null)
                {
                    MCMSettings.DebugLog("TextInquiry: portrait — missing critical types");
                    return false;
                }

                // Step 2: Create CharacterCode from hero
                System.Reflection.MethodInfo createFrom = null;
                var heroCharType = hero.CharacterObject.GetType();
                foreach (var m in charCodeType.GetMethods(System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public))
                {
                    if (m.Name != "CreateFrom") continue;
                    var parms = m.GetParameters();
                    if (parms.Length == 1 && parms[0].ParameterType.IsAssignableFrom(heroCharType))
                    { createFrom = m; break; }
                }
                if (createFrom == null)
                {
                    MCMSettings.DebugLog("TextInquiry: portrait — CreateFrom method not found");
                    return false;
                }

                var charCode = createFrom.Invoke(null, new object[] { hero.CharacterObject });
                if (charCode == null)
                {
                    MCMSettings.DebugLog("TextInquiry: portrait — CreateFrom returned null");
                    return false;
                }

                // Step 3: Create ImageIdentifierWidget and set TextureProviderName
                var imgWidget = (Widget)Activator.CreateInstance(imgWidgetType, new object[] { uiContext });
                imgWidget.WidthSizePolicy = SizePolicy.StretchToParent;
                imgWidget.HeightSizePolicy = SizePolicy.StretchToParent;

                // Set TextureProviderName — this creates the provider framework internally
                Type searchType = imgWidgetType;
                while (searchType != null && searchType != typeof(object))
                {
                    var texProvNameProp = searchType.GetProperty("TextureProviderName",
                        System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public
                        | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.DeclaredOnly);
                    if (texProvNameProp != null && texProvNameProp.CanWrite)
                    {
                        texProvNameProp.SetValue(imgWidget, "ImageIdentifierTextureProvider");
                        break;
                    }
                    searchType = searchType.BaseType;
                }

                // Step 4: Get imageId from CharacterImageIdentifierVM
                string imageId = null;
                if (charImgIdVMType != null)
                {
                    object vm = null;
                    // Try constructing VM from CharacterCode directly
                    foreach (var c in charImgIdVMType.GetConstructors())
                    {
                        var cp = c.GetParameters();
                        if (cp.Length == 1 && cp[0].ParameterType.IsAssignableFrom(charCode.GetType()))
                        { vm = c.Invoke(new[] { charCode }); break; }
                    }
                    // Try via CharacterImageIdentifier
                    if (vm == null && charImgIdType != null)
                    {
                        object charImgId = null;
                        foreach (var c in charImgIdType.GetConstructors())
                        {
                            var cp = c.GetParameters();
                            if (cp.Length == 1 && cp[0].ParameterType.IsAssignableFrom(charCode.GetType()))
                            { charImgId = c.Invoke(new[] { charCode }); break; }
                        }
                        if (charImgId != null)
                        {
                            foreach (var c in charImgIdVMType.GetConstructors())
                            {
                                var cp = c.GetParameters();
                                if (cp.Length == 1 && cp[0].ParameterType.IsAssignableFrom(charImgIdType))
                                { vm = c.Invoke(new[] { charImgId }); break; }
                            }
                        }
                    }
                    if (vm != null)
                    {
                        var vmIdProp = vm.GetType().GetProperty("Id", flags);
                        if (vmIdProp != null)
                            imageId = vmIdProp.GetValue(vm) as string;
                    }
                }

                // Fallback: try CharacterImageIdentifier.Id directly
                if (string.IsNullOrEmpty(imageId) && charImgIdType != null)
                {
                    object charImgId = null;
                    foreach (var c in charImgIdType.GetConstructors())
                    {
                        var cp = c.GetParameters();
                        if (cp.Length == 1 && cp[0].ParameterType.IsAssignableFrom(charCode.GetType()))
                        { charImgId = c.Invoke(new[] { charCode }); break; }
                    }
                    if (charImgId != null)
                    {
                        var idProp = charImgIdType.GetProperty("Id", flags);
                        imageId = idProp?.GetValue(charImgId) as string;
                    }
                }

                MCMSettings.DebugLog("TextInquiry: portrait — imageId " + (string.IsNullOrEmpty(imageId) ? "EMPTY" : "ok, length=" + imageId.Length));
                if (string.IsNullOrEmpty(imageId))
                    return false;

                // Step 5: Set ImageTypeCode on widget (if property exists)
                System.Reflection.PropertyInfo imgTypeCodeProp = null;
                searchType = imgWidgetType;
                while (searchType != null && searchType != typeof(object))
                {
                    imgTypeCodeProp = searchType.GetProperty("ImageTypeCode",
                        System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public
                        | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.DeclaredOnly);
                    if (imgTypeCodeProp != null) break;
                    searchType = searchType.BaseType;
                }
                if (imgTypeCodeProp != null && imgTypeCodeProp.CanWrite)
                {
                    try
                    {
                        if (imgTypeCodeProp.PropertyType == typeof(int))
                            imgTypeCodeProp.SetValue(imgWidget, 1);
                        else
                            imgTypeCodeProp.SetValue(imgWidget, Convert.ChangeType(1, imgTypeCodeProp.PropertyType));
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: ImageTypeCode set failed: " + ex.ToString()); }
                }

                // Step 6: Set ImageId and AdditionalArgs via widget properties
                var wIdProp = imgWidgetType.GetProperty("ImageId", flags);
                var wArgsProp = imgWidgetType.GetProperty("AdditionalArgs", flags);
                if (wIdProp != null && wIdProp.CanWrite)
                    wIdProp.SetValue(imgWidget, imageId);
                if (wArgsProp != null && wArgsProp.CanWrite)
                    wArgsProp.SetValue(imgWidget, "");

                // Step 7: Set properties via SetTextureProviderProperty API
                var setTexPropMethod = imgWidgetType.GetMethod("SetTextureProviderProperty",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public
                    | System.Reflection.BindingFlags.NonPublic);
                if (setTexPropMethod != null)
                {
                    setTexPropMethod.Invoke(imgWidget, new object[] { "ImageTypeCode", 1 });
                    setTexPropMethod.Invoke(imgWidget, new object[] { "ImageId", imageId });
                    setTexPropMethod.Invoke(imgWidget, new object[] { "AdditionalArgs", "" });
                    setTexPropMethod.Invoke(imgWidget, new object[] { "IsReleased", false });
                }

                // Step 8: Force IsReleased=false in provider properties dictionary
                searchType = imgWidgetType;
                while (searchType != null && searchType != typeof(object))
                {
                    foreach (var f in searchType.GetFields(System.Reflection.BindingFlags.Instance
                        | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Public
                        | System.Reflection.BindingFlags.DeclaredOnly))
                    {
                        if (f.Name.Contains("roviderPropert") && f.FieldType.IsGenericType)
                        {
                            var dict = f.GetValue(imgWidget) as System.Collections.IDictionary;
                            if (dict != null)
                                dict["IsReleased"] = false;
                        }
                    }
                    searchType = searchType.BaseType;
                }

                // Step 9: Add widget to tree (needed for UIContext propagation)
                container.AddChild(imgWidget);

                // Step 10: Create CharacterImageTextureProvider and assign to widget backing field.
                // CRITICAL: Must use CharacterImageTextureProvider specifically for hero portraits.
                // BannerImageTextureProvider (first alphabetically) crashes when it tries to parse
                // a character code as a banner. Search by name first, then fall back to base type scan.
                Type concreteProviderType = null;
                Type baseProviderType = null;

                // Strategy A: Find CharacterImageTextureProvider directly by name (most reliable)
                foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                {
                    try
                    {
                        foreach (var t in asm.GetTypes())
                        {
                            if (t.Name == "CharacterImageTextureProvider" && !t.IsAbstract)
                            {
                                concreteProviderType = t;
                                MCMSettings.DebugLog("TextInquiry: portrait — found CharacterImageTextureProvider: " + t.FullName);
                                break;
                            }
                            // Also pick up the base type and any fallback while scanning
                            if (t.Name == "ImageIdentifierTextureProvider")
                                baseProviderType = t;
                        }
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: unexpected error: " + ex.ToString()); } // GetTypes() can throw ReflectionTypeLoadException
                    if (concreteProviderType != null) break;
                }

                // Strategy B: If direct name scan failed, try known namespaces for base type
                if (concreteProviderType == null && baseProviderType == null)
                {
                    foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                    {
                        baseProviderType = asm.GetType("TaleWorlds.GauntletUI.ImageIdentifierTextureProvider")
                            ?? asm.GetType("TaleWorlds.MountAndBlade.GauntletUI.ImageIdentifierTextureProvider")
                            ?? asm.GetType("TaleWorlds.Engine.GauntletUI.ImageIdentifierTextureProvider")
                            ?? asm.GetType("TaleWorlds.TwoDimension.ImageIdentifierTextureProvider");
                        if (baseProviderType != null) break;
                    }
                }

                // Strategy C: If we have base type but not concrete, scan subclasses
                if (concreteProviderType == null && baseProviderType != null)
                {
                    foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                    {
                        try
                        {
                            foreach (var t in asm.GetTypes())
                            {
                                if (!t.IsAbstract && baseProviderType.IsAssignableFrom(t))
                                {
                                    if (t.Name == "CharacterImageTextureProvider")
                                    { concreteProviderType = t; break; }
                                    // Only take non-Banner fallbacks
                                    if (concreteProviderType == null && !t.Name.Contains("Banner"))
                                        concreteProviderType = t;
                                }
                            }
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: unexpected error: " + ex.ToString()); }
                        if (concreteProviderType?.Name == "CharacterImageTextureProvider") break;
                    }
                    // Last resort: use base if not abstract
                    if (concreteProviderType == null && !baseProviderType.IsAbstract)
                        concreteProviderType = baseProviderType;
                }

                MCMSettings.DebugLog("TextInquiry: portrait — baseProvider=" + (baseProviderType?.Name ?? "null")
                    + " concreteProvider=" + (concreteProviderType?.Name ?? "null"));

                if (concreteProviderType != null)
                {
                    object provider = null;
                    try { provider = Activator.CreateInstance(concreteProviderType, true); }
                    catch (Exception ex) { MCMSettings.DebugLog("TextInquiry: portrait provider ctor failed: " + (ex.InnerException?.Message ?? ex.Message)); }

                    if (provider != null)
                    {
                        // Set provider properties via SetProperty or direct property setters
                        var pType = provider.GetType();
                        var spMethod = pType.GetMethod("SetProperty",
                            System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public
                            | System.Reflection.BindingFlags.NonPublic);
                        if (spMethod != null)
                        {
                            try
                            {
                                spMethod.Invoke(provider, new object[] { "ImageTypeCode", 1 });
                                spMethod.Invoke(provider, new object[] { "ImageId", imageId });
                                spMethod.Invoke(provider, new object[] { "AdditionalArgs", "" });
                                spMethod.Invoke(provider, new object[] { "IsReleased", false });
                            }
                            catch (Exception ex) { MCMSettings.DebugLog("Patches: unexpected error: " + ex.ToString()); }
                        }
                        else
                        {
                            // Fallback: direct property setters
                            foreach (var propName in new[] { "ImageTypeCode", "ImageId", "AdditionalArgs", "IsReleased" })
                            {
                                var prop = pType.GetProperty(propName, flags);
                                if (prop != null && prop.CanWrite)
                                {
                                    object val = propName == "ImageTypeCode" ? (object)1
                                        : propName == "ImageId" ? (object)imageId
                                        : propName == "AdditionalArgs" ? (object)""
                                        : (object)false;
                                    try { prop.SetValue(provider, val); } catch (Exception ex) { MCMSettings.DebugLog("Patches: provider property set failed: " + ex.ToString()); }
                                }
                            }
                        }

                        // Assign provider to widget's TextureProvider backing field
                        searchType = imgWidgetType;
                        while (searchType != null && searchType != typeof(object))
                        {
                            foreach (var f in searchType.GetFields(System.Reflection.BindingFlags.Instance
                                | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.DeclaredOnly))
                            {
                                if (f.Name.Contains("TextureProvider") && f.Name.Contains("BackingField")
                                    && f.FieldType.IsAssignableFrom(provider.GetType()))
                                {
                                    f.SetValue(imgWidget, provider);
                                    MCMSettings.DebugLog("TextInquiry: portrait provider assigned successfully");
                                    break;
                                }
                            }
                            searchType = searchType.BaseType;
                        }
                    }
                }
                else
                {
                    MCMSettings.DebugLog("TextInquiry: portrait — no concrete provider type found, face will not render");
                }

                MCMSettings.DebugLog("TextInquiry: portrait widget added to container, returning true");
                return true;
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TextInquiry: TryCreateHeroPortrait error: " + ex.Message
                    + (ex.InnerException != null ? " inner: " + ex.InnerException.Message : ""));
                return false;
            }
        }

        /// <summary>
        /// Creates a banner image using ImageIdentifierWidget with ImageTypeCode=3.
        /// Uses the clan's Banner.Serialize() as the imageId, and creates a
        /// BannerTableauTextureProvider to actually render the banner emblem.
        /// </summary>
        private static bool TryCreateBannerImage(UIContext uiContext, Widget container,
            System.Reflection.BindingFlags flags)
        {
            try
            {
                if (_bannerClan == null || _bannerClan.Banner == null) return false;

                // Get banner serialized string
                string bannerCode = _bannerClan.Banner.Serialize();
                if (string.IsNullOrEmpty(bannerCode)) return false;

                MCMSettings.DebugLog("TextInquiry: banner code length=" + bannerCode.Length);

                // Find ImageIdentifierWidget type
                Type imgWidgetType = null;
                foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                {
                    imgWidgetType = imgWidgetType ?? asm.GetType("TaleWorlds.MountAndBlade.GauntletUI.Widgets.ImageIdentifierWidget");
                    if (imgWidgetType != null) break;
                }
                if (imgWidgetType == null) return false;

                // Create widget
                var imgWidget = (Widget)Activator.CreateInstance(imgWidgetType, new object[] { uiContext });
                imgWidget.WidthSizePolicy = SizePolicy.StretchToParent;
                imgWidget.HeightSizePolicy = SizePolicy.StretchToParent;

                // Set TextureProviderName — creates the provider framework internally
                Type searchType = imgWidgetType;
                while (searchType != null && searchType != typeof(object))
                {
                    var texProvNameProp = searchType.GetProperty("TextureProviderName",
                        System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public
                        | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.DeclaredOnly);
                    if (texProvNameProp != null && texProvNameProp.CanWrite)
                    {
                        texProvNameProp.SetValue(imgWidget, "ImageIdentifierTextureProvider");
                        break;
                    }
                    searchType = searchType.BaseType;
                }

                // Set ImageTypeCode = 3 (Banner)
                searchType = imgWidgetType;
                while (searchType != null && searchType != typeof(object))
                {
                    var imgTypeCodeProp = searchType.GetProperty("ImageTypeCode",
                        System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public
                        | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.DeclaredOnly);
                    if (imgTypeCodeProp != null && imgTypeCodeProp.CanWrite)
                    {
                        if (imgTypeCodeProp.PropertyType == typeof(int))
                            imgTypeCodeProp.SetValue(imgWidget, 3);
                        else
                            imgTypeCodeProp.SetValue(imgWidget, Convert.ChangeType(3, imgTypeCodeProp.PropertyType));
                        MCMSettings.DebugLog("TextInquiry: banner ImageTypeCode set to 3");
                        break;
                    }
                    searchType = searchType.BaseType;
                }

                // Set ImageId and AdditionalArgs via widget properties
                var wIdProp = imgWidgetType.GetProperty("ImageId", flags);
                var wArgsProp = imgWidgetType.GetProperty("AdditionalArgs", flags);
                if (wIdProp != null && wIdProp.CanWrite)
                    wIdProp.SetValue(imgWidget, bannerCode);
                if (wArgsProp != null && wArgsProp.CanWrite)
                    wArgsProp.SetValue(imgWidget, "");

                // Set via SetTextureProviderProperty API
                var setTexPropMethod = imgWidgetType.GetMethod("SetTextureProviderProperty",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public
                    | System.Reflection.BindingFlags.NonPublic);
                if (setTexPropMethod != null)
                {
                    setTexPropMethod.Invoke(imgWidget, new object[] { "ImageTypeCode", 3 });
                    setTexPropMethod.Invoke(imgWidget, new object[] { "ImageId", bannerCode });
                    setTexPropMethod.Invoke(imgWidget, new object[] { "AdditionalArgs", "" });
                    setTexPropMethod.Invoke(imgWidget, new object[] { "IsReleased", false });
                }

                // Force IsReleased=false in provider properties dictionary
                searchType = imgWidgetType;
                while (searchType != null && searchType != typeof(object))
                {
                    foreach (var f in searchType.GetFields(System.Reflection.BindingFlags.Instance
                        | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Public
                        | System.Reflection.BindingFlags.DeclaredOnly))
                    {
                        if (f.Name.Contains("roviderPropert") && f.FieldType.IsGenericType)
                        {
                            var dict = f.GetValue(imgWidget) as System.Collections.IDictionary;
                            if (dict != null)
                                dict["IsReleased"] = false;
                        }
                    }
                    searchType = searchType.BaseType;
                }

                // Add widget to tree before creating provider (needed for UIContext propagation)
                container.AddChild(imgWidget);

                // Find BannerTableauTextureProvider (or BannerImageTextureProvider)
                Type bannerProviderType = null;
                Type baseProviderType = null;

                foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                {
                    try
                    {
                        foreach (var t in asm.GetTypes())
                        {
                            if (!t.IsAbstract)
                            {
                                if (t.Name == "BannerTableauTextureProvider")
                                {
                                    bannerProviderType = t;
                                    break;
                                }
                                if (t.Name == "BannerImageTextureProvider" && bannerProviderType == null)
                                    bannerProviderType = t;
                            }
                            if (t.Name == "ImageIdentifierTextureProvider")
                                baseProviderType = t;
                        }
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: unexpected error: " + ex.ToString()); } // GetTypes() can throw ReflectionTypeLoadException
                    if (bannerProviderType?.Name == "BannerTableauTextureProvider") break;
                }

                // Fallback: scan for any Banner-related texture provider subclass
                if (bannerProviderType == null && baseProviderType != null)
                {
                    foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                    {
                        try
                        {
                            foreach (var t in asm.GetTypes())
                            {
                                if (!t.IsAbstract && baseProviderType.IsAssignableFrom(t)
                                    && t.Name.Contains("Banner"))
                                {
                                    bannerProviderType = t;
                                    break;
                                }
                            }
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: unexpected error: " + ex.ToString()); }
                        if (bannerProviderType != null) break;
                    }
                }

                // bannerProvider resolved: baseProvider + bannerProvider types found

                if (bannerProviderType != null)
                {
                    var pType = bannerProviderType;

                    object provider = null;
                    try { provider = Activator.CreateInstance(bannerProviderType, true); }
                    catch (Exception ex) { MCMSettings.DebugLog("TextInquiry: banner provider ctor failed: " + (ex.InnerException?.Message ?? ex.Message)); }

                    if (provider != null)
                    {
                        // PRIMARY: Set BannerCodeText — this is the key property the provider reads
                        bool bannerCodeSet = false;
                        foreach (var propName in new[] { "BannerCodeText", "BannerCode", "BannerKey" })
                        {
                            var prop = pType.GetProperty(propName, flags);
                            if (prop != null && prop.CanWrite && prop.PropertyType == typeof(string))
                            {
                                try
                                {
                                    prop.SetValue(provider, bannerCode);
                                    bannerCodeSet = true;
                                    // BannerCodeText set successfully
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("TextInquiry: banner set " + propName + " failed: " + ex.ToString()); }
                                break;
                            }
                        }

                        // Ensure IsHidden = false
                        var isHiddenProp = pType.GetProperty("IsHidden", flags);
                        if (isHiddenProp != null && isHiddenProp.CanWrite)
                        {
                            try { isHiddenProp.SetValue(provider, false); }
                            catch (Exception ex) { MCMSettings.DebugLog("Patches: provider IsHidden set failed: " + ex.ToString()); }
                        }

                        // Set CustomRenderScale if available
                        var renderScaleProp = pType.GetProperty("CustomRenderScale", flags);
                        if (renderScaleProp != null && renderScaleProp.CanWrite)
                        {
                            try { renderScaleProp.SetValue(provider, 1.0f); }
                            catch (Exception ex) { MCMSettings.DebugLog("Patches: provider CustomRenderScale set failed: " + ex.ToString()); }
                        }

                        // Set IsNineGrid = false (we want the full emblem)
                        var nineGridProp = pType.GetProperty("IsNineGrid", flags);
                        if (nineGridProp != null && nineGridProp.CanWrite)
                        {
                            try { nineGridProp.SetValue(provider, false); }
                            catch (Exception ex) { MCMSettings.DebugLog("Patches: provider IsNineGrid set failed: " + ex.ToString()); }
                        }

                        // SetTargetSize if available (banner tableaus need dimensions)
                        var setTargetSize = pType.GetMethod("SetTargetSize",
                            System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public
                            | System.Reflection.BindingFlags.NonPublic);
                        if (setTargetSize != null)
                        {
                            try
                            {
                                var szParams = setTargetSize.GetParameters();
                                if (szParams.Length == 2)
                                    setTargetSize.Invoke(provider, new object[] { 128, 128 });
                                // SetTargetSize(128,128) called
                            }
                            catch (Exception ex) { MCMSettings.DebugLog("TextInquiry: banner SetTargetSize failed: " + ex.ToString()); }
                        }

                        if (!bannerCodeSet)
                            MCMSettings.DebugLog("TextInquiry: WARNING — BannerCodeText not found, banner may not render");

                        // Assign provider to widget's TextureProvider backing field
                        searchType = imgWidgetType;
                        while (searchType != null && searchType != typeof(object))
                        {
                            foreach (var f in searchType.GetFields(System.Reflection.BindingFlags.Instance
                                | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.DeclaredOnly))
                            {
                                if (f.Name.Contains("TextureProvider") && f.Name.Contains("BackingField")
                                    && f.FieldType.IsAssignableFrom(provider.GetType()))
                                {
                                    f.SetValue(imgWidget, provider);
                                    // banner provider assigned to widget backing field
                                    break;
                                }
                            }
                            searchType = searchType.BaseType;
                        }
                    }
                }
                else
                {
                    MCMSettings.DebugLog("TextInquiry: banner — no banner provider type found, emblem will not render");
                }

                // banner widget added to container
                return true;
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TextInquiry: TryCreateBannerImage error: " + ex.ToString());
                return false;
            }
        }

        /// <summary>
        /// Searches all GauntletLayers for the TextInquiry popup's preview text widget
        /// and constrains it. Returns true if the preview was found and wrapped.
        /// </summary>
        private static bool TryFindAndConstrainPreview()
        {
            try
            {
                var flags = System.Reflection.BindingFlags.Instance
                          | System.Reflection.BindingFlags.Public
                          | System.Reflection.BindingFlags.NonPublic
                          | System.Reflection.BindingFlags.Static;

                var layersToSearch = new List<TaleWorlds.Engine.GauntletUI.GauntletLayer>();

                var topScreen = TaleWorlds.ScreenSystem.ScreenManager.TopScreen;
                if (topScreen != null)
                {
                    foreach (var layer in topScreen.Layers)
                    {
                        if (layer is TaleWorlds.Engine.GauntletUI.GauntletLayer gl)
                            layersToSearch.Add(gl);
                    }
                }

                var smType = typeof(TaleWorlds.ScreenSystem.ScreenManager);
                foreach (var fieldName in new[] { "_globalLayers", "GlobalLayers", "_activeGlobalLayers" })
                {
                    var field = smType.GetField(fieldName, flags);
                    if (field != null)
                    {
                        var globalLayers = field.GetValue(null) as System.Collections.IEnumerable;
                        if (globalLayers != null)
                        {
                            foreach (var obj in globalLayers)
                            {
                                if (obj is TaleWorlds.Engine.GauntletUI.GauntletLayer ggl)
                                {
                                    layersToSearch.Add(ggl);
                                }
                                else if (obj != null)
                                {
                                    var layerProp = obj.GetType().GetProperty("Layer", flags);
                                    if (layerProp != null)
                                    {
                                        var inner = layerProp.GetValue(obj) as TaleWorlds.Engine.GauntletUI.GauntletLayer;
                                        if (inner != null)
                                            layersToSearch.Add(inner);
                                    }
                                }
                            }
                        }
                        break;
                    }
                }

                foreach (var gl in layersToSearch)
                {
                    Widget root = GetLayerRootWidget(gl);
                    if (root == null) continue;

                    // Find the EditableTextWidget first to locate the popup structure
                    var editWidget = FindEditableTextWidget(root);
                    if (editWidget == null || editWidget.Id == "SearchInputWidget") continue;

                    Widget directParent = editWidget.ParentWidget;
                    if (directParent == null) continue;

                    // Check if we already wrapped the preview (look for our marker)
                    Widget popupBody = directParent.ParentWidget;
                    if (popupBody == null) continue;

                    bool alreadyWrapped = false;
                    for (int i = 0; i < popupBody.ChildCount; i++)
                    {
                        var childId = popupBody.GetChild(i).Id;
                        if (childId == PreviewClipMarkerId || childId == PreviewScrollPanelId)
                        { alreadyWrapped = true; break; }
                    }
                    if (alreadyWrapped)
                    {
                        MCMSettings.DebugLog("TextInquiry: preview already wrapped, skipping");
                        return true;
                    }

                    // Try to constrain the preview.
                    // If the popup body has children but no long text, the preview
                    // is short and doesn't need wrapping — return true to stop retrying.
                    bool wrapped = TryConstrainPreviewTextDeferred(popupBody, directParent);
                    if (!wrapped && popupBody.ChildCount > 0)
                    {
                        // Check if any text widget has text populated (even short).
                        // If yes, the dialog is fully built — no point retrying.
                        bool hasAnyText = false;
                        var fl = System.Reflection.BindingFlags.Instance
                            | System.Reflection.BindingFlags.Public
                            | System.Reflection.BindingFlags.NonPublic;
                        for (int i = 0; i < popupBody.ChildCount; i++)
                        {
                            var ch = popupBody.GetChild(i);
                            if (!ch.GetType().Name.Contains("Text")) continue;
                            try
                            {
                                var tp = ch.GetType().GetProperty("Text", fl);
                                if (tp != null)
                                {
                                    string t = tp.GetValue(ch) as string ?? "";
                                    if (t.Length > 0) { hasAnyText = true; break; }
                                }
                            }
                            catch (Exception ex) { MCMSettings.DebugLog("Patches: unexpected error: " + ex.ToString()); }
                        }
                        if (hasAnyText)
                        {
                            // BUGFIX: this used to `return true` ("stop retrying"), which is
                            // what let the LoreStory template preview leak across the screen.
                            //
                            // Popups whose text is passed into TextInquiryData up front (Edit
                            // Description) already hold their full text when this runs, so the
                            // wrap happens and all is well. But popups that RESOLVE their text
                            // after opening - the LoreStory template dialogs, see
                            // ShowSequentialTemplateDialogs / ShowNextTemplateField - still show
                            // only short placeholder text at this instant. Returning true here
                            // declared victory ~4ms in, tore down the retry timer, and nothing
                            // ever wrapped the long text that arrived a moment later. Unwrapped
                            // means untagged, and PreviewTextRenderPrefix only scissor-clips
                            // widgets under PreviewScrollPanelId - hence the full-screen spill.
                            //
                            // Returning false keeps the retry loop alive so a late-populated
                            // preview still gets wrapped. This cannot spin: TickPreviewConstrain
                            // is bounded by PreviewConstrainMaxRetries, and for a genuinely short
                            // preview the retries simply expire having done nothing, which is the
                            // correct outcome anyway.
                            MCMSettings.DebugLog("TextInquiry: preview text is short - retrying in case "
                                + "it is populated later (template dialogs resolve text after open)");
                            return false;
                        }
                    }
                    return wrapped;
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TextInquiry: TryFindAndConstrainPreview error: " + ex.ToString());
            }
            return false;
        }

        /// <summary>
        /// Standalone version of TryConstrainPreviewText that searches the popup body
        /// for the preview text widget. Returns true if found and wrapped.
        /// </summary>
        private static bool TryConstrainPreviewTextDeferred(Widget popupBody, Widget inputContainer)
        {
            try
            {
                var flags = System.Reflection.BindingFlags.Instance
                    | System.Reflection.BindingFlags.Public
                    | System.Reflection.BindingFlags.NonPublic;

                MCMSettings.DebugLog("TextInquiry: deferred preview search — popupBody type=" + popupBody.GetType().Name
                    + " children=" + popupBody.ChildCount);

                for (int i = 0; i < popupBody.ChildCount; i++)
                {
                    Widget child = popupBody.GetChild(i);
                    if (child == inputContainer) continue;
                    if (child.Id == PreviewClipMarkerId || child.Id == PreviewScrollPanelId) continue;
                    // Skip OUR OWN injected tip label. It is a RichTextWidget carrying ~97
                    // characters ("Tip: The preview above shows your current text. ..."), which
                    // sails past the >10 char test below and gets wrapped as if it were the
                    // preview. The finder then reports success and stops, so the REAL preview is
                    // never wrapped, never tagged PreviewScrollPanelId, and PreviewTextRenderPrefix
                    // never scissor-clips it - which is the full-screen text spill.
                    //
                    // Edit Description hid this because its preview already exists on the first
                    // pass and is found before the tip is injected. LoreStory template dialogs
                    // resolve their text later, so by retry time the tip was the only long text
                    // present and it won the race. Confirmed from debug.log: "found preview text
                    // widget type=RichTextWidget textLen=97" immediately after "editing tips
                    // injected".
                    if (child.Id == EditingTipsMarkerId) continue;

                    string typeName = child.GetType().Name;
                    // Skip native popup widgets like AutoHideRichTextWidget (title/description)
                    if (typeName.Contains("AutoHide")) continue;
                    bool isTextWidget = typeName == "TextWidget" || typeName == "RichTextWidget"
                        || typeName.Contains("Text");

                    string text = "";
                    if (isTextWidget)
                    {
                        try
                        {
                            var textProp = child.GetType().GetProperty("Text", flags);
                            if (textProp != null)
                                text = textProp.GetValue(child) as string ?? "";
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: text property read failed: " + ex.ToString()); }
                    }

                    // Also check children
                    if (text.Length < 10 && child.ChildCount > 0)
                    {
                        for (int j = 0; j < child.ChildCount; j++)
                        {
                            Widget grandChild = child.GetChild(j);
                            string gcType = grandChild.GetType().Name;
                            if (gcType.Contains("Text"))
                            {
                                try
                                {
                                    var tp = grandChild.GetType().GetProperty("Text", flags);
                                    if (tp != null)
                                    {
                                        string t = tp.GetValue(grandChild) as string ?? "";
                                        if (t.Length > text.Length) text = t;
                                    }
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: unexpected error: " + ex.ToString()); }
                            }
                        }
                    }

                    if (text.Length < 10) continue;

                    MCMSettings.DebugLog("TextInquiry: deferred — found preview text widget type="
                        + typeName + " textLen=" + text.Length + " at index " + i);

                    WrapPreviewInScrollPanel(popupBody, child, i);
                    return true;
                }

                // Try grandparent level
                Widget grandParent = popupBody.ParentWidget;
                if (grandParent != null && grandParent != popupBody)
                {
                    for (int i = 0; i < grandParent.ChildCount; i++)
                    {
                        Widget child = grandParent.GetChild(i);
                        if (child == popupBody) continue;
                        string typeName = child.GetType().Name;
                        if (!typeName.Contains("Text")) continue;

                        string text = "";
                        try
                        {
                            var textProp = child.GetType().GetProperty("Text", flags);
                            if (textProp != null)
                                text = textProp.GetValue(child) as string ?? "";
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: text property read failed: " + ex.ToString()); }

                        if (text.Length < 10) continue;

                        WrapPreviewInScrollPanel(grandParent, child, i);
                        return true;
                    }
                }

                return false;
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TextInquiry: TryConstrainPreviewTextDeferred error: " + ex.ToString());
                return false;
            }
        }

        /// <summary>
        /// Finds the EditableTextWidget in the text inquiry dialog and sets its character limit.
        /// The InformationManager popup uses a global layer, not a screen layer, so we search
        /// both TopScreen.Layers and ScreenManager's global layers.
        /// </summary>
        private static bool TryApplyCharLimitToWidget(int limit)
        {
            try
            {
                var flags = System.Reflection.BindingFlags.Instance
                          | System.Reflection.BindingFlags.Public
                          | System.Reflection.BindingFlags.NonPublic
                          | System.Reflection.BindingFlags.Static;

                // Collect all GauntletLayers from both the top screen and global layers
                var layersToSearch = new List<TaleWorlds.Engine.GauntletUI.GauntletLayer>();

                var topScreen = TaleWorlds.ScreenSystem.ScreenManager.TopScreen;
                if (topScreen != null)
                {
                    foreach (var layer in topScreen.Layers)
                    {
                        if (layer is TaleWorlds.Engine.GauntletUI.GauntletLayer gl)
                            layersToSearch.Add(gl);
                    }
                }

                // Also search global layers via ScreenManager reflection
                var smType = typeof(TaleWorlds.ScreenSystem.ScreenManager);
                foreach (var fieldName in new[] { "_globalLayers", "GlobalLayers", "_activeGlobalLayers" })
                {
                    var field = smType.GetField(fieldName, flags);
                    if (field != null)
                    {
                        var globalLayers = field.GetValue(null) as System.Collections.IEnumerable;
                        if (globalLayers != null)
                        {
                            foreach (var obj in globalLayers)
                            {
                                // GlobalLayer wraps a ScreenLayer — try to get the inner layers
                                if (obj is TaleWorlds.Engine.GauntletUI.GauntletLayer ggl)
                                {
                                    layersToSearch.Add(ggl);
                                }
                                else if (obj != null)
                                {
                                    // GlobalLayer might have a Layer property
                                    var layerProp = obj.GetType().GetProperty("Layer", flags);
                                    if (layerProp != null)
                                    {
                                        var inner = layerProp.GetValue(obj) as TaleWorlds.Engine.GauntletUI.GauntletLayer;
                                        if (inner != null)
                                            layersToSearch.Add(inner);
                                    }
                                }
                            }
                        }
                        break;
                    }
                }

                MCMSettings.DebugLog("TextInquiry: searching " + layersToSearch.Count + " GauntletLayers for EditableTextWidget");

                foreach (var gl in layersToSearch)
                {
                    Widget root = GetLayerRootWidget(gl);
                    if (root == null) continue;

                    var editWidget = FindEditableTextWidget(root);
                    if (editWidget == null || editWidget.Id == "SearchInputWidget") continue;

                    TrySetCharLimitOnWidget(editWidget, limit);

                    // Pre-populate the input field with default/template text if pending.
                    if (!string.IsNullOrEmpty(_pendingDefaultText))
                    {
                        TrySetWidgetText(editWidget, _pendingDefaultText);
                        _pendingDefaultText = null;
                    }

                    // Enlarge the text area for comfortable lore writing.
                    // Find the popup panel (first Fixed-height widget ancestor) and make it taller,
                    // then enlarge the EditableTextWidget itself.
                    try
                    {
                        TryEnlargeTextInquiryPopup(editWidget);
                    }
                    catch (Exception enlargeEx)
                    {
                        MCMSettings.DebugLog("TextInquiry: enlarge failed: " + enlargeEx.Message);
                    }

                    // Add editing tips hint above the input field.
                    try
                    {
                        TryInjectEditingTips(editWidget);
                    }
                    catch (Exception tipsEx)
                    {
                        MCMSettings.DebugLog("TextInquiry: tips injection failed: " + tipsEx.Message);
                    }

                    return true;
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TextInquiry: error applying char limit: " + ex.ToString());
            }
            return false;
        }

        private static Widget GetLayerRootWidget(TaleWorlds.Engine.GauntletUI.GauntletLayer layer)
        {
            var flags = System.Reflection.BindingFlags.Instance
                      | System.Reflection.BindingFlags.Public
                      | System.Reflection.BindingFlags.NonPublic;
            var type = typeof(TaleWorlds.Engine.GauntletUI.GauntletLayer);

            foreach (var fieldName in new[] { "_gauntletUIContext", "_uiContext", "_context" })
            {
                var field = type.GetField(fieldName, flags);
                if (field != null)
                {
                    var ctx = field.GetValue(layer) as TaleWorlds.GauntletUI.UIContext;
                    if (ctx?.EventManager?.Root != null)
                        return ctx.EventManager.Root;
                }
            }
            foreach (var propName in new[] { "UIContext", "_gauntletUIContext" })
            {
                var prop = type.GetProperty(propName, flags);
                if (prop != null)
                {
                    var ctx = prop.GetValue(layer) as TaleWorlds.GauntletUI.UIContext;
                    if (ctx?.EventManager?.Root != null)
                        return ctx.EventManager.Root;
                }
            }
            // Try _movie._movieRootNode as fallback
            foreach (var movieFieldName in new[] { "_movie", "_gauntletMovie" })
            {
                var movieField = type.GetField(movieFieldName, flags);
                if (movieField == null) continue;
                var movie = movieField.GetValue(layer);
                if (movie == null) continue;
                foreach (var nodeName in new[] { "_movieRootNode", "RootNode" })
                {
                    var nodeField = movie.GetType().GetField(nodeName, flags);
                    if (nodeField != null)
                    {
                        var node = nodeField.GetValue(movie) as Widget;
                        if (node != null) return node;
                    }
                    var nodeProp = movie.GetType().GetProperty(nodeName, flags);
                    if (nodeProp != null)
                    {
                        var node = nodeProp.GetValue(movie) as Widget;
                        if (node != null) return node;
                    }
                }
            }
            return null;
        }

        private static bool TrySetCharLimitOnWidget(Widget editWidget, int limit)
        {
            var flags = System.Reflection.BindingFlags.Instance
                      | System.Reflection.BindingFlags.Public
                      | System.Reflection.BindingFlags.NonPublic;
            var wType = editWidget.GetType();
            bool anySet = false;

            // Set ALL matching properties — don't stop at the first one.
            // The widget may have multiple limit properties that each enforce independently.
            foreach (var propName in new[] { "MaxLength", "MaxCharacterCount", "MaxInputCharacterCount", "CharacterLimit" })
            {
                var prop = wType.GetProperty(propName, flags);
                if (prop != null && prop.CanWrite && prop.PropertyType == typeof(int))
                {
                    prop.SetValue(editWidget, limit);
                    MCMSettings.DebugLog("TextInquiry: set " + propName + " = " + limit + " on " + wType.Name);
                    anySet = true;
                }
            }
            foreach (var fieldName in new[] { "_maxLength", "MaxLength", "<MaxLength>k__BackingField",
                "_maxCharacterCount", "<MaxCharacterCount>k__BackingField" })
            {
                var field = wType.GetField(fieldName, flags);
                if (field != null && field.FieldType == typeof(int))
                {
                    field.SetValue(editWidget, limit);
                    MCMSettings.DebugLog("TextInquiry: set " + fieldName + " = " + limit + " on " + wType.Name);
                    anySet = true;
                }
            }

            if (anySet) return true;

            // Scan for int fields with small limit-like values (128, 256, 512, 1024)
            // and override them all — these are likely character limits.
            foreach (var field in wType.GetFields(flags))
            {
                if (field.FieldType == typeof(int))
                {
                    int val = (int)field.GetValue(editWidget);
                    if (val == 128 || val == 256 || val == 512 || val == 1024)
                    {
                        field.SetValue(editWidget, limit);
                        MCMSettings.DebugLog("TextInquiry: set " + field.Name + " = " + limit
                            + " on " + wType.Name + " (was " + val + ")");
                        anySet = true;
                    }
                }
            }

            if (anySet) return true;

            MCMSettings.DebugLog("TextInquiry: found " + wType.Name + " #" + (editWidget.Id ?? "?")
                + " but no char limit field. Int fields: "
                + string.Join(", ", GetIntFieldSummary(editWidget)));
            return false;
        }

        private static List<string> GetIntFieldSummary(Widget widget)
        {
            var result = new List<string>();
            var flags = System.Reflection.BindingFlags.Instance
                      | System.Reflection.BindingFlags.Public
                      | System.Reflection.BindingFlags.NonPublic;
            foreach (var field in widget.GetType().GetFields(flags))
            {
                if (field.FieldType == typeof(int))
                {
                    try { result.Add(field.Name + "=" + (int)field.GetValue(widget)); } catch (Exception ex) { MCMSettings.DebugLog("Patches: int field summary failed: " + ex.ToString()); }
                }
            }
            return result;
        }

        /// <summary>
        /// Sets the Text property on an EditableTextWidget to pre-populate the input field.
        /// The native TextInquiry's defaultInputText constructor param doesn't work,
        /// so we inject the text directly on the widget via reflection.
        /// </summary>
        private static void TrySetWidgetText(Widget editWidget, string text)
        {
            try
            {
                var flags = System.Reflection.BindingFlags.Instance
                          | System.Reflection.BindingFlags.Public
                          | System.Reflection.BindingFlags.NonPublic;
                var wType = editWidget.GetType();
                bool anySet = false;

                // Set ALL writable string properties that look like text fields.
                // EditableTextWidget may use RealText internally and Text for display —
                // we need to set both to ensure the value shows up AND is returned on confirm.
                foreach (var propName in new[] { "RealText", "Text", "EditText" })
                {
                    var prop = wType.GetProperty(propName, flags);
                    if (prop != null && prop.CanWrite && prop.PropertyType == typeof(string))
                    {
                        prop.SetValue(editWidget, text);
                        MCMSettings.DebugLog("TextInquiry: set " + propName + " on " + wType.Name + " (" + text.Length + " chars)");
                        anySet = true;
                    }
                }

                // Also try backing fields in case properties are read-only wrappers
                if (!anySet)
                {
                    foreach (var fieldName in new[] { "_realText", "_text", "<RealText>k__BackingField", "<Text>k__BackingField" })
                    {
                        var field = wType.GetField(fieldName, flags);
                        if (field != null && field.FieldType == typeof(string))
                        {
                            field.SetValue(editWidget, text);
                            MCMSettings.DebugLog("TextInquiry: set field " + fieldName + " on " + wType.Name + " (" + text.Length + " chars)");
                            anySet = true;
                        }
                    }
                }

                if (!anySet)
                {
                    // Log all string properties for debugging
                    var props = new List<string>();
                    foreach (var p in wType.GetProperties(flags))
                    {
                        if (p.PropertyType == typeof(string))
                            props.Add(p.Name + (p.CanWrite ? "(rw)" : "(ro)"));
                    }
                    MCMSettings.DebugLog("TextInquiry: could not set text on " + wType.Name
                        + ". String props: " + string.Join(", ", props));
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TextInquiry: error setting text: " + ex.ToString());
            }
        }

        private static Widget FindEditableTextWidget(Widget parent, int depth = 0)
        {
            if (parent == null || depth > 20) return null;
            if (parent.GetType().Name == "EditableTextWidget")
                return parent;
            for (int i = 0; i < parent.ChildCount; i++)
            {
                var result = FindEditableTextWidget(parent.GetChild(i), depth + 1);
                if (result != null) return result;
            }
            return null;
        }

        /// <summary>
        /// Enlarges the native TextInquiry popup so the text area is comfortable
        /// for writing long lore. Walks up from the EditableTextWidget to find
        /// the popup panel and increases its height, then enlarges the text area.
        /// </summary>
        /// <summary>
        /// Marker Id set on the EditableTextWidget's parent after we've already
        /// enlarged it, so retries don't re-process the same widget.
        /// </summary>
        private const string EnlargedMarkerId = "__EE_Enlarged";

        private const string EditingTipsMarkerId = "__EE_EditTips";

        /// <summary>
        /// Adds a small tips hint label just above the input field so the user
        /// knows useful editing shortcuts.
        /// </summary>
        private static void TryInjectEditingTips(Widget editWidget)
        {
            if (editWidget == null) return;

            Widget directParent = editWidget.ParentWidget;
            if (directParent == null) return;

            Widget popupBody = directParent.ParentWidget;
            if (popupBody == null) return;

            // Guard: don't inject twice
            for (int i = 0; i < popupBody.ChildCount; i++)
            {
                if (popupBody.GetChild(i).Id == EditingTipsMarkerId) return;
            }

            try
            {
                var uiContext = editWidget.Context;
                var tipsWidget = new RichTextWidget(uiContext);
                tipsWidget.Id = EditingTipsMarkerId;
                tipsWidget.WidthSizePolicy = SizePolicy.StretchToParent;
                tipsWidget.HeightSizePolicy = SizePolicy.CoverChildren;
                tipsWidget.MarginBottom = 4;
                tipsWidget.MarginLeft = 6;

                string customTip = PendingCustomTipText;
                PendingCustomTipText = null;
                tipsWidget.Text = !string.IsNullOrEmpty(customTip) ? customTip : Localization.L("edit_tips");

                // Style: small, muted text
                try
                {
                    var brushProp = typeof(RichTextWidget).GetProperty("Brush",
                        System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public);
                    if (brushProp != null)
                    {
                        var existingBrush = brushProp.GetValue(editWidget) as Brush;
                        if (existingBrush != null)
                        {
                            var tipsBrush = existingBrush.Clone();
                            // Make it smaller and dimmer
                            try
                            {
                                var fontSizeP = tipsBrush.GetType().GetProperty("FontSize",
                                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public);
                                if (fontSizeP != null)
                                    fontSizeP.SetValue(tipsBrush, 18);

                                var fontColorP = tipsBrush.GetType().GetProperty("FontColor",
                                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public);
                                if (fontColorP != null)
                                    fontColorP.SetValue(tipsBrush, new Color(0.6f, 0.55f, 0.45f, 0.7f));
                            }
                            catch (Exception ex) { MCMSettings.DebugLog("Patches: unexpected error: " + ex.ToString()); }
                            brushProp.SetValue(tipsWidget, tipsBrush);
                        }
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: tips brush assignment failed: " + ex.ToString()); }

                // Insert just before the input container
                int inputIdx = -1;
                for (int i = 0; i < popupBody.ChildCount; i++)
                {
                    if (popupBody.GetChild(i) == directParent) { inputIdx = i; break; }
                }
                if (inputIdx >= 0)
                    popupBody.AddChildAtIndex(tipsWidget, inputIdx);
                else
                    popupBody.AddChild(tipsWidget);

                MCMSettings.DebugLog("TextInquiry: editing tips injected");
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TextInquiry: TryInjectEditingTips error: " + ex.ToString());
            }
        }

        private static void TryEnlargeTextInquiryPopup(Widget editWidget)
        {
            if (editWidget == null) return;

            // Guard: skip if we've already processed this widget tree
            Widget directParent = editWidget.ParentWidget;
            if (directParent != null && directParent.Id == EnlargedMarkerId)
            {
                MCMSettings.DebugLog("TextInquiry: already enlarged, skipping");
                return;
            }

            float targetEditHeight = 70f; // keep input box compact, like native dialog
            MCMSettings.DebugLog("TextInquiry: parent type=" + (directParent?.GetType().Name ?? "null")
                + " H=" + (directParent?.SuggestedHeight ?? 0)
                + " HPolicy=" + (directParent?.HeightSizePolicy.ToString() ?? "?")
                + " children=" + (directParent?.ChildCount ?? 0));

            // ── 1. Enlarge the parent and widget ──
            // Text overflow is handled by the Harmony scissor clipping patch on
            // EditableTextWidget.OnRender (see EditableTextRenderPrefix).
            // ClipContents alone does NOT clip EditableTextWidget text rendering.
            if (directParent != null)
            {
                directParent.HeightSizePolicy = SizePolicy.Fixed;
                directParent.SuggestedHeight = targetEditHeight;
                directParent.ScaledSuggestedHeight = targetEditHeight;
                directParent.ClipContents = true;
                directParent.Id = EnlargedMarkerId;

                MCMSettings.DebugLog("TextInquiry: set parent to Fixed height " + targetEditHeight + " with ClipContents");
            }

            editWidget.HeightSizePolicy = SizePolicy.Fixed;
            editWidget.SuggestedHeight = targetEditHeight;
            editWidget.ScaledSuggestedHeight = targetEditHeight;
            editWidget.WidthSizePolicy = SizePolicy.StretchToParent;
            editWidget.ClipContents = true;

            // ── 2. Constrain the description/preview text widget ──
            // The native TextInquiry shows the full text as a read-only preview
            // ABOVE the input field. This preview has no height constraint and
            // overflows the entire screen for long texts. Find it and clip it.
            TryConstrainPreviewText(directParent, editWidget);

            // Let the native popup auto-size everything. The DimensionSyncWidget
            // handles frame sizing based on content. No forced heights needed.
        }

        private const string PreviewClipMarkerId = "__EE_PreviewClip";
        private const string PreviewScrollPanelId = "__EE_PreviewScrollPanel";
        // 200px, not 350. The popup FRAME (DimensionSyncWidget) does not grow past its own
        // limit, so a taller preview pushes the input field and Cancel/Done below the frame,
        // where they float over the encyclopedia page. 200 is the size this was originally
        // built around - see PreviewTextRenderPrefix's comment, "fixed 200px" - and something
        // later raised it to 350 without adjusting anything else.
        private const float MaxPreviewHeight = 200f;
        // Used to estimate how tall the preview box needs to be so short text does not leave
        // a gap. Approximate by design - see the sizing block in WrapPreviewInScrollPanel.
        private const int PreviewCharsPerLine = 62;
        private const float PreviewLineHeight = 21f;
        // Vertical space the rest of the popup needs: portrait + title + divider, the tip
        // line, the input field, the button row, and outer margins. The preview may only use
        // what is left of the screen after this, or the buttons end up outside the frame.
        private const float PopupChromeReserve = 470f;
        private const float MinPreviewHeight = 140f;
        // Never let the popup frame exceed this share of the screen height.
        private const float MaxPopupScreenFraction = 0.88f;

        /// <summary>
        /// Screen height from the UI context's TwoDimensionContext, or 0 if unavailable.
        /// Used to cap the preview box so the popup still fits on screen.
        /// </summary>
        private static float TryGetScreenHeight(object uiContext)
        {
            try
            {
                if (uiContext == null || _twoDimCtxProp == null) return 0f;
                var tdc = _twoDimCtxProp.GetValue(uiContext);
                if (tdc == null) return 0f;
                var hp = tdc.GetType().GetProperty("Height");
                if (hp == null) return 0f;
                return Convert.ToSingle(hp.GetValue(tdc));
            }
            catch { return 0f; }
        }

        /// <summary>
        /// Finds the description/preview TextWidget in the native TextInquiry popup
        /// (sibling of the EditableTextWidget's container) and constrains its height
        /// to prevent overflow. Also applies scissor clipping since TextWidget renders
        /// text outside ClipContents bounds.
        /// </summary>
        private static void TryConstrainPreviewText(Widget inputContainer, Widget editWidget)
        {
            try
            {
                if (inputContainer == null) return;

                // The popup body is the parent of the input container.
                // It typically contains: TitleText, DescriptionText, InputContainer, Buttons
                Widget popupBody = inputContainer.ParentWidget;
                if (popupBody == null)
                {
                    MCMSettings.DebugLog("TextInquiry: popupBody is null, can't constrain preview");
                    return;
                }

                // Check if already wrapped by deferred path
                for (int c = 0; c < popupBody.ChildCount; c++)
                {
                    if (popupBody.GetChild(c).Id == PreviewScrollPanelId)
                    {
                        MCMSettings.DebugLog("TextInquiry: preview already wrapped by deferred path, skipping");
                        return;
                    }
                }

                MCMSettings.DebugLog("TextInquiry: popupBody type=" + popupBody.GetType().Name
                    + " children=" + popupBody.ChildCount + " H=" + popupBody.SuggestedHeight);

                var flags = System.Reflection.BindingFlags.Instance
                    | System.Reflection.BindingFlags.Public
                    | System.Reflection.BindingFlags.NonPublic;

                // Walk popupBody's children to find text widgets that aren't the input container
                for (int i = 0; i < popupBody.ChildCount; i++)
                {
                    Widget child = popupBody.GetChild(i);
                    if (child == inputContainer) continue;
                    if (child.Id == PreviewClipMarkerId || child.Id == PreviewScrollPanelId) continue;
                    // Skip OUR OWN injected tip label. It is a RichTextWidget carrying ~97
                    // characters ("Tip: The preview above shows your current text. ..."), which
                    // sails past the >10 char test below and gets wrapped as if it were the
                    // preview. The finder then reports success and stops, so the REAL preview is
                    // never wrapped, never tagged PreviewScrollPanelId, and PreviewTextRenderPrefix
                    // never scissor-clips it - which is the full-screen text spill.
                    //
                    // Edit Description hid this because its preview already exists on the first
                    // pass and is found before the tip is injected. LoreStory template dialogs
                    // resolve their text later, so by retry time the tip was the only long text
                    // present and it won the race. Confirmed from debug.log: "found preview text
                    // widget type=RichTextWidget textLen=97" immediately after "editing tips
                    // injected".
                    if (child.Id == EditingTipsMarkerId) continue;

                    string typeName = child.GetType().Name;
                    // Skip native popup widgets like AutoHideRichTextWidget (title/description)
                    if (typeName.Contains("AutoHide")) continue;
                    bool isTextWidget = typeName == "TextWidget" || typeName == "RichTextWidget"
                        || typeName.Contains("Text");

                    // Check if this widget has a Text property with content
                    string text = "";
                    if (isTextWidget)
                    {
                        try
                        {
                            var textProp = child.GetType().GetProperty("Text", flags);
                            if (textProp != null)
                                text = textProp.GetValue(child) as string ?? "";
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: text property read failed: " + ex.ToString()); }
                    }

                    // Also check for widgets containing a text child with longer content
                    if (text.Length < 10 && child.ChildCount > 0)
                    {
                        for (int j = 0; j < child.ChildCount; j++)
                        {
                            Widget grandChild = child.GetChild(j);
                            string gcType = grandChild.GetType().Name;
                            if (gcType.Contains("Text"))
                            {
                                try
                                {
                                    var tp = grandChild.GetType().GetProperty("Text", flags);
                                    if (tp != null)
                                    {
                                        string t = tp.GetValue(grandChild) as string ?? "";
                                        if (t.Length > text.Length) text = t;
                                    }
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: unexpected error: " + ex.ToString()); }
                            }
                        }
                    }

                    if (text.Length < 10 && !isTextWidget) continue;
                    if (text.Length < 10) continue;

                    MCMSettings.DebugLog("TextInquiry: found preview text widget type="
                        + typeName + " textLen=" + text.Length + " at index " + i
                        + " H=" + child.SuggestedHeight + " HPolicy=" + child.HeightSizePolicy);

                    // Wrap the preview in a ScrollablePanel for dark tint + scrolling
                    WrapPreviewInScrollPanel(popupBody, child, i);
                    return;
                }

                // If no text widget found directly, try one more level up — some
                // dialog layouts wrap everything in an extra container
                Widget grandParent = popupBody.ParentWidget;
                if (grandParent != null && grandParent != popupBody)
                {
                    MCMSettings.DebugLog("TextInquiry: no preview in popupBody, trying grandParent type="
                        + grandParent.GetType().Name + " children=" + grandParent.ChildCount);
                    for (int i = 0; i < grandParent.ChildCount; i++)
                    {
                        Widget child = grandParent.GetChild(i);
                        if (child == popupBody) continue;
                        string typeName = child.GetType().Name;
                        if (!typeName.Contains("Text")) continue;

                        string text = "";
                        try
                        {
                            var textProp = child.GetType().GetProperty("Text", flags);
                            if (textProp != null)
                                text = textProp.GetValue(child) as string ?? "";
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: text property read failed: " + ex.ToString()); }

                        if (text.Length < 10) continue;

                        WrapPreviewInScrollPanel(grandParent, child, i);
                        MCMSettings.DebugLog("TextInquiry: wrapped preview at grandParent level");
                        return;
                    }
                }

                MCMSettings.DebugLog("TextInquiry: no preview text widget found to constrain");
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TextInquiry: TryConstrainPreviewText error: " + ex.ToString());
            }
        }

        /// <summary>
        /// Constrains the preview text in the TextInquiry dialog by replacing the
        /// RichTextWidget with a plain TextWidget inside a ScrollablePanel.
        ///
        /// Both RichTextWidget and TextWidget bypass ClipRect during v1.3.13's render pass,
        /// so the PreviewTextRenderPrefix scissor patch clips rendering to the ScrollablePanel's
        /// fixed 200px bounds. The ScrollablePanel handles scroll input to let users read
        /// the full text.
        ///
        /// Falls back to text truncation if required types are unavailable.
        /// </summary>
        private static void WrapPreviewInScrollPanel(Widget parentPanel, Widget previewWidget, int childIndex)
        {
            try
            {
                var uiContext = previewWidget.EventManager?.Context as UIContext;
                if (uiContext == null)
                {
                    TruncatePreviewText(previewWidget);
                    return;
                }

                var allFlags = System.Reflection.BindingFlags.Instance
                    | System.Reflection.BindingFlags.Public
                    | System.Reflection.BindingFlags.NonPublic;

                // ── Read text from the original RichTextWidget ──
                string previewText = "";
                try
                {
                    var textProp = previewWidget.GetType().GetProperty("Text", allFlags);
                    if (textProp != null)
                        previewText = textProp.GetValue(previewWidget) as string ?? "";
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: text property read failed: " + ex.ToString()); }

                if (string.IsNullOrEmpty(previewText))
                    return;

                // ── Find required types ──
                Type scrollPanelType = null;
                Type scrollbarType = null;
                Type listPanelType = null;
                foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                {
                    if (scrollPanelType == null)
                        scrollPanelType = asm.GetType("TaleWorlds.GauntletUI.BaseTypes.ScrollablePanel")
                                       ?? asm.GetType("TaleWorlds.GauntletUI.ExtraWidgets.ScrollablePanel");
                    if (scrollbarType == null)
                        scrollbarType = asm.GetType("TaleWorlds.GauntletUI.BaseTypes.ScrollbarWidget")
                                     ?? asm.GetType("TaleWorlds.GauntletUI.ExtraWidgets.ScrollbarWidget");
                    if (listPanelType == null)
                    {
                        listPanelType = asm.GetType("TaleWorlds.GauntletUI.BaseTypes.ListPanel")
                                     ?? asm.GetType("TaleWorlds.GauntletUI.ListPanel");
                    }
                    if (scrollPanelType != null && scrollbarType != null && listPanelType != null) break;
                }

                if (scrollPanelType == null || listPanelType == null)
                {
                    TruncatePreviewText(previewWidget);
                    return;
                }

                // ── Clone brush from the original RichTextWidget ──
                Brush previewBrush = null;
                try
                {
                    if (previewWidget is BrushWidget bw && bw.ReadOnlyBrush != null)
                        previewBrush = bw.ReadOnlyBrush.Clone();
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: preview brush clone failed: " + ex.ToString()); }

                // ── Build hierarchy BEFORE inserting into widget tree ──

                // 1. Remove original RichTextWidget
                parentPanel.RemoveChild(previewWidget);

                // 2. TextWidget replaces RichTextWidget (TextWidget renders from top, not middle)
                var textWidget = new TextWidget(uiContext);
                textWidget.Id = PreviewClipMarkerId;
                textWidget.Text = previewText;
                textWidget.WidthSizePolicy = SizePolicy.StretchToParent;
                textWidget.HeightSizePolicy = SizePolicy.CoverChildren;
                textWidget.MarginLeft = 40;  // match native popup text inset
                textWidget.MarginRight = 35; // space for scrollbar track
                if (previewBrush != null)
                    textWidget.Brush = previewBrush;

                // 3. Decide: short text gets a simple tinted container,
                //    long text gets a full ScrollablePanel with scrollbar
                bool isLongText = previewText.Length >= 200;
                Widget scrollPanel; // the outer container we insert into the parent

                if (!isLongText)
                {
                    // ── Short text: simple dark-tinted container, no scrollbar ──
                    scrollPanel = new Widget(uiContext);
                    scrollPanel.Id = PreviewScrollPanelId;
                    scrollPanel.WidthSizePolicy = SizePolicy.StretchToParent;
                    scrollPanel.HeightSizePolicy = SizePolicy.CoverChildren;
                    scrollPanel.MarginBottom = 40;
                    scrollPanel.Color = new Color(0.06f, 0.05f, 0.03f, 0.65f);
                    scrollPanel.AddChild(textWidget);
                }
                else
                {
                    // ── Long text: ScrollablePanel with scrollbar ──
                    scrollPanel = (Widget)Activator.CreateInstance(scrollPanelType, new object[] { uiContext });
                    scrollPanel.Id = PreviewScrollPanelId;
                    scrollPanel.WidthSizePolicy = SizePolicy.StretchToParent;
                    // Shrink to fit, capped at MaxPreviewHeight.
                    //
                    // This used to be pinned to MaxPreviewHeight unconditionally, so a short
                    // preview left a large empty gap under the text before the tip line.
                    // Gauntlet gives no measured text height here (the widget has not laid
                    // out yet), so estimate from character count: roughly PreviewCharsPerLine
                    // characters per line at this panel width, PreviewLineHeight px per line.
                    // Newlines are counted too, since they force a break early.
                    //
                    // The estimate is deliberately generous - one spare line - because
                    // under-estimating would hide text with no way to scroll to it, whereas
                    // over-estimating merely leaves a thin gap.
                    int newlineCount = 0;
                    for (int ci = 0; ci < previewText.Length; ci++)
                        if (previewText[ci] == '\n') newlineCount++;

                    int estimatedLines = newlineCount
                        + (previewText.Length / PreviewCharsPerLine) + 1;
                    float estimatedHeight = (estimatedLines + 1) * PreviewLineHeight;

                    // The cap must also respect the SCREEN, not just MaxPreviewHeight.
                    //
                    // The popup frame cannot grow past the display, so if the preview eats
                    // too much of it the input field and Cancel/Done get pushed BELOW the
                    // frame and float over the encyclopedia page - which reads as the popup
                    // leaking. Reserve room for the rest of the popup's furniture and cap the
                    // preview to whatever is genuinely left.
                    float cap = MaxPreviewHeight;
                    float screenH = TryGetScreenHeight(uiContext);
                    if (screenH > 100f)
                    {
                        float avail = screenH - PopupChromeReserve;
                        if (avail < MinPreviewHeight) avail = MinPreviewHeight;
                        if (avail < cap) cap = avail;
                    }

                    float panelHeight = estimatedHeight < cap ? estimatedHeight : cap;

                    scrollPanel.HeightSizePolicy = SizePolicy.Fixed;
                    scrollPanel.SuggestedHeight = panelHeight;
                    scrollPanel.ScaledSuggestedHeight = panelHeight;
                    scrollPanel.MarginBottom = 40;
                    scrollPanel.Color = new Color(0.06f, 0.05f, 0.03f, 0.65f);

                    // ClipRect — viewport
                    var clipRect = new Widget(uiContext);
                    clipRect.Id = "EE_PreviewClipRect";
                    clipRect.WidthSizePolicy = SizePolicy.StretchToParent;
                    clipRect.HeightSizePolicy = SizePolicy.StretchToParent;
                    clipRect.ClipContents = true;

                    // InnerPanel — ListPanel with CoverChildren
                    var innerPanel = (Widget)Activator.CreateInstance(listPanelType, new object[] { uiContext });
                    innerPanel.Id = "EE_PreviewInnerPanel";
                    innerPanel.WidthSizePolicy = SizePolicy.StretchToParent;
                    innerPanel.HeightSizePolicy = SizePolicy.CoverChildren;

                    // Wire: InnerPanel > TextWidget, ClipRect > InnerPanel
                    innerPanel.AddChild(textWidget);
                    clipRect.AddChild(innerPanel);

                    // ScrollbarWidget with Handle child
                    Widget scrollbar = null;
                    if (scrollbarType != null)
                    {
                        try
                        {
                            scrollbar = (Widget)Activator.CreateInstance(scrollbarType, new object[] { uiContext });
                            scrollbar.Id = "EE_PreviewScrollbar";
                            scrollbar.WidthSizePolicy = SizePolicy.Fixed;
                            scrollbar.SuggestedWidth = 18;
                            scrollbar.ScaledSuggestedWidth = 18;
                            scrollbar.HeightSizePolicy = SizePolicy.StretchToParent;
                            scrollbar.HorizontalAlignment = HorizontalAlignment.Right;

                            // Set vertical alignment axis so handle slides up/down
                            var alignAxisProp = scrollbarType.GetProperty("AlignmentAxis", allFlags);
                            if (alignAxisProp != null && alignAxisProp.CanWrite)
                            {
                                // AlignmentAxis enum: 0=Horizontal, 1=Vertical
                                var axisType = alignAxisProp.PropertyType;
                                if (axisType.IsEnum)
                                    alignAxisProp.SetValue(scrollbar, Enum.ToObject(axisType, 1));
                                else
                                    alignAxisProp.SetValue(scrollbar, 1);
                                MCMSettings.DebugLog("TextInquiry: set scrollbar AlignmentAxis=1 (vertical)");
                            }
                            else
                            {
                                MCMSettings.DebugLog("TextInquiry: AlignmentAxis property not found on ScrollbarWidget");
                            }

                            // Track background — use BrushWidget with a real brush so it renders
                            var track = new BrushWidget(uiContext);
                            track.Id = "EE_ScrollTrack";
                            track.WidthSizePolicy = SizePolicy.StretchToParent;
                            track.HeightSizePolicy = SizePolicy.StretchToParent;
                            var trackBrush = TryGetBrushByName(uiContext, "SPOptions.Slider.Filler", allFlags)
                                          ?? TryGetBrushByName(uiContext, "SPOptions.Slider.Track", allFlags)
                                          ?? TryGetBrushByName(uiContext, "SPOptions.Slider", allFlags)
                                          ?? TryGetBrushByName(uiContext, "SPOptions.CollapserLine", allFlags)
                                          ?? TryGetBrushByName(uiContext, "Tooltip.Frame", allFlags);
                            if (trackBrush != null)
                            {
                                track.Brush = trackBrush;
                                track.Brush.GlobalAlphaFactor = 0.4f;
                            }
                            MCMSettings.DebugLog("TextInquiry: scrollbar trackBrush="
                                + (trackBrush != null ? trackBrush.Name : "null"));
                            scrollbar.AddChild(track);

                            // Draggable handle — use BrushWidget with a real brush
                            var handle = new BrushWidget(uiContext);
                            handle.Id = "EE_ScrollHandle";
                            handle.WidthSizePolicy = SizePolicy.Fixed;
                            handle.SuggestedWidth = 10;
                            handle.ScaledSuggestedWidth = 10;
                            handle.HorizontalAlignment = HorizontalAlignment.Center;
                            handle.HeightSizePolicy = SizePolicy.Fixed;
                            handle.SuggestedHeight = 50;
                            handle.ScaledSuggestedHeight = 50;
                            var handleBrush = TryGetBrushByName(uiContext, "SPOptions.Slider.Handle", allFlags)
                                           ?? TryGetBrushByName(uiContext, "Scrollbar.Handle", allFlags)
                                           ?? TryGetBrushByName(uiContext, "ScrollbarHandle", allFlags)
                                           ?? TryGetBrushByName(uiContext, "Encyclopedia.Scrollbar.Handle", allFlags);
                            if (handleBrush != null)
                                handle.Brush = handleBrush;
                            scrollbar.AddChild(handle);

                            MCMSettings.DebugLog("TextInquiry: scrollbar trackBrush="
                                + (trackBrush != null ? trackBrush.Name : "null")
                                + " handleBrush=" + (handleBrush != null ? handleBrush.Name : "null"));

                            var handleProp = scrollbarType.GetProperty("Handle", allFlags);
                            if (handleProp != null && handleProp.CanWrite)
                                handleProp.SetValue(scrollbar, handle);
                        }
                        catch (Exception ex)
                        {
                            MCMSettings.DebugLog("TextInquiry: ScrollbarWidget creation failed: " + ex.ToString());
                            scrollbar = null;
                        }
                    }

                    // Add children to ScrollablePanel (clipRect first, scrollbar on top)
                    scrollPanel.AddChild(clipRect);
                    if (scrollbar != null)
                        scrollPanel.AddChild(scrollbar);

                    // Link ScrollablePanel properties
                    var clipRectProp = scrollPanelType.GetProperty("ClipRect", allFlags);
                    var innerPanelProp = scrollPanelType.GetProperty("InnerPanel", allFlags);
                    var autoHideProp = scrollPanelType.GetProperty("AutoHideScrollBars", allFlags);
                    var vScrollProp = scrollPanelType.GetProperty("VerticalScrollbar", allFlags);

                    if (clipRectProp != null && clipRectProp.CanWrite)
                        clipRectProp.SetValue(scrollPanel, clipRect);
                    if (innerPanelProp != null && innerPanelProp.CanWrite)
                        innerPanelProp.SetValue(scrollPanel, innerPanel);
                    if (autoHideProp != null && autoHideProp.CanWrite)
                        autoHideProp.SetValue(scrollPanel, false);
                    if (scrollbar != null && vScrollProp != null && vScrollProp.CanWrite)
                        vScrollProp.SetValue(scrollPanel, scrollbar);
                }

                // 10. Insert into parent at original index
                parentPanel.AddChildAtIndex(scrollPanel, childIndex);

                // GROW THE FRAME to fit what we just put in it.
                //
                // The frame (DimensionSyncWidget) is HeightSizePolicy=Fixed - confirmed from
                // the LAYOUT diagnostic below - so it does NOT expand for its children. Its
                // height is decided once, from the popup's ORIGINAL content, and swapping in
                // our ScrollablePanel never re-syncs it. When the hero's description was
                // short the frame was built short, and our preview then pushed the input
                // field and Cancel/Done below the frame, where they float over the
                // encyclopedia page. That is the "native input and buttons leaking".
                //
                // Size it explicitly: preview + the chrome above and below it, capped so the
                // popup still fits on screen.
                try
                {
                    Widget frameToGrow = parentPanel.ParentWidget;
                    if (frameToGrow != null)
                    {
                        float needed = scrollPanel.SuggestedHeight + PopupChromeReserve;
                        float scrH = TryGetScreenHeight(previewWidget.Context);
                        float ceiling = scrH > 100f ? scrH * MaxPopupScreenFraction : needed;
                        if (needed > ceiling) needed = ceiling;

                        // Only ever grow. Shrinking could clip a popup that was already fine.
                        if (needed > frameToGrow.SuggestedHeight)
                        {
                            frameToGrow.HeightSizePolicy = SizePolicy.Fixed;
                            frameToGrow.SuggestedHeight = needed;
                            frameToGrow.ScaledSuggestedHeight = needed;
                            MCMSettings.DebugLog("TextInquiry: grew popup frame to " + needed
                                + "px (preview=" + scrollPanel.SuggestedHeight
                                + " reserve=" + PopupChromeReserve + " screenH=" + scrH + ")");
                        }
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("TextInquiry: frame grow failed: " + ex.Message); }

                // Diagnostics for popup overflow. If the input field or buttons end up below
                // the frame, these are the numbers that decide it: compare the frame's height
                // against the body's. Body taller than frame == content spilling out the
                // bottom, and the preview height is the part we control.
                try
                {
                    Widget frame = parentPanel.ParentWidget;
                    MCMSettings.DebugLog("TextInquiry: LAYOUT"
                        + " screenH=" + TryGetScreenHeight(previewWidget.Context)
                        + " frameType=" + (frame == null ? "null" : frame.GetType().Name)
                        + " frameSuggH=" + (frame == null ? -1f : frame.SuggestedHeight)
                        + " frameScaledH=" + (frame == null ? -1f : frame.ScaledSuggestedHeight)
                        + " frameHPolicy=" + (frame == null ? "?" : frame.HeightSizePolicy.ToString())
                        + " bodySuggH=" + parentPanel.SuggestedHeight
                        + " bodyScaledH=" + parentPanel.ScaledSuggestedHeight
                        + " bodyChildren=" + parentPanel.ChildCount
                        + " previewH=" + scrollPanel.SuggestedHeight);
                }
                catch (Exception ex) { MCMSettings.DebugLog("TextInquiry: layout diag failed: " + ex.Message); }

                // Read the height back off the widget: the locals that computed it are scoped
                // to the long-text branch, and this logs for the short-text path too.
                MCMSettings.DebugLog("TextInquiry: replaced RichTextWidget with TextWidget in ScrollablePanel ("
                    + scrollPanel.SuggestedHeight + "px) textLen=" + previewText.Length
                    + " brush=" + (previewBrush != null)
                    + " at index " + childIndex);
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TextInquiry: WrapPreviewInScrollPanel error: " + ex.ToString());
                TruncatePreviewText(previewWidget);
            }
        }

        /// <summary>
        /// Fallback: truncates the preview text to prevent overflow when
        /// proper container reparenting isn't possible.
        /// </summary>
        private static void TruncatePreviewText(Widget previewWidget)
        {
            try
            {
                var flags = System.Reflection.BindingFlags.Instance
                    | System.Reflection.BindingFlags.Public
                    | System.Reflection.BindingFlags.NonPublic;
                var textProp = previewWidget.GetType().GetProperty("Text", flags);
                if (textProp == null || !textProp.CanWrite) return;

                string fullText = textProp.GetValue(previewWidget) as string ?? "";
                if (fullText.Length <= 400) return;

                string truncated = fullText.Length >= 400 ? fullText.Substring(0, 400) : fullText;
                int lastSpace = truncated.LastIndexOf(' ');
                if (lastSpace > 260 && lastSpace <= truncated.Length) truncated = truncated.Substring(0, lastSpace);
                truncated += "...";
                textProp.SetValue(previewWidget, truncated);
                previewWidget.Id = PreviewClipMarkerId;

                MCMSettings.DebugLog("TextInquiry: truncated preview from " + fullText.Length + " to " + truncated.Length + " chars");
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: unexpected error: " + ex.ToString()); }
        }


        /// <summary>
        /// Attempts to wrap the EditableTextWidget in a ScrollablePanel for proper
        /// text clipping and scrolling. Returns true on success.
        /// Structure: ScrollablePanel > ClipRect (ClipContents=true) > EditableTextWidget
        /// </summary>
        private static bool TryWrapInScrollablePanel(Widget editWidget, Widget directParent,
            UIContext uiContext, float targetHeight)
        {
            if (directParent == null || uiContext == null) return false;

            // Find ScrollablePanel type
            var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public
                | System.Reflection.BindingFlags.NonPublic;
            Type scrollType = typeof(Widget).Assembly.GetType("TaleWorlds.GauntletUI.BaseTypes.ScrollablePanel")
                          ?? typeof(Widget).Assembly.GetType("TaleWorlds.GauntletUI.ExtraWidgets.ScrollablePanel");
            if (scrollType == null)
            {
                foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                {
                    scrollType = asm.GetType("TaleWorlds.GauntletUI.BaseTypes.ScrollablePanel")
                              ?? asm.GetType("TaleWorlds.GauntletUI.ExtraWidgets.ScrollablePanel");
                    if (scrollType != null) break;
                }
            }
            if (scrollType == null)
            {
                MCMSettings.DebugLog("TextInquiry: ScrollablePanel type not found");
                return false;
            }
            MCMSettings.DebugLog("TextInquiry: found ScrollablePanel type: " + scrollType.FullName);

            // Log ScrollablePanel properties for discovery
            foreach (var p in scrollType.GetProperties(flags))
            {
                if (p.DeclaringType == scrollType || p.Name.Contains("Clip") || p.Name.Contains("Inner")
                    || p.Name.Contains("Scroll") || p.Name.Contains("Auto"))
                    MCMSettings.DebugLog("TextInquiry: ScrollablePanel." + p.Name
                        + " : " + p.PropertyType.Name + " (canSet=" + p.CanWrite + ")");
            }

            // Find the EditableTextWidget's index in its parent
            int editIndex = -1;
            for (int i = 0; i < directParent.ChildCount; i++)
            {
                if (directParent.GetChild(i) == editWidget)
                { editIndex = i; break; }
            }
            if (editIndex < 0)
            {
                MCMSettings.DebugLog("TextInquiry: EditableTextWidget not found in parent children");
                return false;
            }

            // Create the ScrollablePanel
            Widget scrollPanel;
            try
            {
                scrollPanel = (Widget)Activator.CreateInstance(scrollType, new object[] { uiContext });
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TextInquiry: ScrollablePanel ctor failed: " + ex.ToString());
                return false;
            }
            scrollPanel.WidthSizePolicy = SizePolicy.StretchToParent;
            scrollPanel.HeightSizePolicy = SizePolicy.Fixed;
            scrollPanel.SuggestedHeight = targetHeight;
            scrollPanel.ScaledSuggestedHeight = targetHeight;
            scrollPanel.Id = EnlargedMarkerId;

            // Create ClipRect widget
            var clipRect = new Widget(uiContext);
            clipRect.Id = "EE_ClipRect";
            clipRect.WidthSizePolicy = SizePolicy.StretchToParent;
            clipRect.HeightSizePolicy = SizePolicy.StretchToParent;
            clipRect.ClipContents = true;

            // Remove EditableTextWidget from its current parent
            // Widget.RemoveChild or similar - try reflection if not available
            try
            {
                var removeMethod = directParent.GetType().GetMethod("RemoveChild",
                    new Type[] { typeof(Widget) });
                if (removeMethod != null)
                {
                    removeMethod.Invoke(directParent, new object[] { editWidget });
                    MCMSettings.DebugLog("TextInquiry: removed EditableTextWidget from parent via RemoveChild");
                }
                else
                {
                    MCMSettings.DebugLog("TextInquiry: RemoveChild not found, trying RemoveAllChildren+re-add");
                    // Fallback: if we can't remove just the one child
                    return false;
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TextInquiry: RemoveChild failed: " + ex.ToString());
                return false;
            }

            // Set EditableTextWidget to CoverChildren height so it grows with text content
            // (the ScrollablePanel will handle scrolling)
            editWidget.HeightSizePolicy = SizePolicy.CoverChildren;
            editWidget.WidthSizePolicy = SizePolicy.StretchToParent;

            // Build tree: ScrollablePanel > ClipRect > EditableTextWidget
            clipRect.AddChild(editWidget);
            scrollPanel.AddChild(clipRect);

            // Set ScrollablePanel properties via reflection
            var clipRectProp = scrollType.GetProperty("ClipRect", flags);
            var innerPanelProp = scrollType.GetProperty("InnerPanel", flags);
            var autoHideProp = scrollType.GetProperty("AutoHideScrollBars", flags);

            if (clipRectProp != null && clipRectProp.CanWrite)
            {
                clipRectProp.SetValue(scrollPanel, clipRect);
                MCMSettings.DebugLog("TextInquiry: set ClipRect property");
            }
            else
            {
                MCMSettings.DebugLog("TextInquiry: ClipRect prop " + (clipRectProp == null ? "not found" : "read-only"));
            }

            if (innerPanelProp != null && innerPanelProp.CanWrite)
            {
                // InnerPanel can be the clipRect itself or a child of it
                // In the XML example, InnerPanel is a ListPanel inside ClipRect.
                // Here the EditableTextWidget IS the inner panel content.
                // Try setting InnerPanel to the clipRect (content holder)
                innerPanelProp.SetValue(scrollPanel, clipRect);
                MCMSettings.DebugLog("TextInquiry: set InnerPanel property to clipRect");
            }
            else
            {
                MCMSettings.DebugLog("TextInquiry: InnerPanel prop " + (innerPanelProp == null ? "not found" : "read-only"));
            }

            if (autoHideProp != null && autoHideProp.CanWrite)
            {
                autoHideProp.SetValue(scrollPanel, true);
                MCMSettings.DebugLog("TextInquiry: set AutoHideScrollBars = true");
            }

            // Insert ScrollablePanel where EditableTextWidget was
            directParent.AddChildAtIndex(scrollPanel, editIndex);

            // Enlarge parent to fit
            directParent.HeightSizePolicy = SizePolicy.Fixed;
            directParent.SuggestedHeight = targetHeight;
            directParent.ScaledSuggestedHeight = targetHeight;

            // Re-focus the EditableTextWidget after reparenting
            // (moving it to a new parent loses focus)
            try
            {
                var evtMgr = uiContext.EventManager;
                if (evtMgr != null)
                {
                    // Try SetWidgetFocused first, then FocusedWidget property
                    var setFocusMethod = evtMgr.GetType().GetMethod("SetWidgetFocused",
                        flags, null, new Type[] { typeof(Widget), typeof(bool) }, null);
                    if (setFocusMethod != null)
                    {
                        setFocusMethod.Invoke(evtMgr, new object[] { editWidget, true });
                        MCMSettings.DebugLog("TextInquiry: re-focused via SetWidgetFocused");
                    }
                    else
                    {
                        // Try single-param version
                        setFocusMethod = evtMgr.GetType().GetMethod("SetWidgetFocused",
                            flags, null, new Type[] { typeof(Widget) }, null);
                        if (setFocusMethod != null)
                        {
                            setFocusMethod.Invoke(evtMgr, new object[] { editWidget });
                            MCMSettings.DebugLog("TextInquiry: re-focused via SetWidgetFocused(widget)");
                        }
                        else
                        {
                            // Try FocusedWidget property
                            var focusProp = evtMgr.GetType().GetProperty("FocusedWidget", flags);
                            if (focusProp != null && focusProp.CanWrite)
                            {
                                focusProp.SetValue(evtMgr, editWidget);
                                MCMSettings.DebugLog("TextInquiry: re-focused via FocusedWidget property");
                            }
                            else
                            {
                                // Log available focus methods for discovery
                                MCMSettings.DebugLog("TextInquiry: no focus method found. EventManager methods:");
                                foreach (var m in evtMgr.GetType().GetMethods(flags))
                                {
                                    if (m.Name.ToLower().Contains("focus")
                                        || m.Name.ToLower().Contains("widget"))
                                        MCMSettings.DebugLog("  " + m.Name + "("
                                            + string.Join(", ", Array.ConvertAll(m.GetParameters(),
                                                p => p.ParameterType.Name + " " + p.Name)) + ")");
                                }
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TextInquiry: re-focus failed: " + ex.ToString());
            }

            MCMSettings.DebugLog("TextInquiry: wrapped EditableTextWidget in ScrollablePanel at index " + editIndex
                + " parentChildren=" + directParent.ChildCount);
            return true;
        }

        // ================================================================
        //  Harmony patch: force scissor clipping on EditableTextWidget
        //  in the enlarged TextInquiry popup. The native ClipContents
        //  doesn't work for EditableTextWidget's text rendering.
        // ================================================================

        private static bool _clipPatchApplied;
        private static System.Reflection.MethodInfo _setScissorMethod;
        private static bool _scissorMethodSearched;

        /// <summary>
        /// Applies a Harmony prefix+finalizer on EditableTextWidget.OnRender to
        /// manually push a scissor rect before the widget renders text.
        /// Must be called once during mod initialization.
        /// </summary>
        internal static void TryApplyClipPatch(HarmonyLib.Harmony harmony)
        {
            if (_clipPatchApplied) return;
            _clipHarmony = harmony;   // needed later by the one-time scissor discovery
            try
            {
                var editableType = typeof(TaleWorlds.GauntletUI.BaseTypes.EditableTextWidget);
                var target = editableType.GetMethod("OnRender",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic
                    | System.Reflection.BindingFlags.Public);
                if (target == null)
                {
                    MCMSettings.DebugLog("EditableTextClip: OnRender not found on EditableTextWidget");
                    return;
                }

                var prefix = typeof(EncyclopediaEditPopup).GetMethod(
                    nameof(EditableTextRenderPrefix),
                    System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic);
                var finalizer = typeof(EncyclopediaEditPopup).GetMethod(
                    nameof(EditableTextRenderFinalizer),
                    System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic);

                harmony.Patch(target,
                    prefix: new HarmonyLib.HarmonyMethod(prefix),
                    finalizer: new HarmonyLib.HarmonyMethod(finalizer));
                _clipPatchApplied = true;
                MCMSettings.DebugLog("EditableTextClip: patched EditableTextWidget.OnRender for scissor clipping");
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("EditableTextClip: patch failed: " + ex.ToString());
            }

            // Also patch TextWidget.OnRender for preview text clipping
            TryApplyPreviewClipPatch(harmony);
        }

        private static bool _previewClipPatchApplied;

        private static void TryApplyPreviewClipPatch(HarmonyLib.Harmony harmony)
        {
            if (_previewClipPatchApplied) return;
            try
            {
                Type textWidgetType = null;
                foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                {
                    textWidgetType = asm.GetType("TaleWorlds.GauntletUI.BaseTypes.TextWidget");
                    if (textWidgetType != null) break;
                }
                if (textWidgetType == null)
                {
                    MCMSettings.DebugLog("PreviewClip: TextWidget type not found");
                    return;
                }

                var target = textWidgetType.GetMethod("OnRender",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic
                    | System.Reflection.BindingFlags.Public);
                if (target == null)
                {
                    MCMSettings.DebugLog("PreviewClip: OnRender not found on TextWidget");
                    return;
                }

                var prefix = typeof(EncyclopediaEditPopup).GetMethod(
                    nameof(PreviewTextRenderPrefix),
                    System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic);
                var finalizer = typeof(EncyclopediaEditPopup).GetMethod(
                    nameof(PreviewTextRenderFinalizer),
                    System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic);

                harmony.Patch(target,
                    prefix: new HarmonyLib.HarmonyMethod(prefix),
                    finalizer: new HarmonyLib.HarmonyMethod(finalizer));
                _previewClipPatchApplied = true;
                MCMSettings.DebugLog("PreviewClip: patched TextWidget.OnRender for preview scissor clipping");
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("PreviewClip: patch failed: " + ex.ToString());
            }
        }

        // Cached reflection handles for the scissor clipping
        private static System.Reflection.PropertyInfo _twoDimCtxProp; // UIContext.TwoDimensionContext
        private static System.Reflection.MethodInfo _resetScissorMethod;
        private static System.Reflection.ConstructorInfo _scissorCtor;
        private static Type _scissorTestInfoType;
        private static bool _scissorReady;
        [ThreadStatic] private static bool _scissorActive;
        private static int _scissorLogCount;

        /// <summary>
        /// Harmony prefix: Before EditableTextWidget.OnRender, if the widget is in our
        /// enlarged popup (parent Id == EnlargedMarkerId), push a scissor rect via
        /// TwoDimensionContext.SetScissor to clip the text rendering.
        /// </summary>
        private static void EditableTextRenderPrefix(Widget __instance)
        {
            try
            {
                var parent = __instance.ParentWidget;
                if (parent == null || parent.Id != EnlargedMarkerId) return;

                var flags = System.Reflection.BindingFlags.Instance
                    | System.Reflection.BindingFlags.Public
                    | System.Reflection.BindingFlags.NonPublic;

                // One-time setup: discover ScissorTestInfo type and constructors
                if (!_scissorMethodSearched)
                {
                    _scissorMethodSearched = true;

                    var uiCtx = __instance.Context;
                    if (uiCtx == null) return;

                    _twoDimCtxProp = uiCtx.GetType().GetProperty("TwoDimensionContext", flags);
                    if (_twoDimCtxProp == null) return;

                    var twoDimCtx = _twoDimCtxProp.GetValue(uiCtx);
                    if (twoDimCtx == null) return;

                    // Find SetScissor and ResetScissor methods
                    _setScissorMethod = twoDimCtx.GetType().GetMethod("SetScissor", flags);
                    _resetScissorMethod = twoDimCtx.GetType().GetMethod("ResetScissor", flags);

                    // Start recording the engine's scissor rect so our finalizers can restore
                    // it. Without this they call ResetScissor(), which clears clipping for
                    // every widget drawn after ours - that is the encyclopedia page text
                    // painting through the popup's input field and buttons.
                    ScissorState.TryApply(_clipHarmony, twoDimCtx);

                    if (_setScissorMethod == null || _resetScissorMethod == null)
                    {
                        MCMSettings.DebugLog("EditableTextClip: SetScissor/ResetScissor not found");
                        return;
                    }

                    // Discover ScissorTestInfo type from SetScissor parameter
                    var setParams = _setScissorMethod.GetParameters();
                    if (setParams.Length != 1)
                    {
                        MCMSettings.DebugLog("EditableTextClip: SetScissor has " + setParams.Length + " params, expected 1");
                        return;
                    }

                    _scissorTestInfoType = setParams[0].ParameterType;
                    MCMSettings.DebugLog("EditableTextClip: ScissorTestInfo type=" + _scissorTestInfoType.FullName);

                    // Log all constructors
                    foreach (var ctor in _scissorTestInfoType.GetConstructors(flags
                        | System.Reflection.BindingFlags.Static))
                    {
                        var ctorParams = ctor.GetParameters();
                        MCMSettings.DebugLog("EditableTextClip: ScissorTestInfo ctor("
                            + string.Join(", ",
                                Array.ConvertAll(ctorParams, p => p.ParameterType.Name + " " + p.Name))
                            + ")");
                        // Cache the best constructor (prefer one with 4-5 numeric params)
                        if (ctorParams.Length >= 4)
                            _scissorCtor = ctor;
                    }

                    // Log all fields
                    foreach (var f in _scissorTestInfoType.GetFields(flags))
                    {
                        MCMSettings.DebugLog("EditableTextClip: ScissorTestInfo." + f.Name
                            + " : " + f.FieldType.Name);
                    }

                    // Log all properties
                    foreach (var p in _scissorTestInfoType.GetProperties(flags))
                    {
                        MCMSettings.DebugLog("EditableTextClip: ScissorTestInfo." + p.Name
                            + " : " + p.PropertyType.Name + " (prop)");
                    }

                    _scissorReady = _scissorCtor != null || _scissorTestInfoType.IsValueType;
                    MCMSettings.DebugLog("EditableTextClip: scissorReady=" + _scissorReady
                        + " hasCtor=" + (_scissorCtor != null)
                        + " isValueType=" + _scissorTestInfoType.IsValueType);
                }

                if (!_scissorReady || _setScissorMethod == null) return;

                // Get the TwoDimensionContext for this frame
                var ctx = __instance.Context;
                if (ctx == null) return;
                var twoDimContext = _twoDimCtxProp.GetValue(ctx);
                if (twoDimContext == null) return;

                // Get parent widget's global position and size for the scissor rect.
                // Use reflection to avoid needing System.Numerics.Vectors reference.
                var parentType = parent.GetType();
                var globalPosProp = parentType.GetProperty("GlobalPosition", flags);
                var sizeProp = parentType.GetProperty("Size", flags);
                if (globalPosProp == null || sizeProp == null) return;
                object globalPos = globalPosProp.GetValue(parent);
                object size = sizeProp.GetValue(parent);
                if (globalPos == null || size == null) return;
                var vecType = globalPos.GetType();
                var xField = vecType.GetField("X");
                var yField = vecType.GetField("Y");
                if (xField == null || yField == null) return;
                float x = (float)xField.GetValue(globalPos);
                float y = (float)yField.GetValue(globalPos);
                float w = (float)xField.GetValue(size);
                float h = (float)yField.GetValue(size);

                // Create ScissorTestInfo and call SetScissor
                object scissorInfo = null;
                if (_scissorCtor != null)
                {
                    var ctorParams = _scissorCtor.GetParameters();
                    if (ctorParams.Length == 4)
                        scissorInfo = _scissorCtor.Invoke(new object[] { x, y, x + w, y + h });
                    else if (ctorParams.Length == 5)
                        scissorInfo = _scissorCtor.Invoke(new object[] { true, x, y, x + w, y + h });
                }
                else if (_scissorTestInfoType.IsValueType)
                {
                    // Try creating via Activator and setting fields
                    scissorInfo = Activator.CreateInstance(_scissorTestInfoType);
                    foreach (var f in _scissorTestInfoType.GetFields(flags))
                    {
                        string fn = f.Name.ToLower();
                        if (fn.Contains("x") && !fn.Contains("y") && !fn.Contains("w") && !fn.Contains("h")
                            && f.FieldType == typeof(float))
                            f.SetValue(scissorInfo, x);
                        else if (fn.Contains("y") && f.FieldType == typeof(float))
                            f.SetValue(scissorInfo, y);
                        else if ((fn.Contains("w") || fn.Contains("right") || fn.Contains("x2")) && f.FieldType == typeof(float))
                            f.SetValue(scissorInfo, x + w);
                        else if ((fn.Contains("h") || fn.Contains("bottom") || fn.Contains("y2")) && f.FieldType == typeof(float))
                            f.SetValue(scissorInfo, y + h);
                        else if (fn.Contains("enabled") && f.FieldType == typeof(bool))
                            f.SetValue(scissorInfo, true);
                    }
                }

                if (scissorInfo != null)
                {
                    // Capture the engine's clip BEFORE overwriting it, so the finalizer can
                    // restore it rather than clearing clipping for the rest of the frame.
                    _scissorHadPrev = ScissorState.HasCurrent;
                    _scissorPrev = ScissorState.Current;

                    _setScissorMethod.Invoke(twoDimContext, new object[] { scissorInfo });
                    _scissorActive = true;

                    if (_scissorLogCount < 3)
                    {
                        _scissorLogCount++;
                        MCMSettings.DebugLog("EditableTextClip: SetScissor called — x=" + x
                            + " y=" + y + " x2=" + (x + w) + " y2=" + (y + h)
                            + " parentId=" + parent.Id
                            + " parentW=" + w + " parentH=" + h);
                    }
                }
                else if (_scissorLogCount < 3)
                {
                    _scissorLogCount++;
                    MCMSettings.DebugLog("EditableTextClip: scissorInfo is null — could not create ScissorTestInfo");
                }
            }
            catch (Exception ex)
            {
                if (_scissorLogCount < 3)
                {
                    _scissorLogCount++;
                    MCMSettings.DebugLog("EditableTextClip: prefix exception — " + ex.ToString());
                }
            }
        }

        /// <summary>
        /// Harmony finalizer (runs after OnRender, even on exception): restore scissor state
        /// by calling ResetScissor on the TwoDimensionContext.
        /// </summary>
        private static void EditableTextRenderFinalizer(Widget __instance)
        {
            try
            {
                if (!_scissorActive) return;
                _scissorActive = false;

                // No need to re-check parent — _scissorActive means the prefix set it
                if (_resetScissorMethod == null || _twoDimCtxProp == null) return;

                var ctx = __instance.Context;
                if (ctx == null) return;
                var twoDimContext = _twoDimCtxProp.GetValue(ctx);
                if (twoDimContext == null) return;

                // RESTORE the engine's clip rather than clearing it. ResetScissor() removes
                // clipping outright, so everything Gauntlet drew after us in the frame -
                // notably the encyclopedia page's description text - rendered unclipped and
                // painted through the popup's input field and Cancel/Done buttons.
                ScissorState.Restore(twoDimContext, _scissorHadPrev, _scissorPrev);
                _scissorHadPrev = false;
                _scissorPrev = null;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: unexpected error: " + ex.ToString()); }
        }

        // ================================================================
        //  Harmony patch: force scissor clipping on preview TextWidget
        //  in the native TextInquiry popup (the description text above
        //  the input field). Uses the same cached scissor infrastructure.
        // ================================================================

        [ThreadStatic] private static bool _previewScissorActive;
        private static int _previewScissorLogCount;

        // Scissor state captured BEFORE we push our own rect, so the finalizers can put the
        // engine's clip back instead of calling ResetScissor(), which clears clipping for
        // everything drawn after us in the frame. See ScissorState for the full explanation.
        [ThreadStatic] private static bool _scissorHadPrev;
        [ThreadStatic] private static object _scissorPrev;
        [ThreadStatic] private static bool _previewHadPrev;
        [ThreadStatic] private static object _previewPrev;

        // Kept so the one-time scissor discovery (which runs inside a render prefix, where no
        // Harmony instance is in scope) can install the ScissorState tracking postfixes.
        private static HarmonyLib.Harmony _clipHarmony;

        /// <summary>
        /// Harmony prefix: Before TextWidget.OnRender, if the widget has our
        /// PreviewClipMarkerId, push a scissor rect clipped to the ScrollablePanel
        /// ancestor's bounds (fixed 200px). This prevents the TextWidget from rendering
        /// beyond the ScrollablePanel's visual area — both RichTextWidget and TextWidget
        /// bypass ClipRect/ClipContents during v1.3.13's render pass.
        /// </summary>
        private static void PreviewTextRenderPrefix(Widget __instance)
        {
            try
            {
                if (__instance.Id != PreviewClipMarkerId) return;

                // Reuse the same scissor infrastructure discovered by EditableTextRenderPrefix
                if (!_scissorReady || _setScissorMethod == null || _twoDimCtxProp == null) return;

                var flags = System.Reflection.BindingFlags.Instance
                    | System.Reflection.BindingFlags.Public
                    | System.Reflection.BindingFlags.NonPublic;

                var ctx = __instance.Context;
                if (ctx == null) return;
                var twoDimContext = _twoDimCtxProp.GetValue(ctx);
                if (twoDimContext == null) return;

                // Find the ScrollablePanel ancestor to use its bounds for clipping.
                // The TextWidget renders at full content height; we clip to the
                // ScrollablePanel's fixed 200px viewport.
                Widget clipSource = null;
                Widget parent = __instance.ParentWidget;
                for (int depth = 0; depth < 5 && parent != null; depth++)
                {
                    if (parent.Id == PreviewScrollPanelId)
                    {
                        clipSource = parent;
                        break;
                    }
                    parent = parent.ParentWidget;
                }

                // Fall back to widget's own bounds if ScrollablePanel not found
                if (clipSource == null)
                    clipSource = __instance;

                var widgetType = clipSource.GetType();
                object globalPos = widgetType.GetProperty("GlobalPosition", flags)?.GetValue(clipSource);
                object size = widgetType.GetProperty("Size", flags)?.GetValue(clipSource);
                if (globalPos == null || size == null) return;

                var vecType = globalPos.GetType();
                var xFieldP = vecType.GetField("X");
                var yFieldP = vecType.GetField("Y");
                if (xFieldP == null || yFieldP == null) return;
                float x = (float)xFieldP.GetValue(globalPos);
                float y = (float)yFieldP.GetValue(globalPos);
                float w = (float)xFieldP.GetValue(size);
                float h = (float)yFieldP.GetValue(size);

                object scissorInfo = null;
                if (_scissorCtor != null)
                {
                    var ctorParams = _scissorCtor.GetParameters();
                    if (ctorParams.Length == 4)
                        scissorInfo = _scissorCtor.Invoke(new object[] { x, y, x + w, y + h });
                    else if (ctorParams.Length == 5)
                        scissorInfo = _scissorCtor.Invoke(new object[] { true, x, y, x + w, y + h });
                }

                if (scissorInfo != null)
                {
                    // Capture the engine's clip BEFORE overwriting it (see above).
                    _previewHadPrev = ScissorState.HasCurrent;
                    _previewPrev = ScissorState.Current;

                    _setScissorMethod.Invoke(twoDimContext, new object[] { scissorInfo });
                    _previewScissorActive = true;

                    if (_previewScissorLogCount < 5)
                    {
                        _previewScissorLogCount++;
                        MCMSettings.DebugLog("PreviewClip: SetScissor — x=" + x + " y=" + y
                            + " x2=" + (x + w) + " y2=" + (y + h)
                            + " W=" + w + " H=" + h
                            + " source=" + clipSource.Id);
                    }
                }
            }
            catch (Exception ex)
            {
                if (_previewScissorLogCount < 5)
                {
                    _previewScissorLogCount++;
                    MCMSettings.DebugLog("PreviewClip: prefix error: " + ex.ToString());
                }
            }
        }

        /// <summary>
        /// Harmony finalizer: After TextWidget.OnRender, reset scissor state.
        /// </summary>
        private static void PreviewTextRenderFinalizer(Widget __instance)
        {
            try
            {
                if (!_previewScissorActive) return;
                _previewScissorActive = false;

                if (_resetScissorMethod == null || _twoDimCtxProp == null) return;
                var ctx = __instance.Context;
                if (ctx == null) return;
                var twoDimContext = _twoDimCtxProp.GetValue(ctx);
                if (twoDimContext == null) return;

                // RESTORE, don't clear — see EditableTextRenderFinalizer for why.
                ScissorState.Restore(twoDimContext, _previewHadPrev, _previewPrev);
                _previewHadPrev = false;
                _previewPrev = null;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: unexpected error: " + ex.ToString()); }
        }

        /// <summary>
        /// Public entry point for opening a specific info field editor from other injectors
        /// (e.g., LoreSectionInjector click-to-edit, per-field add buttons).
        /// </summary>
        public static void TryOpenField(string fieldKey, string heroId)
        {
            if (_popupOpen) return;
            if (EncyclopediaEditBehavior.Instance == null) return;
            EncyclopediaInputBlocker.Block();
            OpenInfoFieldEditor(fieldKey, heroId);
        }

        /// <summary>
        /// Public entry point for deleting (resetting) a specific info field.
        /// </summary>
        public static void TryDeleteField(string fieldKey, string heroId)
        {
            if (_popupOpen) return;
            if (EncyclopediaEditBehavior.Instance == null) return;
            var behavior = EncyclopediaEditBehavior.Instance;
            string fieldLabel = Localization.L("info_field_" + fieldKey);

            _popupOpen = true; _popupGeneration++;
            EncyclopediaInputBlocker.Block();

            var capturedRefreshAction = EncyclopediaPageTracker.CurrentRefreshAction;
            int capturedGen = _popupGeneration;

            InformationManager.ShowInquiry(
                new InquiryData(
                    fieldLabel,
                    Localization.L("info_field_reset_confirm", fieldLabel),
                    true, true,
                    Localization.L("info_field_reset_yes"),
                    Localization.L("edit_cancel"),
                    delegate()
                    {
                        ReleasePopup();
                        behavior.SetHeroInfoField(fieldKey, heroId, "");
                        MCMSettings.DebugLog("Info field '" + fieldKey + "' deleted via Lore section for " + heroId);

                        bool showConfirm = true;
                        try { var s = MCMSettings.Instance; if (s != null) showConfirm = s.ShowConfirmationMessages; } catch (Exception ex) { MCMSettings.DebugLog("Patches: MCM ShowConfirmationMessages read failed: " + ex.ToString()); }
                        if (showConfirm)
                            InformationManager.DisplayMessage(new InformationMessage(
                                Localization.L("msg_info_field_reset", fieldLabel), Colors.Green));

                        // Only refresh if no newer popup has opened since this one
                        if (capturedGen == _popupGeneration && capturedRefreshAction != null)
                        {
                            try { capturedRefreshAction(); } catch (Exception ex) { MCMSettings.DebugLog("Patches: page refresh callback failed: " + ex.ToString()); }
                        }
                    },
                    delegate() { ReleasePopup(); }),
                false, false);
        }

        /// <summary>
        /// Public entry point for opening the description editor from other injectors.
        /// </summary>
        public static void TryOpenDescription(string heroId)
        {
            if (_popupOpen) return;
            if (EncyclopediaEditBehavior.Instance == null) return;
            EncyclopediaInputBlocker.Block();
            OpenDescriptionEditor(heroId);
        }

        public static void TryOpen()
        {
            if (_popupOpen)
            {
                // If a popup is flagged as open but the LoreEditorPopup layer is actually present,
                // force-close it so the user can re-trigger.  This prevents "stuck" state when the
                // editor layer renders behind the encyclopedia and becomes unreachable.
                if (EditPopupInjector.IsOpen)
                {
                    MCMSettings.DebugLog("TryOpen: _popupOpen was stuck (EditPopupInjector still open). Force-closing.");
                    EditPopupInjector.Close();
                    _popupOpen = false;
                    // Fall through to re-open the picker / editor
                }
                else if (LoreEditorPopup.IsOpen)
                {
                    MCMSettings.DebugLog("TryOpen: _popupOpen was stuck (LoreEditorPopup still open). Force-closing.");
                    LoreEditorPopup.Close();
                    _popupOpen = false;
                    // Fall through to re-open the picker / editor
                }
                else if (SelectionPopupHelper.IsOpen)
                {
                    MCMSettings.DebugLog("TryOpen: _popupOpen was stuck (SelectionPopup still open). Force-closing.");
                    SelectionPopupHelper.Close();
                    _popupOpen = false;
                }
                else
                {
                    MCMSettings.DebugLog("TryOpen: blocked — _popupOpen is true (native inquiry may be active)");
                    return;
                }
            }
            if (EncyclopediaEditBehavior.Instance == null) return;
            if (string.IsNullOrEmpty(EncyclopediaPageTracker.CurrentObjectId)) return;

            // Check MCM setting
            try
            {
                var settings = MCMSettings.Instance;
                if (settings != null && !settings.EnableHeroEditing) return;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: MCM settings read failed: " + ex.ToString()); }

            // Block encyclopedia input while popup is open
            EncyclopediaInputBlocker.Block();

            // On hero pages, show a picker: "Edit Description" + 6 structured info fields
            if (EncyclopediaPageTracker.CurrentPageType == "Hero" && EncyclopediaPageTracker.CurrentHero != null)
            {
                _popupOpen = true; _popupGeneration++;
                ShowHeroEditPicker();
                return;
            }

            _popupOpen = true; _popupGeneration++;

            string objectId = EncyclopediaPageTracker.CurrentObjectId;
            string existingText = EncyclopediaEditBehavior.Instance.GetDescription(objectId)
                                  ?? EncyclopediaPageTracker.CurrentDescription
                                  ?? string.Empty;

            // Strip [Edited] / localized edited prefix if present
            string editedPrefix = Localization.L("edited_prefix");
            if (existingText.StartsWith(editedPrefix) && existingText.Length >= editedPrefix.Length)
                existingText = existingText.Substring(editedPrefix.Length);
            else if (existingText.StartsWith("[Edited] ") && existingText.Length >= 9)
                existingText = existingText.Substring(9);

            // Strip any hint suffixes (both compact "[E Edit | ...]" and legacy "[Ctrl+E ...]" formats)
            foreach (string hintPrefix in new[] { "[E ", "[R ", "[Z ", "[N ", "[B ", "[U ", "[O ", "[G ", "[J ", "[F ",
                "[Ctrl+E", "[Ctrl+R", "[Ctrl+Z", "[Ctrl+N", "[Ctrl+B", "[Ctrl+U", "[Ctrl+O", "[Ctrl+G", "[Ctrl+J", "[Ctrl+F",
                "[Strg+E", "[Strg+R", "[Strg+Z", "[Strg+N", "[Strg+B", "[Strg+U", "[Strg+O", "[Strg+G", "[Strg+J", "[Strg+F",
                "[Press E" })
            {
                int idx = existingText.IndexOf(hintPrefix);
                if (idx >= 0 && idx <= existingText.Length)
                    existingText = existingText.Substring(0, idx).TrimEnd();
            }

            MCMSettings.DebugLog("Opening edit popup for objectId=" + objectId + " (text length=" + existingText.Length + ")");

            int maxLength = 0;
            try
            {
                var mcmSettings = MCMSettings.Instance;
                if (mcmSettings != null) maxLength = mcmSettings.MaxDescriptionLength;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: MCM MaxDescriptionLength read failed: " + ex.ToString()); }

            // Build personalized title using entity name from tracker
            string entityName = EncyclopediaPageTracker.CurrentName;
            string popupTitle = !string.IsNullOrEmpty(entityName)
                ? Localization.L("edit_title_story", entityName)
                : Localization.L("edit_title");

            Action<string> onConfirm = delegate (string newText)
            {
                int maxLen = 0;
                try
                {
                    var mcm = MCMSettings.Instance;
                    if (mcm != null) maxLen = mcm.MaxDescriptionLength;
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: MCM MaxDescriptionLength read failed: " + ex.ToString()); }

                if (maxLen > 0 && newText != null && newText.Length > maxLen)
                {
                    InformationManager.DisplayMessage(
                        new InformationMessage(
                            Localization.L("msg_too_long", newText.Length, maxLen),
                            Colors.Red));
                    ReleasePopup();
                    return;
                }

                ReleasePopup();

                // Store undo state before saving
                EncyclopediaPageTracker.PushUndo(objectId, EncyclopediaEditBehavior.Instance.GetDescription(objectId));

                EncyclopediaEditBehavior.Instance.SetDescription(objectId, newText);

                MCMSettings.DebugLog("Description saved for " + objectId + " (" + newText.Length + " chars)");

                bool showConfirm = true;
                try
                {
                    var settings = MCMSettings.Instance;
                    if (settings != null) showConfirm = settings.ShowConfirmationMessages;
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: MCM ShowConfirmationMessages read failed: " + ex.ToString()); }

                if (showConfirm)
                {
                    InformationManager.DisplayMessage(
                        new InformationMessage(Localization.L("msg_description_updated"), Colors.Green));
                }

                // Directly set the new text on the page
                var setText = EncyclopediaPageTracker.CurrentSetTextAction;
                if (setText != null)
                {
                    bool showHint = true;
                    try
                    {
                        var s = MCMSettings.Instance;
                        if (s != null) showHint = s.ShowEditHint;
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: MCM ShowEditHint read failed: " + ex.ToString()); }

                    string displayText = string.IsNullOrWhiteSpace(newText)
                        ? (EncyclopediaPageTracker.OriginalDescription ?? "")
                        : newText;
                    bool hasCustom = !string.IsNullOrWhiteSpace(newText);

                    bool showIndicator = false;
                    try
                    {
                        var si = MCMSettings.Instance;
                        if (si != null) showIndicator = si.ShowEditedIndicator;
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: MCM ShowEditedIndicator read failed: " + ex.ToString()); }

                    string editPfx = (hasCustom && showIndicator) ? Localization.L("edited_prefix") : "";
                    string suffix = showHint
                        ? (hasCustom ? Localization.L("hint_edit_reset_undo") : Localization.L("hint_edit_undo"))
                        : "";
                    string finalDisplay = editPfx + displayText + suffix;
                    string cleanFinal = MarkdownFormatter.HasFormatting(finalDisplay)
                        ? MarkdownFormatter.StripMarkers(finalDisplay) : finalDisplay;
                    setText(cleanFinal);
                    EncyclopediaPageTracker.CurrentDescription = displayText;
                }

                // Refresh the page to trigger the Harmony postfix pipeline
                try
                {
                    var refresh = EncyclopediaPageTracker.CurrentRefreshAction;
                    if (refresh != null) refresh();
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: page refresh after save failed: " + ex.ToString()); }

                // Always schedule a DescriptionFormatter pass with the NEW text.
                // This ensures the old formatted container gets replaced, even if
                // the new text is plain (no markdown). Without this, the old
                // RichTextWidget container from DescriptionFormatter persists.
                if (!string.IsNullOrEmpty(newText))
                {
                    bool showInd = false;
                    try { var si = MCMSettings.Instance; if (si != null) showInd = si.ShowEditedIndicator; } catch { }
                    DescriptionFormatter.ScheduleFormat(newText, showInd);
                    MCMSettings.DebugLog("Patches: scheduled DescriptionFormatter after save (" + newText.Length + " chars)");
                }
            };

            Action onCancelAction = delegate
            {
                ReleasePopup();
                MCMSettings.DebugLog("Edit popup cancelled for " + objectId);
            };

            // Use the editor popup loaded into the encyclopedia's own layer (which has
            // the correct brush catalog). Falls back to native TextInquiry if it fails.
            // Pass existingText as both currentText (input field) and description (preview),
            // so the input field is pre-populated with the existing text for editing.
            EditPopupInjector.ScheduleShow(popupTitle, existingText, maxLength,
                onConfirm, onCancelAction,
                onFailed: () =>
                {
                    MCMSettings.DebugLog("EditPopupInjector failed for " + objectId + " — falling back to native TextInquiry");
                    ShowNativeTextInquiry(popupTitle, existingText, maxLength, onConfirm, onCancelAction);
                },
                description: existingText);
        }

        /// <summary>
        /// Shows a selection popup listing "Edit Description" plus the 6 structured hero info fields.
        /// Uses the native ShowMultiSelectionInquiry (game's built-in UI) as primary approach,
        /// falling back to the custom Gauntlet popup if unavailable.
        /// </summary>
        private static void ShowHeroEditPicker()
        {
            try
            {
                string heroId = EncyclopediaPageTracker.CurrentObjectId;
                var behavior = EncyclopediaEditBehavior.Instance;

                if (TryShowHeroEditPickerMultiSelection(heroId, behavior))
                    return;

                // Fallback: custom Gauntlet popup
                ShowHeroEditPickerGauntlet(heroId, behavior);
            }
            catch (Exception ex)
            {
                _popupOpen = false;
                EncyclopediaInputBlocker.Unblock();
                MCMSettings.DebugLog("ShowHeroEditPicker failed: " + ex.ToString());
            }
        }

        /// <summary>
        /// Primary approach: use the game's native ShowMultiSelectionInquiry for the hero edit picker.
        /// Thread-safe — InformationManager handles main-thread marshaling internally.
        /// </summary>
        private static bool TryShowHeroEditPickerMultiSelection(string heroId, EncyclopediaEditBehavior behavior)
        {
            try
            {
                // Round 4 finding N-C2: cached scan replaces 5+ identical inline assembly walks.
                Type inquiryElementType = InquiryTypeCache.InquiryElement;
                Type multiSelDataType = InquiryTypeCache.MultiSelectionInquiryData;

                if (inquiryElementType == null || multiSelDataType == null)
                {
                    MCMSettings.DebugLog("HeroEditPicker: MultiSelection types not found");
                    return false;
                }

                var showMethod = MultiSelectionMethodCache.Find(multiSelDataType);
                if (showMethod == null)
                {
                    MCMSettings.DebugLog("HeroEditPicker: ShowMultiSelectionInquiry not found");
                    return false;
                }

                var elementCtor = MultiSelectionMethodCache.FindInquiryElementCtor(inquiryElementType, out bool secondParamIsTextObject);
                if (elementCtor == null)
                    return false;

                var elementCtorParams = elementCtor.GetParameters();
                var listType = typeof(List<>).MakeGenericType(inquiryElementType);
                var elements = (System.Collections.IList)Activator.CreateInstance(listType);

                // "Edit Description" option
                string descLabel = Localization.L("hero_edit_description_option");
                string existingDesc = behavior.GetDescription(heroId);
                string descDisplay = string.IsNullOrEmpty(existingDesc) ? descLabel : descLabel + " *";
                elements.Add(MultiSelectionMethodCache.CreateInquiryElement(
                    elementCtor, elementCtorParams, secondParamIsTextObject,
                    "__description__", descDisplay));

                // 6 structured info fields
                foreach (string fieldKey in EncyclopediaEditBehavior.InfoFieldKeys)
                {
                    string fieldLabel = Localization.L("info_field_" + fieldKey);
                    string existing = behavior.GetHeroInfoField(fieldKey, heroId);
                    string label = string.IsNullOrEmpty(existing) ? fieldLabel : fieldLabel + " *";
                    elements.Add(MultiSelectionMethodCache.CreateInquiryElement(
                        elementCtor, elementCtorParams, secondParamIsTextObject,
                        fieldKey, label));
                }

                // Build callbacks
                var actionType = typeof(Action<>).MakeGenericType(listType);

                var affHandler = new HeroEditPickerHandler(heroId);
                var affParam = System.Linq.Expressions.Expression.Parameter(listType, "elements");
                var affCall = System.Linq.Expressions.Expression.Call(
                    System.Linq.Expressions.Expression.Constant(affHandler),
                    typeof(HeroEditPickerHandler).GetMethod("OnSelected"),
                    System.Linq.Expressions.Expression.Convert(affParam, typeof(object)));
                var affirmativeDelegate = System.Linq.Expressions.Expression.Lambda(actionType, affCall, affParam).Compile();

                var negParam = System.Linq.Expressions.Expression.Parameter(listType, "elements");
                var negBody = System.Linq.Expressions.Expression.Call(
                    System.Linq.Expressions.Expression.Constant(affHandler),
                    typeof(HeroEditPickerHandler).GetMethod("OnCancel"),
                    System.Linq.Expressions.Expression.Convert(negParam, typeof(object)));
                var negativeDelegate = System.Linq.Expressions.Expression.Lambda(actionType, negBody, negParam).Compile();

                // Find constructor
                System.Reflection.ConstructorInfo dataCtor = null;
                foreach (var ctor in multiSelDataType.GetConstructors())
                {
                    var pars = ctor.GetParameters();
                    if (pars.Length >= 8 && (dataCtor == null || pars.Length > dataCtor.GetParameters().Length))
                        dataCtor = ctor;
                }

                if (dataCtor == null)
                {
                    MCMSettings.DebugLog("HeroEditPicker: MultiSelectionInquiryData ctor not found");
                    return false;
                }

                string title = Localization.L("hero_edit_picker_title");
                string desc = Localization.L("hero_edit_picker_desc");

                object dataObj = MultiSelectionMethodCache.BuildMultiSelectionInquiryData(
                    dataCtor, title, desc,
                    Localization.L("edit_save"), Localization.L("edit_cancel"),
                    elements, listType, affirmativeDelegate, negativeDelegate);

                var showParams = showMethod.GetParameters();
                if (showParams.Length == 1)
                    showMethod.Invoke(null, new object[] { dataObj });
                else if (showParams.Length == 2)
                    showMethod.Invoke(null, new object[] { dataObj, false });
                else
                    showMethod.Invoke(null, new object[] { dataObj, false, false });

                MCMSettings.DebugLog("Showed hero edit picker via MultiSelectionInquiry (7 items)");

                // ShowMultiSelectionInquiry causes the encyclopedia to navigate to Home
                // as a side effect. Schedule a deferred GoToLink to navigate back to the
                // page the user was viewing.
                EncyclopediaNavigationGuard.ScheduleNavigateBack();

                return true;
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TryShowHeroEditPickerMultiSelection failed: " + ex.ToString());
                return false;
            }
        }

        /// <summary>
        /// Handler for the hero edit picker multi-selection callback.
        /// </summary>
        private class HeroEditPickerHandler
        {
            private readonly string _heroId;
            public HeroEditPickerHandler(string heroId) { _heroId = heroId; }

            public void OnSelected(object elementsObj)
            {
                _popupOpen = false;
                try
                {
                    var list = elementsObj as System.Collections.IList;
                    if (list == null || list.Count == 0) return;

                    string selectedId = MultiSelectionMethodCache.GetInquiryElementId(list[0]);
                    if (string.IsNullOrEmpty(selectedId)) return;

                    MCMSettings.DebugLog("Hero edit picker selected: " + selectedId);

                    if (selectedId == "__description__")
                    {
                        OpenDescriptionEditor(_heroId);
                    }
                    else
                    {
                        // It's one of the info field keys
                        OpenInfoFieldEditor(selectedId, _heroId);
                    }
                }
                catch (Exception ex)
                {
                    MCMSettings.DebugLog("HeroEditPickerHandler.OnSelected error: " + ex.ToString());
                }
            }

            public void OnCancel(object elementsObj)
            {
                ReleasePopup();
                MCMSettings.DebugLog("Hero edit picker cancelled");
            }
        }

        /// <summary>
        /// Fallback: custom Gauntlet popup for hero edit picker.
        /// </summary>
        private static void ShowHeroEditPickerGauntlet(string heroId, EncyclopediaEditBehavior behavior)
        {
            string title = Localization.L("hero_edit_picker_title");
            string desc = Localization.L("hero_edit_picker_desc");

            var items = new MBBindingList<SelectionItemVM>();

            // "Edit Description" option (first)
            items.Add(new SelectionItemVM(Localization.L("hero_edit_description_option"), false, () =>
            {
                SelectionPopupHelper.Close();
                _popupOpen = false;
                OpenDescriptionEditor(heroId);
            }));

            // 6 structured info fields
            foreach (string fieldKey in EncyclopediaEditBehavior.InfoFieldKeys)
            {
                string fk = fieldKey;
                string fieldLabel = Localization.L("info_field_" + fk);
                string existing = behavior.GetHeroInfoField(fk, heroId);
                string label = string.IsNullOrEmpty(existing) ? fieldLabel : fieldLabel + " *";

                items.Add(new SelectionItemVM(label, false, () =>
                {
                    SelectionPopupHelper.Close();
                    _popupOpen = false;
                    OpenInfoFieldEditor(fk, heroId);
                }));
            }

            // Schedule on main thread — we're called from the timer thread
            SelectionPopupHelper.ScheduleShow(title, desc, items, () => { _popupOpen = false; });
        }

        /// <summary>
        /// Opens the multi-line lore editor for hero descriptions.
        /// Uses the custom Gauntlet popup with a large text area.
        /// </summary>
        private static void OpenDescriptionEditor(string overrideObjectId = null)
        {
            if (EncyclopediaEditBehavior.Instance == null) return;

            string objectId = overrideObjectId ?? EncyclopediaPageTracker.CurrentObjectId;
            if (string.IsNullOrEmpty(objectId)) return;

            _popupOpen = true; _popupGeneration++;
            string existingText = EncyclopediaEditBehavior.Instance.GetDescription(objectId)
                                  ?? EncyclopediaPageTracker.CurrentDescription
                                  ?? string.Empty;

            // Strip [Edited] / localized edited prefix if present
            string editedPrefix = Localization.L("edited_prefix");
            if (existingText.StartsWith(editedPrefix) && existingText.Length >= editedPrefix.Length)
                existingText = existingText.Substring(editedPrefix.Length);
            else if (existingText.StartsWith("[Edited] ") && existingText.Length >= 9)
                existingText = existingText.Substring(9);

            // Strip any hint suffixes (both compact "[E Edit | ...]" and legacy "[Ctrl+E ...]" formats)
            foreach (string hintPrefix in new[] { "[E ", "[R ", "[Z ", "[N ", "[B ", "[U ", "[O ", "[G ", "[J ", "[F ",
                "[Ctrl+E", "[Ctrl+R", "[Ctrl+Z", "[Ctrl+N", "[Ctrl+B", "[Ctrl+U", "[Ctrl+O", "[Ctrl+G", "[Ctrl+J", "[Ctrl+F",
                "[Strg+E", "[Strg+R", "[Strg+Z", "[Strg+N", "[Strg+B", "[Strg+U", "[Strg+O", "[Strg+G", "[Strg+J", "[Strg+F",
                "[Press E" })
            {
                int idx = existingText.IndexOf(hintPrefix);
                if (idx >= 0 && idx <= existingText.Length)
                    existingText = existingText.Substring(0, idx).TrimEnd();
            }

            int maxLength = 0;
            try { var m = MCMSettings.Instance; if (m != null) maxLength = m.MaxDescriptionLength; } catch (Exception ex) { MCMSettings.DebugLog("Patches: MCM MaxDescriptionLength read failed: " + ex.ToString()); }

            // Build personalized title: "Edit the story of [Name]" or "Edit the story of [Name]\n[Title]"
            string entityName = EncyclopediaPageTracker.CurrentName;
            string heroTitle = EncyclopediaPageTracker.CurrentTitle;
            string displayName = entityName;
            if (!string.IsNullOrEmpty(displayName) && !string.IsNullOrEmpty(heroTitle))
                displayName = displayName + "\n" + heroTitle;
            string popupTitle = !string.IsNullOrEmpty(displayName)
                ? Localization.L("edit_title_story", displayName)
                : Localization.L("edit_title");

            // Capture tracker state before any dialog clears it (ShowTextInquiry navigates to Home)
            var capturedSetText = EncyclopediaPageTracker.CurrentSetTextAction;
            var capturedOriginalDesc = EncyclopediaPageTracker.OriginalDescription;
            var capturedUpdateTs = EncyclopediaPageTracker.CurrentUpdateTimestampAction;

            Action<string> onConfirm = delegate (string newText)
            {
                int maxLen = 0;
                try { var mcm = MCMSettings.Instance; if (mcm != null) maxLen = mcm.MaxDescriptionLength; } catch (Exception ex) { MCMSettings.DebugLog("Patches: MCM MaxDescriptionLength read failed: " + ex.ToString()); }

                if (maxLen > 0 && newText != null && newText.Length > maxLen)
                {
                    InformationManager.DisplayMessage(new InformationMessage(
                        Localization.L("msg_too_long", newText.Length, maxLen), Colors.Red));
                    ReleasePopup();
                    return;
                }

                ReleasePopup();

                EncyclopediaPageTracker.PushUndo(objectId, EncyclopediaEditBehavior.Instance.GetDescription(objectId));

                EncyclopediaEditBehavior.Instance.SetDescription(objectId, newText);
                MCMSettings.DebugLog("Description saved for " + objectId + " (" + newText.Length + " chars)");

                bool showConfirm = true;
                try { var s = MCMSettings.Instance; if (s != null) showConfirm = s.ShowConfirmationMessages; } catch (Exception ex) { MCMSettings.DebugLog("Patches: MCM ShowConfirmationMessages read failed: " + ex.ToString()); }
                if (showConfirm)
                    InformationManager.DisplayMessage(new InformationMessage(Localization.L("msg_description_updated"), Colors.Green));

                if (capturedSetText != null)
                {
                    bool showHint = true;
                    try { var s = MCMSettings.Instance; if (s != null) showHint = s.ShowEditHint; } catch (Exception ex) { MCMSettings.DebugLog("Patches: MCM ShowEditHint read failed: " + ex.ToString()); }

                    string displayText = string.IsNullOrWhiteSpace(newText)
                        ? (capturedOriginalDesc ?? "") : newText;
                    bool hasCustom = !string.IsNullOrWhiteSpace(newText);

                    bool showIndicator = false;
                    try { var si = MCMSettings.Instance; if (si != null) showIndicator = si.ShowEditedIndicator; } catch (Exception ex) { MCMSettings.DebugLog("Patches: MCM ShowEditedIndicator read failed: " + ex.ToString()); }

                    string editPfx = (hasCustom && showIndicator) ? Localization.L("edited_prefix") : "";
                    string suffix = showHint
                        ? (hasCustom ? Localization.L("hint_edit_reset_undo") : Localization.L("hint_edit_undo"))
                        : "";
                    string finalDisplay = editPfx + displayText + suffix;
                    string cleanFinal = MarkdownFormatter.HasFormatting(finalDisplay)
                        ? MarkdownFormatter.StripMarkers(finalDisplay) : finalDisplay;
                    capturedSetText(cleanFinal);
                    EncyclopediaPageTracker.CurrentDescription = displayText;
                }

                // Refresh page for full pipeline
                try
                {
                    var refresh = EncyclopediaPageTracker.CurrentRefreshAction;
                    if (refresh != null) refresh();
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: page refresh after save failed: " + ex.ToString()); }

                // Always schedule DescriptionFormatter with the new text so the old
                // formatted container gets replaced (even if new text is plain)
                if (!string.IsNullOrEmpty(newText))
                {
                    bool showInd = false;
                    try { var si = MCMSettings.Instance; if (si != null) showInd = si.ShowEditedIndicator; } catch { }
                    DescriptionFormatter.ScheduleFormat(newText, showInd);
                    MCMSettings.DebugLog("Patches: scheduled DescriptionFormatter after save (" + newText.Length + " chars)");
                }
            };

            Action onCancelAction = delegate { ReleasePopup(); };

            // Use the editor popup loaded into the encyclopedia's own layer (which has
            // the correct brush catalog). Falls back to native TextInquiry if it fails.
            // Pass existingText as both currentText (input field) and description (preview),
            // so the input field is pre-populated with the existing text for editing.
            EditPopupInjector.ScheduleShow(popupTitle, existingText, maxLength,
                onConfirm, onCancelAction,
                onFailed: () =>
                {
                    MCMSettings.DebugLog("EditPopupInjector failed for description — falling back to native TextInquiry");
                    ShowNativeTextInquiry(popupTitle, existingText, maxLength, onConfirm, onCancelAction);
                },
                description: existingText);
        }

        /// <summary>
        /// Opens a text inquiry for a specific hero info field (backstory, personality, etc.).
        /// If the field already has content, shows a sub-menu first with "Edit" and "Reset to Default".
        /// </summary>
        private static void OpenInfoFieldEditor(string fieldKey, string heroId)
        {
            _popupOpen = true; _popupGeneration++;

            var behavior = EncyclopediaEditBehavior.Instance;
            string existingText = behavior.GetHeroInfoField(fieldKey, heroId) ?? "";
            string fieldLabel = Localization.L("info_field_" + fieldKey);

            // If the field already has content, show a sub-menu with Edit / Reset options
            if (!string.IsNullOrEmpty(existingText))
            {
                // Capture tracker state before ShowInquiry clears it (navigates to Home)
                var capturedRefreshAction = EncyclopediaPageTracker.CurrentRefreshAction;

                InformationManager.ShowInquiry(
                    new InquiryData(
                        fieldLabel,
                        Localization.L("info_field_submenu_desc", fieldLabel),
                        true, true,
                        Localization.L("info_field_edit_existing"),
                        Localization.L("info_field_reset_default"),
                        delegate()
                        {
                            // "Edit" chosen — open text editor with existing content
                            DoOpenInfoFieldTextEditor(fieldKey, heroId, existingText, fieldLabel);
                        },
                        delegate()
                        {
                            // "Reset to Default" chosen — confirm and clear
                            InformationManager.ShowInquiry(
                                new InquiryData(
                                    fieldLabel,
                                    Localization.L("info_field_reset_confirm", fieldLabel),
                                    true, true,
                                    Localization.L("info_field_reset_yes"),
                                    Localization.L("edit_cancel"),
                                    delegate()
                                    {
                                        ReleasePopup();
                                        behavior.SetHeroInfoField(fieldKey, heroId, "");
                                        MCMSettings.DebugLog("Info field '" + fieldKey + "' reset for " + heroId);

                                        bool showConfirm = true;
                                        try { var s = MCMSettings.Instance; if (s != null) showConfirm = s.ShowConfirmationMessages; } catch (Exception ex) { MCMSettings.DebugLog("Patches: MCM ShowConfirmationMessages read failed: " + ex.ToString()); }
                                        if (showConfirm)
                                            InformationManager.DisplayMessage(new InformationMessage(
                                                Localization.L("msg_info_field_reset", fieldLabel), Colors.Green));

                                        if (capturedRefreshAction != null)
                                        {
                                            try { capturedRefreshAction(); } catch (Exception ex) { MCMSettings.DebugLog("Patches: page refresh callback failed: " + ex.ToString()); }
                                        }
                                    },
                                    delegate() { ReleasePopup(); }),
                                false, false);
                        }),
                    false, false);
                return;
            }

            // Field is empty — go straight to text editor
            DoOpenInfoFieldTextEditor(fieldKey, heroId, existingText, fieldLabel);
        }

        /// <summary>
        /// Opens the text editor for a hero info field.
        /// Narrative fields (backstory, rumors) use the large multi-line lore editor.
        /// Short fields (personality, goals, etc.) use the native text inquiry.
        /// </summary>
        /// <summary>
        /// Returns the appropriate character limit for a given field key,
        /// using section-specific MCM settings (narrative vs stats fields).
        /// </summary>
        private static int GetMaxLengthForField(string fieldKey)
        {
            try
            {
                var m = MCMSettings.Instance;
                if (m == null) return 0;

                bool isNarrative = fieldKey == "backstory" || fieldKey == "rumors";
                return isNarrative ? m.MaxNarrativeFieldLength : m.MaxStatsFieldLength;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: GetMaxLengthForField failed: " + ex.ToString()); return 0; }
        }

        /// <summary>
        /// Resolves template placeholders like {name}, {culture}, {faction}, {settlement}
        /// with actual hero data from the currently viewed hero.
        /// </summary>
        private static Hero FindHeroById(string heroId)
        {
            var hero = EncyclopediaPageTracker.CurrentHero;
            if (hero != null) return hero;

            // CurrentHero may be null if MultiSelectionInquiry navigated away.
            // Look up by StringId from the campaign object manager.
            try
            {
                hero = Hero.FindFirst(h => h.StringId == heroId);
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: hero lookup failed: " + ex.ToString()); }
            return hero;
        }

        private static string ResolveTemplatePlaceholders(string template, string heroId)
        {
            try
            {
                var hero = FindHeroById(heroId);
                if (hero == null) return template;

                string name = hero.Name?.ToString() ?? heroId;
                string culture = hero.Culture?.Name?.ToString() ?? "Unknown";
                string clan = hero.Clan?.Name?.ToString() ?? "None";
                string faction = hero.MapFaction?.Name?.ToString() ?? clan;
                string settlement = hero.HomeSettlement?.Name?.ToString() ?? "Unknown";
                string occupation = hero.Occupation.ToString();

                // Also get the current in-game date for templates
                string date = "";
                try { date = EncyclopediaEditBehavior.GetCurrentGameDateString(); }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: unexpected error: " + ex.ToString()); }

                template = template.Replace("{name}", name);
                template = template.Replace("{culture}", culture);
                template = template.Replace("{faction}", faction);
                template = template.Replace("{clan}", clan);
                template = template.Replace("{settlement}", settlement);
                template = template.Replace("{occupation}", occupation);
                template = template.Replace("{date}", date);
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: template placeholder resolution failed: " + ex.ToString()); }
            return template;
        }

        private static void DoOpenInfoFieldTextEditor(string fieldKey, string heroId, string existingText, string fieldLabel)
        {
            _popupOpen = true; _popupGeneration++;

            var behavior = EncyclopediaEditBehavior.Instance;

            // Capture tracker state before any ShowInquiry/ShowTextInquiry clears it
            var capturedRefreshAction = EncyclopediaPageTracker.CurrentRefreshAction;

            int maxLength = GetMaxLengthForField(fieldKey);

            Action<string> onSave = delegate (string newText)
            {
                int maxLen = GetMaxLengthForField(fieldKey);

                if (maxLen > 0 && newText != null && newText.Length > maxLen)
                {
                    InformationManager.DisplayMessage(new InformationMessage(
                        Localization.L("msg_too_long", newText.Length, maxLen), Colors.Red));
                    ReleasePopup();
                    return;
                }

                ReleasePopup();
                behavior.SetHeroInfoField(fieldKey, heroId, newText);
                MCMSettings.DebugLog("Info field '" + fieldKey + "' saved for " + heroId + " (" + (newText?.Length ?? 0) + " chars)");

                bool showConfirm = true;
                try { var s = MCMSettings.Instance; if (s != null) showConfirm = s.ShowConfirmationMessages; } catch (Exception ex) { MCMSettings.DebugLog("Patches: MCM ShowConfirmationMessages read failed: " + ex.ToString()); }
                if (showConfirm)
                    InformationManager.DisplayMessage(new InformationMessage(
                        Localization.L("msg_info_field_updated", fieldLabel), Colors.Green));

                if (capturedRefreshAction != null)
                {
                    try { capturedRefreshAction(); } catch (Exception ex) { MCMSettings.DebugLog("Patches: page refresh callback failed: " + ex.ToString()); }
                }
            };

            Action onCancel = delegate { ReleasePopup(); };

            // If field is empty and a template exists, ask: Use Template or Write Manually
            if (string.IsNullOrEmpty(existingText))
            {
                string resolvedTemplate = ResolveFieldTemplate(fieldKey, heroId);
                if (resolvedTemplate != null)
                {
                    InformationManager.ShowInquiry(
                        new InquiryData(
                            fieldLabel,
                            Localization.L("template_choice_desc"),
                            true, true,
                            Localization.L("template_choice_use"),
                            Localization.L("template_choice_manual"),
                            delegate()
                            {
                                // Use Template — sequential field-by-field dialogs
                                MCMSettings.DebugLog("Using sequential template dialogs for '" + fieldKey + "'");
                                ShowSequentialTemplateDialogs(fieldLabel, resolvedTemplate, maxLength, onSave, onCancel);
                            },
                            delegate()
                            {
                                // Write Manually — single empty text input
                                MCMSettings.DebugLog("Manual input chosen for '" + fieldKey + "'");
                                ShowNativeTextInquiry(fieldLabel, "", maxLength, onSave, onCancel);
                            }),
                        false, false);
                    return;
                }
            }

            // Existing text or no template — use single dialog
            bool isNarrative = fieldKey == "backstory" || fieldKey == "rumors";

            if (isNarrative)
            {
                EditPopupInjector.ScheduleShow(fieldLabel, existingText, maxLength, onSave, onCancel,
                    onFailed: () =>
                    {
                        MCMSettings.DebugLog("EditPopupInjector failed for field '" + fieldKey + "' — falling back to native TextInquiry");
                        ShowNativeTextInquiry(fieldLabel, existingText, maxLength, onSave, onCancel);
                    });
            }
            else
            {
                ShowNativeTextInquiry(fieldLabel, existingText, maxLength, onSave, onCancel);
            }
        }

        /// <summary>
        /// Resolves the best template for a field key and hero, returning the resolved
        /// template string with placeholders filled in, or null if no template exists.
        /// </summary>
        internal static string ResolveFieldTemplate(string fieldKey, string heroId)
        {
            string templateKey = "template_" + fieldKey;
            string template = null;
            var hero = FindHeroById(heroId);

            if (hero != null)
            {
                // Check custom occupation first (set via Ctrl+O), then fall back to native
                string occupationName = null;
                var behavior = EncyclopediaEditBehavior.Instance;
                if (behavior != null)
                {
                    int customOcc = behavior.GetCustomOccupation(heroId);
                    if (customOcc >= 0)
                        occupationName = ((Occupation)customOcc).ToString();
                }
                if (string.IsNullOrEmpty(occupationName))
                    occupationName = hero.Occupation.ToString();

                // Try occupation-specific: template_backstory_Lord, template_backstory_GangLeader, etc.
                string occKey = templateKey + "_" + occupationName;
                string occTemplate = Localization.L(occKey);
                if (occTemplate != occKey) template = occTemplate;

                // Try culture-specific: template_backstory_Sturgia, etc.
                if (template == null && hero.Culture?.Name != null)
                {
                    string cultureKey = templateKey + "_" + hero.Culture.StringId;
                    string cultureTemplate = Localization.L(cultureKey);
                    if (cultureTemplate != cultureKey) template = cultureTemplate;
                }
            }

            // Fall back to default template
            if (template == null)
            {
                string defaultTemplate = Localization.L(templateKey);
                if (defaultTemplate != templateKey) template = defaultTemplate;
            }

            // Try LoreStory .txt files FIRST (pre-written unique lore, no duplicates per hero)
            // These have full stories vs the localization templates which are just empty prompts
            try
            {
                string loreEntry = LoreStoryLoader.GetLoreEntry(fieldKey, heroId);
                if (!string.IsNullOrEmpty(loreEntry))
                    return loreEntry;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: LoreStoryLoader failed: " + ex.ToString()); }

            if (template == null) return null;
            return ResolveTemplatePlaceholders(template, heroId);
        }

        /// <summary>
        /// Parses a resolved template into label:value pairs, then shows one native
        /// TextInquiry dialog per field sequentially. Each dialog is pre-filled with
        /// the resolved default value. On completion, all values are combined and saved.
        /// </summary>
        private static void ShowSequentialTemplateDialogs(string fieldLabel, string resolvedTemplate,
            int maxLength, Action<string> onComplete, Action onCancel)
        {
            // Parse "Born in: Diathma\nNoble House: Hravalding\n..." into field entries
            var lines = resolvedTemplate.Split('\n');
            var fields = new List<KeyValuePair<string, string>>();

            foreach (var line in lines)
            {
                string trimmed = line.Trim();
                if (string.IsNullOrEmpty(trimmed)) continue;

                int colonIdx = trimmed.IndexOf(':');
                if (colonIdx > 0)
                {
                    string label = colonIdx <= trimmed.Length ? trimmed.Substring(0, colonIdx).Trim() : trimmed.Trim();
                    string value = colonIdx + 1 <= trimmed.Length ? trimmed.Substring(colonIdx + 1).Trim() : "";
                    fields.Add(new KeyValuePair<string, string>(label, value));
                }
                else
                {
                    // Line without colon is CONTENT, not a label.
                    //
                    // It used to be stored as the label with an empty value, and
                    // ShowNextTemplateField builds its dialog title as
                    // `fieldLabel + " - " + field.Key`. A backstory paragraph contains no
                    // colon, so the entire paragraph became the title - and titles render
                    // large, centred and unclipped, which is the text spilling across the
                    // screen. Storing it as the VALUE with an empty key puts it in the
                    // editable/preview field instead, where the ScrollablePanel treatment
                    // applies (same as Edit Description).
                    fields.Add(new KeyValuePair<string, string>("", trimmed));
                }
            }

            if (fields.Count == 0)
            {
                // No parseable fields — fall back to single dialog
                ShowNativeTextInquiry(fieldLabel, resolvedTemplate, maxLength, onComplete, onCancel);
                return;
            }

            var results = new string[fields.Count];
            MCMSettings.DebugLog("Sequential template: " + fields.Count + " fields to fill");

            ShowNextTemplateField(fieldLabel, fields, results, 0, maxLength, onComplete, onCancel);
        }

        private static void ShowNextTemplateField(string fieldLabel,
            List<KeyValuePair<string, string>> fields, string[] results, int index,
            int maxLength, Action<string> onComplete, Action onCancel)
        {
            if (index >= fields.Count)
            {
                // All fields filled — combine into final text
                var sb = new System.Text.StringBuilder();
                for (int i = 0; i < fields.Count; i++)
                {
                    // Empty key = a line that had no colon; write it back as the raw line
                    // rather than ": text", so the saved template round-trips unchanged.
                    sb.Append(string.IsNullOrEmpty(fields[i].Key)
                        ? results[i]
                        : fields[i].Key + ": " + results[i]);
                    if (i < fields.Count - 1) sb.Append("\n");
                }

                string finalText = sb.ToString();
                MCMSettings.DebugLog("Sequential template complete: " + finalText.Length + " chars");
                onComplete?.Invoke(finalText);
                return;
            }

            var field = fields[index];
            string defaultValue = field.Value;
            bool isLast = (index == fields.Count - 1);
            string doneText = isLast ? Localization.L("edit_done") : Localization.L("edit_done") + " >";

            // TITLE MUST STAY SHORT. It renders large, centred and unclipped, so anything
            // long here paints straight across the screen. Never interpolate field content
            // into it: an empty key means the line was raw content, so use the section label
            // alone, and hard-cap the key for safety.
            string keyForTitle = field.Key ?? "";
            if (keyForTitle.Length > 48) keyForTitle = keyForTitle.Substring(0, 48).TrimEnd() + "...";
            string title = string.IsNullOrEmpty(keyForTitle)
                ? fieldLabel
                : fieldLabel + " - " + keyForTitle;

            // Field counter goes in the tip line, which is small and already styled for it.
            // It used to be prefixed onto the description ALONG WITH the whole default value,
            // which is a second way the long text reached an unclipped widget.
            string counterTip = (index + 1) + " / " + fields.Count + "  -  "
                + Localization.L("edit_tips");

            // Go through the SAME path as Edit Description. EditPopupInjector.Show puts the
            // long text in the editable/preview field and runs the portrait injection, char
            // limit override and preview constrain (ScrollablePanel + scissor clip) that make
            // Edit Description render correctly. Building a raw TextInquiryData here was what
            // bypassed all of it.
            EditPopupInjector.Show(
                title,
                defaultValue,
                maxLength > 0 ? maxLength : 10000,
                delegate (string text)
                {
                    // If user typed nothing, keep the default value
                    results[index] = string.IsNullOrEmpty(text) ? defaultValue : text;
                    MCMSettings.DebugLog("Sequential field " + (index + 1) + "/" + fields.Count
                        + " '" + field.Key + "' = " + (results[index] ?? "").Length + " chars");
                    ShowNextTemplateField(fieldLabel, fields, results, index + 1, maxLength, onComplete, onCancel);
                },
                delegate
                {
                    // Cancel — abort the whole chain
                    MCMSettings.DebugLog("Sequential template cancelled at field " + (index + 1));
                    onCancel?.Invoke();
                },
                null,
                doneText,
                counterTip);
        }
    }

    // ============================================
    //  Undo handler logic
    // ============================================
    public static class EncyclopediaUndoHandler
    {
        public static void TryUndo()
        {
            if (!EncyclopediaPageTracker.HasUndo)
            {
                InformationManager.DisplayMessage(
                    new InformationMessage(Localization.L("msg_nothing_to_undo"),
                        new Color(1f, 0.9f, 0.2f)));
                return;
            }

            if (EncyclopediaEditBehavior.Instance == null)
                return;

            var undoEntry = EncyclopediaPageTracker.PopUndo();
            if (undoEntry == null) return;

            string objectId = undoEntry.ObjectId;
            string previousDesc = undoEntry.PreviousDescription;

            EncyclopediaEditBehavior.Instance.SetDescription(objectId, previousDesc);

            int remaining = EncyclopediaPageTracker.UndoCount;
            MCMSettings.DebugLog("Undo applied for " + objectId + " (" + remaining + " undo levels remaining)");

            bool showConfirm = true;
            try
            {
                var settings = MCMSettings.Instance;
                if (settings != null) showConfirm = settings.ShowConfirmationMessages;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: MCM ShowConfirmationMessages read failed: " + ex.ToString()); }

            if (showConfirm)
            {
                string msg = Localization.L("msg_undo_applied");
                if (remaining > 0)
                    msg += " (" + remaining + " more)";
                InformationManager.DisplayMessage(
                    new InformationMessage(msg, Colors.Green));
            }

            if (objectId == EncyclopediaPageTracker.CurrentObjectId)
            {
                var setText = EncyclopediaPageTracker.CurrentSetTextAction;
                if (setText != null)
                {
                    bool showHint = true;
                    try
                    {
                        var s = MCMSettings.Instance;
                        if (s != null) showHint = s.ShowEditHint;
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: MCM ShowEditHint read failed: " + ex.ToString()); }

                    string displayText = !string.IsNullOrWhiteSpace(previousDesc)
                        ? previousDesc
                        : (EncyclopediaPageTracker.OriginalDescription ?? "");
                    bool hasCustom = !string.IsNullOrWhiteSpace(previousDesc);

                    bool showIndicator = false;
                    try
                    {
                        var s = MCMSettings.Instance;
                        if (s != null) showIndicator = s.ShowEditedIndicator;
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: MCM ShowEditedIndicator read failed: " + ex.ToString()); }

                    string prefix = (hasCustom && showIndicator) ? Localization.L("edited_prefix") : "";
                    string suffix = showHint
                        ? (hasCustom ? Localization.L("hint_edit_reset") : Localization.L("hint_edit"))
                        : "";
                    setText(prefix + displayText + suffix);
                    EncyclopediaPageTracker.CurrentDescription = displayText;
                }

                // Refresh the timestamp (undo may restore or remove it)
                try
                {
                    var updateTs = EncyclopediaPageTracker.CurrentUpdateTimestampAction;
                    if (updateTs != null) updateTs();
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: timestamp update failed: " + ex.ToString()); }
            }
        }
    }

    // ============================================
    //  Reset popup logic
    // ============================================
    public static class EncyclopediaResetPopup
    {
        private static volatile bool _popupOpen = false;
        public static bool IsPopupOpen => _popupOpen;

        public static void TryOpen()
        {
            if (_popupOpen) return;
            if (EncyclopediaEditBehavior.Instance == null) return;

            string objectId = EncyclopediaPageTracker.CurrentObjectId;
            if (string.IsNullOrEmpty(objectId)) return;

            if (!EncyclopediaEditBehavior.Instance.HasCustomDescription(objectId))
            {
                InformationManager.DisplayMessage(
                    new InformationMessage(Localization.L("msg_no_custom_to_reset"),
                        new Color(1f, 0.9f, 0.2f)));
                return;
            }

            EncyclopediaInputBlocker.Block();
            _popupOpen = true;

            MCMSettings.DebugLog("Opening reset confirmation for objectId=" + objectId);

            // Capture tracker state before ShowInquiry clears it (navigates to Home)
            var capturedSetText = EncyclopediaPageTracker.CurrentSetTextAction;
            var capturedOriginalDesc = EncyclopediaPageTracker.OriginalDescription;
            var capturedUpdateTs = EncyclopediaPageTracker.CurrentUpdateTimestampAction;
            var capturedRefreshAction = EncyclopediaPageTracker.CurrentRefreshAction;

            InformationManager.ShowInquiry(
                new InquiryData(
                    Localization.L("reset_title"),
                    Localization.L("reset_message"),
                    true,
                    true,
                    Localization.L("reset_confirm"),
                    Localization.L("reset_cancel"),
                    delegate
                    {
                        _popupOpen = false;
                        EncyclopediaInputBlocker.Unblock();

                        // Store undo state before reset
                        EncyclopediaPageTracker.PushUndo(objectId, EncyclopediaEditBehavior.Instance.GetDescription(objectId));

                        EncyclopediaEditBehavior.Instance.SetDescription(objectId, null);

                        MCMSettings.DebugLog("Description reset for " + objectId);

                        bool showConfirm = true;
                        try
                        {
                            var settings = MCMSettings.Instance;
                            if (settings != null) showConfirm = settings.ShowConfirmationMessages;
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: MCM ShowConfirmationMessages read failed: " + ex.ToString()); }

                        if (showConfirm)
                        {
                            InformationManager.DisplayMessage(
                                new InformationMessage(Localization.L("msg_description_reset"), Colors.Green));
                        }

                        if (capturedSetText != null)
                        {
                            string originalText = capturedOriginalDesc ?? "";

                            bool showHint = true;
                            try
                            {
                                var s = MCMSettings.Instance;
                                if (s != null) showHint = s.ShowEditHint;
                            }
                            catch (Exception ex) { MCMSettings.DebugLog("Patches: MCM ShowEditHint read failed: " + ex.ToString()); }

                            string suffix = showHint ? Localization.L("hint_edit_undo") : "";
                            capturedSetText(originalText + suffix);
                            EncyclopediaPageTracker.CurrentDescription = originalText;
                        }

                        // Refresh the timestamp (removes it since description was cleared)
                        try
                        {
                            if (capturedUpdateTs != null) capturedUpdateTs();
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: timestamp update failed: " + ex.ToString()); }

                        // Refresh the page to reflect the reset
                        if (capturedRefreshAction != null)
                        {
                            try { capturedRefreshAction(); } catch (Exception ex) { MCMSettings.DebugLog("Patches: page refresh callback failed: " + ex.ToString()); }
                        }
                    },
                    delegate
                    {
                        _popupOpen = false;
                        EncyclopediaInputBlocker.Unblock();
                        MCMSettings.DebugLog("Reset popup cancelled for " + objectId);
                    }),
                false,
                false);
        }
    }

    // ============================================
    //  Encyclopedia list page patch — applies custom hero names to list items
    // ============================================
    public static class EncyclopediaListPatcher
    {
        public static void TryPatch(HarmonyLib.Harmony harmony)
        {
            try
            {
                // Find the list page type at runtime — it's in the .List namespace
                var assembly = typeof(EncyclopediaHeroPageVM).Assembly;
                var listType = assembly.GetType("TaleWorlds.CampaignSystem.ViewModelCollection.Encyclopedia.List.EncyclopediaListVM");
                if (listType == null)
                {
                    MCMSettings.DebugLog("EncyclopediaListPatcher: Could not find list page VM type");
                    return;
                }

                var refreshMethod = listType.GetMethod("Refresh", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public);
                if (refreshMethod == null)
                {
                    MCMSettings.DebugLog("EncyclopediaListPatcher: Could not find Refresh method on " + listType.FullName);
                    return;
                }

                var postfix = typeof(EncyclopediaListPatcher).GetMethod("ListPagePostfix", System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public);
                harmony.Patch(refreshMethod, postfix: new HarmonyMethod(postfix));
                MCMSettings.DebugLog("EncyclopediaListPatcher: Successfully patched " + listType.FullName + ".Refresh()");
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("EncyclopediaListPatcher: Patch failed - " + ex.ToString());
            }
        }

        /// <summary>
        /// DEPRECATED: This method is no longer called. Changing actual hero properties
        /// (CharacterObject.Occupation, Hero.Culture) causes heroes with non-standard values
        /// to be excluded from GetListItems(), making them disappear from the encyclopedia list.
        /// Custom values are now only persisted in EncyclopediaEditBehavior and displayed
        /// via Stats panel overrides. Custom filter predicates read from behavior data
        /// via HeroMatchesCustomFilter().
        /// </summary>
        private static void ReapplyAllCustomCulturesAndOccupations()
        {
            try
            {
                var behavior = EncyclopediaEditBehavior.Instance;
                if (behavior == null) return;

                // Skip if there's nothing to re-apply
                if (behavior.GetCustomCultureCount() == 0 && behavior.GetCustomOccupationCount() == 0)
                    return;

                var reflFlags = System.Reflection.BindingFlags.Instance
                              | System.Reflection.BindingFlags.Public
                              | System.Reflection.BindingFlags.NonPublic;

                // Build a culture lookup (only once)
                Dictionary<string, CultureObject> cultureCache = null;

                int cultureUpdated = 0;
                int occupationUpdated = 0;

                void ProcessHero(Hero hero)
                {
                    if (hero == null) return;
                    string heroId = hero.StringId;

                    // Re-apply custom culture
                    string customCultureId = behavior.GetCustomCulture(heroId);
                    if (!string.IsNullOrEmpty(customCultureId))
                    {
                        if (hero.Culture == null || hero.Culture.StringId != customCultureId)
                        {
                            // Lazy-init culture cache
                            if (cultureCache == null)
                            {
                                cultureCache = new Dictionary<string, CultureObject>(StringComparer.OrdinalIgnoreCase);
                                foreach (var c in TaleWorlds.ObjectSystem.MBObjectManager.Instance.GetObjectTypeList<CultureObject>())
                                {
                                    if (c != null && !string.IsNullOrEmpty(c.StringId))
                                        cultureCache[c.StringId] = c;
                                }
                            }

                            if (cultureCache.TryGetValue(customCultureId, out var targetCulture))
                            {
                                // Primary: set on CharacterObject (what the game reads from)
                                if (hero.CharacterObject != null)
                                {
                                    var charCultureProp = hero.CharacterObject.GetType().GetProperty("Culture", reflFlags);
                                    if (charCultureProp != null && charCultureProp.CanWrite)
                                        charCultureProp.SetValue(hero.CharacterObject, targetCulture);
                                    else
                                    {
                                        var charField = hero.CharacterObject.GetType().GetField("_culture", reflFlags)
                                                     ?? hero.CharacterObject.GetType().GetField("<Culture>k__BackingField", reflFlags);
                                        if (charField != null && charField.FieldType == typeof(CultureObject))
                                            charField.SetValue(hero.CharacterObject, targetCulture);
                                    }
                                }
                                // Secondary: also set on Hero directly
                                var cultureProp = typeof(Hero).GetProperty("Culture", reflFlags);
                                if (cultureProp != null && cultureProp.CanWrite)
                                    cultureProp.SetValue(hero, targetCulture);
                                else
                                {
                                    var cultureField = typeof(Hero).GetField("_culture", reflFlags)
                                                    ?? typeof(Hero).GetField("<Culture>k__BackingField", reflFlags);
                                    if (cultureField != null && cultureField.FieldType == typeof(CultureObject))
                                        cultureField.SetValue(hero, targetCulture);
                                }
                                cultureUpdated++;
                            }
                        }
                    }

                    // Re-apply custom occupation
                    int customOccupation = behavior.GetCustomOccupation(heroId);
                    if (customOccupation >= 0 && hero.CharacterObject != null)
                    {
                        var occ = (Occupation)customOccupation;
                        if (hero.CharacterObject.Occupation != occ)
                        {
                            // Primary: set on CharacterObject (what the game reads from)
                            var occProp = hero.CharacterObject.GetType().GetProperty("Occupation", reflFlags);
                            if (occProp != null && occProp.CanWrite)
                            {
                                occProp.SetValue(hero.CharacterObject, occ);
                            }
                            else
                            {
                                var occField = hero.CharacterObject.GetType().GetField("_occupation", reflFlags)
                                            ?? hero.CharacterObject.GetType().GetField("<Occupation>k__BackingField", reflFlags);
                                if (occField != null)
                                    occField.SetValue(hero.CharacterObject, occ);
                                else
                                {
                                    foreach (var field in hero.CharacterObject.GetType().GetFields(reflFlags))
                                    {
                                        if (field.FieldType == typeof(Occupation))
                                        {
                                            field.SetValue(hero.CharacterObject, occ);
                                            break;
                                        }
                                    }
                                }
                            }
                            // Secondary: also set on Hero directly
                            try
                            {
                                var heroOccProp = typeof(Hero).GetProperty("Occupation", reflFlags);
                                if (heroOccProp != null && heroOccProp.CanWrite)
                                    heroOccProp.SetValue(hero, occ);
                                else
                                {
                                    var heroOccField = typeof(Hero).GetField("_occupation", reflFlags)
                                                    ?? typeof(Hero).GetField("<Occupation>k__BackingField", reflFlags);
                                    if (heroOccField != null && heroOccField.FieldType == typeof(Occupation))
                                        heroOccField.SetValue(hero, occ);
                                }
                            }
                            catch (Exception ex) { MCMSettings.DebugLog("Patches: hero occupation set failed: " + ex.ToString()); }
                            occupationUpdated++;
                        }
                    }
                }

                foreach (var hero in Hero.AllAliveHeroes)
                    ProcessHero(hero);
                foreach (var hero in Hero.DeadOrDisabledHeroes)
                    ProcessHero(hero);

                if (cultureUpdated > 0 || occupationUpdated > 0)
                    MCMSettings.DebugLog("List page re-applied " + cultureUpdated + " cultures, " + occupationUpdated + " occupations");
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("ReapplyAllCustomCulturesAndOccupations failed: " + ex.ToString());
            }
        }

        public static void ListPagePostfix(object __instance)
        {
            try
            {
                // Clear the page tracker so hotkeys (Ctrl+E etc.) won't fire
                // on non-editable pages like the list/search results page.
                EncyclopediaPageTracker.CurrentObjectId = null;
                EncyclopediaPageTracker.CurrentPageType = null;
                EncyclopediaPageTracker.CurrentHero = null;

                if (EncyclopediaEditBehavior.Instance == null) return;

                // NOTE: We intentionally do NOT call ReapplyAllCustomCulturesAndOccupations() here.
                // Changing actual hero.CharacterObject.Occupation / Culture properties causes heroes
                // with non-standard values (e.g. "Preacher") to be excluded from GetListItems(),
                // making them disappear from the encyclopedia list entirely.
                // Custom values are stored in EncyclopediaEditBehavior and displayed via
                // Stats panel overrides on the detail page. Custom filter predicates read
                // from behavior data via HeroMatchesCustomFilter(), not from hero properties.

                // Find the Items/ListItems collection on the list page VM via reflection
                var vmType = __instance.GetType();
                var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public;

                // Try to find the items collection property
                object items = null;
                string itemsPropName = null;
                foreach (var candidate in new[] { "Items", "ListItems", "FilteredItems" })
                {
                    var prop = vmType.GetProperty(candidate, flags);
                    if (prop != null)
                    {
                        items = prop.GetValue(__instance);
                        itemsPropName = candidate;
                        break;
                    }
                }

                if (items == null)
                {
                    // Debug: log all properties to find the items collection
                    var allProps = vmType.GetProperties(flags);
                    foreach (var p in allProps)
                    {
                        MCMSettings.DebugLog("  ListPage prop: " + p.Name + " (type=" + p.PropertyType.Name + ")");
                    }
                    return;
                }

                MCMSettings.DebugLog("Found list items via '" + itemsPropName + "'");

                // Iterate through items and apply custom names
                var enumerable = items as System.Collections.IEnumerable;
                if (enumerable == null) return;

                int updated = 0;
                foreach (var item in enumerable)
                {
                    if (item == null) continue;
                    var itemType = item.GetType();

                    // Get the underlying object from the list item
                    var objProp = itemType.GetProperty("Object", flags) ?? itemType.GetProperty("Obj", flags);
                    if (objProp == null) continue;

                    var obj = objProp.GetValue(item);
                    if (obj == null) continue;

                    // Determine the object's StringId and current display name
                    string stringId = null;
                    string currentGameName = null;

                    var hero = obj as Hero;
                    if (hero != null)
                    {
                        stringId = hero.StringId;
                        currentGameName = hero.Name?.ToString();
                    }
                    else
                    {
                        var clan = obj as Clan;
                        if (clan != null)
                        {
                            stringId = clan.StringId;
                            currentGameName = clan.Name?.ToString();
                        }
                        else
                        {
                            var kingdom = obj as Kingdom;
                            if (kingdom != null)
                            {
                                stringId = kingdom.StringId;
                                currentGameName = kingdom.Name?.ToString();
                            }
                            else
                            {
                                var settlement = obj as Settlement;
                                if (settlement != null)
                                {
                                    stringId = settlement.StringId;
                                    currentGameName = settlement.Name?.ToString();
                                }
                            }
                        }
                    }

                    if (string.IsNullOrEmpty(stringId)) continue;

                    string customName = EncyclopediaEditBehavior.Instance.GetCustomName(stringId);
                    if (!string.IsNullOrEmpty(customName))
                    {
                        // Apply custom name to the list item
                        foreach (var namePropName in new[] { "Name", "NameText" })
                        {
                            var nameProp = itemType.GetProperty(namePropName, flags);
                            if (nameProp != null && nameProp.CanWrite)
                            {
                                nameProp.SetValue(item, customName);
                                updated++;
                                break;
                            }
                        }
                    }
                    else
                    {
                        // No custom name — ensure the list item reflects the object's current name.
                        // This handles the case where a previously applied custom name was cleared.
                        if (!string.IsNullOrEmpty(currentGameName))
                        {
                            foreach (var namePropName in new[] { "Name", "NameText" })
                            {
                                var nameProp = itemType.GetProperty(namePropName, flags);
                                if (nameProp != null && nameProp.CanWrite)
                                {
                                    string current = nameProp.GetValue(item)?.ToString() ?? "";
                                    if (current != currentGameName)
                                    {
                                        nameProp.SetValue(item, currentGameName);
                                        updated++;
                                    }
                                    break;
                                }
                            }
                        }
                    }
                }

                if (updated > 0)
                    MCMSettings.DebugLog("Updated " + updated + " names in list page");

                // Update culture/occupation filter labels with custom display names
                try
                {
                    UpdateFilterLabels(__instance, vmType, flags);
                }
                catch (Exception ex2)
                {
                    MCMSettings.DebugLog("Filter label update failed: " + ex2.Message);
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("ListPagePostfix exception: " + ex.ToString());
            }
        }

        /// <summary>
        /// Detects the list type (Hero, Clan, Kingdom) from the list items, then
        /// finds filter groups and adds new filter items for custom cultures and occupations.
        /// </summary>
        private static void UpdateFilterLabels(object listVM, Type vmType, System.Reflection.BindingFlags flags)
        {
            if (EncyclopediaEditBehavior.Instance == null) return;

            // Auto-clean orphaned custom entries before building filters
            try { EncyclopediaEditBehavior.Instance.PurgeOrphanedCustomEntries(); }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: orphan purge failed: " + ex.ToString()); }

            // Detect list type by inspecting the first item's underlying Object
            string listObjectType = DetectListObjectType(listVM, vmType, flags);

            // --- Collect custom culture data ---
            var customCultures = new Dictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase);

            foreach (var hero in Hero.AllAliveHeroes)
            {
                if (hero == null) continue;
                string displayName = EncyclopediaEditBehavior.Instance.GetCustomCultureDisplayName(hero.StringId);
                if (!string.IsNullOrEmpty(displayName))
                {
                    if (!customCultures.ContainsKey(displayName))
                        customCultures[displayName] = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    customCultures[displayName].Add(hero.StringId);
                }
            }
            foreach (var hero in Hero.DeadOrDisabledHeroes)
            {
                if (hero == null) continue;
                string displayName = EncyclopediaEditBehavior.Instance.GetCustomCultureDisplayName(hero.StringId);
                if (!string.IsNullOrEmpty(displayName))
                {
                    if (!customCultures.ContainsKey(displayName))
                        customCultures[displayName] = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    customCultures[displayName].Add(hero.StringId);
                }
            }

            // --- Collect custom occupation data ---
            // Heroes with custom occupations that may need new filter entries
            var customOccupations = new Dictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase);

            foreach (var hero in Hero.AllAliveHeroes)
            {
                if (hero == null) continue;
                int occValue = EncyclopediaEditBehavior.Instance.GetCustomOccupation(hero.StringId);
                if (occValue >= 0)
                {
                    string occName = EncyclopediaOccupationEditPopup.GetFriendlyName(occValue);
                    if (!customOccupations.ContainsKey(occName))
                        customOccupations[occName] = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    customOccupations[occName].Add(hero.StringId);
                }
            }
            foreach (var hero in Hero.DeadOrDisabledHeroes)
            {
                if (hero == null) continue;
                int occValue = EncyclopediaEditBehavior.Instance.GetCustomOccupation(hero.StringId);
                if (occValue >= 0)
                {
                    string occName = EncyclopediaOccupationEditPopup.GetFriendlyName(occValue);
                    if (!customOccupations.ContainsKey(occName))
                        customOccupations[occName] = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    customOccupations[occName].Add(hero.StringId);
                }
            }

            bool hasCultures = customCultures.Count > 0;
            bool hasOccupations = customOccupations.Count > 0;
            bool hasStaleFilters = _injectedCultureFilterNames.Count > 0 || _injectedOccupationFilterNames.Count > 0;
            if (!hasCultures && !hasOccupations && !hasStaleFilters) return;

            // Find filter groups on the VM
            object filterGroups = null;
            foreach (var candidate in new[] { "FilterGroups", "Filters", "FilterItems" })
            {
                var prop = vmType.GetProperty(candidate, flags);
                if (prop != null)
                {
                    filterGroups = prop.GetValue(listVM);
                    if (filterGroups != null) break;
                }
            }

            if (filterGroups == null) return;

            var filterEnumerable = filterGroups as System.Collections.IEnumerable;
            if (filterEnumerable == null) return;

            // Build reference sets to identify filter group types (cached for performance)
            long now = DateTime.UtcNow.Ticks;
            if (_cachedAllCultureNames == null || _cachedAllOccupationNames == null
                || (now - _filterCacheTimestamp) > FilterCacheDurationTicks)
            {
                _cachedAllCultureNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                _cachedAllOccupationNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                foreach (var hero in Hero.AllAliveHeroes)
                {
                    if (hero?.Culture?.Name != null)
                        _cachedAllCultureNames.Add(hero.Culture.Name.ToString());
                    if (hero?.CharacterObject != null)
                        _cachedAllOccupationNames.Add(hero.CharacterObject.Occupation.ToString());
                }
                _filterCacheTimestamp = now;
            }
            var allCultureNames = _cachedAllCultureNames;
            var allOccupationNames = _cachedAllOccupationNames;

            foreach (var filterGroup in filterEnumerable)
            {
                if (filterGroup == null) continue;
                var fgType = filterGroup.GetType();

                // Find filter items collection on this group
                object filterItems = null;
                foreach (var candidate in new[] { "Filters", "Items", "FilterItems" })
                {
                    var p = fgType.GetProperty(candidate, flags);
                    if (p != null)
                    {
                        filterItems = p.GetValue(filterGroup);
                        if (filterItems != null) break;
                    }
                }
                if (filterItems == null) continue;

                var itemEnumerable = filterItems as System.Collections.IEnumerable;
                if (itemEnumerable == null) continue;

                // Collect existing labels and detect whether this is a culture or occupation group
                bool isCultureGroup = false;
                bool isOccupationGroup = false;
                var existingLabels = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                object sampleItem = null;

                foreach (var item in itemEnumerable)
                {
                    if (item == null) continue;
                    if (sampleItem == null) sampleItem = item;
                    var fiType = item.GetType();
                    var nameProp = fiType.GetProperty("Name", flags);
                    if (nameProp != null)
                    {
                        string label = nameProp.GetValue(item)?.ToString();
                        if (!string.IsNullOrEmpty(label))
                        {
                            existingLabels.Add(label);
                            if (allCultureNames.Contains(label)) isCultureGroup = true;
                            if (allOccupationNames.Contains(label)) isOccupationGroup = true;
                        }
                    }
                }

                if (sampleItem == null) continue;

                // Inject custom culture filters (or clean up stale ones)
                if (isCultureGroup && (hasCultures || _injectedCultureFilterNames.Count > 0) && !isOccupationGroup)
                {
                    MCMSettings.DebugLog("Found culture filter group (" + listObjectType + " list) with " + existingLabels.Count + " items");

                    // Remove ALL previously injected custom culture filters FIRST, including stale ones
                    // whose data has already been purged. Use the tracked set which includes names
                    // from prior sessions that may no longer be in customCultures.Keys.
                    var cultureNamesToRemove = new HashSet<string>(_injectedCultureFilterNames, StringComparer.OrdinalIgnoreCase);
                    foreach (var key in customCultures.Keys)
                        cultureNamesToRemove.Add(key);
                    TryRemoveCustomFilters(filterGroup, filterItems, cultureNamesToRemove, flags);

                    if (hasCultures)
                    {
                        // Wrap vanilla culture filter predicates AFTER removing custom ones,
                        // so we only wrap actual vanilla predicates (not our custom star-prefixed ones).
                        WrapVanillaFilterPredicates(filterGroup, "Culture", flags);
                    }
                    else
                    {
                        // All custom cultures deleted (e.g., via MCM) — restore vanilla predicates
                        UnwrapVanillaFilterPredicates();
                    }

                    // Clear tracked set and rebuild with only the current valid filters
                    _injectedCultureFilterNames.Clear();
                    foreach (var kvp in customCultures)
                    {
                        // Mark custom cultures with a star prefix so users can tell them apart from vanilla
                        string filterLabel = "\u2605 " + kvp.Key;
                        TryAddCustomFilter(filterGroup, filterItems, sampleItem, filterLabel, kvp.Value, listObjectType, "Culture", flags);
                        _injectedCultureFilterNames.Add(filterLabel);
                    }
                }

                // Strip junk occupation filter entries the game creates from internal enum values
                if (isOccupationGroup && !isCultureGroup)
                {
                    TryRemoveJunkOccupationFilters(filterGroup, filterItems, flags);
                }

                // Inject custom occupation filters (or clean up stale ones)
                if (isOccupationGroup && (hasOccupations || _injectedOccupationFilterNames.Count > 0) && !isCultureGroup)
                {
                    MCMSettings.DebugLog("Found occupation filter group (" + listObjectType + " list) with " + existingLabels.Count + " items");

                    // Remove ALL previously injected custom occupation filters FIRST
                    var occNamesToRemove = new HashSet<string>(_injectedOccupationFilterNames, StringComparer.OrdinalIgnoreCase);
                    foreach (var key in customOccupations.Keys)
                        occNamesToRemove.Add(key);
                    TryRemoveCustomFilters(filterGroup, filterItems, occNamesToRemove, flags);

                    if (hasOccupations)
                    {
                        // Wrap vanilla occupation filter predicates AFTER removing custom ones,
                        // so we only wrap actual vanilla predicates (not our custom star-prefixed ones).
                        WrapVanillaFilterPredicates(filterGroup, "Occupation", flags);
                    }
                    else
                    {
                        // All custom occupations deleted (e.g., via MCM) — restore vanilla predicates
                        UnwrapVanillaFilterPredicates();
                    }

                    // Clear tracked set and rebuild with only the current valid filters
                    _injectedOccupationFilterNames.Clear();
                    foreach (var kvp in customOccupations)
                    {
                        // Mark custom occupations with a star prefix so users can tell them apart from vanilla
                        string filterLabel = "\u2605 " + kvp.Key;
                        TryAddCustomFilter(filterGroup, filterItems, sampleItem, filterLabel, kvp.Value, listObjectType, "Occupation", flags);
                        _injectedOccupationFilterNames.Add(filterLabel);
                    }
                }
            }
        }

        /// <summary>
        /// Inspects the first list item's Object property to determine the list type.
        /// Returns "Hero", "Clan", "Kingdom", or "Unknown".
        /// </summary>
        private static string DetectListObjectType(object listVM, Type vmType, System.Reflection.BindingFlags flags)
        {
            try
            {
                object items = null;
                foreach (var candidate in new[] { "Items", "ListItems", "FilteredItems" })
                {
                    var prop = vmType.GetProperty(candidate, flags);
                    if (prop != null)
                    {
                        items = prop.GetValue(listVM);
                        if (items != null) break;
                    }
                }
                if (items == null) return "Unknown";

                var enumerable = items as System.Collections.IEnumerable;
                if (enumerable == null) return "Unknown";

                foreach (var item in enumerable)
                {
                    if (item == null) continue;
                    var itemType = item.GetType();
                    var objProp = itemType.GetProperty("Object", flags) ?? itemType.GetProperty("Obj", flags);
                    if (objProp == null) continue;

                    var obj = objProp.GetValue(item);
                    if (obj is Hero) return "Hero";
                    if (obj is Clan) return "Clan";
                    if (obj is Kingdom) return "Kingdom";
                    if (obj is Settlement) return "Settlement";
                    return obj?.GetType().Name ?? "Unknown";
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: DetectListObjectType failed: " + ex.ToString()); }
            return "Unknown";
        }

        /// <summary>
        /// Removes any existing custom filter items whose names match the given set.
        /// Removes from both the VM collection (UI checkboxes) and the underlying
        /// data list (EncyclopediaFilterItem predicates). This ensures stale predicates
        /// with outdated hero ID snapshots are replaced with fresh ones.
        /// </summary>
        /// <summary>
        /// Junk occupation labels the game creates from internal enum sentinel values.
        /// These are matched case-insensitively and with partial matching to catch
        /// variants like "Number Of Occupations", "Number Of Occupation", "NumberOfOccupations", etc.
        /// </summary>
        // Track custom filter names we've injected into the UI so we can remove
        // stale ones even after the underlying data has been purged.
        private static HashSet<string> _injectedCultureFilterNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        private static HashSet<string> _injectedOccupationFilterNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        // Cached reference sets for filter group detection (avoid iterating all heroes every refresh)
        private static HashSet<string> _cachedAllCultureNames;
        private static HashSet<string> _cachedAllOccupationNames;
        private static long _filterCacheTimestamp;
        private const long FilterCacheDurationTicks = 50000000; // 5 seconds in ticks

        private static readonly string[] _junkOccupationLabels = new[]
        {
            "NumberOfOccupations", "Number Of Occupations", "Number Of Occupation",
            "NotAssigned", "Not Assigned", "Custom"
        };

        private static void TryRemoveJunkOccupationFilters(
            object filterGroup, object filterCollection, System.Reflection.BindingFlags flags)
        {
            try
            {
                var junk = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                foreach (var j in _junkOccupationLabels)
                    junk.Add(j);

                // Remove from VM list
                var vmList = filterCollection as System.Collections.IList;
                if (vmList != null)
                {
                    for (int i = vmList.Count - 1; i >= 0; i--)
                    {
                        var item = vmList[i];
                        if (item == null) continue;
                        var nameProp = item.GetType().GetProperty("Name", flags);
                        if (nameProp == null) continue;
                        string name = nameProp.GetValue(item)?.ToString();
                        if (!string.IsNullOrEmpty(name) && junk.Contains(name))
                        {
                            vmList.RemoveAt(i);
                            MCMSettings.DebugLog("Removed junk occupation filter: " + name);
                        }
                    }
                }

                // Remove from underlying data list
                var reflFlags = System.Reflection.BindingFlags.Public |
                    System.Reflection.BindingFlags.NonPublic |
                    System.Reflection.BindingFlags.Instance;
                var fgType = filterGroup.GetType();

                foreach (var f in fgType.GetFields(reflFlags))
                {
                    if (f.FieldType.FullName == null || !f.FieldType.FullName.Contains("EncyclopediaFilterItem"))
                        continue;
                    var dataList = f.GetValue(filterGroup) as System.Collections.IList;
                    if (dataList == null) continue;

                    for (int i = dataList.Count - 1; i >= 0; i--)
                    {
                        var dataItem = dataList[i];
                        if (dataItem == null) continue;
                        var diNameProp = dataItem.GetType().GetProperty("Name", reflFlags);
                        if (diNameProp == null) continue;
                        string diName = diNameProp.GetValue(dataItem)?.ToString();
                        if (!string.IsNullOrEmpty(diName) && junk.Contains(diName))
                        {
                            dataList.RemoveAt(i);
                            MCMSettings.DebugLog("Removed junk occupation filter data: " + diName);
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TryRemoveJunkOccupationFilters failed: " + ex.ToString());
            }
        }

        private static void TryRemoveCustomFilters(
            object filterGroup, object filterCollection,
            IEnumerable<string> customNames, System.Reflection.BindingFlags flags)
        {
            try
            {
                var reflFlags = System.Reflection.BindingFlags.Public |
                    System.Reflection.BindingFlags.NonPublic |
                    System.Reflection.BindingFlags.Instance;
                var namesToRemove = new HashSet<string>(customNames, StringComparer.OrdinalIgnoreCase);
                if (namesToRemove.Count == 0) return;

                // Remove from the VM collection (MBBindingList<EncyclopediaListFilterVM>)
                var vmList = filterCollection as System.Collections.IList;
                if (vmList != null)
                {
                    for (int i = vmList.Count - 1; i >= 0; i--)
                    {
                        var item = vmList[i];
                        if (item == null) continue;
                        var nameProp = item.GetType().GetProperty("Name", flags);
                        if (nameProp == null) continue;
                        string name = nameProp.GetValue(item)?.ToString();
                        if (!string.IsNullOrEmpty(name) && namesToRemove.Contains(name))
                        {
                            vmList.RemoveAt(i);
                            MCMSettings.DebugLog("Removed stale custom filter VM: " + name);
                        }
                    }
                }

                // Remove from the underlying data list (List<EncyclopediaFilterItem>)
                // Uses multi-strategy name resolution (property → field → TextObject brute force)
                // because EncyclopediaFilterItem.Name property may return null.
                var fgType = filterGroup.GetType();
                var fgFields = fgType.GetFields(reflFlags);

                foreach (var f in fgFields)
                {
                    if (f.FieldType.FullName == null) continue;
                    if (!f.FieldType.FullName.Contains("EncyclopediaFilterItem")) continue;

                    var dataList = f.GetValue(filterGroup) as System.Collections.IList;
                    if (dataList == null) continue;

                    RemoveDataItemsByName(dataList, namesToRemove, reflFlags, true);
                }

                // Also check nested data group fields
                foreach (var f in fgFields)
                {
                    if (f.FieldType.Name == null) continue;
                    if (!f.FieldType.Name.Contains("FilterGroup") && !f.FieldType.Name.Contains("EncyclopediaFilterGroup"))
                        continue;

                    var dataGroup = f.GetValue(filterGroup);
                    if (dataGroup == null) continue;

                    foreach (var dgf in dataGroup.GetType().GetFields(reflFlags))
                    {
                        if (dgf.FieldType.FullName == null || !dgf.FieldType.FullName.Contains("EncyclopediaFilterItem"))
                            continue;

                        var dataList = dgf.GetValue(dataGroup) as System.Collections.IList;
                        if (dataList == null) continue;

                        RemoveDataItemsByName(dataList, namesToRemove, reflFlags, true);
                    }
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TryRemoveCustomFilters failed: " + ex.ToString());
            }
        }

        /// <summary>
        /// Resolves the display name of a filter data item using multiple strategies:
        /// 1. Name property, 2. _name / backing field, 3. brute-force TextObject field scan.
        /// Returns null if no name could be resolved.
        /// </summary>
        private static string ResolveDataItemName(object dataItem, System.Reflection.BindingFlags reflFlags)
        {
            var diType = dataItem.GetType();

            // Strategy 1: Name property
            var nameProp = diType.GetProperty("Name", reflFlags);
            if (nameProp != null)
            {
                string name = nameProp.GetValue(dataItem)?.ToString();
                if (!string.IsNullOrEmpty(name)) return name;
            }

            // Strategy 2: _name field or backing field
            var nameField = diType.GetField("_name", reflFlags)
                         ?? diType.GetField("<Name>k__BackingField", reflFlags);
            if (nameField != null)
            {
                string name = nameField.GetValue(dataItem)?.ToString();
                if (!string.IsNullOrEmpty(name)) return name;
            }

            // Strategy 3: brute-force scan all TextObject fields
            foreach (var f in diType.GetFields(reflFlags))
            {
                if (f.FieldType == typeof(TextObject) || f.FieldType.Name == "TextObject")
                {
                    var val = f.GetValue(dataItem);
                    if (val != null)
                    {
                        string s = val.ToString();
                        if (!string.IsNullOrEmpty(s)) return s;
                    }
                }
            }

            return null;
        }

        /// <summary>
        /// Removes data items from an IList whose resolved name matches any name in the given set.
        /// Uses the multi-strategy name resolution (ResolveDataItemName).
        /// </summary>
        private static void RemoveDataItemsByName(
            System.Collections.IList dataList, HashSet<string> namesToRemove,
            System.Reflection.BindingFlags reflFlags, bool log)
        {
            for (int i = dataList.Count - 1; i >= 0; i--)
            {
                var dataItem = dataList[i];
                if (dataItem == null) continue;

                string diName = ResolveDataItemName(dataItem, reflFlags);
                if (!string.IsNullOrEmpty(diName) && namesToRemove.Contains(diName))
                {
                    dataList.RemoveAt(i);
                    if (log)
                        MCMSettings.DebugLog("Removed stale custom filter data: " + diName);
                }
            }
        }

        /// <summary>
        /// Creates and adds a new filter item for a custom culture or occupation.
        /// Adds both the data-level EncyclopediaFilterItem (so filtering works)
        /// and the VM-level EncyclopediaListFilterVM (so the checkbox appears).
        /// Supports Hero, Clan, and Kingdom list pages with type-appropriate predicates.
        /// filterKind is "Culture" or "Occupation" — affects predicate logic.
        /// </summary>
        private static void TryAddCustomFilter(
            object filterGroup, object filterCollection, object sampleItem,
            string customName, HashSet<string> heroIds, string listObjectType,
            string filterKind, System.Reflection.BindingFlags flags)
        {
            try
            {
                var reflFlags = System.Reflection.BindingFlags.Public |
                    System.Reflection.BindingFlags.NonPublic |
                    System.Reflection.BindingFlags.Instance;
                var sampleType = sampleItem.GetType();
                var collectionType = filterCollection.GetType();
                var fgType = filterGroup.GetType();

                // 0. Guard: skip if filter with this name already exists in VM collection.
                //    This prevents duplicate accumulation when the data list removal fails
                //    and the game re-creates VMs from polluted data lists across refreshes.
                var vmList = filterCollection as System.Collections.IList;
                if (vmList != null)
                {
                    foreach (var existing in vmList)
                    {
                        if (existing == null) continue;
                        var np = existing.GetType().GetProperty("Name", reflFlags);
                        if (np != null)
                        {
                            string existName = np.GetValue(existing)?.ToString();
                            if (string.Equals(existName, customName, StringComparison.OrdinalIgnoreCase))
                            {
                                MCMSettings.DebugLog("Skipping duplicate " + filterKind.ToLower() + " filter '" + customName + "' (already in VM)");
                                return;
                            }
                        }
                    }
                }

                // 1. Find the EncyclopediaFilterItem data type
                var csAssembly = typeof(Hero).Assembly;
                var filterItemDataType = csAssembly.GetType(
                    "TaleWorlds.CampaignSystem.Encyclopedia.EncyclopediaFilterItem");
                if (filterItemDataType == null)
                {
                    MCMSettings.DebugLog("Cannot find EncyclopediaFilterItem type");
                    return;
                }

                // 2. Create a dynamic predicate that queries the behavior at runtime.
                // This ensures the predicate always reflects the current state, even
                // if heroes are added/removed from a custom culture/occupation after
                // the filter was created.
                string capturedName = customName;
                string capturedKind = filterKind;

                // 3. Find the EncyclopediaFilterItem constructor to determine the expected predicate type
                var textObj = new TextObject(customName);
                var dataCtors = filterItemDataType.GetConstructors(reflFlags);

                System.Reflection.ConstructorInfo dataCtor = null;
                foreach (var ctor in dataCtors)
                {
                    var pars = ctor.GetParameters();
                    if (pars.Length == 2
                        && pars[0].ParameterType == typeof(TextObject)
                        && pars[1].ParameterType.Name.Contains("Predicate"))
                    {
                        dataCtor = ctor;
                        break;
                    }
                }
                if (dataCtor == null)
                {
                    MCMSettings.DebugLog("Cannot find EncyclopediaFilterItem(TextObject, Predicate) constructor");
                    return;
                }

                // Determine the expected predicate item type from the constructor parameter.
                // The game uses typed predicates (e.g. Predicate<Hero>, Predicate<Clan>).
                // We must create a delegate of the exact matching type — Predicate<object>
                // may not be accepted even though Predicate<in T> is contravariant, because
                // ConstructorInfo.Invoke can reject mismatched delegate types at runtime.
                Type ctorPredicateType = dataCtor.GetParameters()[1].ParameterType;
                Type predicateItemType = typeof(object);
                if (ctorPredicateType.IsGenericType)
                {
                    var genArgs = ctorPredicateType.GetGenericArguments();
                    if (genArgs.Length > 0)
                        predicateItemType = genArgs[0];
                }

                object predicate;

                if (listObjectType == "Clan" && (predicateItemType == typeof(Clan) || predicateItemType == typeof(object)))
                {
                    if (predicateItemType == typeof(Clan))
                    {
                        predicate = new Predicate<Clan>((clan) =>
                        {
                            if (clan == null) return false;
                            var beh = EncyclopediaEditBehavior.Instance;
                            if (beh == null) return false;
                            foreach (var hero in clan.Heroes)
                            {
                                if (hero != null && HeroMatchesCustomFilter(beh, hero.StringId, capturedName, capturedKind))
                                    return true;
                            }
                            return false;
                        });
                    }
                    else
                    {
                        predicate = new Predicate<object>((obj) =>
                        {
                            var clan = obj as Clan;
                            if (clan == null) return false;
                            var beh = EncyclopediaEditBehavior.Instance;
                            if (beh == null) return false;
                            foreach (var hero in clan.Heroes)
                            {
                                if (hero != null && HeroMatchesCustomFilter(beh, hero.StringId, capturedName, capturedKind))
                                    return true;
                            }
                            return false;
                        });
                    }
                }
                else if (listObjectType == "Kingdom" && (predicateItemType == typeof(Kingdom) || predicateItemType == typeof(object)))
                {
                    if (predicateItemType == typeof(Kingdom))
                    {
                        predicate = new Predicate<Kingdom>((kingdom) =>
                        {
                            if (kingdom == null) return false;
                            var beh = EncyclopediaEditBehavior.Instance;
                            if (beh == null) return false;
                            foreach (var clan in kingdom.Clans)
                            {
                                if (clan == null) continue;
                                foreach (var hero in clan.Heroes)
                                {
                                    if (hero != null && HeroMatchesCustomFilter(beh, hero.StringId, capturedName, capturedKind))
                                        return true;
                                }
                            }
                            return false;
                        });
                    }
                    else
                    {
                        predicate = new Predicate<object>((obj) =>
                        {
                            var kingdom = obj as Kingdom;
                            if (kingdom == null) return false;
                            var beh = EncyclopediaEditBehavior.Instance;
                            if (beh == null) return false;
                            foreach (var clan in kingdom.Clans)
                            {
                                if (clan == null) continue;
                                foreach (var hero in clan.Heroes)
                                {
                                    if (hero != null && HeroMatchesCustomFilter(beh, hero.StringId, capturedName, capturedKind))
                                        return true;
                                }
                            }
                            return false;
                        });
                    }
                }
                else if (listObjectType == "Settlement" && (predicateItemType == typeof(Settlement) || predicateItemType == typeof(object)))
                {
                    // Settlement list: match if the settlement's owner hero has the custom culture
                    if (predicateItemType == typeof(Settlement))
                    {
                        predicate = new Predicate<Settlement>((s) =>
                        {
                            if (s == null) return false;
                            var beh = EncyclopediaEditBehavior.Instance;
                            if (beh == null) return false;
                            var owner = s.OwnerClan?.Leader;
                            if (owner == null) return false;
                            return HeroMatchesCustomFilter(beh, owner.StringId, capturedName, capturedKind);
                        });
                    }
                    else
                    {
                        predicate = new Predicate<object>((obj) =>
                        {
                            var s = obj as Settlement;
                            if (s == null) return false;
                            var beh = EncyclopediaEditBehavior.Instance;
                            if (beh == null) return false;
                            var owner = s.OwnerClan?.Leader;
                            if (owner == null) return false;
                            return HeroMatchesCustomFilter(beh, owner.StringId, capturedName, capturedKind);
                        });
                    }
                }
                else
                {
                    // Default: Hero list (or unknown list type)
                    if (predicateItemType == typeof(Hero))
                    {
                        predicate = new Predicate<Hero>((hero) =>
                        {
                            if (hero == null) return false;
                            var beh = EncyclopediaEditBehavior.Instance;
                            if (beh == null) return false;
                            return HeroMatchesCustomFilter(beh, hero.StringId, capturedName, capturedKind);
                        });
                    }
                    else
                    {
                        predicate = new Predicate<object>((obj) =>
                        {
                            var hero = obj as Hero;
                            if (hero == null) return false;
                            var beh = EncyclopediaEditBehavior.Instance;
                            if (beh == null) return false;
                            return HeroMatchesCustomFilter(beh, hero.StringId, capturedName, capturedKind);
                        });
                    }
                }

                MCMSettings.DebugLog("Custom filter predicate type: " + predicate.GetType().Name
                    + " (expected: " + ctorPredicateType.Name + ", itemType: " + predicateItemType.Name + ")");

                object dataItem;
                try
                {
                    dataItem = dataCtor.Invoke(new object[] { textObj, predicate });
                }
                catch (Exception ctorEx)
                {
                    // If the typed predicate fails, fall back to Predicate<object>
                    MCMSettings.DebugLog("Filter ctor failed with typed predicate (" + ctorEx.GetType().Name
                        + ": " + ctorEx.Message + "), retrying with Predicate<object>");
                    Predicate<object> fallbackPredicate = (obj) =>
                    {
                        var beh = EncyclopediaEditBehavior.Instance;
                        if (beh == null) return false;
                        var hero = obj as Hero;
                        if (hero != null)
                            return HeroMatchesCustomFilter(beh, hero.StringId, capturedName, capturedKind);
                        var s = obj as Settlement;
                        if (s != null)
                        {
                            var owner = s.OwnerClan?.Leader;
                            return owner != null && HeroMatchesCustomFilter(beh, owner.StringId, capturedName, capturedKind);
                        }
                        return false;
                    };
                    dataItem = dataCtor.Invoke(new object[] { textObj, fallbackPredicate });
                }

                // Verify the predicate was actually stored in the data item
                try
                {
                    var dataItemType = dataItem.GetType();
                    foreach (var f in dataItemType.GetFields(reflFlags))
                    {
                        if (f.FieldType.Name.Contains("Predicate"))
                        {
                            var storedPred = f.GetValue(dataItem);
                            if (storedPred == null)
                                MCMSettings.DebugLog("WARNING: Predicate field '" + f.Name + "' is null after construction — filter will not work");
                            else
                                MCMSettings.DebugLog("Predicate field '" + f.Name + "' stored OK (type=" + storedPred.GetType().Name + ")");
                            break;
                        }
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: predicate verification failed: " + ex.ToString()); }

                // 4. Inject the data item into the filter group's underlying data list
                bool injectedDataItem = false;

                var fgFields = fgType.GetFields(reflFlags);

                // First check if the VM itself has a list of EncyclopediaFilterItem
                foreach (var f in fgFields)
                {
                    if (f.FieldType.FullName != null && f.FieldType.FullName.Contains("EncyclopediaFilterItem"))
                    {
                        var dataList = f.GetValue(filterGroup);
                        if (dataList != null)
                        {
                            // Remove any existing data items with the same name to prevent accumulation
                            RemoveDuplicateDataItems(dataList, customName, reflFlags);

                            var addM = dataList.GetType().GetMethod("Add");
                            if (addM != null)
                            {
                                addM.Invoke(dataList, new object[] { dataItem });
                                injectedDataItem = true;
                                break;
                            }
                        }
                    }
                }

                // Then check the FilterGroup data object's Filters field
                if (!injectedDataItem)
                {
                    foreach (var f in fgFields)
                    {
                        if (!f.FieldType.Name.Contains("EncyclopediaFilterGroup") &&
                            !f.FieldType.Name.Contains("FilterGroup"))
                            continue;

                        var dataGroup = f.GetValue(filterGroup);
                        if (dataGroup == null) continue;

                        var dgType = dataGroup.GetType();

                        // Check fields (List<EncyclopediaFilterItem> Filters is a field)
                        foreach (var dgf in dgType.GetFields(reflFlags))
                        {
                            if (!injectedDataItem &&
                                dgf.FieldType.FullName != null &&
                                dgf.FieldType.FullName.Contains("EncyclopediaFilterItem"))
                            {
                                var dataList = dgf.GetValue(dataGroup);
                                if (dataList != null)
                                {
                                    // Remove any existing data items with the same name to prevent accumulation
                                    RemoveDuplicateDataItems(dataList, customName, reflFlags);

                                    var addM = dataList.GetType().GetMethod("Add");
                                    if (addM != null)
                                    {
                                        addM.Invoke(dataList, new object[] { dataItem });
                                        injectedDataItem = true;
                                    }
                                }
                            }
                        }

                        // Check properties as fallback
                        if (!injectedDataItem)
                        {
                            foreach (var dgp in dgType.GetProperties(reflFlags))
                            {
                                if (dgp.PropertyType.FullName != null &&
                                    dgp.PropertyType.FullName.Contains("EncyclopediaFilterItem"))
                                {
                                    var dataList = dgp.GetValue(dataGroup);
                                    if (dataList != null)
                                    {
                                        RemoveDuplicateDataItems(dataList, customName, reflFlags);

                                        var addM = dataList.GetType().GetMethod("Add");
                                        if (addM != null)
                                        {
                                            addM.Invoke(dataList, new object[] { dataItem });
                                            injectedDataItem = true;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }

                if (!injectedDataItem)
                {
                    MCMSettings.DebugLog("WARNING: Could not inject " + filterKind + " filter data for '" + customName + "'");
                    return;
                }

                // 5. Extract the _updateFilters callback from the sample VM item
                var updateFiltersField = sampleType.GetField("_updateFilters", reflFlags);
                if (updateFiltersField == null)
                {
                    MCMSettings.DebugLog("Cannot find _updateFilters field on filter VM");
                    return;
                }
                var updateFiltersCallback = updateFiltersField.GetValue(sampleItem);

                // 6. Create the EncyclopediaListFilterVM
                var vmCtors = sampleType.GetConstructors(reflFlags);
                System.Reflection.ConstructorInfo vmCtor = null;
                foreach (var ctor in vmCtors)
                {
                    var pars = ctor.GetParameters();
                    if (pars.Length == 2) { vmCtor = ctor; break; }
                }
                if (vmCtor == null)
                {
                    MCMSettings.DebugLog("Cannot find EncyclopediaListFilterVM 2-param constructor");
                    return;
                }
                var newFilterVM = vmCtor.Invoke(new object[] { dataItem, updateFiltersCallback });

                // 7. Add to the MBBindingList<EncyclopediaListFilterVM> collection (UI)
                var addMethod = collectionType.GetMethod("Add");
                if (addMethod == null)
                {
                    MCMSettings.DebugLog("Cannot find Add method on filter collection");
                    return;
                }
                addMethod.Invoke(filterCollection, new object[] { newFilterVM });

                MCMSettings.DebugLog("Added custom " + filterKind.ToLower() + " filter '" + customName + "' for " + listObjectType + " list (dynamic predicate)");
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TryAddCustomFilter failed for '" + customName + "' (" + filterKind + "): " + ex.ToString());
            }
        }

        /// <summary>
        /// Removes all items from a data list (List&lt;EncyclopediaFilterItem&gt;) whose name
        /// matches the given custom name. Uses multiple strategies to read the name:
        /// Name property, _name field, and TextObject ToString(). This prevents
        /// duplicate data items from accumulating across list page refreshes.
        /// </summary>
        private static void RemoveDuplicateDataItems(object dataList, string customName,
            System.Reflection.BindingFlags reflFlags)
        {
            try
            {
                var iList = dataList as System.Collections.IList;
                if (iList == null || iList.Count == 0) return;

                var nameSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { customName };
                RemoveDataItemsByName(iList, nameSet, reflFlags, false);
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("RemoveDuplicateDataItems failed for '" + customName + "': " + ex.ToString());
            }
        }

        // Store original (unwrapped) predicates for vanilla filter data items.
        // Key: data item object reference, Value: original predicate before wrapping.
        // This prevents double-wrapping and enables clean restoration when all customs are deleted.
        private static Dictionary<object, object> _originalFilterPredicates =
            new Dictionary<object, object>(new ObjectReferenceEqualityComparer());

        // Also track the predicate FieldInfo so we can restore originals in UnwrapVanillaFilterPredicates
        private static System.Reflection.FieldInfo _cachedPredicateField;

        private class ObjectReferenceEqualityComparer : IEqualityComparer<object>
        {
            public new bool Equals(object x, object y) => ReferenceEquals(x, y);
            public int GetHashCode(object obj) => System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode(obj);
        }

        /// <summary>
        /// Wraps vanilla filter predicates on the given filter group so that heroes with
        /// custom culture or occupation are excluded from the original vanilla filters.
        /// This prevents a hero with custom culture "SD" from still appearing under "Nord".
        /// IMPORTANT: Call this AFTER TryRemoveCustomFilters so that only vanilla data items
        /// remain in the list (our star-prefixed custom items should already be removed).
        /// </summary>
        private static void WrapVanillaFilterPredicates(
            object filterGroup, string filterKind, System.Reflection.BindingFlags flags)
        {
            try
            {
                var reflFlags = System.Reflection.BindingFlags.Public
                              | System.Reflection.BindingFlags.NonPublic
                              | System.Reflection.BindingFlags.Instance;
                var fgType = filterGroup.GetType();

                // Find the EncyclopediaFilterItem data list (same approach as TryAddCustomFilter)
                System.Collections.IList dataList = null;

                foreach (var f in fgType.GetFields(reflFlags))
                {
                    if (f.FieldType.FullName != null && f.FieldType.FullName.Contains("EncyclopediaFilterItem"))
                    {
                        dataList = f.GetValue(filterGroup) as System.Collections.IList;
                        if (dataList != null) break;
                    }
                }

                // Fallback: check nested FilterGroup data object
                if (dataList == null)
                {
                    foreach (var f in fgType.GetFields(reflFlags))
                    {
                        if (!f.FieldType.Name.Contains("FilterGroup") &&
                            !f.FieldType.Name.Contains("EncyclopediaFilterGroup"))
                            continue;
                        var dataGroup = f.GetValue(filterGroup);
                        if (dataGroup == null) continue;
                        foreach (var dgf in dataGroup.GetType().GetFields(reflFlags))
                        {
                            if (dgf.FieldType.FullName != null && dgf.FieldType.FullName.Contains("EncyclopediaFilterItem"))
                            {
                                dataList = dgf.GetValue(dataGroup) as System.Collections.IList;
                                if (dataList != null) break;
                            }
                        }
                        if (dataList != null) break;
                    }
                }

                if (dataList == null || dataList.Count == 0) return;

                // Find the predicate field on EncyclopediaFilterItem
                var itemType = dataList[0].GetType();
                System.Reflection.FieldInfo predicateField = null;
                foreach (var f in itemType.GetFields(reflFlags))
                {
                    if (f.FieldType.Name.Contains("Predicate"))
                    {
                        predicateField = f;
                        break;
                    }
                }

                if (predicateField == null)
                {
                    MCMSettings.DebugLog("Could not find Predicate field on " + itemType.Name);
                    return;
                }

                string capturedKind = filterKind;
                int wrapped = 0;
                int skippedCustom = 0;

                _cachedPredicateField = predicateField;

                for (int i = 0; i < dataList.Count; i++)
                {
                    var item = dataList[i];
                    if (item == null) continue;

                    // Safety: skip any remaining custom filters (star prefix)
                    string itemName = ResolveDataItemName(item, reflFlags);
                    if (!string.IsNullOrEmpty(itemName) && itemName.StartsWith("\u2605"))
                    {
                        skippedCustom++;
                        continue;
                    }

                    // Get the original (unwrapped) predicate — either from our cache or from the item
                    object originalPredicate;
                    if (_originalFilterPredicates.TryGetValue(item, out var storedOriginal))
                    {
                        // Already wrapped before — use the stored original to avoid double-wrapping
                        originalPredicate = storedOriginal;
                    }
                    else
                    {
                        // First time wrapping — current predicate IS the original
                        originalPredicate = predicateField.GetValue(item);
                        if (originalPredicate == null) continue;
                        _originalFilterPredicates[item] = originalPredicate;
                    }

                    var invokeMethod = originalPredicate.GetType().GetMethod("Invoke");
                    if (invokeMethod == null) continue;

                    // Wrap the predicate to exclude heroes with custom culture/occupation.
                    // Create a typed wrapper that matches the predicate field type (e.g. Predicate<Hero>)
                    // to avoid type mismatch when the game evaluates filters.
                    var capturedOriginal = originalPredicate;
                    var capturedInvoke = invokeMethod;

                    // Determine the predicate item type from the field
                    Type fieldPredicateItemType = typeof(object);
                    if (predicateField.FieldType.IsGenericType)
                    {
                        var fGenArgs = predicateField.FieldType.GetGenericArguments();
                        if (fGenArgs.Length > 0)
                            fieldPredicateItemType = fGenArgs[0];
                    }

                    object wrappedPredicate;
                    if (fieldPredicateItemType == typeof(Hero))
                    {
                        wrappedPredicate = new Predicate<Hero>((hero) =>
                        {
                            if (hero != null)
                            {
                                var beh = EncyclopediaEditBehavior.Instance;
                                if (beh != null)
                                {
                                    if (capturedKind == "Culture"
                                        && !string.IsNullOrEmpty(beh.GetCustomCultureDisplayName(hero.StringId)))
                                        return false;
                                    if (capturedKind == "Occupation"
                                        && beh.HasCustomOccupation(hero.StringId))
                                        return false;
                                }
                            }
                            return (bool)capturedInvoke.Invoke(capturedOriginal, new object[] { hero });
                        });
                    }
                    else
                    {
                        wrappedPredicate = new Predicate<object>((obj) =>
                        {
                            var hero = obj as Hero;
                            if (hero != null)
                            {
                                var beh = EncyclopediaEditBehavior.Instance;
                                if (beh != null)
                                {
                                    if (capturedKind == "Culture"
                                        && !string.IsNullOrEmpty(beh.GetCustomCultureDisplayName(hero.StringId)))
                                        return false;
                                    if (capturedKind == "Occupation"
                                        && beh.HasCustomOccupation(hero.StringId))
                                        return false;
                                }
                            }
                            return (bool)capturedInvoke.Invoke(capturedOriginal, new[] { obj });
                        });
                    }

                    predicateField.SetValue(item, wrappedPredicate);
                    wrapped++;
                }

                if (wrapped > 0 || skippedCustom > 0)
                    MCMSettings.DebugLog("Wrapped " + wrapped + " vanilla " + filterKind
                        + " filter predicates (skipped " + skippedCustom + " custom)");
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("WrapVanillaFilterPredicates failed: " + ex.ToString());
            }
        }

        /// <summary>
        /// Restores original (unwrapped) predicates on all previously wrapped vanilla filter items.
        /// Called when all custom cultures/occupations have been deleted (e.g., via MCM bulk delete)
        /// so that vanilla filters return to their normal behavior without the exclusion check.
        /// </summary>
        private static void UnwrapVanillaFilterPredicates()
        {
            try
            {
                if (_originalFilterPredicates.Count == 0) return;
                if (_cachedPredicateField == null) return;

                int restored = 0;
                foreach (var kvp in _originalFilterPredicates)
                {
                    try
                    {
                        _cachedPredicateField.SetValue(kvp.Key, kvp.Value);
                        restored++;
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: restoring filter predicate failed: " + ex.ToString()); }
                }
                _originalFilterPredicates.Clear();

                if (restored > 0)
                    MCMSettings.DebugLog("Unwrapped " + restored + " vanilla filter predicates (all customs deleted)");
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("UnwrapVanillaFilterPredicates failed: " + ex.ToString());
            }
        }

        /// <summary>
        /// Checks if a hero matches a custom filter by querying the behavior at runtime.
        /// For Culture filters, checks the custom culture display name.
        /// For Occupation filters, checks the custom occupation enum name.
        /// </summary>
        private static bool HeroMatchesCustomFilter(EncyclopediaEditBehavior behavior,
            string heroId, string filterName, string filterKind)
        {
            // Strip the star prefix (★ ) added to custom filter labels before comparing
            string rawName = filterName;
            if (rawName.StartsWith("\u2605 ") && rawName.Length >= 2)
                rawName = rawName.Substring(2);

            if (filterKind == "Culture")
            {
                string dn = behavior.GetCustomCultureDisplayName(heroId);
                return string.Equals(dn, rawName, StringComparison.OrdinalIgnoreCase);
            }
            else // Occupation
            {
                int occ = behavior.GetCustomOccupation(heroId);
                if (occ < 0) return false;
                string friendlyName = EncyclopediaOccupationEditPopup.GetFriendlyName(occ);
                return string.Equals(friendlyName, rawName, StringComparison.OrdinalIgnoreCase);
            }
        }
    }

    // ============================================
    //  Name/Title edit popup (Ctrl+N)
    // ============================================
    public static class EncyclopediaNameEditPopup
    {
        private static volatile bool _namePopupOpen = false;
        private static volatile bool _titlePopupOpen = false;
        public static bool IsPopupOpen => _namePopupOpen || _titlePopupOpen;

        private const int DefaultMaxNameLength = 100;

        private static readonly string[] SupportedPageTypes =
            { "Hero", "Clan", "Kingdom", "Settlement", "Concept" };

        private static int GetMaxNameLength()
        {
            try
            {
                var settings = MCMSettings.Instance;
                if (settings != null) return settings.MaxNameLength;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: MaxNameLength read failed: " + ex.ToString()); }
            return DefaultMaxNameLength;
        }

        private static string SanitizeName(string input)
        {
            if (string.IsNullOrEmpty(input)) return null;
            string trimmed = input.Trim();
            if (string.IsNullOrEmpty(trimmed)) return null;

            // Strip control characters, newlines, tabs
            var sb = new System.Text.StringBuilder(trimmed.Length);
            bool hadInvalidChars = false;
            foreach (char c in trimmed)
            {
                if (char.IsControl(c))
                {
                    hadInvalidChars = true;
                    continue;
                }
                sb.Append(c);
            }

            string result = sb.ToString().Trim();
            if (string.IsNullOrEmpty(result)) return null;

            // Enforce max length
            int maxLen = GetMaxNameLength();
            if (result.Length > maxLen)
            {
                result = result.Substring(0, maxLen);
                hadInvalidChars = true;
            }

            if (hadInvalidChars)
            {
                try
                {
                    InformationManager.DisplayMessage(
                        new InformationMessage(Localization.L("name_invalid_chars"), Colors.Yellow));
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: invalid chars warning failed: " + ex.ToString()); }
            }

            return result;
        }

        public static void TryOpen()
        {
            if (_namePopupOpen || _titlePopupOpen) return;
            if (EncyclopediaEditBehavior.Instance == null) return;
            if (string.IsNullOrEmpty(EncyclopediaPageTracker.CurrentObjectId)) return;

            string pageType = EncyclopediaPageTracker.CurrentPageType;

            if (Array.IndexOf(SupportedPageTypes, pageType) < 0)
            {
                MCMSettings.DebugLog("Ctrl+N ignored - unsupported page type (type=" + pageType + ")");
                return;
            }

            try
            {
                var settings = MCMSettings.Instance;
                if (settings != null && !settings.EnableHeroNameEditing) return;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: checking EnableHeroNameEditing setting failed: " + ex.ToString()); }

            EncyclopediaInputBlocker.Block();
            _namePopupOpen = true;
            string objectId = EncyclopediaPageTracker.CurrentObjectId;
            bool isHero = pageType == "Hero";

            string currentName = EncyclopediaEditBehavior.Instance.GetCustomName(objectId)
                                 ?? EncyclopediaPageTracker.CurrentName
                                 ?? "";

            string originalName = EncyclopediaPageTracker.CurrentName ?? "";

            string popupTitle;
            switch (pageType)
            {
                case "Kingdom": popupTitle = Localization.L("name_edit_title_kingdom"); break;
                case "Clan": popupTitle = Localization.L("name_edit_title_clan"); break;
                case "Settlement": popupTitle = Localization.L("name_edit_title_settlement"); break;
                case "Concept": popupTitle = Localization.L("name_edit_title_concept"); break;
                default: popupTitle = Localization.L("name_edit_title"); break;
            }

            string saveButtonText = isHero ? Localization.L("name_edit_next") : Localization.L("edit_save");

            string description = isHero
                ? Localization.L("name_edit_desc_hero").Replace("{0}", originalName)
                : Localization.L("name_edit_desc_nonhero").Replace("{0}", originalName);

            MCMSettings.DebugLog("Opening name edit popup for " + objectId + " (name=" + currentName + ", type=" + pageType + ")");

            int maxLen = GetMaxNameLength();

            Action<string> onConfirm = delegate (string newName)
            {
                string sanitized = SanitizeName(newName);

                if (sanitized == null || sanitized == originalName)
                    EncyclopediaEditBehavior.Instance.SetCustomName(objectId, null);
                else
                    EncyclopediaEditBehavior.Instance.SetCustomName(objectId, sanitized);

                MCMSettings.DebugLog("Name saved for " + objectId + ": " + (sanitized ?? "(reset)"));

                if (isHero)
                {
                    _namePopupOpen = false;
                    ShowTitlePopup(objectId);
                }
                else
                {
                    _namePopupOpen = false;
                    EncyclopediaInputBlocker.Unblock();
                    ApplyNonHeroNameAndRefresh(objectId);
                }
            };

            Action onCancel = delegate
            {
                _namePopupOpen = false;
                EncyclopediaInputBlocker.Unblock();
                MCMSettings.DebugLog("Name edit cancelled for " + objectId);
            };

            string nameDescription = isHero
                ? Localization.L("name_edit_desc_hero").Replace("{0}", originalName)
                : Localization.L("name_edit_desc_nonhero").Replace("{0}", originalName);

            string nameTip = Localization.L("edit_tips_name").Replace("{0}", maxLen.ToString());
            string confirmBtn = isHero ? Localization.L("name_edit_next") : Localization.L("edit_done");

            EditPopupInjector.ScheduleShow(popupTitle, currentName, maxLen,
                onConfirm, onCancel,
                onFailed: () =>
                {
                    MCMSettings.DebugLog("EditPopupInjector failed for name edit — falling back to native TextInquiry");
                    EncyclopediaEditPopup.ShowNativeTextInquiry(popupTitle, currentName, maxLen, onConfirm, onCancel);
                },
                description: nameDescription,
                confirmText: confirmBtn,
                tipText: nameTip);
        }

        private static void ApplyHeroNameOnObject(string objectId)
        {
            try
            {
                string finalName = EncyclopediaEditBehavior.Instance.GetCustomName(objectId);
                var hero = EncyclopediaPageTracker.CurrentHero;
                if (hero == null) return;

                if (!string.IsNullOrEmpty(finalName))
                {
                    EncyclopediaPageTracker.SetHeroName(hero, finalName);
                }
                else
                {
                    string origName = EncyclopediaEditBehavior.Instance.GetOriginalName(objectId);
                    if (!string.IsNullOrEmpty(origName))
                    {
                        EncyclopediaPageTracker.SetHeroName(hero, origName);
                        MCMSettings.DebugLog("Restored original name for " + objectId + ": " + origName);
                    }
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: ApplyHeroNameOnObject failed: " + ex.ToString()); }
        }

        private static void RefreshPageAndTimestamp()
        {
            var refresh = EncyclopediaPageTracker.CurrentRefreshAction;
            if (refresh != null)
                try { refresh(); } catch (Exception ex) { MCMSettings.DebugLog("Patches: page refresh failed: " + ex.ToString()); }

            try
            {
                var updateTs = EncyclopediaPageTracker.CurrentUpdateTimestampAction;
                if (updateTs != null) updateTs();
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: timestamp update failed: " + ex.ToString()); }
        }

        private static void ShowConfirmationIfEnabled(string messageKey)
        {
            bool showConfirm = true;
            try
            {
                var settings = MCMSettings.Instance;
                if (settings != null) showConfirm = settings.ShowConfirmationMessages;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: reading ShowConfirmationMessages failed: " + ex.ToString()); }

            if (showConfirm)
            {
                InformationManager.DisplayMessage(
                    new InformationMessage(Localization.L(messageKey), Colors.Green));
            }
        }

        private static void RefreshSettlementNameplate()
        {
            if (EncyclopediaPageTracker.CurrentPageType != "Settlement") return;
            try
            {
                var vm = EncyclopediaPageTracker.CurrentViewModel;
                if (vm == null) return;
                var settlement = vm.GetType().GetProperty("Obj",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public)
                    ?.GetValue(vm) as Settlement;
                if (settlement != null)
                    SettlementNameplateMixin.RefreshNameForSettlement(settlement);
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: settlement nameplate refresh failed: " + ex.ToString()); }

            SettlementNameplateMixin.ScheduleDeferredRefresh();
        }

        private static void ApplyNonHeroNameAndRefresh(string objectId)
        {
            try
            {
                string finalName = EncyclopediaEditBehavior.Instance.GetCustomName(objectId);
                string nameToApply = !string.IsNullOrEmpty(finalName) ? finalName
                    : (EncyclopediaEditBehavior.Instance.GetOriginalName(objectId) ?? "");

                var setName = EncyclopediaPageTracker.CurrentSetNameAction;
                if (setName != null)
                    try { setName(nameToApply); } catch (Exception ex) { MCMSettings.DebugLog("Patches: setName action failed: " + ex.ToString()); }
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: ApplyNonHeroNameAndRefresh name application failed: " + ex.ToString()); }

            RefreshSettlementNameplate();
            RefreshPageAndTimestamp();
            ShowConfirmationIfEnabled("name_saved_nonhero_message");
            // The map nameplate uses a baked Gauntlet widget that can't be refreshed mid-game.
            // Inform the player that the map label will update after save+reload or opening Options.
            try
            {
                InformationManager.DisplayMessage(new InformationMessage(
                    "Map nameplate will update after saving & reloading, or pressing Esc \u2192 Options \u2192 Back.",
                    TaleWorlds.Library.Colors.Gray));
            }
            catch { }
        }

        private static void ShowTitlePopup(string objectId)
        {
            _titlePopupOpen = true;

            string currentTitle = EncyclopediaEditBehavior.Instance.GetCustomTitle(objectId)
                                  ?? EncyclopediaPageTracker.CurrentTitle
                                  ?? "";

            string originalTitle = EncyclopediaEditBehavior.Instance.GetOriginalTitle(objectId)
                                   ?? EncyclopediaPageTracker.CurrentTitle
                                   ?? "";

            string titleDescription = Localization.L("title_edit_desc")
                .Replace("{0}", originalTitle);

            int maxLen = GetMaxNameLength();

            Action<string> onConfirm = delegate (string newTitle)
            {
                _titlePopupOpen = false;
                EncyclopediaInputBlocker.Unblock();

                string sanitized = SanitizeName(newTitle);

                if (sanitized == null || sanitized == originalTitle)
                {
                    EncyclopediaEditBehavior.Instance.SetCustomTitle(objectId, null);
                    var setTitle = EncyclopediaPageTracker.CurrentSetTitleAction;
                    if (setTitle != null)
                        try { setTitle(originalTitle); } catch (Exception ex) { MCMSettings.DebugLog("Patches: setTitle restore failed: " + ex.ToString()); }
                }
                else
                {
                    EncyclopediaEditBehavior.Instance.SetCustomTitle(objectId, sanitized);
                    var setTitle = EncyclopediaPageTracker.CurrentSetTitleAction;
                    if (setTitle != null)
                        try { setTitle(sanitized); } catch (Exception ex) { MCMSettings.DebugLog("Patches: setTitle apply failed: " + ex.ToString()); }
                }

                MCMSettings.DebugLog("Title saved for " + objectId + ": " + (sanitized ?? "(reset)"));

                ApplyHeroNameOnObject(objectId);
                RefreshPageAndTimestamp();
                ShowConfirmationIfEnabled("name_saved_message");
            };

            Action onCancel = delegate
            {
                _titlePopupOpen = false;
                EncyclopediaInputBlocker.Unblock();
                MCMSettings.DebugLog("Title edit cancelled for " + objectId);

                ApplyHeroNameOnObject(objectId);
                RefreshPageAndTimestamp();

                try
                {
                    InformationManager.DisplayMessage(
                        new InformationMessage(Localization.L("name_edit_cancelled_title_kept"), Colors.Yellow));
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: cancel message failed: " + ex.ToString()); }
            };

            string titleTip = Localization.L("edit_tips_title").Replace("{0}", maxLen.ToString());

            EditPopupInjector.ScheduleShow(Localization.L("title_edit_title"), currentTitle, maxLen,
                onConfirm, onCancel,
                onFailed: () =>
                {
                    MCMSettings.DebugLog("EditPopupInjector failed for title edit — falling back to native TextInquiry");
                    EncyclopediaEditPopup.ShowNativeTextInquiry(Localization.L("title_edit_title"), currentTitle, maxLen, onConfirm, onCancel);
                },
                description: titleDescription,
                tipText: titleTip);
        }
    }

    // ============================================
    //  Shared: Find ShowMultiSelectionInquiry across all assemblies
    // ============================================

    /// <summary>
    /// Searches InformationManager and all loaded assemblies for ShowMultiSelectionInquiry.
    /// In newer Bannerlord versions the method may live on MBInformationManager or elsewhere.
    /// Result is cached after the first lookup.
    /// </summary>
    internal static class MultiSelectionMethodCache
    {
        private static System.Reflection.MethodInfo _cached;
        private static bool _searched;

        internal static System.Reflection.MethodInfo Find(Type multiSelDataType)
        {
            if (_searched) return _cached;
            _searched = true;

            var pubStatic = System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public;

            // 1. Try InformationManager directly
            try
            {
                var imType = typeof(InformationManager);
                foreach (var m in imType.GetMethods(pubStatic))
                {
                    if (m.Name == "ShowMultiSelectionInquiry")
                    {
                        _cached = m;
                        MCMSettings.DebugLog("Found ShowMultiSelectionInquiry on InformationManager");
                        return _cached;
                    }
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: InformationManager ShowMultiSelectionInquiry lookup failed: " + ex.ToString()); }

            // 2. Search all assemblies for any type with ShowMultiSelectionInquiry
            //    (e.g. MBInformationManager, InformationManagerBase, etc.)
            MCMSettings.DebugLog("ShowMultiSelectionInquiry not on InformationManager, searching all assemblies...");
            foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
            {
                try
                {
                    foreach (var t in asm.GetTypes())
                    {
                        if (_cached != null) break;
                        // Skip types unlikely to have UI methods
                        if (!t.Name.Contains("Information") && !t.Name.Contains("Inquiry"))
                            continue;

                        foreach (var m in t.GetMethods(pubStatic))
                        {
                            if (m.Name == "ShowMultiSelectionInquiry")
                            {
                                _cached = m;
                                MCMSettings.DebugLog("Found ShowMultiSelectionInquiry on " + t.FullName);
                                break;
                            }
                        }
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: assembly scan for ShowMultiSelectionInquiry failed: " + ex.ToString()); }
                if (_cached != null) break;
            }

            // 3. Broader search: any static method whose first param is MultiSelectionInquiryData
            if (_cached == null && multiSelDataType != null)
            {
                MCMSettings.DebugLog("Searching for any method accepting MultiSelectionInquiryData...");
                foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                {
                    try
                    {
                        foreach (var t in asm.GetTypes())
                        {
                            if (_cached != null) break;
                            foreach (var m in t.GetMethods(pubStatic))
                            {
                                var pars = m.GetParameters();
                                if (pars.Length >= 1 && pars[0].ParameterType == multiSelDataType)
                                {
                                    _cached = m;
                                    MCMSettings.DebugLog("Found method " + t.FullName + "." + m.Name + " accepting MultiSelectionInquiryData");
                                    break;
                                }
                            }
                        }
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: broader assembly scan for MultiSelectionInquiryData method failed: " + ex.ToString()); }
                    if (_cached != null) break;
                }
            }

            if (_cached == null)
                MCMSettings.DebugLog("ShowMultiSelectionInquiry not found anywhere");

            return _cached;
        }

        /// <summary>
        /// Finds the best InquiryElement constructor and returns it along with a flag
        /// indicating whether the second parameter is TextObject (vs string).
        /// Returns null if no suitable constructor is found.
        /// </summary>
        internal static System.Reflection.ConstructorInfo FindInquiryElementCtor(
            Type inquiryElementType, out bool secondParamIsTextObject)
        {
            secondParamIsTextObject = false;

            // First pass: constructors with >= 3 params where first is string
            foreach (var ctor in inquiryElementType.GetConstructors())
            {
                var pars = ctor.GetParameters();
                if (pars.Length >= 3 && pars[0].ParameterType == typeof(string))
                {
                    secondParamIsTextObject = pars[1].ParameterType != typeof(string);
                    MCMSettings.DebugLog("InquiryElement ctor: " + pars.Length + " params, param1=" + pars[1].ParameterType.Name);
                    return ctor;
                }
            }

            // Broader search: any constructor with >= 3 params
            foreach (var ctor in inquiryElementType.GetConstructors())
            {
                var pars = ctor.GetParameters();
                if (pars.Length >= 3)
                {
                    secondParamIsTextObject = pars.Length > 1 && pars[1].ParameterType != typeof(string);
                    MCMSettings.DebugLog("InquiryElement ctor (broad): " + pars.Length + " params, param0=" + pars[0].ParameterType.Name + ", param1=" + pars[1].ParameterType.Name);
                    return ctor;
                }
            }

            MCMSettings.DebugLog("InquiryElement constructor not found (no ctor with >= 3 params)");
            return null;
        }

        /// <summary>
        /// Creates an InquiryElement instance, handling both string and TextObject
        /// second parameter depending on the Bannerlord version.
        /// </summary>
        internal static object CreateInquiryElement(
            System.Reflection.ConstructorInfo ctor,
            System.Reflection.ParameterInfo[] ctorParams,
            bool secondParamIsTextObject,
            string id, string label)
        {
            // Build second parameter: either string or TextObject
            object secondParam = secondParamIsTextObject
                ? (object)new TextObject(label)
                : (object)label;

            object[] args;
            if (ctorParams.Length == 3)
                args = new object[] { id, secondParam, null };
            else if (ctorParams.Length == 4)
                args = new object[] { id, secondParam, null, true };
            else
                args = new object[] { id, secondParam, null, true, null };

            return ctor.Invoke(args);
        }

        /// <summary>
        /// Dynamically builds a MultiSelectionInquiryData constructor arg array
        /// by matching parameter types and names. Works for any Bannerlord version.
        /// </summary>
        internal static object BuildMultiSelectionInquiryData(
            System.Reflection.ConstructorInfo dataCtor,
            string title, string desc, string affText, string negText,
            object elements, Type listType, Delegate affirmativeDelegate, Delegate negativeDelegate)
        {
            var pars = dataCtor.GetParameters();
            var actionType = typeof(Action<>).MakeGenericType(listType);

            // Log all parameter types for diagnostics
            var paramInfo = new System.Text.StringBuilder();
            for (int i = 0; i < pars.Length; i++)
            {
                if (i > 0) paramInfo.Append(", ");
                paramInfo.Append(pars[i].Name + ":" + pars[i].ParameterType.Name);
            }
            MCMSettings.DebugLog("MultiSelectionInquiryData ctor(" + pars.Length + "): " + paramInfo);

            var args = new object[pars.Length];
            bool affDelegateUsed = false;
            int stringIndex = 0; // Track which string param we're filling

            for (int i = 0; i < pars.Length; i++)
            {
                var pt = pars[i].ParameterType;
                var pname = (pars[i].Name ?? "").ToLowerInvariant();

                if (pt == listType || pt.IsAssignableFrom(listType))
                {
                    args[i] = elements;
                }
                else if (pt == actionType || (pt.IsGenericType && pt.GetGenericTypeDefinition() == typeof(Action<>)))
                {
                    if (!affDelegateUsed)
                    {
                        args[i] = affirmativeDelegate;
                        affDelegateUsed = true;
                    }
                    else
                    {
                        args[i] = negativeDelegate;
                    }
                }
                else if (pt == typeof(string))
                {
                    // Match by param name, fall back to positional
                    if (pname.Contains("title"))
                        args[i] = title;
                    else if (pname.Contains("desc"))
                        args[i] = desc;
                    else if (pname.Contains("affirm"))
                        args[i] = affText;
                    else if (pname.Contains("negat") || pname.Contains("cancel"))
                        args[i] = negText;
                    else if (pname.Contains("sound"))
                        args[i] = "";
                    else
                    {
                        // Positional fallback for unnamed/unknown string params
                        switch (stringIndex)
                        {
                            case 0: args[i] = title; break;
                            case 1: args[i] = desc; break;
                            case 2: args[i] = affText; break;
                            case 3: args[i] = negText; break;
                            default: args[i] = ""; break;
                        }
                    }
                    stringIndex++;
                }
                else if (pt == typeof(bool))
                {
                    // isExitShown = true, isSearchAvailable = true
                    args[i] = true;
                }
                else if (pt == typeof(int))
                {
                    // minSelectableOptionCount = 1, maxSelectableOptionCount = 1
                    args[i] = 1;
                }
                else
                {
                    args[i] = pt.IsValueType ? Activator.CreateInstance(pt) : null;
                }
            }

            return dataCtor.Invoke(args);
        }

        /// <summary>
        /// Extracts the identifier string from an InquiryElement instance.
        /// Tries "Id", "Identifier", then any property returning the expected string.
        /// </summary>
        internal static string GetInquiryElementId(object element)
        {
            if (element == null) return null;
            var type = element.GetType();

            // Try common property names
            foreach (var propName in new[] { "Id", "Identifier", "UniqueIdentifier" })
            {
                var prop = type.GetProperty(propName);
                if (prop != null)
                {
                    var val = prop.GetValue(element);
                    if (val != null) return val.ToString();
                }
            }

            // Try fields
            foreach (var fieldName in new[] { "Id", "Identifier", "_id", "_identifier" })
            {
                var field = type.GetField(fieldName,
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic);
                if (field != null)
                {
                    var val = field.GetValue(element);
                    if (val != null) return val.ToString();
                }
            }

            // Last resort: log all properties for diagnostics
            var props = type.GetProperties();
            var sb = new System.Text.StringBuilder("InquiryElement props: ");
            foreach (var p in props)
            {
                try { sb.Append(p.Name).Append("=").Append(p.GetValue(element)?.ToString() ?? "null").Append(", "); }
                catch (Exception ex) { sb.Append(p.Name).Append("=<err: ").Append(ex.Message).Append(">, "); }
            }
            MCMSettings.DebugLog(sb.ToString());

            return null;
        }
    }

    // ============================================
    //  Inquiry type cache (round 4 finding N-C2)
    // ============================================

    /// <summary>
    /// Caches the discovery of InquiryElement and MultiSelectionInquiryData types via
    /// AppDomain assembly scan. Round 4 finding N-C2 documented 5+ identical inline
    /// scan blocks each running on Refresh hot paths — they all now share this single
    /// cache that scans once per session.
    /// </summary>
    internal static class InquiryTypeCache
    {
        private static Type _inquiryElementType;
        private static Type _multiSelectionInquiryDataType;
        private static volatile bool _searched;
        private static readonly object _lock = new object();

        private static void EnsureSearched()
        {
            if (_searched) return;
            lock (_lock)
            {
                if (_searched) return;
                try
                {
                    foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                    {
                        try
                        {
                            foreach (var t in asm.GetTypes())
                            {
                                if (t.Name == "InquiryElement" && _inquiryElementType == null)
                                    _inquiryElementType = t;
                                if (t.Name == "MultiSelectionInquiryData" && _multiSelectionInquiryDataType == null)
                                    _multiSelectionInquiryDataType = t;
                            }
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("InquiryTypeCache: asm scan inner failed: " + ex.ToString()); }
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("InquiryTypeCache: outer scan failed: " + ex.ToString()); }
                _searched = true;
            }
        }

        internal static Type InquiryElement
        {
            get { EnsureSearched(); return _inquiryElementType; }
        }

        internal static Type MultiSelectionInquiryData
        {
            get { EnsureSearched(); return _multiSelectionInquiryDataType; }
        }
    }

    // ============================================
    //  Gauntlet Selection Popup (fallback when MultiSelection API unavailable)
    // ============================================

    /// <summary>
    /// Shows a custom Gauntlet popup with a scrollable list of clickable items.
    /// Used as a fallback when InformationManager.ShowMultiSelectionInquiry is unavailable.
    /// </summary>
    internal static class SelectionPopupHelper
    {
        private static GauntletLayer _layer;
        private static SelectionPopupVM _vm;

        // ── Main-thread action queue ──
        // GauntletLayer creation & AddLayer must happen on the main game thread.
        // Timer-thread callers use ScheduleShow() which queues the work here,
        // and OnApplicationTick drains it via TickMainThread().
        private static readonly object _queueLock = new object();
        private static Action _pendingShowAction;

        /// <summary>
        /// Called from OnApplicationTick (main game thread).
        /// Drains any pending Show action that was scheduled from a background thread.
        /// </summary>
        public static void TickMainThread()
        {
            Action action = null;
            lock (_queueLock)
            {
                action = _pendingShowAction;
                _pendingShowAction = null;
            }
            if (action != null)
            {
                try { action(); }
                catch (Exception ex)
                {
                    MCMSettings.DebugLog("SelectionPopupHelper.TickMainThread error: " + ex.ToString());
                }
            }
        }

        /// <summary>
        /// Schedules a Show call to execute on the main game thread (next OnApplicationTick).
        /// Safe to call from any thread.
        /// </summary>
        public static void ScheduleShow(string title, string desc,
            MBBindingList<SelectionItemVM> items, Action onClose)
        {
            lock (_queueLock)
            {
                _pendingShowAction = () => Show(title, desc, items, onClose);
            }
        }

        /// <summary>
        /// Schedules Close() to run on the main game thread (next OnApplicationTick).
        /// Safe to call from any thread. Used when the encyclopedia is closed
        /// while a selection popup layer might still be attached.
        /// </summary>
        public static void ScheduleClose()
        {
            lock (_queueLock)
            {
                _pendingShowAction = () => Close();
            }
        }

        /// <summary>
        /// Shows a clickable Gauntlet popup for culture selection.
        /// Returns true if the popup was successfully shown, false on failure.
        /// </summary>
        public static bool TryShowCulturePopup(string objectId, Hero hero,
            string currentCulture, List<string> cultureNames, Dictionary<string, CultureObject> cultureMap,
            bool hasCustom, Action onClose)
        {
            try
            {
                string title = Localization.L("culture_list_title");
                string desc = Localization.L("culture_list_select_message", currentCulture);

                var items = new MBBindingList<SelectionItemVM>();
                foreach (var cultureName in cultureNames)
                {
                    string cn = cultureName; // capture for closure
                    bool isCustomEntry = !cultureMap.ContainsKey(cn);
                    string label = isCustomEntry ? cn + " " + Localization.L("culture_custom_tag") : cn;
                    bool isCurrent = cn == currentCulture;
                    if (isCurrent) label = "* " + label;

                    items.Add(new SelectionItemVM(label, isCurrent, () =>
                    {
                        Close();
                        onClose?.Invoke();
                        EncyclopediaCultureEditPopup.TryApplyMatchedCulture(objectId, hero, cn, cultureNames, cultureMap);
                    }));
                }

                // "Custom..." option
                items.Add(new SelectionItemVM(Localization.L("culture_select_type"), false, () =>
                {
                    Close();
                    onClose?.Invoke();
                    EncyclopediaCultureEditPopup.ShowBaseCulturePicker(objectId, hero, "", cultureNames, cultureMap);
                }));

                // "Reset" option if applicable
                if (hasCustom)
                {
                    items.Add(new SelectionItemVM(Localization.L("culture_reset_option"), false, () =>
                    {
                        Close();
                        onClose?.Invoke();
                        EncyclopediaCultureEditPopup.ResetCulture(objectId, hero);
                    }));
                }

                // Schedule on main thread — callers may be on the timer thread
                ScheduleShow(title, desc, items, onClose);
                return true;
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TryShowCulturePopup failed: " + ex.ToString());
                return false;
            }
        }

        /// <summary>
        /// Shows a clickable Gauntlet popup for occupation selection.
        /// Returns true if the popup was successfully shown, false on failure.
        /// </summary>
        public static bool TryShowOccupationPopup(string objectId, Hero hero,
            string currentOccupation, List<string> validOccupations,
            Dictionary<string, int> occValueMap, bool hasCustom, Action onClose)
        {
            try
            {
                string title = Localization.L("occupation_edit_title");
                string desc = Localization.L("occupation_list_select_message", currentOccupation);

                var items = new MBBindingList<SelectionItemVM>();
                foreach (var occName in validOccupations)
                {
                    string name = occName; // capture for closure
                    bool isCurrent = name == currentOccupation;
                    string label = isCurrent ? "* " + name : name;

                    items.Add(new SelectionItemVM(label, isCurrent, () =>
                    {
                        Close();
                        onClose?.Invoke();
                        if (occValueMap.TryGetValue(name, out int occValue))
                            EncyclopediaOccupationEditPopup.ApplyOccupation(objectId, hero, occValue);
                    }));
                }

                // "Reset" option if applicable
                if (hasCustom)
                {
                    items.Add(new SelectionItemVM(Localization.L("occupation_reset_btn"), false, () =>
                    {
                        Close();
                        onClose?.Invoke();
                        EncyclopediaOccupationEditPopup.ResetOccupation(objectId, hero);
                    }));
                }

                // Schedule on main thread — callers may be on the timer thread
                ScheduleShow(title, desc, items, onClose);
                return true;
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TryShowOccupationPopup failed: " + ex.ToString());
                return false;
            }
        }

        internal static bool Show(string title, string desc,
            MBBindingList<SelectionItemVM> items, Action onClose)
        {
            Close();

            _vm = new SelectionPopupVM(title, desc, items, () =>
            {
                Close();
                onClose?.Invoke();
            });

            _layer = new GauntletLayer("EditableEncyclopediaSelection", 9999, false);
            _layer.LoadMovie("EditableEncyclopediaSelection", _vm);
            _layer.IsFocusLayer = true;

            var topScreen = ScreenManager.TopScreen;
            if (topScreen == null)
            {
                MCMSettings.DebugLog("SelectionPopupHelper: TopScreen is null");
                return false;
            }

            topScreen.AddLayer(_layer);
            // 2026-05-30: 1.4.x layout-inversion compat. EditableEncyclopediaSelection.xml hardcodes
            // VerticalBottomToTop (top-down on <=1.3); on 1.4 that renders bottom-up (reversed items),
            // so flip the static stacks to the version-correct top-down enum. No-op on <=1.3.
            LoreSectionInjector.ApplyTopDownLayoutToTree(_layer);
            _layer.InputRestrictions.SetInputRestrictions(true);
            ScreenManager.TrySetFocus(_layer);
            MCMSettings.DebugLog("Showed Gauntlet selection popup: " + title + " (" + items.Count + " items)");
            return true;
        }

        public static void Close()
        {
            if (_layer != null)
            {
                try
                {
                    _layer.InputRestrictions.ResetInputRestrictions();
                    var topScreen = ScreenManager.TopScreen;
                    topScreen?.RemoveLayer(_layer);
                    ScreenManager.TryLoseFocus(_layer);
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: SelectionPopupHelper.Close layer removal failed: " + ex.ToString()); }
                _layer = null;
            }
            _vm = null;
        }

        public static bool IsOpen => _layer != null;
    }

    // ============================================
    //  Lore Editor Popup — large multiline text editor for descriptions/backstory
    // ============================================
    internal static class LoreEditorPopup
    {
        private static TaleWorlds.Engine.GauntletUI.GauntletLayer _layer;
        private static EncyclopediaEditVM _vm;

        // Main-thread action queue — same pattern as SelectionPopupHelper
        private static readonly object _queueLock = new object();
        private static Action _pendingAction;

        /// <summary>
        /// Called from OnApplicationTick (main game thread).
        /// </summary>
        public static void TickMainThread()
        {
            Action action = null;
            lock (_queueLock)
            {
                action = _pendingAction;
                _pendingAction = null;
            }
            if (action != null)
            {
                try { action(); }
                catch (Exception ex)
                {
                    MCMSettings.DebugLog("LoreEditorPopup.TickMainThread error: " + ex.ToString());
                }
            }
        }

        /// <summary>
        /// Schedules showing the editor on the main game thread.
        /// Safe to call from any thread.
        /// </summary>
        public static void ScheduleShow(string title, string currentText, int maxLength,
            Action<string> onConfirm, Action onCancel, Action onFailed = null)
        {
            lock (_queueLock)
            {
                _pendingAction = () =>
                {
                    if (!Show(title, currentText, maxLength, onConfirm, onCancel))
                        onFailed?.Invoke();
                };
            }
        }

        /// <summary>
        /// Schedules Close() on the main game thread.
        /// </summary>
        public static void ScheduleClose()
        {
            lock (_queueLock)
            {
                _pendingAction = () => Close();
            }
        }

        /// <summary>
        /// Shows the lore editor popup on the current screen.
        /// </summary>
        public static bool Show(string title, string currentText, int maxLength,
            Action<string> onConfirm, Action onCancel)
        {
            try
            {
                Close();

                var topScreen = ScreenManager.TopScreen;
                if (topScreen == null)
                {
                    MCMSettings.DebugLog("LoreEditorPopup: TopScreen is null — cannot show editor");
                    return false;
                }

                _vm = new EncyclopediaEditVM(title, currentText, maxLength,
                    text =>
                    {
                        Close();
                        onConfirm?.Invoke(text);
                    },
                    () =>
                    {
                        Close();
                        onCancel?.Invoke();
                    });

                // Use high localOrder (10000) to guarantee the popup renders
                // above all encyclopedia layers (which may have high Z-orders
                // on modded screens like NavalMapScreen).
                _layer = new TaleWorlds.Engine.GauntletUI.GauntletLayer("EncyclopediaEditPopup", 10000, false);

                object movie = null;
                try
                {
                    movie = _layer.LoadMovie("EncyclopediaEditPopup", _vm);
                }
                catch (Exception movieEx)
                {
                    MCMSettings.DebugLog("LoreEditorPopup: LoadMovie failed: " + movieEx.Message);
                    Close();
                    return false;
                }

                if (movie == null)
                {
                    MCMSettings.DebugLog("LoreEditorPopup: LoadMovie returned null — XML prefab 'EncyclopediaEditPopup' may be missing");
                    Close();
                    return false;
                }

                MCMSettings.DebugLog("LoreEditorPopup: LoadMovie returned " + movie.GetType().Name);

                _layer.IsFocusLayer = true;

                topScreen.AddLayer(_layer);

                // Check if the widget tree was actually created and rendered properly.
                // The UIContext root always exists, so we need to check deeper:
                // root → Window wrapper → our XML root (popup panel) must have children.
                Widget layerRoot = GetLayerRootWidget();
                if (layerRoot == null || layerRoot.ChildCount == 0)
                {
                    MCMSettings.DebugLog("LoreEditorPopup: RootWidget is null/empty after LoadMovie — XML prefab not loaded. Releasing layer.");
                    Close();
                    return false;
                }

                // Check deeper: the Window wrapper's child (our popup panel) should have
                // at least 3 children (title, text area, buttons). If it has 0, the brushes
                // or sprites failed and inner widgets weren't instantiated.
                int deepChildCount = 0;
                try
                {
                    Widget windowWrapper = layerRoot.GetChild(0);
                    if (windowWrapper != null)
                        deepChildCount = windowWrapper.ChildCount;
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: LoreEditorPopup deep child count check failed: " + ex.ToString()); }
                if (deepChildCount < 3)
                {
                    MCMSettings.DebugLog("LoreEditorPopup: popup panel has " + deepChildCount + " children (expected 5+) — widgets failed to instantiate. Releasing layer.");
                    Close();
                    return false;
                }

                _layer.InputRestrictions.SetInputRestrictions(true);
                ScreenManager.TrySetFocus(_layer);

                // Apply MaxLength to the EditableTextWidget after movie load
                if (maxLength > 0)
                    TrySetMaxLengthOnWidget(maxLength);

                // Diagnostic: dump widget tree structure for debugging visibility issues
                try
                {
                    var diagSb = new System.Text.StringBuilder();
                    diagSb.Append("LoreEditorPopup: showed editor '").Append(title).Append("'");
                    diagSb.Append(" rootChildren=").Append(layerRoot.ChildCount);
                    diagSb.Append(" screenLayers=").Append(topScreen.Layers.Count);
                    diagSb.Append(" layerIsActive=").Append(_layer.IsActive);
                    diagSb.Append(" root.IsVisible=").Append(layerRoot.IsVisible);
                    diagSb.Append(" root.W=").Append(layerRoot.SuggestedWidth).Append(" H=").Append(layerRoot.SuggestedHeight);
                    DumpWidgetTree(diagSb, layerRoot, 0, 6);
                    MCMSettings.DebugLog(diagSb.ToString());
                }
                catch (Exception diagEx)
                {
                    MCMSettings.DebugLog("LoreEditorPopup: showed editor '" + title
                        + "' rootChildren=" + layerRoot.ChildCount
                        + " screenLayers=" + topScreen.Layers.Count
                        + " (diag error: " + diagEx.Message + ")");
                }
                return true;
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("LoreEditorPopup.Show FAILED: " + ex);
                Close();
                return false;
            }
        }

        public static void Close()
        {
            if (_layer != null)
            {
                try
                {
                    _layer.InputRestrictions.ResetInputRestrictions();
                    var topScreen = ScreenManager.TopScreen;
                    topScreen?.RemoveLayer(_layer);
                    ScreenManager.TryLoseFocus(_layer);
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: LoreEditorPopup.Close layer removal failed: " + ex.ToString()); }
                _layer = null;
            }
            _vm = null;
        }

        public static bool IsOpen => _layer != null;

        /// <summary>
        /// Gets the root widget from the layer via UIContext.EventManager.Root.
        /// </summary>
        private static Widget GetLayerRootWidget()
        {
            if (_layer == null) return null;
            try
            {
                var flags = System.Reflection.BindingFlags.Instance
                          | System.Reflection.BindingFlags.Public
                          | System.Reflection.BindingFlags.NonPublic;
                var layerType = typeof(TaleWorlds.Engine.GauntletUI.GauntletLayer);

                // Try UIContext fields
                foreach (var fieldName in new[] { "_gauntletUIContext", "_uiContext", "_context" })
                {
                    var field = layerType.GetField(fieldName, flags);
                    if (field != null)
                    {
                        var uiCtx = field.GetValue(_layer) as TaleWorlds.GauntletUI.UIContext;
                        if (uiCtx?.EventManager?.Root != null)
                            return uiCtx.EventManager.Root;
                    }
                }
                // Try UIContext properties
                foreach (var propName in new[] { "UIContext", "_gauntletUIContext" })
                {
                    var prop = layerType.GetProperty(propName, flags);
                    if (prop != null)
                    {
                        var ctx = prop.GetValue(_layer) as TaleWorlds.GauntletUI.UIContext;
                        if (ctx?.EventManager?.Root != null)
                            return ctx.EventManager.Root;
                    }
                }
                // Try _movie._movieRootNode as fallback
                foreach (var movieFieldName in new[] { "_movie", "_gauntletMovie" })
                {
                    var movieField = layerType.GetField(movieFieldName, flags);
                    if (movieField == null) continue;
                    var movie = movieField.GetValue(_layer);
                    if (movie == null) continue;
                    foreach (var nodeName in new[] { "_movieRootNode", "RootNode" })
                    {
                        var nodeField = movie.GetType().GetField(nodeName, flags);
                        if (nodeField != null)
                        {
                            var node = nodeField.GetValue(movie) as Widget;
                            if (node != null) return node;
                        }
                        var nodeProp = movie.GetType().GetProperty(nodeName, flags);
                        if (nodeProp != null)
                        {
                            var node = nodeProp.GetValue(movie) as Widget;
                            if (node != null) return node;
                        }
                    }
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: GetLayerRootWidget failed: " + ex.ToString()); }
            return null;
        }

        /// <summary>
        /// Diagnostic: recursively dumps the widget tree structure for debug logging.
        /// </summary>
        private static void DumpWidgetTree(System.Text.StringBuilder sb, Widget widget, int depth, int maxDepth)
        {
            if (widget == null || depth > maxDepth) return;
            string indent = new string(' ', depth * 2);
            sb.AppendLine();
            sb.Append(indent).Append(widget.GetType().Name);
            sb.Append(" vis=").Append(widget.IsVisible);
            sb.Append(" hidden=").Append(widget.IsHidden);
            sb.Append(" W=").Append(widget.SuggestedWidth).Append(" H=").Append(widget.SuggestedHeight);
            sb.Append(" children=").Append(widget.ChildCount);

            // Check if widget has a Brush assigned
            try
            {
                var brushProp = widget.GetType().GetProperty("Brush",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public);
                if (brushProp != null)
                {
                    var brush = brushProp.GetValue(widget);
                    sb.Append(" brush=").Append(brush != null ? brush.ToString() : "NULL");
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: DumpWidgetTree brush check failed: " + ex.ToString()); }

            for (int i = 0; i < widget.ChildCount && i < 10; i++)
            {
                DumpWidgetTree(sb, widget.GetChild(i), depth + 1, maxDepth);
            }
        }

        /// <summary>
        /// After loading the movie, find the EditableTextWidget and set MaxLength.
        /// </summary>
        private static void TrySetMaxLengthOnWidget(int maxLength)
        {
            try
            {
                Widget root = GetLayerRootWidget();
                if (root == null) return;

                // Find EditableTextWidget and set MaxLength
                SetMaxLengthRecursive(root, maxLength);
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("LoreEditorPopup: TrySetMaxLengthOnWidget error: " + ex.ToString());
            }
        }

        private static bool SetMaxLengthRecursive(TaleWorlds.GauntletUI.BaseTypes.Widget widget, int maxLength)
        {
            if (widget == null) return false;
            if (widget.GetType().Name == "EditableTextWidget")
            {
                try
                {
                    var prop = widget.GetType().GetProperty("MaxLength",
                        System.Reflection.BindingFlags.Instance
                        | System.Reflection.BindingFlags.Public);
                    if (prop != null && prop.CanWrite)
                    {
                        prop.SetValue(widget, maxLength);
                        MCMSettings.DebugLog("LoreEditorPopup: set MaxLength = " + maxLength);
                        return true;
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: SetMaxLengthRecursive failed: " + ex.ToString()); }
            }
            for (int i = 0; i < widget.ChildCount; i++)
            {
                if (SetMaxLengthRecursive(widget.GetChild(i), maxLength))
                    return true;
            }
            return false;
        }
    }

    // ============================================
    //  Custom Culture Manager — creates real CultureObjects with custom troop trees
    // ============================================
    internal static class CustomCultureManager
    {
        // Cache of custom CultureObjects we've created, keyed by custom culture id
        private static readonly Dictionary<string, CultureObject> _registeredCultures
            = new Dictionary<string, CultureObject>(StringComparer.OrdinalIgnoreCase);

        // Reflection flags for accessing private/internal fields
        private static readonly System.Reflection.BindingFlags ReflFlags
            = System.Reflection.BindingFlags.Instance
            | System.Reflection.BindingFlags.Public
            | System.Reflection.BindingFlags.NonPublic;

        /// <summary>
        /// Creates and registers a custom CultureObject with the given troop assignments.
        /// Clones visual properties (color, banner, etc.) from the base culture.
        /// Returns the CultureObject, or null on failure.
        /// </summary>
        public static CultureObject GetOrCreateCulture(string customCultureId, string displayName,
            string baseCultureId, string basicTroopId, string eliteTroopId)
        {
            // Return cached if already created this session
            if (_registeredCultures.TryGetValue(customCultureId, out var existing))
                return existing;

            try
            {
                var objMgr = TaleWorlds.ObjectSystem.MBObjectManager.Instance;
                if (objMgr == null)
                {
                    MCMSettings.DebugLog("CustomCultureManager: MBObjectManager.Instance is null");
                    return null;
                }

                // Find the base culture to clone from
                CultureObject baseCulture = null;
                foreach (var c in objMgr.GetObjectTypeList<CultureObject>())
                {
                    if (c != null && string.Equals(c.StringId, baseCultureId, StringComparison.OrdinalIgnoreCase))
                    {
                        baseCulture = c;
                        break;
                    }
                }
                if (baseCulture == null)
                {
                    MCMSettings.DebugLog("CustomCultureManager: base culture '" + baseCultureId + "' not found");
                    return null;
                }

                // Find the troop CharacterObjects
                var basicTroop = objMgr.GetObject<TaleWorlds.CampaignSystem.CharacterObject>(basicTroopId);
                var eliteTroop = objMgr.GetObject<TaleWorlds.CampaignSystem.CharacterObject>(eliteTroopId);

                if (basicTroop == null)
                {
                    MCMSettings.DebugLog("CustomCultureManager: basic troop '" + basicTroopId + "' not found");
                    return null;
                }
                if (eliteTroop == null)
                {
                    MCMSettings.DebugLog("CustomCultureManager: elite troop '" + eliteTroopId + "' not found");
                    return null;
                }

                // Check if this culture id is already registered in MBObjectManager
                CultureObject customCulture = null;
                foreach (var c in objMgr.GetObjectTypeList<CultureObject>())
                {
                    if (c != null && string.Equals(c.StringId, customCultureId, StringComparison.OrdinalIgnoreCase))
                    {
                        customCulture = c;
                        break;
                    }
                }

                // Round 4 finding N-W2: only run the expensive clone+troop assignment when
                // the CultureObject is freshly created. If it was already in MBObjectManager
                // (Phase-1 reload from save), it already has its persisted fields — re-cloning
                // here would silently overwrite troop trees with whatever values this call has.
                if (customCulture == null)
                {
                    customCulture = objMgr.CreateObject<CultureObject>(customCultureId);
                    MCMSettings.DebugLog("CustomCultureManager: created new CultureObject '" + customCultureId + "'");

                    // Clone ALL fields from base culture so the custom culture is complete
                    // (settlements and militia systems rely on many culture properties)
                    CloneAllCultureFields(customCulture, baseCulture);

                    // Set the display name via reflection AFTER cloning
                    // (cloning skips name fields, but do this after to be safe)
                    SetCultureName(customCulture, displayName);

                    // Also clone visual properties (handles property-based cloning)
                    CloneVisualProperties(customCulture, baseCulture);

                    // Set the troop assignments via reflection
                    SetTroopField(customCulture, "_basicTroop", "basic_troop", "BasicTroop", basicTroop);
                    SetTroopField(customCulture, "_eliteBasicTroop", "elite_basic_troop", "EliteBasicTroop", eliteTroop);
                }
                else
                {
                    MCMSettings.DebugLog("CustomCultureManager: re-registering existing CultureObject '" + customCultureId
                        + "' (preserving persisted fields)");
                }

                _registeredCultures[customCultureId] = customCulture;
                MCMSettings.DebugLog("CustomCultureManager: registered culture '" + customCultureId
                    + "' (name=" + displayName + ", base=" + baseCultureId
                    + ", troop=" + basicTroopId + ", elite=" + eliteTroopId + ")");

                return customCulture;
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("CustomCultureManager: failed to create culture '" + customCultureId + "': " + ex.ToString());
                return null;
            }
        }

        /// <summary>
        /// Copies ALL instance fields from base culture to custom culture, walking the full
        /// type hierarchy (CultureObject -> BasicCultureObject -> MBObjectBase...).
        /// Skips StringId and any object-identity fields so the custom culture keeps its own id.
        /// This ensures the custom culture has militia templates, party templates, and all other
        /// data that settlements and game systems rely on.
        /// </summary>
        private static void CloneAllCultureFields(CultureObject target, CultureObject source)
        {
            var flags = System.Reflection.BindingFlags.Instance
                      | System.Reflection.BindingFlags.Public
                      | System.Reflection.BindingFlags.NonPublic;

            int cloned = 0;
            for (var type = typeof(CultureObject); type != null && type != typeof(object); type = type.BaseType)
            {
                var fields = type.GetFields(flags | System.Reflection.BindingFlags.DeclaredOnly);
                foreach (var field in fields)
                {
                    // Skip identity and name fields (name is set separately)
                    if (field.Name == "StringId" || field.Name == "_stringId"
                        || field.Name == "<StringId>k__BackingField"
                        || field.Name == "id" || field.Name == "_id"
                        || field.Name == "_name" || field.Name == "<Name>k__BackingField"
                        || field.Name == "Name")
                        continue;

                    try
                    {
                        var value = field.GetValue(source);
                        field.SetValue(target, value);
                        cloned++;
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: cloning culture field " + field.Name + " failed: " + ex.ToString()); }
                }
            }
            MCMSettings.DebugLog("CustomCultureManager: cloned " + cloned + " fields from base culture");
        }

        /// <summary>
        /// Sets the Name (TextObject) on a CultureObject by walking the full type hierarchy
        /// to find the backing field. Private fields on base classes (BasicCultureObject, etc.)
        /// require searching at each level with DeclaredOnly.
        /// </summary>
        private static void SetCultureName(CultureObject culture, string displayName)
        {
            try
            {
                var nameValue = new TaleWorlds.Localization.TextObject(displayName);
                bool set = false;

                // Walk the type hierarchy to find name-related fields
                string[] candidateFields = { "_name", "<Name>k__BackingField" };
                for (var type = culture.GetType(); type != null && type != typeof(object); type = type.BaseType)
                {
                    foreach (var fieldName in candidateFields)
                    {
                        var field = type.GetField(fieldName,
                            System.Reflection.BindingFlags.Instance
                            | System.Reflection.BindingFlags.NonPublic
                            | System.Reflection.BindingFlags.Public
                            | System.Reflection.BindingFlags.DeclaredOnly);
                        if (field != null && field.FieldType == typeof(TaleWorlds.Localization.TextObject))
                        {
                            field.SetValue(culture, nameValue);
                            set = true;
                            MCMSettings.DebugLog("CustomCultureManager: set Name via "
                                + type.Name + "." + fieldName + " = '" + displayName + "'");
                            break;
                        }
                    }
                    if (set) break;
                }

                // Fallback: try property setter
                if (!set)
                {
                    for (var type = culture.GetType(); type != null && type != typeof(object); type = type.BaseType)
                    {
                        var nameProp = type.GetProperty("Name",
                            System.Reflection.BindingFlags.Instance
                            | System.Reflection.BindingFlags.Public
                            | System.Reflection.BindingFlags.NonPublic
                            | System.Reflection.BindingFlags.DeclaredOnly);
                        if (nameProp != null && nameProp.CanWrite)
                        {
                            nameProp.SetValue(culture, nameValue);
                            set = true;
                            MCMSettings.DebugLog("CustomCultureManager: set Name via "
                                + type.Name + ".Name property = '" + displayName + "'");
                            break;
                        }
                    }
                }

                if (!set)
                    MCMSettings.DebugLog("CustomCultureManager: could not find Name field/property on culture hierarchy");
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("CustomCultureManager: SetCultureName failed: " + ex.ToString());
            }
        }

        /// <summary>
        /// Copies color, color2, and other visual properties from one CultureObject to another via reflection.
        /// </summary>
        private static void CloneVisualProperties(CultureObject target, CultureObject source)
        {
            string[] fieldNames = { "_color", "_color2", "_clothAlternativeColor", "_clothAlternativeColor2",
                                    "_bannerKey", "_cultureBackgroundMeshName", "_encounterBackgroundMesh" };
            foreach (var fieldName in fieldNames)
            {
                try
                {
                    var field = typeof(CultureObject).GetField(fieldName, ReflFlags);
                    if (field == null)
                    {
                        // Try BasicCultureObject (parent class)
                        field = typeof(BasicCultureObject).GetField(fieldName, ReflFlags);
                    }
                    if (field != null)
                    {
                        var value = field.GetValue(source);
                        field.SetValue(target, value);
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: cloning visual field failed: " + ex.ToString()); }
            }

            // Also try property-based cloning for Color, Color2
            string[] propNames = { "Color", "Color2" };
            foreach (var propName in propNames)
            {
                try
                {
                    var prop = typeof(CultureObject).GetProperty(propName, ReflFlags)
                            ?? typeof(BasicCultureObject).GetProperty(propName, ReflFlags);
                    if (prop != null && prop.CanRead && prop.CanWrite)
                    {
                        prop.SetValue(target, prop.GetValue(source));
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: cloning visual property failed: " + ex.ToString()); }
            }
        }

        /// <summary>
        /// Sets a troop CharacterObject field on a CultureObject via reflection.
        /// Tries multiple field name patterns since the exact naming varies by game version.
        /// </summary>
        private static void SetTroopField(CultureObject culture, string fieldName1, string fieldName2, string propName, TaleWorlds.CampaignSystem.CharacterObject troop)
        {
            try
            {
                // Try private field first
                var field = typeof(CultureObject).GetField(fieldName1, ReflFlags)
                         ?? typeof(CultureObject).GetField(fieldName2, ReflFlags)
                         ?? typeof(BasicCultureObject).GetField(fieldName1, ReflFlags)
                         ?? typeof(BasicCultureObject).GetField(fieldName2, ReflFlags);

                if (field != null && field.FieldType.IsAssignableFrom(typeof(TaleWorlds.CampaignSystem.CharacterObject)))
                {
                    field.SetValue(culture, troop);
                    MCMSettings.DebugLog("CustomCultureManager: set " + fieldName1 + " = " + troop.StringId);
                    return;
                }

                // Try property
                var prop = typeof(CultureObject).GetProperty(propName, ReflFlags)
                        ?? typeof(BasicCultureObject).GetProperty(propName, ReflFlags);
                if (prop != null && prop.CanWrite)
                {
                    prop.SetValue(culture, troop);
                    MCMSettings.DebugLog("CustomCultureManager: set " + propName + " property = " + troop.StringId);
                    return;
                }

                // Try backing field
                var backingField = typeof(CultureObject).GetField("<" + propName + ">k__BackingField", ReflFlags)
                                ?? typeof(BasicCultureObject).GetField("<" + propName + ">k__BackingField", ReflFlags);
                if (backingField != null)
                {
                    backingField.SetValue(culture, troop);
                    MCMSettings.DebugLog("CustomCultureManager: set backing field for " + propName + " = " + troop.StringId);
                    return;
                }

                // Last resort: scan all fields for CharacterObject type on CultureObject and BasicCultureObject
                MCMSettings.DebugLog("CustomCultureManager: could not find field for " + propName + ", scanning all fields...");
                foreach (var type in new[] { typeof(CultureObject), typeof(BasicCultureObject) })
                {
                    foreach (var f in type.GetFields(ReflFlags))
                    {
                        if (f.FieldType.IsAssignableFrom(typeof(TaleWorlds.CampaignSystem.CharacterObject))
                            && f.Name.IndexOf(propName.Replace("Troop", ""), StringComparison.OrdinalIgnoreCase) >= 0)
                        {
                            f.SetValue(culture, troop);
                            MCMSettings.DebugLog("CustomCultureManager: set field " + f.Name + " = " + troop.StringId + " (scan match)");
                            return;
                        }
                    }
                }

                MCMSettings.DebugLog("CustomCultureManager: WARNING - no field found for " + propName);
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("CustomCultureManager: failed to set " + propName + ": " + ex.ToString());
            }
        }

        /// <summary>
        /// Gets a previously created custom CultureObject by its id.
        /// Returns null if not yet created.
        /// </summary>
        public static CultureObject GetCachedCulture(string customCultureId)
        {
            _registeredCultures.TryGetValue(customCultureId, out var culture);
            return culture;
        }

        /// <summary>
        /// Checks if a culture ID corresponds to a registered custom culture definition
        /// (runtime-created, not a vanilla culture). Used by SaveSanitizerPatch to
        /// determine which hero cultures need sanitization before save.
        /// </summary>
        public static bool HasRegisteredCulture(string customCultureId)
        {
            return !string.IsNullOrEmpty(customCultureId)
                && _registeredCultures.ContainsKey(customCultureId);
        }

        /// <summary>
        /// Re-registers all custom culture definitions from the behavior's save data.
        /// Called after SyncData loads a save. Also re-applies hero.Culture for heroes
        /// assigned to custom cultures.
        /// </summary>
        public static void ReregisterAllFromSaveData()
        {
            // Phase 1 — recreate CultureObjects (safe to call early, only needs MBObjectManager)
            RegisterOnlyFromSaveData();
            // Phase 2 — reapply hero.Culture (needs Hero.AllAliveHeroes ready)
            try { ReapplyHeroCultures(); }
            catch (Exception ex) { MCMSettings.DebugLog("CustomCultureManager: ReapplyHeroCultures failed: " + ex.ToString()); }
        }

        /// <summary>
        /// Phase 1 only: recreates CultureObjects in MBObjectManager from saved definitions.
        /// Safe to call from SyncData / OnGameLoaded — does not touch Hero or Settlement lists.
        /// This closes the timing window where settlements could briefly reference a stale
        /// custom culture before the deferred tick re-registration fires.
        /// </summary>
        public static void RegisterOnlyFromSaveData()
        {
            try
            {
                var behavior = EncyclopediaEditBehavior.Instance;
                if (behavior == null) return;

                var defs = behavior.GetAllCustomCultureDefinitions();
                if (defs.Count == 0) return;

                MCMSettings.DebugLog("CustomCultureManager: registering " + defs.Count + " custom cultures (early phase)");

                foreach (var def in defs)
                {
                    string cultureId = def.Item1;
                    string displayName = def.Item2;
                    string baseCultureId = def.Item3;
                    string basicTroopId = def.Item4;
                    string eliteTroopId = def.Item5;

                    GetOrCreateCulture(cultureId, displayName, baseCultureId, basicTroopId, eliteTroopId);
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("CustomCultureManager: RegisterOnlyFromSaveData failed: " + ex.ToString());
            }
        }

        /// <summary>
        /// Sets hero.Culture (and hero.CharacterObject.Culture) to the custom CultureObject
        /// for all heroes whose persisted culture id matches a custom culture definition.
        /// </summary>
        public static void ReapplyHeroCultures()
        {
            try
            {
                var behavior = EncyclopediaEditBehavior.Instance;
                if (behavior == null) return;

                int applied = 0;

                void ProcessHero(Hero hero)
                {
                    if (hero == null) return;
                    string cultureId = behavior.GetCustomCulture(hero.StringId);
                    if (string.IsNullOrEmpty(cultureId)) return;

                    // Check if this cultureId corresponds to a custom culture definition
                    if (!_registeredCultures.TryGetValue(cultureId, out var customCulture))
                        return;

                    // Apply via reflection — use fields first, DeclaredOnly on properties to avoid ambiguity
                    try
                    {
                        var declaredFlags = ReflFlags | System.Reflection.BindingFlags.DeclaredOnly;

                        if (hero.CharacterObject != null)
                        {
                            bool charSet = false;
                            var charField = hero.CharacterObject.GetType().GetField("_culture", ReflFlags)
                                         ?? hero.CharacterObject.GetType().GetField("<Culture>k__BackingField", ReflFlags);
                            if (charField != null && charField.FieldType.IsAssignableFrom(typeof(CultureObject)))
                            {
                                charField.SetValue(hero.CharacterObject, customCulture);
                                charSet = true;
                            }
                            if (!charSet)
                            {
                                try
                                {
                                    var charProp = hero.CharacterObject.GetType().GetProperty("Culture", declaredFlags);
                                    if (charProp != null && charProp.CanWrite)
                                        charProp.SetValue(hero.CharacterObject, customCulture);
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: setting CharacterObject.Culture property failed: " + ex.ToString()); }
                            }
                        }

                        bool heroSet = false;
                        var heroField = typeof(Hero).GetField("_culture", ReflFlags)
                                     ?? typeof(Hero).GetField("<Culture>k__BackingField", ReflFlags);
                        if (heroField != null && heroField.FieldType.IsAssignableFrom(typeof(CultureObject)))
                        {
                            heroField.SetValue(hero, customCulture);
                            heroSet = true;
                        }
                        if (!heroSet)
                        {
                            try
                            {
                                var heroProp = typeof(Hero).GetProperty("Culture", declaredFlags);
                                if (heroProp != null && heroProp.CanWrite)
                                    heroProp.SetValue(hero, customCulture);
                            }
                            catch (Exception ex) { MCMSettings.DebugLog("Patches: setting Hero.Culture property failed: " + ex.ToString()); }
                        }
                        applied++;
                        // Force-refresh volunteer troop slots for notables after save load
                        EncyclopediaCultureEditPopup.RefreshNotableVolunteers(hero, customCulture, hero.StringId);
                        // Update settlement culture for clan leaders after save load
                        EncyclopediaCultureEditPopup.UpdateOwnedSettlementsCulture(hero, customCulture, hero.StringId);
                    }
                    catch (Exception ex)
                    {
                        MCMSettings.DebugLog("CustomCultureManager: failed to apply culture to hero " + hero.StringId + ": " + ex.ToString());
                    }
                }

                foreach (var hero in Hero.AllAliveHeroes)
                    ProcessHero(hero);
                foreach (var hero in Hero.DeadOrDisabledHeroes)
                    ProcessHero(hero);

                if (applied > 0)
                    MCMSettings.DebugLog("CustomCultureManager: re-applied hero.Culture for " + applied + " heroes");
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("CustomCultureManager: ReapplyHeroCultures failed: " + ex.ToString());
            }
        }

        /// <summary>
        /// Clears the runtime cache. Call this on game end / new game.
        /// </summary>
        public static void ClearCache()
        {
            _registeredCultures.Clear();
        }

        /// <summary>
        /// Generates a unique custom culture id from a display name.
        /// </summary>
        public static string GenerateCultureId(string displayName)
        {
            // Sanitize: keep alphanumeric/underscore, replace others with _
            var sb = new System.Text.StringBuilder("ee_custom_");
            foreach (char c in displayName)
            {
                if (char.IsLetterOrDigit(c))
                    sb.Append(char.ToLowerInvariant(c));
                else if (c == ' ' || c == '_')
                    sb.Append('_');
            }
            sb.Append('_');
            // Round 4 finding N-W5: second-resolution timestamp collides on rapid creation.
            // Use millisecond timestamp + 8-char Guid suffix for collision-proof IDs.
            sb.Append(DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
            sb.Append('_');
            sb.Append(Guid.NewGuid().ToString("N").Substring(0, 8));
            return sb.ToString();
        }

        /// <summary>
        /// Returns a list of (name, stringId) for all CharacterObject troops suitable for troop tree selection.
        /// Filters out heroes and hidden characters. Sorted by name.
        /// </summary>
        public static List<Tuple<string, string>> GetAvailableTroops()
        {
            var result = new List<Tuple<string, string>>();
            try
            {
                var objMgr = TaleWorlds.ObjectSystem.MBObjectManager.Instance;
                if (objMgr == null) return result;

                foreach (var character in objMgr.GetObjectTypeList<TaleWorlds.CampaignSystem.CharacterObject>())
                {
                    if (character == null) continue;
                    if (character.IsHero) continue; // Skip hero characters
                    if (string.IsNullOrEmpty(character.StringId)) continue;

                    string name = character.Name?.ToString();
                    if (string.IsNullOrEmpty(name)) continue;

                    // Include culture prefix for easier identification
                    string cultureName = "";
                    try
                    {
                        if (character.Culture != null)
                            cultureName = character.Culture.Name?.ToString() ?? character.Culture.StringId ?? "";
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: reading character culture name failed: " + ex.ToString()); }

                    string displayLabel = string.IsNullOrEmpty(cultureName)
                        ? name
                        : "[" + cultureName + "] " + name;

                    result.Add(Tuple.Create(displayLabel, character.StringId));
                }

                // Sort by display label
                result.Sort((a, b) => string.Compare(a.Item1, b.Item1, StringComparison.OrdinalIgnoreCase));
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("CustomCultureManager: GetAvailableTroops failed: " + ex.ToString());
            }
            return result;
        }
    }

    // ============================================
    //  Culture Edit Popup (Ctrl+U) — Hero pages only
    // ============================================
    public static class EncyclopediaCultureEditPopup
    {
        private static volatile bool _popupOpen = false;
        public static bool IsPopupOpen => _popupOpen;

        public static void TryOpen()
        {
            if (_popupOpen) return;
            if (EncyclopediaEditBehavior.Instance == null) return;
            if (string.IsNullOrEmpty(EncyclopediaPageTracker.CurrentObjectId)) return;

            if (EncyclopediaPageTracker.CurrentPageType != "Hero")
            {
                MCMSettings.DebugLog("Ctrl+U ignored - not a hero page (type=" + EncyclopediaPageTracker.CurrentPageType + ")");
                return;
            }

            try
            {
                var settings = MCMSettings.Instance;
                if (settings != null && !settings.EnableCultureEditing) return;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: checking EnableCultureEditing setting failed: " + ex.ToString()); }

            var hero = EncyclopediaPageTracker.CurrentHero;
            if (hero == null) return;

            EncyclopediaInputBlocker.Block();
            _popupOpen = true;
            string objectId = EncyclopediaPageTracker.CurrentObjectId;

            // Store original culture for reset
            try
            {
                if (hero.Culture != null)
                    EncyclopediaEditBehavior.Instance.StoreOriginalCulture(objectId, hero.Culture.StringId);
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: storing original culture failed: " + ex.ToString()); }

            // Build list of all available cultures
            var cultureNames = new List<string>();
            var cultureMap = new Dictionary<string, CultureObject>(StringComparer.OrdinalIgnoreCase);
            try
            {
                foreach (var culture in TaleWorlds.ObjectSystem.MBObjectManager.Instance.GetObjectTypeList<CultureObject>())
                {
                    if (culture != null && !string.IsNullOrEmpty(culture.StringId))
                    {
                        // Skip our custom cultures — they are added below via the custom names scan
                        // with their proper display names rather than the raw internal IDs
                        if (culture.StringId.StartsWith("ee_custom_", StringComparison.OrdinalIgnoreCase))
                            continue;

                        string displayName = culture.Name?.ToString() ?? culture.StringId;
                        if (!cultureMap.ContainsKey(displayName))
                        {
                            cultureNames.Add(displayName);
                            cultureMap[displayName] = culture;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Failed to enumerate cultures: " + ex.ToString());
            }

            // Add previously created custom culture names to the available list
            try
            {
                var allCustomNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                foreach (var h in Hero.AllAliveHeroes)
                {
                    if (h == null) continue;
                    string dn = EncyclopediaEditBehavior.Instance.GetCustomCultureDisplayName(h.StringId);
                    if (!string.IsNullOrEmpty(dn)) allCustomNames.Add(dn);
                }
                foreach (var h in Hero.DeadOrDisabledHeroes)
                {
                    if (h == null) continue;
                    string dn = EncyclopediaEditBehavior.Instance.GetCustomCultureDisplayName(h.StringId);
                    if (!string.IsNullOrEmpty(dn)) allCustomNames.Add(dn);
                }
                foreach (var cn in allCustomNames)
                {
                    if (!cultureMap.ContainsKey(cn))
                        cultureNames.Add(cn);
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: enumerating custom culture display names failed: " + ex.ToString()); }

            cultureNames.Sort();

            // Show custom display name if one exists, then persisted culture, then hero.Culture
            string currentCulture;
            string customDisplayName = EncyclopediaEditBehavior.Instance.GetCustomCultureDisplayName(objectId);
            if (!string.IsNullOrEmpty(customDisplayName))
                currentCulture = customDisplayName;
            else
                currentCulture = ResolvePersistedCultureName(objectId, hero);

            MCMSettings.DebugLog("Opening culture edit for " + objectId + " (current=" + currentCulture + ", available=" + cultureNames.Count + ")");

            // Native search is enabled in the multi-selection carousel (isSearchAvailable=true)
            ShowCultureSelectionList(objectId, hero, cultureNames, cultureMap);
        }

        private static void ShowCultureSelectionList(string objectId, Hero hero,
            List<string> cultureNames, Dictionary<string, CultureObject> cultureMap)
        {
            // Show custom display name if one exists, then persisted culture, then hero.Culture
            string currentCulture;
            string customDN = EncyclopediaEditBehavior.Instance?.GetCustomCultureDisplayName(objectId);
            if (!string.IsNullOrEmpty(customDN))
                currentCulture = customDN;
            else
                currentCulture = ResolvePersistedCultureName(objectId, hero);

            // Try to use the clickable multi-selection inquiry via reflection
            if (TryShowMultiSelectionCultureList(objectId, hero, currentCulture, cultureNames, cultureMap))
                return;

            // Fallback 2: Custom Gauntlet clickable popup
            bool hasCustom = EncyclopediaEditBehavior.Instance?.HasCustomCulture(objectId) ?? false;
            if (SelectionPopupHelper.TryShowCulturePopup(objectId, hero, currentCulture, cultureNames, cultureMap, hasCustom,
                    () => { _popupOpen = false; }))
                return;

            // Fallback 3: paginated numbered list
            MCMSettings.DebugLog("Gauntlet popup unavailable, using numbered list input");
            ShowCultureNumberedList(objectId, hero, currentCulture, cultureNames, cultureMap, hasCustom, 0);
        }

        private const int CulturePageSize = 15;

        /// <summary>
        /// Shows cultures in a paginated text input dialog as a numbered list.
        /// The user types a number to select, or a custom name.
        /// </summary>
        private static void ShowCultureNumberedList(string objectId, Hero hero,
            string currentCulture, List<string> cultureNames,
            Dictionary<string, CultureObject> cultureMap, bool hasCustom, int page)
        {
            int totalPages = (cultureNames.Count + CulturePageSize - 1) / CulturePageSize;
            if (totalPages < 1) totalPages = 1;
            int start = page * CulturePageSize;
            int end = Math.Min(start + CulturePageSize, cultureNames.Count);

            var sb = new System.Text.StringBuilder();
            sb.AppendLine(Localization.L("numbered_list_culture_header", currentCulture));
            if (totalPages > 1)
                sb.AppendLine("(" + (page + 1) + "/" + totalPages + ")");
            sb.AppendLine();

            for (int i = start; i < end; i++)
            {
                string name = cultureNames[i];
                bool isCustomEntry = !cultureMap.ContainsKey(name);
                string label = isCustomEntry ? name + " " + Localization.L("culture_custom_tag") : name;
                string marker = name == currentCulture ? " *" : "";
                sb.AppendLine((i + 1) + ". " + label + marker);
            }

            if (page < totalPages - 1)
                sb.AppendLine("\n> " + Localization.L("numbered_list_next_hint"));
            if (page > 0)
                sb.AppendLine("> " + Localization.L("numbered_list_prev_hint"));
            if (hasCustom)
                sb.AppendLine("\n" + Localization.L("numbered_list_reset_hint"));
            sb.AppendLine(Localization.L("numbered_list_custom_hint"));

            EEInquiry.Show(
                new TextInquiryData(
                    Localization.L("culture_list_title"),
                    sb.ToString(),
                    true,
                    true,
                    Localization.L("edit_save"),
                    Localization.L("edit_cancel"),
                    delegate(string input)
                    {
                        input = (input ?? "").Trim();

                        if (string.IsNullOrEmpty(input))
                        {
                            _popupOpen = false;
                            return;
                        }

                        // Navigate pages
                        if (input.Equals("next", StringComparison.OrdinalIgnoreCase) ||
                            input.Equals("n", StringComparison.OrdinalIgnoreCase))
                        {
                            if (page < totalPages - 1)
                                ShowCultureNumberedList(objectId, hero, currentCulture, cultureNames, cultureMap, hasCustom, page + 1);
                            else
                                ShowCultureNumberedList(objectId, hero, currentCulture, cultureNames, cultureMap, hasCustom, page);
                            return;
                        }
                        if (input.Equals("prev", StringComparison.OrdinalIgnoreCase) ||
                            input.Equals("p", StringComparison.OrdinalIgnoreCase))
                        {
                            if (page > 0)
                                ShowCultureNumberedList(objectId, hero, currentCulture, cultureNames, cultureMap, hasCustom, page - 1);
                            else
                                ShowCultureNumberedList(objectId, hero, currentCulture, cultureNames, cultureMap, hasCustom, page);
                            return;
                        }

                        _popupOpen = false;

                        // Check for "0" or "reset" to reset
                        if (hasCustom && (input == "0" || input.Equals("reset", StringComparison.OrdinalIgnoreCase)))
                        {
                            ResetCulture(objectId, hero);
                            return;
                        }

                        // Try parse as number (works across all pages)
                        int choice;
                        if (int.TryParse(input, out choice) && choice >= 1 && choice <= cultureNames.Count)
                        {
                            TryApplyMatchedCulture(objectId, hero, cultureNames[choice - 1], cultureNames, cultureMap);
                            return;
                        }

                        // Try match by name (exact or case-insensitive)
                        string matched = null;
                        foreach (var cn in cultureNames)
                        {
                            if (cn.Equals(input, StringComparison.OrdinalIgnoreCase))
                            {
                                matched = cn;
                                break;
                            }
                        }
                        if (matched != null)
                        {
                            TryApplyMatchedCulture(objectId, hero, matched, cultureNames, cultureMap);
                            return;
                        }

                        // Treat as custom culture name
                        ShowBaseCulturePicker(objectId, hero, input, cultureNames, cultureMap);
                    },
                    delegate()
                    {
                        _popupOpen = false;
                        MCMSettings.DebugLog("Culture numbered list cancelled for " + objectId);
                    }
                ),
                false);

            EncyclopediaNavigationGuard.ScheduleNavigateBack();
        }

        /// <summary>
        /// Attempts to show a clickable multi-selection culture list via reflection.
        /// Returns true if successful, false if the API is not available at runtime.
        /// </summary>
        private static bool TryShowMultiSelectionCultureList(string objectId, Hero hero,
            string currentCulture, List<string> cultureNames, Dictionary<string, CultureObject> cultureMap)
        {
            try
            {
                // Round 4 finding N-C2: cached scan replaces inline assembly walk.
                Type inquiryElementType = InquiryTypeCache.InquiryElement;
                Type multiSelDataType = InquiryTypeCache.MultiSelectionInquiryData;
                System.Reflection.MethodInfo showMethod = null;

                if (inquiryElementType == null || multiSelDataType == null)
                {
                    MCMSettings.DebugLog("MultiSelection types not found (InquiryElement=" + (inquiryElementType != null) + ", MultiSelData=" + (multiSelDataType != null) + ")");
                    return false;
                }

                // Find ShowMultiSelectionInquiry — try InformationManager first, then all assemblies
                showMethod = MultiSelectionMethodCache.Find(multiSelDataType);

                if (showMethod == null)
                {
                    MCMSettings.DebugLog("ShowMultiSelectionInquiry method not found on any type");
                    return false;
                }

                // Find InquiryElement constructor using shared helper
                var elementCtor = MultiSelectionMethodCache.FindInquiryElementCtor(inquiryElementType, out bool secondParamIsTextObject);
                if (elementCtor == null)
                    return false;

                // Build InquiryElement list
                var elementCtorParams = elementCtor.GetParameters();
                var listType = typeof(List<>).MakeGenericType(inquiryElementType);
                var elements = (System.Collections.IList)Activator.CreateInstance(listType);

                foreach (var cultureName in cultureNames)
                {
                    bool isCustom = !cultureMap.ContainsKey(cultureName);
                    string displayLabel = isCustom ? cultureName + " " + Localization.L("culture_custom_tag") : cultureName;
                    elements.Add(MultiSelectionMethodCache.CreateInquiryElement(elementCtor, elementCtorParams, secondParamIsTextObject, cultureName, displayLabel));
                }

                // Add "Custom..." entry
                elements.Add(MultiSelectionMethodCache.CreateInquiryElement(elementCtor, elementCtorParams, secondParamIsTextObject, "__custom__", Localization.L("culture_select_type")));

                // Add "Reset to Original" entry if the hero has a custom culture
                bool hasCustom = EncyclopediaEditBehavior.Instance.HasCustomCulture(objectId);
                if (hasCustom)
                {
                    elements.Add(MultiSelectionMethodCache.CreateInquiryElement(elementCtor, elementCtorParams, secondParamIsTextObject, "__reset__", Localization.L("culture_reset_option")));
                }

                // Build callbacks using Expression trees to bridge parameter types.
                // The API expects Action<List<InquiryElement>> but we can't reference
                // InquiryElement at compile time, so we build delegates dynamically.
                var actionType = typeof(Action<>).MakeGenericType(listType);

                // Affirmative callback: apply selected culture
                var affHandler = new CultureSelectionHandler(objectId, hero, cultureNames, cultureMap);
                var affParam = System.Linq.Expressions.Expression.Parameter(listType, "elements");
                var affCall = System.Linq.Expressions.Expression.Call(
                    System.Linq.Expressions.Expression.Constant(affHandler),
                    typeof(CultureSelectionHandler).GetMethod("OnCultureSelected"),
                    System.Linq.Expressions.Expression.Convert(affParam, typeof(object)));
                var affirmativeDelegate = System.Linq.Expressions.Expression.Lambda(actionType, affCall, affParam).Compile();

                // Negative callback: cancel
                var negHandler = new CultureSelectionCancelHandler();
                var negParam = System.Linq.Expressions.Expression.Parameter(listType, "elements");
                var negCall = System.Linq.Expressions.Expression.Call(
                    System.Linq.Expressions.Expression.Constant(negHandler),
                    typeof(CultureSelectionCancelHandler).GetMethod("OnCancel"),
                    System.Linq.Expressions.Expression.Convert(negParam, typeof(object)));
                var negativeDelegate = System.Linq.Expressions.Expression.Lambda(actionType, negCall, negParam).Compile();

                // Find MultiSelectionInquiryData constructor — prefer the longest (newest API)
                System.Reflection.ConstructorInfo dataCtor = null;
                foreach (var ctor in multiSelDataType.GetConstructors())
                {
                    var pars = ctor.GetParameters();
                    if (pars.Length >= 8 && (dataCtor == null || pars.Length > dataCtor.GetParameters().Length))
                        dataCtor = ctor;
                }

                if (dataCtor == null)
                {
                    MCMSettings.DebugLog("MultiSelectionInquiryData constructor not found");
                    return false;
                }

                // Build MultiSelectionInquiryData dynamically based on parameter types
                string title = Localization.L("culture_list_title");
                string desc = Localization.L("culture_list_select_message", currentCulture);
                string affText = Localization.L("edit_save");
                string negText = Localization.L("edit_cancel");

                object dataObj = MultiSelectionMethodCache.BuildMultiSelectionInquiryData(
                    dataCtor, title, desc, affText, negText,
                    elements, listType, affirmativeDelegate, negativeDelegate);

                // Call ShowMultiSelectionInquiry
                var showParams = showMethod.GetParameters();
                if (showParams.Length == 1)
                    showMethod.Invoke(null, new object[] { dataObj });
                else if (showParams.Length == 2)
                    showMethod.Invoke(null, new object[] { dataObj, false });
                else
                    showMethod.Invoke(null, new object[] { dataObj, false, false });

                MCMSettings.DebugLog("Showed multi-selection culture list with " + cultureNames.Count + " cultures + custom option");
                EncyclopediaNavigationGuard.ScheduleNavigateBack();
                return true;
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TryShowMultiSelectionCultureList failed: " + ex.ToString());
                return false;
            }
        }

        /// <summary>
        /// Handler for multi-selection culture list affirmative callback.
        /// Must be a class with a public method for Delegate.CreateDelegate.
        /// </summary>
        private class CultureSelectionHandler
        {
            private readonly string _objectId;
            private readonly Hero _hero;
            private readonly List<string> _cultureNames;
            private readonly Dictionary<string, CultureObject> _cultureMap;

            public CultureSelectionHandler(string objectId, Hero hero,
                List<string> cultureNames, Dictionary<string, CultureObject> cultureMap)
            {
                _objectId = objectId;
                _hero = hero;
                _cultureNames = cultureNames;
                _cultureMap = cultureMap;
            }

            public void OnCultureSelected(object selectedElements)
            {
                try
                {
                    var list = selectedElements as System.Collections.IList;
                    if (list == null || list.Count == 0)
                    {
                        MCMSettings.DebugLog("OnCultureSelected: no items selected");
                        _popupOpen = false;
                        return;
                    }

                    // Get the identifier of the first selected element
                    var selected = list[0];
                    string selectedId = MultiSelectionMethodCache.GetInquiryElementId(selected);
                    MCMSettings.DebugLog("OnCultureSelected: selectedId=" + (selectedId ?? "null"));

                    if (string.IsNullOrEmpty(selectedId))
                    {
                        _popupOpen = false;
                        return;
                    }

                    if (selectedId == "__custom__")
                    {
                        // User chose to type a custom culture name
                        ShowCustomCultureInput(_objectId, _hero, _cultureMap, _cultureNames);
                        return;
                    }

                    if (selectedId == "__reset__")
                    {
                        _popupOpen = false;
                        ResetCulture(_objectId, _hero);
                        return;
                    }

                    _popupOpen = false;

                    // Try to apply the selected culture
                    if (TryApplyMatchedCulture(_objectId, _hero, selectedId, _cultureNames, _cultureMap))
                        return;

                    MCMSettings.DebugLog("Culture not matched from selection: " + selectedId);
                }
                catch (Exception ex)
                {
                    _popupOpen = false;
                    MCMSettings.DebugLog("OnCultureSelected failed: " + ex.ToString());
                }
            }
        }

        /// <summary>
        /// Handler for multi-selection culture list cancel callback.
        /// </summary>
        private class CultureSelectionCancelHandler
        {
            public void OnCancel(object selectedElements)
            {
                _popupOpen = false;
                MCMSettings.DebugLog("Culture multi-selection cancelled");
            }
        }

        /// <summary>
        /// Resolves the current culture display name using persisted data first (since the game
        /// may revert hero.Culture for vanilla characters), falling back to hero.Culture.
        /// </summary>
        private static string ResolvePersistedCultureName(string objectId, Hero hero)
        {
            try
            {
                string persistedId = EncyclopediaEditBehavior.Instance?.GetCustomCulture(objectId);
                if (!string.IsNullOrEmpty(persistedId))
                {
                    foreach (var c in TaleWorlds.ObjectSystem.MBObjectManager.Instance.GetObjectTypeList<CultureObject>())
                    {
                        if (c != null && string.Equals(c.StringId, persistedId, StringComparison.OrdinalIgnoreCase))
                            return c.Name?.ToString() ?? persistedId;
                    }
                    return persistedId;
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: ResolvePersistedCultureName failed: " + ex.ToString()); }
            return hero.Culture?.Name?.ToString() ?? hero.Culture?.StringId ?? "Unknown";
        }

        private static void ShowCustomCultureInput(string objectId, Hero hero,
            Dictionary<string, CultureObject> cultureMap, List<string> cultureNames)
        {
            EEInquiry.Show(
                new TextInquiryData(
                    Localization.L("culture_custom_title"),
                    "",
                    true,
                    true,
                    Localization.L("name_edit_next"),
                    Localization.L("edit_cancel"),
                    delegate(string input)
                    {
                        string trimmed = input?.Trim();
                        if (string.IsNullOrEmpty(trimmed))
                        {
                            _popupOpen = false;
                            return;
                        }

                        // Check if input matches an existing culture (by name or StringId)
                        CultureObject matchedCulture = null;
                        if (cultureMap.ContainsKey(trimmed))
                        {
                            matchedCulture = cultureMap[trimmed];
                        }
                        else
                        {
                            foreach (var kvp in cultureMap)
                            {
                                if (string.Equals(kvp.Value.StringId, trimmed, StringComparison.OrdinalIgnoreCase))
                                {
                                    matchedCulture = kvp.Value;
                                    break;
                                }
                            }
                        }

                        if (matchedCulture != null)
                        {
                            _popupOpen = false;
                            ApplyCulture(objectId, hero, matchedCulture, null);
                        }
                        else
                        {
                            // Custom name — ask which existing culture to use as base
                            ShowBaseCulturePicker(objectId, hero, trimmed, cultureNames, cultureMap);
                        }
                    },
                    delegate
                    {
                        _popupOpen = false;
                        MCMSettings.DebugLog("Custom culture input cancelled for " + objectId);
                    }),
                false,
                false);

            EncyclopediaNavigationGuard.ScheduleNavigateBack();
        }

        internal static void ShowBaseCulturePicker(string objectId, Hero hero,
            string customName, List<string> cultureNames, Dictionary<string, CultureObject> cultureMap)
        {
            // Default to hero's current culture as the base
            string currentCultureName = hero.Culture?.Name?.ToString() ?? (cultureNames.Count > 0 ? cultureNames[0] : "");

            // Ask whether to create a display-only label or a full custom culture with troops
            InformationManager.ShowInquiry(
                new InquiryData(
                    Localization.L("culture_base_title"),
                    Localization.L("culture_custom_type_prompt", customName, currentCultureName),
                    true,  // affirmative = "With Troops" (gameplay-affecting)
                    true,  // negative = "Display Only" (label only, existing behavior)
                    Localization.L("culture_with_troops_btn"),
                    Localization.L("culture_display_only_btn"),
                    delegate()
                    {
                        // "With Troops" — chain to base culture selection, then troop pickers
                        CultureObject baseCulture = hero.Culture ?? (cultureNames.Count > 0 ? cultureMap[cultureNames[0]] : null);
                        if (baseCulture == null)
                        {
                            _popupOpen = false;
                            return;
                        }
                        ShowTroopPicker(objectId, hero, customName, baseCulture, "basic");
                    },
                    delegate()
                    {
                        // "Display Only" — use existing behavior (label only, no gameplay effect)
                        _popupOpen = false;
                        CultureObject baseCulture = hero.Culture ?? (cultureNames.Count > 0 ? cultureMap[cultureNames[0]] : null);
                        if (baseCulture != null)
                            ApplyCulture(objectId, hero, baseCulture, customName);
                    }
                ),
                false);
        }

        /// <summary>
        /// Shows a troop picker for basic or elite troop selection.
        /// Chains: basic troop → elite troop → create and apply custom culture.
        /// </summary>
        private static void ShowTroopPicker(string objectId, Hero hero,
            string customName, CultureObject baseCulture, string troopType)
        {
            bool isBasic = troopType == "basic";
            string title = isBasic
                ? Localization.L("troop_pick_basic_title")
                : Localization.L("troop_pick_elite_title");
            string desc = isBasic
                ? Localization.L("troop_pick_basic_desc", customName)
                : Localization.L("troop_pick_elite_desc", customName);

            var troops = CustomCultureManager.GetAvailableTroops();
            if (troops.Count == 0)
            {
                _popupOpen = false;
                MCMSettings.DebugLog("No troops available for custom culture troop picker");
                InformationManager.DisplayMessage(
                    new InformationMessage(Localization.L("ui_no_troops"), Colors.Red));
                return;
            }

            // Try multi-selection list first, fall back to numbered list
            if (!TryShowTroopMultiSelectionList(objectId, hero, customName, baseCulture, troops, troopType, title, desc))
            {
                ShowTroopNumberedList(objectId, hero, customName, baseCulture, troops, troopType, title, 0);
            }
        }

        /// <summary>
        /// Stores the selected basic troop id while waiting for elite troop selection.
        /// </summary>
        private static string _pendingBasicTroopId;

        /// <summary>
        /// Shows a multi-selection clickable list of troops for troop picker.
        /// Returns true if the multi-selection API was available.
        /// </summary>
        private static bool TryShowTroopMultiSelectionList(string objectId, Hero hero,
            string customName, CultureObject baseCulture, List<Tuple<string, string>> troops,
            string troopType, string title, string desc)
        {
            try
            {
                // Round 4 finding N-C2: cached scan replaces inline assembly walk.
                Type inquiryElementType = InquiryTypeCache.InquiryElement;
                Type multiSelDataType = InquiryTypeCache.MultiSelectionInquiryData;

                if (inquiryElementType == null || multiSelDataType == null) return false;

                var showMethod = MultiSelectionMethodCache.Find(multiSelDataType);
                if (showMethod == null) return false;

                var elementCtor = MultiSelectionMethodCache.FindInquiryElementCtor(inquiryElementType, out bool secondParamIsTextObject);
                if (elementCtor == null) return false;

                var elementCtorParams = elementCtor.GetParameters();
                var listType = typeof(List<>).MakeGenericType(inquiryElementType);
                var elements = (System.Collections.IList)Activator.CreateInstance(listType);

                foreach (var troop in troops)
                {
                    elements.Add(MultiSelectionMethodCache.CreateInquiryElement(
                        elementCtor, elementCtorParams, secondParamIsTextObject,
                        troop.Item2, troop.Item1)); // id = stringId, display = label
                }

                // Build affirmative callback
                var handler = new TroopSelectionHandler(objectId, hero, customName, baseCulture, troopType);
                var actionType = typeof(Action<>).MakeGenericType(listType);

                var affParam = System.Linq.Expressions.Expression.Parameter(listType, "elements");
                var affCall = System.Linq.Expressions.Expression.Call(
                    System.Linq.Expressions.Expression.Constant(handler),
                    typeof(TroopSelectionHandler).GetMethod("OnTroopSelected"),
                    System.Linq.Expressions.Expression.Convert(affParam, typeof(object)));
                var affDelegate = System.Linq.Expressions.Expression.Lambda(actionType, affCall, affParam).Compile();

                // Build negative callback
                var cancelHandler = new TroopSelectionCancelHandler();
                var negParam = System.Linq.Expressions.Expression.Parameter(listType, "elements");
                var negCall = System.Linq.Expressions.Expression.Call(
                    System.Linq.Expressions.Expression.Constant(cancelHandler),
                    typeof(TroopSelectionCancelHandler).GetMethod("OnCancel"),
                    System.Linq.Expressions.Expression.Convert(negParam, typeof(object)));
                var negDelegate = System.Linq.Expressions.Expression.Lambda(actionType, negCall, negParam).Compile();

                System.Reflection.ConstructorInfo dataCtor = null;
                foreach (var ctor in multiSelDataType.GetConstructors())
                {
                    var pars = ctor.GetParameters();
                    if (pars.Length >= 8 && (dataCtor == null || pars.Length > dataCtor.GetParameters().Length))
                        dataCtor = ctor;
                }
                if (dataCtor == null) return false;

                string affText = Localization.L("edit_save");
                string negText = Localization.L("edit_cancel");

                object dataObj = MultiSelectionMethodCache.BuildMultiSelectionInquiryData(
                    dataCtor, title, desc, affText, negText,
                    elements, listType, affDelegate, negDelegate);

                var showParams = showMethod.GetParameters();
                if (showParams.Length == 1)
                    showMethod.Invoke(null, new object[] { dataObj });
                else if (showParams.Length == 2)
                    showMethod.Invoke(null, new object[] { dataObj, false });
                else
                    showMethod.Invoke(null, new object[] { dataObj, false, false });

                EncyclopediaNavigationGuard.ScheduleNavigateBack();
                return true;
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TryShowTroopMultiSelectionList failed: " + ex.ToString());
                return false;
            }
        }

        /// <summary>
        /// Fallback: shows troops as a paginated numbered list.
        /// </summary>
        private const int TroopPageSize = 15;

        private static void ShowTroopNumberedList(string objectId, Hero hero,
            string customName, CultureObject baseCulture, List<Tuple<string, string>> troops,
            string troopType, string title, int page)
        {
            bool isBasic = troopType == "basic";
            int totalPages = (troops.Count + TroopPageSize - 1) / TroopPageSize;
            if (totalPages < 1) totalPages = 1;
            int start = page * TroopPageSize;
            int end = Math.Min(start + TroopPageSize, troops.Count);

            var sb = new System.Text.StringBuilder();
            sb.AppendLine(isBasic
                ? Localization.L("troop_pick_basic_desc", customName)
                : Localization.L("troop_pick_elite_desc", customName));
            if (totalPages > 1)
                sb.AppendLine("(" + (page + 1) + "/" + totalPages + ")");
            sb.AppendLine();

            for (int i = start; i < end; i++)
                sb.AppendLine((i + 1) + ". " + troops[i].Item1);

            if (page < totalPages - 1)
                sb.AppendLine("\n> " + Localization.L("numbered_list_next_hint"));
            if (page > 0)
                sb.AppendLine("> " + Localization.L("numbered_list_prev_hint"));

            EEInquiry.Show(
                new TextInquiryData(
                    title,
                    sb.ToString(),
                    true,
                    true,
                    Localization.L("edit_save"),
                    Localization.L("edit_cancel"),
                    delegate(string input)
                    {
                        input = (input ?? "").Trim();
                        if (string.IsNullOrEmpty(input)) { _popupOpen = false; return; }

                        if (input.Equals("next", StringComparison.OrdinalIgnoreCase) || input.Equals("n", StringComparison.OrdinalIgnoreCase))
                        {
                            if (page < totalPages - 1)
                                ShowTroopNumberedList(objectId, hero, customName, baseCulture, troops, troopType, title, page + 1);
                            else
                                ShowTroopNumberedList(objectId, hero, customName, baseCulture, troops, troopType, title, page);
                            return;
                        }
                        if (input.Equals("prev", StringComparison.OrdinalIgnoreCase) || input.Equals("p", StringComparison.OrdinalIgnoreCase))
                        {
                            if (page > 0)
                                ShowTroopNumberedList(objectId, hero, customName, baseCulture, troops, troopType, title, page - 1);
                            else
                                ShowTroopNumberedList(objectId, hero, customName, baseCulture, troops, troopType, title, page);
                            return;
                        }

                        int choice;
                        if (int.TryParse(input, out choice) && choice >= 1 && choice <= troops.Count)
                        {
                            string selectedTroopId = troops[choice - 1].Item2;
                            OnTroopChosen(objectId, hero, customName, baseCulture, troopType, selectedTroopId);
                        }
                        else
                        {
                            _popupOpen = false;
                            MCMSettings.DebugLog("Invalid troop selection: " + input);
                        }
                    },
                    delegate()
                    {
                        _popupOpen = false;
                        MCMSettings.DebugLog("Troop numbered list cancelled");
                    }),
                false, false);

            EncyclopediaNavigationGuard.ScheduleNavigateBack();
        }

        /// <summary>
        /// Called when a troop is chosen (from either multi-selection or numbered list).
        /// If basic troop, stashes it and shows elite troop picker.
        /// If elite troop, creates the custom culture and applies it.
        /// </summary>
        private static void OnTroopChosen(string objectId, Hero hero,
            string customName, CultureObject baseCulture, string troopType, string troopId)
        {
            if (troopType == "basic")
            {
                _pendingBasicTroopId = troopId;
                MCMSettings.DebugLog("Basic troop selected: " + troopId + ", now picking elite troop...");
                ShowTroopPicker(objectId, hero, customName, baseCulture, "elite");
            }
            else
            {
                // Both troops selected — create the custom culture
                string basicTroopId = _pendingBasicTroopId;
                _pendingBasicTroopId = null;

                if (string.IsNullOrEmpty(basicTroopId))
                {
                    _popupOpen = false;
                    MCMSettings.DebugLog("Elite troop selected but basic troop was null — aborting");
                    return;
                }

                string eliteTroopId = troopId;
                string customCultureId = CustomCultureManager.GenerateCultureId(customName);

                MCMSettings.DebugLog("Creating custom culture: id=" + customCultureId
                    + ", name=" + customName + ", base=" + baseCulture.StringId
                    + ", basic=" + basicTroopId + ", elite=" + eliteTroopId);

                // Store the definition in the behavior
                EncyclopediaEditBehavior.Instance.SetCustomCultureDefinition(
                    customCultureId, customName, baseCulture.StringId, basicTroopId, eliteTroopId);

                // Create and register the CultureObject
                var customCulture = CustomCultureManager.GetOrCreateCulture(
                    customCultureId, customName, baseCulture.StringId, basicTroopId, eliteTroopId);

                if (customCulture != null)
                {
                    // Apply the custom culture to the hero (with actual hero.Culture change)
                    ApplyCustomCultureWithTroops(objectId, hero, customCulture, customCultureId, customName);
                }
                else
                {
                    // Fallback: just apply as display-only
                    MCMSettings.DebugLog("Custom culture creation failed, falling back to display-only");
                    ApplyCulture(objectId, hero, baseCulture, customName);
                }

                _popupOpen = false;
            }
        }

        /// <summary>
        /// Applies a custom culture with troop definitions to a hero.
        /// Unlike ApplyCulture(), this DOES change the actual hero.Culture property
        /// so the game uses the custom troop tree for recruitment/AI.
        /// </summary>
        private static void ApplyCustomCultureWithTroops(string objectId, Hero hero,
            CultureObject customCulture, string customCultureId, string displayName)
        {
            try
            {
                var reflFlags = System.Reflection.BindingFlags.Instance
                              | System.Reflection.BindingFlags.Public
                              | System.Reflection.BindingFlags.NonPublic;
                var declaredFlags = reflFlags | System.Reflection.BindingFlags.DeclaredOnly;

                // Actually set hero.Culture and CharacterObject.Culture
                // Use DeclaredOnly to avoid "Ambiguous match found" when base/derived both have Culture
                if (hero.CharacterObject != null)
                {
                    bool charSet = false;
                    // Try field first (more reliable, avoids ambiguity)
                    var charField = hero.CharacterObject.GetType().GetField("_culture", reflFlags)
                                 ?? hero.CharacterObject.GetType().GetField("<Culture>k__BackingField", reflFlags);
                    if (charField != null && charField.FieldType.IsAssignableFrom(typeof(CultureObject)))
                    {
                        charField.SetValue(hero.CharacterObject, customCulture);
                        charSet = true;
                    }
                    if (!charSet)
                    {
                        try
                        {
                            var charProp = hero.CharacterObject.GetType().GetProperty("Culture", declaredFlags);
                            if (charProp != null && charProp.CanWrite)
                                charProp.SetValue(hero.CharacterObject, customCulture);
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: setting CharacterObject.Culture property failed: " + ex.ToString()); }
                    }
                }

                bool heroSet = false;
                var heroField = typeof(Hero).GetField("_culture", reflFlags)
                             ?? typeof(Hero).GetField("<Culture>k__BackingField", reflFlags);
                if (heroField != null && heroField.FieldType.IsAssignableFrom(typeof(CultureObject)))
                {
                    heroField.SetValue(hero, customCulture);
                    heroSet = true;
                }
                if (!heroSet)
                {
                    try
                    {
                        var heroProp = typeof(Hero).GetProperty("Culture", declaredFlags);
                        if (heroProp != null && heroProp.CanWrite)
                            heroProp.SetValue(hero, customCulture);
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: setting Hero.Culture property failed: " + ex.ToString()); }
                }

                // Force-refresh volunteer troop slots for notables so recruitment updates immediately
                RefreshNotableVolunteers(hero, customCulture, objectId);

                // Update settlement culture for clan leaders so militia/garrison use new troop tree
                UpdateOwnedSettlementsCulture(hero, customCulture, objectId);

                // Save to persistence
                EncyclopediaEditBehavior.Instance.SetCustomCulture(objectId, customCultureId);
                EncyclopediaEditBehavior.Instance.SetCustomCultureDisplayName(objectId, displayName);

                MCMSettings.DebugLog("Applied custom culture with troops: " + displayName
                    + " (id=" + customCultureId + ") to hero " + objectId);

                // Refresh the page
                // v2.5.2 fix: defer refresh+message to next tick to avoid same-thread reentrance
                // crash inside GauntletGamepadNavigationManager.Update (Dictionary modified during enum).
                var refresh = EncyclopediaPageTracker.CurrentRefreshAction;
                bool showConfirm = true;
                try
                {
                    var settings = MCMSettings.Instance;
                    if (settings != null) showConfirm = settings.ShowConfirmationMessages;
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: reading ShowConfirmationMessages setting failed: " + ex.ToString()); }

                string confirmMsg = showConfirm ? Localization.L("msg_custom_culture_created", displayName) : null;
                EncyclopediaPatchHelper.SchedulePostApplyRefresh(refresh, confirmMsg);
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("ApplyCustomCultureWithTroops failed: " + ex.ToString());
                InformationManager.DisplayMessage(
                    new InformationMessage(Localization.L("msg_culture_invalid"), Colors.Red));
            }
        }

        /// <summary>
        /// Handler for multi-selection troop list affirmative callback.
        /// </summary>
        private class TroopSelectionHandler
        {
            private readonly string _objectId;
            private readonly Hero _hero;
            private readonly string _customName;
            private readonly CultureObject _baseCulture;
            private readonly string _troopType;

            public TroopSelectionHandler(string objectId, Hero hero, string customName,
                CultureObject baseCulture, string troopType)
            {
                _objectId = objectId;
                _hero = hero;
                _customName = customName;
                _baseCulture = baseCulture;
                _troopType = troopType;
            }

            public void OnTroopSelected(object selectedElements)
            {
                try
                {
                    var list = selectedElements as System.Collections.IList;
                    if (list == null || list.Count == 0)
                    {
                        _popupOpen = false;
                        return;
                    }

                    string selectedId = MultiSelectionMethodCache.GetInquiryElementId(list[0]);
                    if (string.IsNullOrEmpty(selectedId))
                    {
                        _popupOpen = false;
                        return;
                    }

                    OnTroopChosen(_objectId, _hero, _customName, _baseCulture, _troopType, selectedId);
                }
                catch (Exception ex)
                {
                    _popupOpen = false;
                    MCMSettings.DebugLog("OnTroopSelected failed: " + ex.ToString());
                }
            }
        }

        /// <summary>
        /// Handler for multi-selection troop list cancel callback.
        /// </summary>
        private class TroopSelectionCancelHandler
        {
            public void OnCancel(object selectedElements)
            {
                _popupOpen = false;
                _pendingBasicTroopId = null;
                MCMSettings.DebugLog("Troop selection cancelled");
            }
        }

        /// <summary>
        /// Tries to match input to a culture name (exact then partial) and apply it.
        /// Handles both vanilla cultures (in cultureMap) and custom culture names.
        /// Returns true if a match was found and applied.
        /// </summary>
        internal static bool TryApplyMatchedCulture(string objectId, Hero hero,
            string input, List<string> cultureNames, Dictionary<string, CultureObject> cultureMap)
        {
            // Exact match first, then partial
            string matchedName = null;
            foreach (var name in cultureNames)
            {
                if (string.Equals(name, input, StringComparison.OrdinalIgnoreCase))
                { matchedName = name; break; }
            }
            if (matchedName == null)
            {
                foreach (var name in cultureNames)
                {
                    if (name.IndexOf(input, StringComparison.OrdinalIgnoreCase) >= 0)
                    { matchedName = name; break; }
                }
            }
            if (matchedName == null) return false;

            // If it's in cultureMap, it might be vanilla or a registered custom culture with troops
            if (cultureMap.ContainsKey(matchedName))
            {
                var selectedCulture = cultureMap[matchedName];
                // Check if this is a custom culture with troop definitions
                if (selectedCulture.StringId != null && selectedCulture.StringId.StartsWith("ee_custom_")
                    && EncyclopediaEditBehavior.Instance?.HasCustomCultureDefinition(selectedCulture.StringId) == true)
                {
                    ApplyCustomCultureWithTroops(objectId, hero, selectedCulture, selectedCulture.StringId, matchedName);
                    return true;
                }
                ApplyCulture(objectId, hero, selectedCulture, null);
                return true;
            }

            // It's a custom culture name — find which base culture it uses
            // by looking up a hero that has this custom culture display name
            try
            {
                CultureObject baseCulture = null;
                foreach (var h in Hero.AllAliveHeroes)
                {
                    if (h == null) continue;
                    string dn = EncyclopediaEditBehavior.Instance.GetCustomCultureDisplayName(h.StringId);
                    if (string.Equals(dn, matchedName, StringComparison.OrdinalIgnoreCase))
                    {
                        // Get the base culture id stored for this hero
                        string baseCultureId = EncyclopediaEditBehavior.Instance.GetCustomCulture(h.StringId);
                        if (!string.IsNullOrEmpty(baseCultureId))
                        {
                            foreach (var c in TaleWorlds.ObjectSystem.MBObjectManager.Instance.GetObjectTypeList<CultureObject>())
                            {
                                if (c != null && string.Equals(c.StringId, baseCultureId, StringComparison.OrdinalIgnoreCase))
                                { baseCulture = c; break; }
                            }
                        }
                        if (baseCulture == null)
                            baseCulture = h.Culture;
                        break;
                    }
                }

                if (baseCulture != null)
                {
                    // If this is a custom culture with troop definitions, apply it fully
                    // (changing actual hero.Culture) so recruitment uses the custom troop tree
                    if (baseCulture.StringId != null && baseCulture.StringId.StartsWith("ee_custom_")
                        && EncyclopediaEditBehavior.Instance?.HasCustomCultureDefinition(baseCulture.StringId) == true)
                    {
                        ApplyCustomCultureWithTroops(objectId, hero, baseCulture, baseCulture.StringId, matchedName);
                    }
                    else
                    {
                        ApplyCulture(objectId, hero, baseCulture, matchedName);
                    }
                    return true;
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Failed to resolve custom culture '" + matchedName + "': " + ex.ToString());
            }
            return false;
        }

        /// <summary>
        /// Applies an existing culture to the hero. If customDisplayName is provided,
        /// the hero uses this real culture internally (for game mechanics) but the
        /// encyclopedia will show the custom name instead.
        /// </summary>
        private static void ApplyCulture(string objectId, Hero hero, CultureObject culture, string customDisplayName)
        {
            try
            {
                // Set hero.Culture and CharacterObject.Culture via reflection
                // so settlement/clan/kingdom pages show the correct culture
                try
                {
                    var reflFlags = System.Reflection.BindingFlags.Instance
                                  | System.Reflection.BindingFlags.Public
                                  | System.Reflection.BindingFlags.NonPublic;

                    // Store original culture before first change
                    if (hero.Culture != null)
                        EncyclopediaEditBehavior.Instance.StoreOriginalCulture(objectId, hero.Culture.StringId);

                    // Set on Hero
                    var heroField = typeof(Hero).GetField("_culture", reflFlags)
                                 ?? typeof(Hero).GetField("<Culture>k__BackingField", reflFlags);
                    if (heroField != null && heroField.FieldType.IsAssignableFrom(typeof(CultureObject)))
                    {
                        heroField.SetValue(hero, culture);
                        MCMSettings.DebugLog("ApplyCulture: set Hero._culture to " + culture.StringId);
                    }

                    // Set on CharacterObject
                    if (hero.CharacterObject != null)
                    {
                        var charField = hero.CharacterObject.GetType().GetField("_culture", reflFlags)
                                     ?? hero.CharacterObject.GetType().GetField("<Culture>k__BackingField", reflFlags);
                        if (charField != null && charField.FieldType.IsAssignableFrom(typeof(CultureObject)))
                            charField.SetValue(hero.CharacterObject, culture);
                    }

                    // Update owned settlements if hero is clan leader
                    UpdateOwnedSettlementsCulture(hero, culture, objectId);
                }
                catch (Exception ex) { MCMSettings.DebugLog("ApplyCulture: reflection failed: " + ex.ToString()); }

                // Validate and sanitize custom display name
                if (!string.IsNullOrEmpty(customDisplayName))
                {
                    customDisplayName = customDisplayName.Trim();
                    if (customDisplayName.Length > 40)
                        customDisplayName = customDisplayName.Substring(0, 40);
                }

                // Save to persistence: store the real culture id
                EncyclopediaEditBehavior.Instance.SetCustomCulture(objectId, culture.StringId);

                // If a custom display name was given, store it separately
                if (!string.IsNullOrEmpty(customDisplayName))
                    EncyclopediaEditBehavior.Instance.SetCustomCultureDisplayName(objectId, customDisplayName);
                else
                    EncyclopediaEditBehavior.Instance.SetCustomCultureDisplayName(objectId, null);

                string displayName = customDisplayName ?? culture.Name?.ToString() ?? culture.StringId;
                MCMSettings.DebugLog("Culture set to " + displayName + " (base=" + culture.StringId + ") for " + objectId);

                // Force-refresh notable volunteer slots so the recruit panel reflects the new
                // culture immediately instead of waiting for the next daily tick. Mirrors what
                // ResetCulture does. No-ops on non-notables (lords, wanderers, companions).
                RefreshNotableVolunteers(hero, culture, objectId);

                // Refresh the page
                // v2.5.2 fix: defer refresh+message to next tick to avoid same-thread reentrance
                // crash inside GauntletGamepadNavigationManager.Update.
                var refresh = EncyclopediaPageTracker.CurrentRefreshAction;
                bool showConfirm = true;
                try
                {
                    var settings = MCMSettings.Instance;
                    if (settings != null) showConfirm = settings.ShowConfirmationMessages;
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: reading ShowConfirmationMessages setting failed: " + ex.ToString()); }

                string confirmMsg = showConfirm ? Localization.L("msg_culture_updated", displayName) : null;
                EncyclopediaPatchHelper.SchedulePostApplyRefresh(refresh, confirmMsg);

                // Auto-clean orphaned entries after change
                try { EncyclopediaEditBehavior.Instance.PurgeOrphanedCustomEntries(); }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: PurgeOrphanedCustomEntries failed: " + ex.ToString()); }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Failed to set culture: " + ex.ToString());
                InformationManager.DisplayMessage(
                    new InformationMessage(Localization.L("msg_culture_invalid"), Colors.Red));
            }
        }

        /// <summary>
        /// Resets a hero's culture back to the original value and removes all custom culture data.
        /// </summary>
        internal static void ResetCulture(string objectId, Hero hero)
        {
            try
            {
                var behavior = EncyclopediaEditBehavior.Instance;
                if (behavior == null) return;

                string origCultureId = behavior.GetOriginalCulture(objectId);
                if (string.IsNullOrEmpty(origCultureId))
                {
                    MCMSettings.DebugLog("No original culture stored for " + objectId + ", just removing custom data");
                    behavior.RemoveCustomCulture(objectId);

                    var refresh0 = EncyclopediaPageTracker.CurrentRefreshAction;
                    if (refresh0 != null) try { refresh0(); } catch (Exception ex) { MCMSettings.DebugLog("Patches: refresh0(); failed: " + ex.ToString()); }

                    InformationManager.DisplayMessage(
                        new InformationMessage(Localization.L("msg_culture_reset"), Colors.Green));
                    return;
                }

                // Find the original culture object
                CultureObject origCulture = null;
                foreach (var c in TaleWorlds.ObjectSystem.MBObjectManager.Instance.GetObjectTypeList<CultureObject>())
                {
                    if (c != null && string.Equals(c.StringId, origCultureId, StringComparison.OrdinalIgnoreCase))
                    { origCulture = c; break; }
                }

                if (origCulture == null)
                {
                    MCMSettings.DebugLog("WARNING: Original culture '" + origCultureId + "' no longer exists in game for " + objectId);
                    InformationManager.DisplayMessage(
                        new InformationMessage(Localization.L("msg_culture_original_missing", origCultureId), Colors.Yellow));
                    // Still remove custom data so the hero reverts to whatever the game gives them
                    behavior.RemoveCustomCulture(objectId);

                    var refresh1 = EncyclopediaPageTracker.CurrentRefreshAction;
                    if (refresh1 != null) try { refresh1(); } catch (Exception ex) { MCMSettings.DebugLog("Patches: refresh1(); failed: " + ex.ToString()); }
                    return;
                }

                {
                    var flags = System.Reflection.BindingFlags.Instance
                              | System.Reflection.BindingFlags.Public
                              | System.Reflection.BindingFlags.NonPublic;

                    // Primary: set on CharacterObject (what the game reads from)
                    try
                    {
                        if (hero.CharacterObject != null)
                        {
                            var charCultureProp = hero.CharacterObject.GetType().GetProperty("Culture", flags);
                            if (charCultureProp != null && charCultureProp.CanWrite)
                                charCultureProp.SetValue(hero.CharacterObject, origCulture);
                            else
                            {
                                var charField = hero.CharacterObject.GetType().GetField("_culture", flags)
                                             ?? hero.CharacterObject.GetType().GetField("<Culture>k__BackingField", flags);
                                if (charField != null && charField.FieldType == typeof(CultureObject))
                                    charField.SetValue(hero.CharacterObject, origCulture);
                            }
                        }
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: setting CharacterObject culture on reset failed: " + ex.ToString()); }

                    // Secondary: also set on Hero directly
                    var cultureProp = typeof(Hero).GetProperty("Culture", flags);
                    if (cultureProp != null && cultureProp.CanWrite)
                        cultureProp.SetValue(hero, origCulture);
                    else
                    {
                        var cultureField = typeof(Hero).GetField("_culture", flags)
                                        ?? typeof(Hero).GetField("<Culture>k__BackingField", flags);
                        if (cultureField != null && cultureField.FieldType == typeof(CultureObject))
                            cultureField.SetValue(hero, origCulture);
                    }
                }

                // Force-refresh volunteer troop slots with original culture
                RefreshNotableVolunteers(hero, origCulture, objectId);

                // Revert settlement culture for clan leaders
                UpdateOwnedSettlementsCulture(hero, origCulture, objectId);

                // Remove custom culture data from persistence
                behavior.RemoveCustomCulture(objectId);

                string displayName = origCulture.Name?.ToString() ?? origCultureId;
                MCMSettings.DebugLog("Culture reset to original (" + displayName + ") for " + objectId);

                // v2.5.2 fix: defer refresh+message to next tick to avoid same-thread reentrance
                // crash inside GauntletGamepadNavigationManager.Update.
                var refresh = EncyclopediaPageTracker.CurrentRefreshAction;
                EncyclopediaPatchHelper.SchedulePostApplyRefresh(refresh, Localization.L("msg_culture_reset"));

                // Auto-clean orphaned entries after reset
                try { behavior.PurgeOrphanedCustomEntries(); }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: behavior.PurgeOrphanedCustomEntries(); failed: " + ex.ToString()); }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Failed to reset culture: " + ex.ToString());
            }
        }

        /// <summary>
        /// Forces a notable's volunteer troop slots to use the given culture's BasicTroop.
        /// The game only refreshes volunteer slots on daily tick, so without this,
        /// changing a notable's culture wouldn't update recruitment until the next day.
        /// </summary>
        internal static void RefreshNotableVolunteers(Hero hero, CultureObject culture, string objectId)
        {
            try
            {
                bool isNotable = false;
                try { isNotable = hero.IsNotable; } catch (Exception ex) { MCMSettings.DebugLog("Patches: isNotable = hero.IsNotable; failed: " + ex.ToString()); }
                if (!isNotable)
                {
                    MCMSettings.DebugLog("RefreshNotableVolunteers: " + objectId + " is not a notable, skipping");
                    return;
                }

                CharacterObject basicTroop = null;
                try { basicTroop = culture.BasicTroop; } catch (Exception ex) { MCMSettings.DebugLog("Patches: basicTroop = culture.BasicTroop; failed: " + ex.ToString()); }
                if (basicTroop == null)
                {
                    MCMSettings.DebugLog("RefreshNotableVolunteers: culture " + culture.StringId + " has no BasicTroop");
                    return;
                }

                var reflFlags = System.Reflection.BindingFlags.Instance
                              | System.Reflection.BindingFlags.Public
                              | System.Reflection.BindingFlags.NonPublic;

                // --- Strategy 1: Try VolunteerTypes property directly ---
                CharacterObject[] volArray = null;
                System.Reflection.FieldInfo writableField = null;
                try
                {
                    var volProp = typeof(Hero).GetProperty("VolunteerTypes", reflFlags);
                    if (volProp != null)
                    {
                        var val = volProp.GetValue(hero);
                        volArray = val as CharacterObject[];
                        if (volArray == null && val != null)
                        {
                            MCMSettings.DebugLog("RefreshNotableVolunteers: VolunteerTypes property returned "
                                + val.GetType().FullName + " (not CharacterObject[])");
                        }
                    }
                }
                catch (Exception propEx)
                {
                    MCMSettings.DebugLog("RefreshNotableVolunteers: VolunteerTypes property access failed: " + propEx.Message);
                }

                // v2.5.2 fix: even if Strategy 1 found the array via the property, we ALSO need
                // a writable field handle. Some Bannerlord properties return defensive copies —
                // mutating volArray in-place would not persist. Find the backing field eagerly so
                // the post-mutation write-back below restores the array reference into the hero.
                if (volArray != null && writableField == null)
                {
                    var probeNames = new[] { "_volunteerTypes", "volunteerTypes",
                                             "<VolunteerTypes>k__BackingField",
                                             "_volunteerTypesCache", "volunteerTypesCache" };
                    for (var type = hero.GetType(); type != null && writableField == null; type = type.BaseType)
                    {
                        foreach (var name in probeNames)
                        {
                            var field = type.GetField(name, reflFlags | System.Reflection.BindingFlags.DeclaredOnly);
                            if (field != null && field.FieldType == typeof(CharacterObject[]))
                            {
                                writableField = field;
                                MCMSettings.DebugLog("RefreshNotableVolunteers: Strategy-1 backing-field probe found "
                                    + type.Name + "." + name);
                                break;
                            }
                        }
                    }
                }

                // --- Strategy 2: Walk type hierarchy for known field names ---
                if (volArray == null)
                {
                    var fieldNames = new[] { "VolunteerTypes", "_volunteerTypes", "volunteerTypes",
                                             "<VolunteerTypes>k__BackingField",
                                             "_volunteerTypesCache", "volunteerTypesCache" };
                    for (var type = hero.GetType(); type != null && volArray == null; type = type.BaseType)
                    {
                        foreach (var name in fieldNames)
                        {
                            var field = type.GetField(name, reflFlags | System.Reflection.BindingFlags.DeclaredOnly);
                            if (field != null)
                            {
                                var val = field.GetValue(hero);
                                volArray = val as CharacterObject[];
                                if (volArray != null)
                                {
                                    writableField = field;
                                    MCMSettings.DebugLog("RefreshNotableVolunteers: found array via " + type.Name + "." + name);
                                    break;
                                }
                                else if (val != null)
                                {
                                    MCMSettings.DebugLog("RefreshNotableVolunteers: field " + type.Name + "."
                                        + name + " is " + val.GetType().FullName + ", not CharacterObject[]");
                                }
                            }
                        }
                    }
                }

                // --- Strategy 3: Search all fields for any CharacterObject[] ---
                if (volArray == null)
                {
                    MCMSettings.DebugLog("RefreshNotableVolunteers: named fields failed, scanning all fields on Hero...");
                    for (var type = hero.GetType(); type != null && volArray == null; type = type.BaseType)
                    {
                        var fields = type.GetFields(reflFlags | System.Reflection.BindingFlags.DeclaredOnly);
                        foreach (var field in fields)
                        {
                            if (field.FieldType == typeof(CharacterObject[]))
                            {
                                var val = field.GetValue(hero) as CharacterObject[];
                                if (val != null && val.Length > 0)
                                {
                                    volArray = val;
                                    writableField = field;
                                    MCMSettings.DebugLog("RefreshNotableVolunteers: discovered array at "
                                        + type.Name + "." + field.Name + " (length=" + val.Length + ")");
                                    break;
                                }
                                else
                                {
                                    MCMSettings.DebugLog("RefreshNotableVolunteers: found CharacterObject[] field "
                                        + type.Name + "." + field.Name + " but it's "
                                        + (val == null ? "null" : "empty"));
                                }
                            }
                        }
                    }
                }

                if (volArray == null || volArray.Length == 0)
                {
                    // Log all fields on Hero for diagnostic purposes
                    MCMSettings.DebugLog("RefreshNotableVolunteers: FAILED to find volunteer array for " + objectId
                        + ". Dumping Hero fields:");
                    int fieldCount = 0;
                    for (var type = hero.GetType(); type != null && type != typeof(object); type = type.BaseType)
                    {
                        var fields = type.GetFields(reflFlags | System.Reflection.BindingFlags.DeclaredOnly);
                        foreach (var field in fields)
                        {
                            if (field.FieldType.IsArray || field.FieldType.FullName.Contains("CharacterObject"))
                            {
                                object val = null;
                                try { val = field.GetValue(hero); } catch (Exception ex) { MCMSettings.DebugLog("Patches: val = field.GetValue(hero); failed: " + ex.ToString()); }
                                MCMSettings.DebugLog("  " + type.Name + "." + field.Name + " : "
                                    + field.FieldType.Name
                                    + (val != null ? " = " + val.ToString() : " = null"));
                                fieldCount++;
                            }
                        }
                    }
                    MCMSettings.DebugLog("  (logged " + fieldCount + " array/CharacterObject fields)");
                    return;
                }

                // Build troop tree via BFS from BasicTroop following UpgradeTargets
                var allTroops = new List<CharacterObject> { basicTroop };
                var queue = new Queue<CharacterObject>();
                queue.Enqueue(basicTroop);
                var visited = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { basicTroop.StringId };

                while (queue.Count > 0 && allTroops.Count < volArray.Length * 3)
                {
                    var current = queue.Dequeue();
                    try
                    {
                        var upgrades = current.UpgradeTargets;
                        if (upgrades != null)
                        {
                            foreach (var upgrade in upgrades)
                            {
                                if (upgrade != null && visited.Add(upgrade.StringId))
                                {
                                    allTroops.Add(upgrade);
                                    queue.Enqueue(upgrade);
                                }
                            }
                        }
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: reading troop UpgradeTargets failed: " + ex.ToString()); }
                }

                // Fill slots — if we only have the root troop (no upgrade tree), fill all with it.
                // Otherwise distribute across available troops in the tree.
                for (int i = 0; i < volArray.Length; i++)
                    volArray[i] = allTroops[i % allTroops.Count];

                // v2.5.2 fix: Bannerlord's VolunteerTypes property may return a defensive copy.
                // If so, in-place mutation above did NOT persist into the hero's actual storage,
                // so the recruit roster keeps showing default-culture troops. Write the array
                // reference back via the backing field if we have one — this guarantees the
                // mutation reaches the underlying storage even when the getter copies.
                if (writableField != null)
                {
                    try
                    {
                        writableField.SetValue(hero, volArray);
                        MCMSettings.DebugLog("RefreshNotableVolunteers: wrote array back via "
                            + writableField.DeclaringType?.Name + "." + writableField.Name);
                    }
                    catch (Exception wEx)
                    {
                        MCMSettings.DebugLog("RefreshNotableVolunteers: write-back failed: " + wEx.ToString());
                    }
                }

                MCMSettings.DebugLog("RefreshNotableVolunteers: set " + volArray.Length + " slots for " + objectId
                    + " (tree size=" + allTroops.Count + ", root=" + basicTroop.StringId + ")");
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("RefreshNotableVolunteers failed for " + objectId + ": " + ex.ToString());
            }
        }

        /// <summary>
        /// Updates Settlement.Culture on all settlements owned by the hero's clan
        /// (if the hero is the clan leader). Sets the public Culture field directly.
        /// Tracks original cultures so SaveSanitizerPatch can restore them before save.
        /// </summary>
        internal static void UpdateOwnedSettlementsCulture(Hero hero, CultureObject culture, string objectId)
        {
            try
            {
                if (culture == null)
                {
                    MCMSettings.DebugLog("UpdateOwnedSettlementsCulture: REFUSED — culture is null for " + objectId + ". Skipping to prevent corruption.");
                    return;
                }
                if (hero?.Clan == null)
                {
                    MCMSettings.DebugLog("UpdateOwnedSettlementsCulture: hero has no clan for " + objectId);
                    return;
                }
                if (hero.Clan.Leader != hero)
                {
                    MCMSettings.DebugLog("UpdateOwnedSettlementsCulture: not clan leader for " + objectId);
                    return;
                }

                // Take a snapshot of settlements to avoid collection-modified issues
                var settlements = new List<Settlement>();
                try
                {
                    foreach (var s in hero.Clan.Settlements)
                    {
                        if (s != null && (s.IsTown || s.IsCastle || s.IsVillage))
                            settlements.Add(s);
                    }
                }
                catch (Exception ex)
                {
                    MCMSettings.DebugLog("UpdateOwnedSettlementsCulture: failed to enumerate settlements: " + ex.ToString());
                    return;
                }

                int count = 0;
                foreach (var settlement in settlements)
                {
                    try
                    {
                        // Track original culture before overwriting (for SaveSanitizerPatch)
                        lock (SaveSanitizerPatch.OriginalSettlementCultures)
                        {
                            if (!SaveSanitizerPatch.OriginalSettlementCultures.ContainsKey(settlement))
                            {
                                if (settlement.Culture != null)
                                    SaveSanitizerPatch.OriginalSettlementCultures[settlement] = settlement.Culture;
                            }
                        }

                        settlement.Culture = culture;
                        count++;
                    }
                    catch (Exception ex)
                    {
                        MCMSettings.DebugLog("UpdateOwnedSettlementsCulture: failed to set culture on " + (settlement?.StringId ?? "null") + ": " + ex.ToString());
                    }
                }

                if (count > 0)
                    MCMSettings.DebugLog("UpdateOwnedSettlementsCulture: set " + count + " settlements for " + objectId);
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("UpdateOwnedSettlementsCulture failed: " + ex.ToString());
            }
        }

    }

    // ============================================
    //  Save Sanitizer — Harmony Prefix/Finalizer on MBSaveLoad
    //  Restores original settlement cultures before the game serializer
    //  writes settlement data, then re-applies custom cultures after save.
    // ============================================
    public static class SaveSanitizerPatch
    {
        /// <summary>
        /// Tracks the original (vanilla) CultureObject for each settlement whose
        /// culture was overridden by a custom culture. Keyed by settlement instance.
        /// </summary>
        internal static readonly Dictionary<Settlement, CultureObject> OriginalSettlementCultures
            = new Dictionary<Settlement, CultureObject>();

        /// <summary>
        /// Snapshot of settlements that were sanitized during the current save,
        /// along with the custom culture that was on them.
        /// </summary>
        [System.ThreadStatic]
        private static List<KeyValuePair<Settlement, CultureObject>> _sanitizedSnapshot;

        /// <summary>
        /// Snapshot of heroes whose culture was swapped to vanilla before save.
        /// Stores (Hero, customCulture) pairs for re-application after save.
        /// </summary>
        [System.ThreadStatic]
        private static List<KeyValuePair<Hero, CultureObject>> _sanitizedHeroSnapshot;

        // Cached reflection fields for setting hero.Culture
        private static System.Reflection.FieldInfo _heroCultureField;
        private static bool _heroCultureFieldCached;

        private static void EnsureHeroCultureFieldsCached()
        {
            if (_heroCultureFieldCached) return;
            _heroCultureFieldCached = true;
            var flags = System.Reflection.BindingFlags.Instance
                      | System.Reflection.BindingFlags.NonPublic
                      | System.Reflection.BindingFlags.Public;
            _heroCultureField = typeof(Hero).GetField("_culture", flags)
                             ?? typeof(Hero).GetField("<Culture>k__BackingField", flags);
        }

        private static void SetHeroCulture(Hero hero, CultureObject culture)
        {
            EnsureHeroCultureFieldsCached();
            if (_heroCultureField != null && _heroCultureField.FieldType.IsAssignableFrom(typeof(CultureObject)))
            {
                _heroCultureField.SetValue(hero, culture);
            }
            // Also set on CharacterObject
            if (hero.CharacterObject != null)
            {
                var flags = System.Reflection.BindingFlags.Instance
                          | System.Reflection.BindingFlags.NonPublic
                          | System.Reflection.BindingFlags.Public;
                var charField = hero.CharacterObject.GetType().GetField("_culture", flags)
                             ?? hero.CharacterObject.GetType().GetField("<Culture>k__BackingField", flags);
                if (charField != null && charField.FieldType.IsAssignableFrom(typeof(CultureObject)))
                {
                    charField.SetValue(hero.CharacterObject, culture);
                }
            }
        }

        /// <summary>
        /// Attempts to find and patch MBSaveLoad.OnSave (or similar save entry point).
        /// </summary>
        internal static bool TryApply(Harmony harmony)
        {
            try
            {
                // Search for the save method across known class names and method names
                string[] classNames = { "MBSaveLoad", "SaveHandler", "CampaignSaveHandler" };
                string[] methodNames = { "OnSave", "SaveGame", "Save", "OnBeforeSave" };
                var flags = System.Reflection.BindingFlags.Static
                          | System.Reflection.BindingFlags.Instance
                          | System.Reflection.BindingFlags.Public
                          | System.Reflection.BindingFlags.NonPublic;

                System.Reflection.MethodInfo saveMethod = null;
                string foundClass = null;
                string foundMethod = null;

                // First try known TaleWorlds assemblies
                foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                {
                    if (saveMethod != null) break;

                    string asmName = asm.GetName().Name ?? "";
                    if (!asmName.StartsWith("TaleWorlds", StringComparison.OrdinalIgnoreCase))
                        continue;

                    foreach (var className in classNames)
                    {
                        if (saveMethod != null) break;

                        foreach (var type in asm.GetTypes())
                        {
                            if (saveMethod != null) break;
                            if (!type.Name.Equals(className, StringComparison.OrdinalIgnoreCase))
                                continue;

                            foreach (var mn in methodNames)
                            {
                                var m = type.GetMethod(mn, flags);
                                if (m != null)
                                {
                                    saveMethod = m;
                                    foundClass = type.FullName;
                                    foundMethod = mn;
                                    break;
                                }
                            }
                        }
                    }
                }

                // Fallback: search for any type containing "SaveLoad" with a "Save" method
                if (saveMethod == null)
                {
                    foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                    {
                        if (saveMethod != null) break;
                        string asmName = asm.GetName().Name ?? "";
                        if (!asmName.StartsWith("TaleWorlds", StringComparison.OrdinalIgnoreCase))
                            continue;

                        try
                        {
                            foreach (var type in asm.GetTypes())
                            {
                                if (saveMethod != null) break;
                                if (!type.Name.Contains("SaveLoad")) continue;

                                MCMSettings.DebugLog("SaveSanitizerPatch: inspecting " + type.FullName);
                                foreach (var mn in methodNames)
                                {
                                    var m = type.GetMethod(mn, flags);
                                    if (m != null)
                                    {
                                        saveMethod = m;
                                        foundClass = type.FullName;
                                        foundMethod = mn;
                                        MCMSettings.DebugLog("SaveSanitizerPatch: found " + type.FullName + "." + mn);
                                        break;
                                    }
                                }
                            }
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: SaveLoad type scan for save method failed: " + ex.ToString()); }
                    }
                }

                if (saveMethod == null)
                {
                    MCMSettings.DebugLog("SaveSanitizerPatch: could not find save entry point");
                    return false;
                }

                var prefix = typeof(SaveSanitizerPatch).GetMethod("Prefix",
                    System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic);
                var finalizer = typeof(SaveSanitizerPatch).GetMethod("SaveFinalizer",
                    System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic);

                harmony.Patch(saveMethod,
                    prefix: new HarmonyMethod(prefix),
                    finalizer: new HarmonyMethod(finalizer));

                MCMSettings.DebugLog("SaveSanitizerPatch: patched " + foundClass + "." + foundMethod);
                return true;
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("SaveSanitizerPatch: failed: " + ex.ToString());
                return false;
            }
        }

        /// <summary>
        /// Runs BEFORE the game serializer writes settlement data.
        /// Restores all settlements to their original vanilla culture so the
        /// serializer only writes known culture IDs to disk.
        /// </summary>
        static void Prefix()
        {
            _sanitizedSnapshot = null;
            _sanitizedHeroSnapshot = null;

            // ── Sanitize SETTLEMENT cultures ──
            try
            {
                List<KeyValuePair<Settlement, CultureObject>> entries;
                lock (OriginalSettlementCultures)
                {
                    // Snapshot the dictionary to avoid concurrent modification
                    entries = new List<KeyValuePair<Settlement, CultureObject>>(OriginalSettlementCultures);
                }

                if (entries.Count > 0)
                {
                    var snapshot = new List<KeyValuePair<Settlement, CultureObject>>();
                    foreach (var kvp in entries)
                    {
                        try
                        {
                            var settlement = kvp.Key;
                            var originalCulture = kvp.Value;
                            if (settlement == null || originalCulture == null) continue;

                            CultureObject customCulture = null;
                            try { customCulture = settlement.Culture; }
                            catch { continue; } // settlement may have been destroyed

                            if (customCulture != null && customCulture != originalCulture)
                            {
                                snapshot.Add(new KeyValuePair<Settlement, CultureObject>(settlement, customCulture));
                                settlement.Culture = originalCulture;
                            }
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: sanitizing settlement culture for save failed: " + ex.ToString()); }
                    }

                    if (snapshot.Count > 0)
                    {
                        _sanitizedSnapshot = snapshot;
                        MCMSettings.DebugLog("SaveSanitizerPatch.Prefix: sanitized " + snapshot.Count + " settlements before save");
                    }
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("SaveSanitizerPatch.Prefix (settlements) failed: " + ex.ToString());
            }

            // ── Sanitize HERO cultures ──
            // Heroes with custom runtime CultureObjects must be swapped back to their
            // original vanilla culture before save. Without this, the serializer writes
            // unknown culture IDs that crash the game on reload.
            try
            {
                var behavior = EncyclopediaEditBehavior.Instance;
                if (behavior == null) return;

                var heroSnapshot = new List<KeyValuePair<Hero, CultureObject>>();

                void CheckHero(Hero hero)
                {
                    if (hero == null) return;
                    string cultureId = behavior.GetCustomCulture(hero.StringId);
                    if (string.IsNullOrEmpty(cultureId)) return;

                    // Only sanitize if this is a custom culture definition (has troop tree),
                    // not just a vanilla culture reassignment
                    if (!CustomCultureManager.HasRegisteredCulture(cultureId)) return;

                    string origId = behavior.GetOriginalCulture(hero.StringId);
                    if (string.IsNullOrEmpty(origId)) return;

                    // Find the original vanilla culture
                    CultureObject origCulture = null;
                    try
                    {
                        foreach (var culture in TaleWorlds.ObjectSystem.MBObjectManager.Instance.GetObjectTypeList<CultureObject>())
                        {
                            if (culture != null && culture.StringId == origId)
                            {
                                origCulture = culture;
                                break;
                            }
                        }
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: looking up original culture object failed: " + ex.ToString()); }

                    if (origCulture == null) return;

                    var currentCulture = hero.Culture;
                    if (currentCulture != null && currentCulture != origCulture)
                    {
                        heroSnapshot.Add(new KeyValuePair<Hero, CultureObject>(hero, currentCulture));
                        SetHeroCulture(hero, origCulture);
                    }
                }

                foreach (var hero in Hero.AllAliveHeroes) CheckHero(hero);
                foreach (var hero in Hero.DeadOrDisabledHeroes) CheckHero(hero);

                if (heroSnapshot.Count > 0)
                {
                    _sanitizedHeroSnapshot = heroSnapshot;
                    MCMSettings.DebugLog("SaveSanitizerPatch.Prefix: sanitized " + heroSnapshot.Count + " hero cultures before save");
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("SaveSanitizerPatch.Prefix (heroes) failed: " + ex.ToString());
            }
        }

        /// <summary>
        /// Runs AFTER the save completes (even if it throws).
        /// Re-applies custom cultures to all sanitized settlements.
        /// </summary>
        static Exception SaveFinalizer(Exception __exception)
        {
            // ── Restore SETTLEMENT cultures ──
            try
            {
                var snapshot = _sanitizedSnapshot;
                _sanitizedSnapshot = null;
                if (snapshot != null && snapshot.Count > 0)
                {
                    foreach (var kvp in snapshot)
                    {
                        try { kvp.Key.Culture = kvp.Value; } catch (Exception ex) { MCMSettings.DebugLog("Patches: kvp.Key.Culture = kvp.Value; failed: " + ex.ToString()); }
                    }
                    MCMSettings.DebugLog("SaveSanitizerPatch.Finalizer: restored " + snapshot.Count + " settlements after save");
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("SaveSanitizerPatch.Finalizer (settlements) failed: " + ex.ToString());
            }

            // ── Restore HERO cultures ──
            try
            {
                var heroSnapshot = _sanitizedHeroSnapshot;
                _sanitizedHeroSnapshot = null;
                if (heroSnapshot != null && heroSnapshot.Count > 0)
                {
                    foreach (var kvp in heroSnapshot)
                    {
                        try { SetHeroCulture(kvp.Key, kvp.Value); } catch (Exception ex) { MCMSettings.DebugLog("Patches: SetHeroCulture(kvp.Key, kvp.Value); failed: " + ex.ToString()); }
                    }
                    MCMSettings.DebugLog("SaveSanitizerPatch.Finalizer: restored " + heroSnapshot.Count + " hero cultures after save");
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("SaveSanitizerPatch.Finalizer (heroes) failed: " + ex.ToString());
            }

            return __exception;
        }

        /// <summary>
        /// Clears all tracking (call on new game / session change).
        /// </summary>
        internal static void ClearTracking()
        {
            OriginalSettlementCultures.Clear();
            _sanitizedSnapshot = null;
            _sanitizedHeroSnapshot = null;
        }
    }

    // ============================================
    //  Settlement Tooltip — inject Culture line into the campaign map hover tooltip.
    //  Patches the settlement tooltip handler (CampaignUIHelper or similar) to add
    //  a "Culture" property showing the settlement's current culture name.
    // ============================================
    public static class SettlementTooltipCulturePatch
    {
        private static Type _tooltipPropertyType;
        private static System.Reflection.ConstructorInfo _tooltipPropertyCtor;
        private static System.Reflection.PropertyInfo _vmTooltipPropertyListProp;

        // Captured by InformationManager.ShowTooltip interception
        private static Settlement _lastShownSettlement;
        private static MobileParty _lastShownParty;
        private static Clan _lastShownClan;
        private static Kingdom _lastShownKingdom;
        private static bool _injectCultureLogDone; // one-time log for successful injection

        internal static bool TryApply(Harmony harmony)
        {
            try
            {
                var flags = System.Reflection.BindingFlags.Static
                          | System.Reflection.BindingFlags.Instance
                          | System.Reflection.BindingFlags.Public
                          | System.Reflection.BindingFlags.NonPublic;

                // ═══ Phase 1: Discover key types ═══
                // The main settlement hover tooltip is built via PropertyBasedTooltipVM.
                // Call chain: PropertyBasedTooltipVM.Tick() → Refresh()
                //   → PropertyBasedTooltipVMExtensions.UpdateTooltip(vm, ...)
                // The property list is bound as "TooltipPropertyList" on the VM.

                Type tooltipVMType = null;   // PropertyBasedTooltipVM
                Type extensionsType = null;  // PropertyBasedTooltipVMExtensions

                foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                {
                    string asmName = asm.GetName().Name ?? "";
                    if (!asmName.Contains("TaleWorlds") && !asmName.Contains("SandBox")) continue;
                    try
                    {
                        foreach (var type in asm.GetTypes())
                        {
                            if (_tooltipPropertyType == null && type.Name == "TooltipProperty"
                                && type.Namespace != null && type.Namespace.Contains("Information"))
                                _tooltipPropertyType = type;
                            if (tooltipVMType == null && type.Name == "PropertyBasedTooltipVM")
                                tooltipVMType = type;
                            if (extensionsType == null && type.Name == "PropertyBasedTooltipVMExtensions")
                                extensionsType = type;
                        }
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: tooltip type discovery assembly scan failed: " + ex.ToString()); }
                }

                // Fallback: find TooltipProperty by name alone if namespace filter missed it
                if (_tooltipPropertyType == null)
                {
                    foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                    {
                        if (_tooltipPropertyType != null) break;
                        try
                        {
                            foreach (var type in asm.GetTypes())
                            {
                                if (type.Name == "TooltipProperty" && !type.IsInterface)
                                { _tooltipPropertyType = type; break; }
                            }
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: TooltipProperty type fallback scan failed: " + ex.ToString()); }
                    }
                }

                MCMSettings.DebugLog("SettlementTooltipCulturePatch: TooltipProperty="
                    + (_tooltipPropertyType?.FullName ?? "NOT FOUND")
                    + " PropertyBasedTooltipVM=" + (tooltipVMType?.FullName ?? "NOT FOUND")
                    + " Extensions=" + (extensionsType?.FullName ?? "NOT FOUND"));

                // Find TooltipProperty constructor
                if (_tooltipPropertyType != null)
                {
                    foreach (var ctor in _tooltipPropertyType.GetConstructors())
                    {
                        var cp = ctor.GetParameters();
                        if (cp.Length >= 2
                            && cp[0].ParameterType == typeof(string)
                            && cp[1].ParameterType == typeof(string))
                        {
                            _tooltipPropertyCtor = ctor;
                            break;
                        }
                    }
                }

                if (_tooltipPropertyCtor == null)
                {
                    MCMSettings.DebugLog("SettlementTooltipCulturePatch: no suitable TooltipProperty ctor");
                    return false;
                }

                {
                    var ctorParams = _tooltipPropertyCtor.GetParameters();
                    var sigSb = new System.Text.StringBuilder();
                    foreach (var p in ctorParams)
                    {
                        if (sigSb.Length > 0) sigSb.Append(", ");
                        sigSb.Append(p.ParameterType.Name).Append(" ").Append(p.Name);
                        if (p.HasDefaultValue) sigSb.Append("=").Append(p.DefaultValue ?? "null");
                    }
                    MCMSettings.DebugLog("SettlementTooltipCulturePatch: ctor(" + ctorParams.Length + "): " + sigSb);
                }

                // Find TooltipPropertyList on PropertyBasedTooltipVM
                if (tooltipVMType != null)
                {
                    _vmTooltipPropertyListProp = tooltipVMType.GetProperty("TooltipPropertyList", flags);
                    if (_vmTooltipPropertyListProp == null)
                    {
                        // Search all properties for one containing TooltipProperty items
                        foreach (var prop in tooltipVMType.GetProperties(flags))
                        {
                            if (prop.PropertyType.IsGenericType)
                            {
                                var itemTypes = prop.PropertyType.GetGenericArguments();
                                if (itemTypes.Length > 0 && itemTypes[0] == _tooltipPropertyType)
                                { _vmTooltipPropertyListProp = prop; break; }
                            }
                        }
                    }
                    MCMSettings.DebugLog("SettlementTooltipCulturePatch: VM TooltipPropertyList="
                        + (_vmTooltipPropertyListProp?.Name ?? "NOT FOUND")
                        + " type=" + (_vmTooltipPropertyListProp?.PropertyType?.Name ?? "?"));
                }

                // ═══ Phase 2: Find the settlement tooltip refresh method ═══

                // Strategy A: PropertyBasedTooltipVMExtensions.UpdateTooltip overload
                // that takes (PropertyBasedTooltipVM, Settlement) or processes Settlement.
                if (extensionsType != null)
                {
                    MCMSettings.DebugLog("SettlementTooltipCulturePatch: scanning Extensions methods:");
                    System.Reflection.MethodInfo settlementOverload = null;
                    System.Reflection.MethodInfo genericOverload = null;

                    foreach (var method in extensionsType.GetMethods(flags))
                    {
                        if (method.Name != "UpdateTooltip") continue;
                        var parms = method.GetParameters();
                        var psigSb = new System.Text.StringBuilder();
                        foreach (var p in parms)
                        {
                            if (psigSb.Length > 0) psigSb.Append(", ");
                            psigSb.Append(p.ParameterType.Name).Append(" ").Append(p.Name);
                        }
                        MCMSettings.DebugLog("  UpdateTooltip(" + psigSb + ")");

                        // Look for Settlement-specific overload
                        foreach (var p in parms)
                        {
                            if (p.ParameterType == typeof(Settlement))
                            { settlementOverload = method; break; }
                        }

                        // Also track generic overload (takes Type param)
                        foreach (var p in parms)
                        {
                            if (p.ParameterType == typeof(Type))
                            { genericOverload = method; break; }
                        }
                    }

                    // Prefer Settlement-specific, fall back to generic
                    var target = settlementOverload ?? genericOverload;
                    if (target != null)
                    {
                        bool isSettlementSpecific = (target == settlementOverload);
                        string postfixName = isSettlementSpecific
                            ? "ExtensionSettlementPostfix"
                            : "ExtensionGenericPostfix";

                        MCMSettings.DebugLog("SettlementTooltipCulturePatch: patching Extensions."
                            + target.Name + " (" + (isSettlementSpecific ? "settlement-specific" : "generic") + ")");

                        var postfix = typeof(SettlementTooltipCulturePatch).GetMethod(postfixName,
                            System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic);
                        harmony.Patch(target, postfix: new HarmonyMethod(postfix));
                        return true;
                    }
                }

                // Strategy B: Dual-patch approach
                // 1) Patch InformationManager.ShowTooltip to capture Settlement references
                // 2) Patch PropertyBasedTooltipVM.Refresh() postfix to inject Culture line

                // Step B1: Find and patch InformationManager.ShowTooltip
                bool showTooltipPatched = false;
                Type infoManagerType = null;
                foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                {
                    string asmName = asm.GetName().Name ?? "";
                    if (!asmName.Contains("TaleWorlds")) continue;
                    try
                    {
                        foreach (var type in asm.GetTypes())
                        {
                            if (type.Name == "InformationManager"
                                && (type.Namespace == null || type.Namespace.Contains("TaleWorlds")))
                            {
                                infoManagerType = type;
                                break;
                            }
                        }
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: InformationManager type scan failed: " + ex.ToString()); }
                    if (infoManagerType != null) break;
                }

                if (infoManagerType != null)
                {
                    MCMSettings.DebugLog("SettlementTooltipCulturePatch: found " + infoManagerType.FullName);

                    // Find ShowTooltip method(s) — look for one taking (Type, object[]) params
                    System.Reflection.MethodInfo showTooltipMethod = null;
                    foreach (var method in infoManagerType.GetMethods(flags))
                    {
                        if (method.Name != "ShowTooltip") continue;
                        var parms = method.GetParameters();
                        var psigSb = new System.Text.StringBuilder();
                        foreach (var p in parms)
                        {
                            if (psigSb.Length > 0) psigSb.Append(", ");
                            psigSb.Append(p.ParameterType.Name).Append(" ").Append(p.Name);
                        }
                        MCMSettings.DebugLog("  ShowTooltip(" + psigSb + ")");

                        if (parms.Length >= 1 && parms[0].ParameterType == typeof(Type))
                        {
                            showTooltipMethod = method;
                            // Keep scanning to log all overloads, but use first Type-taking one
                        }
                    }

                    if (showTooltipMethod != null)
                    {
                        var prefix = typeof(SettlementTooltipCulturePatch).GetMethod("ShowTooltipPrefix",
                            System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic);
                        harmony.Patch(showTooltipMethod, prefix: new HarmonyMethod(prefix));
                        showTooltipPatched = true;
                        MCMSettings.DebugLog("SettlementTooltipCulturePatch: patched InformationManager.ShowTooltip");
                    }

                    // Also try to patch HideTooltip to clear the captured settlement
                    var hideMethod = infoManagerType.GetMethod("HideTooltip", flags);
                    if (hideMethod != null)
                    {
                        var prefix = typeof(SettlementTooltipCulturePatch).GetMethod("HideTooltipPrefix",
                            System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic);
                        harmony.Patch(hideMethod, prefix: new HarmonyMethod(prefix));
                        MCMSettings.DebugLog("SettlementTooltipCulturePatch: patched InformationManager.HideTooltip");
                    }
                }
                else
                {
                    MCMSettings.DebugLog("SettlementTooltipCulturePatch: InformationManager NOT FOUND");
                }

                // Step B2: Patch PropertyBasedTooltipVM.Refresh()
                if (tooltipVMType != null)
                {
                    var refreshMethod = tooltipVMType.GetMethod("Refresh", flags);
                    if (refreshMethod == null)
                    {
                        foreach (var method in tooltipVMType.GetMethods(flags))
                        {
                            if (method.Name == "RefreshValues" || method.Name == "RefreshData"
                                || method.Name == "OnRefresh")
                            {
                                refreshMethod = method;
                                break;
                            }
                        }
                    }

                    if (refreshMethod != null)
                    {
                        MCMSettings.DebugLog("SettlementTooltipCulturePatch: patching VM."
                            + refreshMethod.Name + " (Refresh strategy)");

                        var postfix = typeof(SettlementTooltipCulturePatch).GetMethod("VMRefreshPostfix",
                            System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic);
                        harmony.Patch(refreshMethod, postfix: new HarmonyMethod(postfix));
                        return true;
                    }
                    else
                    {
                        var methodDumpSb = new System.Text.StringBuilder();
                        foreach (var m in tooltipVMType.GetMethods(flags))
                        {
                            if (m.DeclaringType == tooltipVMType)
                                methodDumpSb.Append(m.Name).Append("(").Append(m.GetParameters().Length).Append("), ");
                        }
                        MCMSettings.DebugLog("SettlementTooltipCulturePatch: no Refresh on VM. Methods: " + methodDumpSb);
                    }
                }

                if (showTooltipPatched)
                {
                    MCMSettings.DebugLog("SettlementTooltipCulturePatch: ShowTooltip patched but no VM.Refresh found — partial");
                    return true;
                }

                MCMSettings.DebugLog("SettlementTooltipCulturePatch: all strategies failed");
                return false;
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("SettlementTooltipCulturePatch failed: " + ex.ToString());
                return false;
            }
        }

        /// <summary>
        /// Creates a TooltipProperty instance using the discovered constructor.
        /// Fills all parameters beyond the first two strings with their default values.
        /// </summary>
        private static object CreateTooltipProperty(string label, string value)
        {
            if (_tooltipPropertyCtor == null) return null;
            try
            {
                var ctorParams = _tooltipPropertyCtor.GetParameters();
                var args = new object[ctorParams.Length];
                args[0] = label;
                args[1] = value;
                for (int i = 2; i < ctorParams.Length; i++)
                {
                    if (ctorParams[i].HasDefaultValue)
                        args[i] = ctorParams[i].DefaultValue;
                    else
                        args[i] = ctorParams[i].ParameterType.IsValueType
                            ? Activator.CreateInstance(ctorParams[i].ParameterType)
                            : null;
                }
                return _tooltipPropertyCtor.Invoke(args);
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("CreateTooltipProperty failed: " + ex.ToString());
                return null;
            }
        }

        /// <summary>
        /// Gets the culture display name for a settlement — uses custom culture name
        /// if one is set, otherwise falls back to the settlement's current Culture.Name.
        /// </summary>
        private static string GetCultureDisplayName(Settlement settlement)
        {
            try
            {
                if (settlement == null) return null;

                // First: check if the settlement's owner has a custom culture display name
                // (this is the authoritative source for mod-assigned cultures)
                string ownerId = settlement.OwnerClan?.Leader?.StringId;
                if (!string.IsNullOrEmpty(ownerId))
                {
                    var behavior = EncyclopediaEditBehavior.Instance;
                    if (behavior != null)
                    {
                        string customDisplayName = behavior.GetCustomCultureDisplayName(ownerId);
                        if (!string.IsNullOrEmpty(customDisplayName))
                            return customDisplayName;
                    }
                }

                // Fallback: use the settlement's Culture.Name
                if (settlement.Culture == null) return null;

                string cultureName = settlement.Culture.Name?.ToString();
                if (!string.IsNullOrEmpty(cultureName))
                    return cultureName;

                // Last resort: StringId
                return settlement.Culture.StringId;
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("GetCultureDisplayName exception: " + ex.ToString());
                return null;
            }
        }

        /// <summary>
        /// Gets the tags for a settlement from the edit behavior.
        /// </summary>
        private static string GetSettlementTags(Settlement settlement)
        {
            try
            {
                if (settlement == null) return null;
                var behavior = EncyclopediaEditBehavior.Instance;
                if (behavior == null) return null;
                return behavior.GetTags(settlement.StringId);
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: GetSettlementTags exception: " + ex.ToString()); return null; }
        }

        /// <summary>
        /// Injects a "Tags" property into the tooltip list after "Culture" (or at end).
        /// </summary>
        private static void InjectTagsIntoList(object listObj, Settlement settlement)
        {
            if (listObj == null || settlement == null || _tooltipPropertyCtor == null) return;

            string tags = GetSettlementTags(settlement);
            if (string.IsNullOrEmpty(tags)) return;

            System.Collections.IList ilist = listObj as System.Collections.IList;
            System.Reflection.PropertyInfo countProp = null;
            System.Reflection.MethodInfo addMethod = null;
            System.Reflection.MethodInfo insertMethod = null;
            System.Reflection.PropertyInfo indexerProp = null;

            int listCount = 0;
            if (ilist != null)
            {
                listCount = ilist.Count;
            }
            else
            {
                var listType = listObj.GetType();
                countProp = listType.GetProperty("Count");
                if (countProp == null) return;
                listCount = (int)countProp.GetValue(listObj);
                addMethod = listType.GetMethod("Add");
                insertMethod = listType.GetMethod("Insert");
                indexerProp = listType.GetProperty("Item");
            }

            var defLabelProp = _tooltipPropertyType.GetProperty("DefinitionLabel")
                           ?? _tooltipPropertyType.GetProperty("PropertyName")
                           ?? _tooltipPropertyType.GetProperty("Definition");

            int insertIdx = -1;
            if (defLabelProp != null)
            {
                for (int i = 0; i < listCount; i++)
                {
                    object item;
                    if (ilist != null)
                        item = ilist[i];
                    else if (indexerProp != null)
                        item = indexerProp.GetValue(listObj, new object[] { i });
                    else
                        break;

                    string label = defLabelProp.GetValue(item)?.ToString() ?? "";
                    if (label == "Tags") return; // Already there
                    if (label == "Culture")
                        insertIdx = i + 1;
                }
            }

            object tagsProperty = CreateTooltipProperty("Tags", tags);
            if (tagsProperty == null) return;

            if (insertIdx >= 0 && insertIdx <= listCount)
            {
                if (ilist != null)
                    ilist.Insert(insertIdx, tagsProperty);
                else if (insertMethod != null)
                    insertMethod.Invoke(listObj, new object[] { insertIdx, tagsProperty });
                else if (addMethod != null)
                    addMethod.Invoke(listObj, new object[] { tagsProperty });
            }
            else
            {
                if (ilist != null)
                    ilist.Add(tagsProperty);
                else if (addMethod != null)
                    addMethod.Invoke(listObj, new object[] { tagsProperty });
            }
        }

        /// <summary>
        /// Injects a "Tags" property into the party tooltip list.
        /// Uses the party leader's hero tags if available.
        /// </summary>
        private static void InjectTagsIntoPartyList(object listObj, MobileParty party)
        {
            if (listObj == null || party == null || _tooltipPropertyCtor == null) return;

            // Try leader hero tags first, then clan tags
            string tags = null;
            var behavior = EncyclopediaEditBehavior.Instance;
            if (behavior == null) return;

            if (party.LeaderHero != null)
                tags = behavior.GetTagsWithAuto(party.LeaderHero.StringId);
            if (string.IsNullOrEmpty(tags) && party.Party?.Owner?.Clan != null)
                tags = behavior.GetTags(party.Party.Owner.Clan.StringId);
            if (string.IsNullOrEmpty(tags)) return;

            System.Collections.IList ilist = listObj as System.Collections.IList;
            System.Reflection.PropertyInfo countProp = null;
            System.Reflection.MethodInfo addMethod = null;
            System.Reflection.PropertyInfo indexerProp = null;

            int listCount = 0;
            if (ilist != null)
            {
                listCount = ilist.Count;
            }
            else
            {
                var listType = listObj.GetType();
                countProp = listType.GetProperty("Count");
                if (countProp == null) return;
                listCount = (int)countProp.GetValue(listObj);
                addMethod = listType.GetMethod("Add");
                indexerProp = listType.GetProperty("Item");
            }

            // Check for duplicate
            var defLabelProp = _tooltipPropertyType.GetProperty("DefinitionLabel")
                           ?? _tooltipPropertyType.GetProperty("PropertyName")
                           ?? _tooltipPropertyType.GetProperty("Definition");
            if (defLabelProp != null)
            {
                for (int i = 0; i < listCount; i++)
                {
                    object item;
                    if (ilist != null)
                        item = ilist[i];
                    else if (indexerProp != null)
                        item = indexerProp.GetValue(listObj, new object[] { i });
                    else
                        break;
                    string label = defLabelProp.GetValue(item)?.ToString() ?? "";
                    if (label == "Tags") return;
                }
            }

            object tagsProperty = CreateTooltipProperty("Tags", tags);
            if (tagsProperty == null) return;

            if (ilist != null)
                ilist.Add(tagsProperty);
            else if (addMethod != null)
                addMethod.Invoke(listObj, new object[] { tagsProperty });
        }

        /// <summary>
        /// Adds a "Culture" property to the tooltip. Accepts the raw list object
        /// (may be MBBindingList&lt;T&gt; which may or may not implement IList).
        /// </summary>
        private static void InjectCultureIntoList(object listObj, Settlement settlement)
        {
            if (listObj == null || settlement == null || _tooltipPropertyCtor == null) return;

            string cultureName = GetCultureDisplayName(settlement);
            if (string.IsNullOrEmpty(cultureName)) return;

            // Access the list via IList if possible, otherwise via reflection
            System.Collections.IList ilist = listObj as System.Collections.IList;

            // Reflection-based accessors for MBBindingList that may not implement IList
            System.Reflection.PropertyInfo countProp = null;
            System.Reflection.MethodInfo addMethod = null;
            System.Reflection.MethodInfo insertMethod = null;
            System.Reflection.PropertyInfo indexerProp = null;

            int listCount = 0;
            if (ilist != null)
            {
                listCount = ilist.Count;
            }
            else
            {
                // MBBindingList<T> doesn't implement IList — use reflection
                var listType = listObj.GetType();
                countProp = listType.GetProperty("Count");
                if (countProp == null)
                {
                    MCMSettings.DebugLog("InjectCulture: list has no Count property, type=" + listType.Name);
                    return;
                }
                listCount = (int)countProp.GetValue(listObj);

                addMethod = listType.GetMethod("Add");
                insertMethod = listType.GetMethod("Insert");
                indexerProp = listType.GetProperty("Item");

            }

            // Check if Culture is already present (avoid duplicates on repeated Refresh)
            var defLabelProp = _tooltipPropertyType.GetProperty("DefinitionLabel")
                           ?? _tooltipPropertyType.GetProperty("PropertyName")
                           ?? _tooltipPropertyType.GetProperty("Definition");

            int insertIdx = -1;
            if (defLabelProp != null)
            {
                for (int i = 0; i < listCount; i++)
                {
                    object item;
                    if (ilist != null)
                        item = ilist[i];
                    else if (indexerProp != null)
                        item = indexerProp.GetValue(listObj, new object[] { i });
                    else
                        break;

                    string label = defLabelProp.GetValue(item)?.ToString() ?? "";
                    if (label == "Culture") return; // Already there
                    if (label.IndexOf("Faction", StringComparison.OrdinalIgnoreCase) >= 0)
                        insertIdx = i + 1;
                }
            }

            object cultureProperty = CreateTooltipProperty("Culture", cultureName);
            if (cultureProperty == null)
            {
                MCMSettings.DebugLog("InjectCulture: CreateTooltipProperty returned null");
                return;
            }

            // Insert or add
            if (insertIdx >= 0 && insertIdx <= listCount)
            {
                if (ilist != null)
                    ilist.Insert(insertIdx, cultureProperty);
                else if (insertMethod != null)
                    insertMethod.Invoke(listObj, new object[] { insertIdx, cultureProperty });
                else if (addMethod != null)
                    addMethod.Invoke(listObj, new object[] { cultureProperty });
            }
            else
            {
                if (ilist != null)
                    ilist.Add(cultureProperty);
                else if (addMethod != null)
                    addMethod.Invoke(listObj, new object[] { cultureProperty });
            }

            // Log only once to avoid spam (Refresh is called every 2 seconds)
            if (!_injectCultureLogDone)
            {
                _injectCultureLogDone = true;
                int newCount = ilist?.Count ?? (int)(countProp?.GetValue(listObj) ?? 0);
                MCMSettings.DebugLog("InjectCulture: added '" + cultureName + "' to tooltip at idx="
                    + insertIdx + " (list has " + newCount + " items)");
            }
        }

        /// <summary>
        /// Strategy A1: Postfix for PropertyBasedTooltipVMExtensions.UpdateTooltip(VM, Settlement).
        /// The Settlement-specific overload — we have direct access to the VM and Settlement.
        /// </summary>
        static void ExtensionSettlementPostfix(object[] __args)
        {
            try
            {
                if (__args == null || __args.Length < 2) return;

                object vm = __args[0];
                Settlement settlement = null;
                for (int i = 1; i < __args.Length; i++)
                {
                    if (__args[i] is Settlement s) { settlement = s; break; }
                }
                if (settlement == null || vm == null) return;

                var list = _vmTooltipPropertyListProp?.GetValue(vm);
                InjectCultureIntoList(list, settlement);
                InjectTagsIntoList(list, settlement);
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("ExtensionSettlementPostfix: " + ex.ToString());
            }
        }

        /// <summary>
        /// Strategy A2: Postfix for PropertyBasedTooltipVMExtensions.UpdateTooltip(VM, Type, object[]).
        /// The generic dispatcher — we check if Type == typeof(Settlement).
        /// </summary>
        static void ExtensionGenericPostfix(object[] __args)
        {
            try
            {
                if (__args == null || __args.Length < 2) return;

                object vm = __args[0];
                Type tooltipType = null;
                Settlement settlement = null;
                MobileParty party = null;

                for (int i = 1; i < __args.Length; i++)
                {
                    if (__args[i] is Type t) tooltipType = t;
                    else if (__args[i] is Settlement s) settlement = s;
                    else if (__args[i] is MobileParty mp) party = mp;
                    else if (__args[i] is object[] innerArgs)
                    {
                        foreach (var inner in innerArgs)
                        {
                            if (inner is Settlement s2) { settlement = s2; break; }
                            if (inner is MobileParty mp2) { party = mp2; break; }
                        }
                    }
                }

                if (vm == null) return;
                var list = _vmTooltipPropertyListProp?.GetValue(vm);

                if (tooltipType == typeof(Settlement) && settlement != null)
                {
                    InjectCultureIntoList(list, settlement);
                    InjectTagsIntoList(list, settlement);
                }
                else if (tooltipType == typeof(MobileParty) && party != null)
                {
                    InjectTagsIntoPartyList(list, party);
                }

                // Also check for Clan and Kingdom in the args
                Clan clan = null;
                Kingdom kingdom = null;
                for (int i = 1; i < __args.Length; i++)
                {
                    if (__args[i] is Clan c) clan = c;
                    else if (__args[i] is Kingdom k) kingdom = k;
                    else if (__args[i] is object[] innerArgs2)
                    {
                        foreach (var inner in innerArgs2)
                        {
                            if (inner is Clan c2) { clan = c2; break; }
                            if (inner is Kingdom k2) { kingdom = k2; break; }
                        }
                    }
                }
                if (tooltipType == typeof(Clan) && clan != null)
                    InjectTagsIntoGenericList(list, clan.StringId);
                else if (tooltipType == typeof(Kingdom) && kingdom != null)
                    InjectTagsIntoGenericList(list, kingdom.StringId);
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("ExtensionGenericPostfix: " + ex.ToString());
            }
        }

        /// <summary>
        /// Prefix for InformationManager.ShowTooltip — captures the Settlement reference
        /// when a settlement tooltip is being opened. The first parameter is a Type
        /// (the tooltip subject type), and the rest are params object[] args.
        /// </summary>
        static void ShowTooltipPrefix(Type __0, object[] __1)
        {
            try
            {
                _lastShownSettlement = null;
                _lastShownParty = null;
                _lastShownClan = null;
                _lastShownKingdom = null;

                if (__0 == typeof(Settlement))
                {
                    if (__1 != null)
                    {
                        foreach (var arg in __1)
                        {
                            if (arg is Settlement s) { _lastShownSettlement = s; break; }
                        }
                    }
                }
                else if (__0 == typeof(MobileParty))
                {
                    if (__1 != null)
                    {
                        foreach (var arg in __1)
                        {
                            if (arg is MobileParty mp) { _lastShownParty = mp; break; }
                        }
                    }
                }
                else if (__0 == typeof(Clan))
                {
                    if (__1 != null)
                    {
                        foreach (var arg in __1)
                        {
                            if (arg is Clan c) { _lastShownClan = c; break; }
                        }
                    }
                }
                else if (__0 == typeof(Kingdom))
                {
                    if (__1 != null)
                    {
                        foreach (var arg in __1)
                        {
                            if (arg is Kingdom k) { _lastShownKingdom = k; break; }
                        }
                    }
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: ShowTooltipPrefix exception: " + ex.ToString()); }
        }

        /// <summary>
        /// Prefix for InformationManager.HideTooltip — clears the captured settlement.
        /// </summary>
        static void HideTooltipPrefix()
        {
            _lastShownSettlement = null;
            _lastShownParty = null;
            _lastShownClan = null;
            _lastShownKingdom = null;
        }

        /// <summary>
        /// Strategy B: Postfix for PropertyBasedTooltipVM.Refresh().
        /// Uses the Settlement captured by ShowTooltipPrefix to inject Culture line.
        /// Also performs a one-time diagnostic dump of all VM fields for debugging.
        /// </summary>
        static void VMRefreshPostfix(object __instance)
        {
            try
            {
                if (__instance == null) return;

                var instType = __instance.GetType();
                var bflags = System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance
                          | System.Reflection.BindingFlags.Public;

                // Use the Settlement/Party captured by ShowTooltipPrefix
                var settlement = _lastShownSettlement;
                var party = _lastShownParty;

                // Fallback: try reading _invokedType and _invokedArgs directly from the VM
                if (settlement == null && party == null)
                {
                    var invokedTypeField = instType.GetField("_invokedType", bflags);
                    if (invokedTypeField != null)
                    {
                        var invType = invokedTypeField.GetValue(__instance) as Type;
                        var invokedArgsField = instType.GetField("_invokedArgs", bflags);
                        object[] invArgs = null;
                        if (invokedArgsField != null)
                            invArgs = invokedArgsField.GetValue(__instance) as object[];

                        if (invType == typeof(Settlement) && invArgs != null)
                        {
                            foreach (var a in invArgs)
                            {
                                if (a is Settlement s) { settlement = s; break; }
                            }
                        }
                        else if (invType == typeof(MobileParty) && invArgs != null)
                        {
                            foreach (var a in invArgs)
                            {
                                if (a is MobileParty mp) { party = mp; break; }
                            }
                        }
                    }
                }

                // Also try Clan and Kingdom
                var clan = _lastShownClan;
                var kingdom = _lastShownKingdom;
                if (clan == null && kingdom == null)
                {
                    var invokedTypeField2 = instType.GetField("_invokedType", bflags);
                    if (invokedTypeField2 != null)
                    {
                        var invType2 = invokedTypeField2.GetValue(__instance) as Type;
                        var invokedArgsField2 = instType.GetField("_invokedArgs", bflags);
                        object[] invArgs2 = invokedArgsField2?.GetValue(__instance) as object[];
                        if (invType2 == typeof(Clan) && invArgs2 != null)
                        {
                            foreach (var a in invArgs2)
                                if (a is Clan c) { clan = c; break; }
                        }
                        else if (invType2 == typeof(Kingdom) && invArgs2 != null)
                        {
                            foreach (var a in invArgs2)
                                if (a is Kingdom k) { kingdom = k; break; }
                        }
                    }
                }

                var list = _vmTooltipPropertyListProp?.GetValue(__instance);

                if (settlement != null)
                {
                    InjectCultureIntoList(list, settlement);
                    InjectTagsIntoList(list, settlement);
                }
                else if (party != null)
                {
                    InjectTagsIntoPartyList(list, party);
                }
                else if (clan != null)
                {
                    InjectTagsIntoGenericList(list, clan.StringId);
                }
                else if (kingdom != null)
                {
                    InjectTagsIntoGenericList(list, kingdom.StringId);
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("VMRefreshPostfix: " + ex.ToString());
            }
        }

        /// <summary>
        /// Injects a "Tags" property into any tooltip list using a generic object ID.
        /// Used for Clan and Kingdom tooltips.
        /// </summary>
        private static void InjectTagsIntoGenericList(object listObj, string objectId)
        {
            if (listObj == null || string.IsNullOrEmpty(objectId) || _tooltipPropertyCtor == null) return;

            var behavior = EncyclopediaEditBehavior.Instance;
            if (behavior == null) return;

            string tags = behavior.GetTagsWithAuto(objectId);
            if (string.IsNullOrEmpty(tags)) return;

            System.Collections.IList ilist = listObj as System.Collections.IList;
            System.Reflection.MethodInfo addMethod = null;
            System.Reflection.PropertyInfo indexerProp = null;

            int listCount = 0;
            if (ilist != null)
            {
                listCount = ilist.Count;
            }
            else
            {
                var listType = listObj.GetType();
                var countProp = listType.GetProperty("Count");
                if (countProp == null) return;
                listCount = (int)countProp.GetValue(listObj);
                addMethod = listType.GetMethod("Add");
                indexerProp = listType.GetProperty("Item");
            }

            // Check for duplicate
            var defLabelProp = _tooltipPropertyType.GetProperty("DefinitionLabel")
                           ?? _tooltipPropertyType.GetProperty("PropertyName")
                           ?? _tooltipPropertyType.GetProperty("Definition");
            if (defLabelProp != null)
            {
                for (int i = 0; i < listCount; i++)
                {
                    object item;
                    if (ilist != null) item = ilist[i];
                    else if (indexerProp != null) item = indexerProp.GetValue(listObj, new object[] { i });
                    else break;
                    string label = defLabelProp.GetValue(item)?.ToString() ?? "";
                    if (label == "Tags") return;
                }
            }

            object tagsProperty = CreateTooltipProperty("Tags", tags);
            if (tagsProperty == null) return;

            if (ilist != null)
                ilist.Add(tagsProperty);
            else if (addMethod != null)
                addMethod.Invoke(listObj, new object[] { tagsProperty });
        }
    }

    // ============================================
    //  Occupation Edit Popup (Ctrl+O) — Hero pages only
    // ============================================
    public static class EncyclopediaOccupationEditPopup
    {
        private static volatile bool _popupOpen = false;
        public static bool IsPopupOpen => _popupOpen;

        // Dynamically discovered occupation names (populated once on first use)
        private static string[] _occupationNames;
        private static string[] OccupationNames
        {
            get
            {
                if (_occupationNames == null)
                    _occupationNames = DiscoverOccupationNames();
                return _occupationNames;
            }
        }

        /// <summary>
        /// Dynamically discovers all Occupation enum values at runtime.
        /// Falls back to a known list if enum discovery fails.
        /// </summary>
        private static string[] DiscoverOccupationNames()
        {
            try
            {
                var names = Enum.GetNames(typeof(Occupation));
                if (names != null && names.Length > 0)
                {
                    // Filter out meta/internal entries that aren't real occupations
                    var filtered = new System.Collections.Generic.List<string>();
                    foreach (var n in names)
                    {
                        if (n == "Custom" || n == "NotAssigned" || n == "NumberOfOccupations")
                            continue;
                        filtered.Add(n);
                    }
                    MCMSettings.DebugLog("Discovered " + filtered.Count + " occupation enum values dynamically (filtered from " + names.Length + ")");
                    return filtered.ToArray();
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Occupation enum discovery failed: " + ex.ToString());
            }

            // Fallback to known list
            MCMSettings.DebugLog("Using fallback occupation list");
            return new string[]
            {
                "Lord", "Wanderer", "GangLeader", "Merchant",
                "Artisan", "Preacher", "Headman", "RuralNotable", "PrisonGuard",
                "Guard", "Blacksmith", "Weaponsmith", "Armorer", "HorseTrader",
                "Tavernkeeper", "RansomBroker", "Townsfolk", "Villager"
            };
        }

        /// <summary>
        /// Returns a user-friendly display name for an occupation enum name.
        /// E.g., "GangLeader" → "Gang Leader", "RuralNotable" → "Rural Notable".
        /// </summary>
        public static string GetFriendlyName(string enumName)
        {
            if (string.IsNullOrEmpty(enumName)) return enumName;

            // Check localization first (allows translation overrides)
            string locKey = "occupation_name_" + enumName;
            string localized = Localization.L(locKey);
            if (localized != locKey) // L() returns the key itself if not found
                return localized;

            // Auto-format: insert spaces before uppercase letters
            // "GangLeader" → "Gang Leader", "RuralNotable" → "Rural Notable"
            var sb = new System.Text.StringBuilder(enumName.Length + 4);
            for (int i = 0; i < enumName.Length; i++)
            {
                char c = enumName[i];
                if (i > 0 && char.IsUpper(c) && !char.IsUpper(enumName[i - 1]))
                    sb.Append(' ');
                sb.Append(c);
            }
            return sb.ToString();
        }

        /// <summary>
        /// Returns a user-friendly display name for an occupation int value.
        /// </summary>
        public static string GetFriendlyName(int occupationValue)
        {
            try
            {
                string enumName = ((Occupation)occupationValue).ToString();
                return GetFriendlyName(enumName);
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Patches: GetFriendlyName exception: " + ex.ToString());
                return "Unknown (" + occupationValue + ")";
            }
        }

        public static void TryOpen()
        {
            if (_popupOpen) return;
            if (EncyclopediaEditBehavior.Instance == null) return;
            if (string.IsNullOrEmpty(EncyclopediaPageTracker.CurrentObjectId)) return;

            if (EncyclopediaPageTracker.CurrentPageType != "Hero")
            {
                MCMSettings.DebugLog("Ctrl+O ignored - not a hero page (type=" + EncyclopediaPageTracker.CurrentPageType + ")");
                return;
            }

            try
            {
                var settings = MCMSettings.Instance;
                if (settings != null && !settings.EnableOccupationEditing) return;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: OccupationEditPopup settings check exception: " + ex.ToString()); }

            var hero = EncyclopediaPageTracker.CurrentHero;
            if (hero == null) return;

            EncyclopediaInputBlocker.Block();
            _popupOpen = true;
            string objectId = EncyclopediaPageTracker.CurrentObjectId;

            // Store original occupation for reset
            try
            {
                if (hero.CharacterObject != null)
                    EncyclopediaEditBehavior.Instance.StoreOriginalOccupation(objectId, (int)hero.CharacterObject.Occupation);
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: StoreOriginalOccupation exception: " + ex.ToString()); }

            // Get current occupation — check persisted value first (game may revert vanilla characters)
            string currentOccupation = "Unknown";
            int currentOccValue = -1;
            try
            {
                int persistedOcc = EncyclopediaEditBehavior.Instance.GetCustomOccupation(objectId);
                if (persistedOcc >= 0)
                {
                    currentOccupation = GetFriendlyName(persistedOcc);
                    currentOccValue = persistedOcc;
                }
                else if (hero.CharacterObject != null)
                {
                    currentOccupation = GetFriendlyName(hero.CharacterObject.Occupation.ToString());
                    currentOccValue = (int)hero.CharacterObject.Occupation;
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: GetCustomOccupation exception: " + ex.ToString()); }

            MCMSettings.DebugLog("Opening occupation edit for " + objectId + " (current=" + currentOccupation + ", value=" + currentOccValue + ")");

            // Build a list of valid occupations with friendly display names
            var validOccupations = new List<string>();
            var validOccValues = new List<int>();
            foreach (var occName in OccupationNames)
            {
                int occValue = -1;
                try
                {
                    occValue = (int)Enum.Parse(typeof(Occupation), occName);
                }
                catch (Exception ex)
                {
                    MCMSettings.DebugLog("Skipping invalid occupation enum name: " + occName + ": " + ex.ToString());
                    continue;
                }

                validOccupations.Add(GetFriendlyName(occName));
                validOccValues.Add(occValue);
            }

            // Build the occupation value map for quick lookup (friendly name → enum value)
            var occValueMap = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            for (int i = 0; i < validOccupations.Count; i++)
                occValueMap[validOccupations[i]] = validOccValues[i];

            bool hasCustomOcc = EncyclopediaEditBehavior.Instance.HasCustomOccupation(objectId);

            // Try to show clickable multi-selection list
            if (TryShowMultiSelectionOccupationList(objectId, hero, currentOccupation,
                    validOccupations, occValueMap, hasCustomOcc))
                return;

            // Fallback 2: Custom Gauntlet clickable popup
            if (SelectionPopupHelper.TryShowOccupationPopup(objectId, hero, currentOccupation,
                    validOccupations, occValueMap, hasCustomOcc,
                    () => { _popupOpen = false; }))
                return;

            // Fallback 3: paginated numbered list
            MCMSettings.DebugLog("Gauntlet popup unavailable, using numbered list input");
            ShowOccupationNumberedList(objectId, hero, currentOccupation, validOccupations, occValueMap, hasCustomOcc, 0);
        }

        private const int OccupationPageSize = 15;

        /// <summary>
        /// Shows occupations in a paginated text input dialog as a numbered list.
        /// The user types a number to select.
        /// </summary>
        private static void ShowOccupationNumberedList(string objectId, Hero hero,
            string currentOccupation, List<string> validOccupations,
            Dictionary<string, int> occValueMap, bool hasCustom, int page)
        {
            int totalPages = (validOccupations.Count + OccupationPageSize - 1) / OccupationPageSize;
            if (totalPages < 1) totalPages = 1;
            int start = page * OccupationPageSize;
            int end = Math.Min(start + OccupationPageSize, validOccupations.Count);

            var sb = new System.Text.StringBuilder();
            sb.AppendLine(Localization.L("numbered_list_occupation_header", currentOccupation));
            if (totalPages > 1)
                sb.AppendLine("(" + (page + 1) + "/" + totalPages + ")");
            sb.AppendLine();

            for (int i = start; i < end; i++)
            {
                string name = validOccupations[i];
                string marker = name == currentOccupation ? " *" : "";
                sb.AppendLine((i + 1) + ". " + name + marker);
            }

            if (page < totalPages - 1)
                sb.AppendLine("\n> " + Localization.L("numbered_list_next_hint"));
            if (page > 0)
                sb.AppendLine("> " + Localization.L("numbered_list_prev_hint"));
            if (hasCustom)
                sb.AppendLine("\n" + Localization.L("numbered_list_reset_hint"));

            EEInquiry.Show(
                new TextInquiryData(
                    Localization.L("occupation_edit_title"),
                    sb.ToString(),
                    true,
                    true,
                    Localization.L("edit_save"),
                    Localization.L("edit_cancel"),
                    delegate(string input)
                    {
                        input = (input ?? "").Trim();

                        if (string.IsNullOrEmpty(input))
                        {
                            _popupOpen = false;
                            return;
                        }

                        // Navigate pages
                        if (input.Equals("next", StringComparison.OrdinalIgnoreCase) ||
                            input.Equals("n", StringComparison.OrdinalIgnoreCase))
                        {
                            if (page < totalPages - 1)
                                ShowOccupationNumberedList(objectId, hero, currentOccupation, validOccupations, occValueMap, hasCustom, page + 1);
                            else
                                ShowOccupationNumberedList(objectId, hero, currentOccupation, validOccupations, occValueMap, hasCustom, page);
                            return;
                        }
                        if (input.Equals("prev", StringComparison.OrdinalIgnoreCase) ||
                            input.Equals("p", StringComparison.OrdinalIgnoreCase))
                        {
                            if (page > 0)
                                ShowOccupationNumberedList(objectId, hero, currentOccupation, validOccupations, occValueMap, hasCustom, page - 1);
                            else
                                ShowOccupationNumberedList(objectId, hero, currentOccupation, validOccupations, occValueMap, hasCustom, page);
                            return;
                        }

                        _popupOpen = false;

                        // Check for "0" or "reset" to reset
                        if (hasCustom && (input == "0" || input.Equals("reset", StringComparison.OrdinalIgnoreCase)))
                        {
                            ResetOccupation(objectId, hero);
                            return;
                        }

                        // Try parse as number (works across all pages)
                        int choice;
                        if (int.TryParse(input, out choice) && choice >= 1 && choice <= validOccupations.Count)
                        {
                            string occName = validOccupations[choice - 1];
                            if (occValueMap.TryGetValue(occName, out int occValue))
                                ApplyOccupation(objectId, hero, occValue);
                            return;
                        }

                        // Try match by name (case-insensitive)
                        foreach (var occName in validOccupations)
                        {
                            if (occName.Equals(input, StringComparison.OrdinalIgnoreCase))
                            {
                                if (occValueMap.TryGetValue(occName, out int occValue))
                                    ApplyOccupation(objectId, hero, occValue);
                                return;
                            }
                        }
                    },
                    delegate()
                    {
                        _popupOpen = false;
                        MCMSettings.DebugLog("Occupation numbered list cancelled for " + objectId);
                    }
                ),
                false);

            EncyclopediaNavigationGuard.ScheduleNavigateBack();
        }

        /// <summary>
        /// Shows a clickable multi-selection occupation list via reflection.
        /// Returns true if successful, false if the API is not available at runtime.
        /// </summary>
        private static bool TryShowMultiSelectionOccupationList(string objectId, Hero hero,
            string currentOccupation, List<string> validOccupations,
            Dictionary<string, int> occValueMap, bool hasCustomOcc)
        {
            try
            {
                // Find InquiryElement and MultiSelectionInquiryData types
                Type inquiryElementType = null;
                Type multiSelDataType = null;
                System.Reflection.MethodInfo showMethod = null;

                // Round 4 finding N-C2: cached scan replaces inline assembly walk.
                inquiryElementType = InquiryTypeCache.InquiryElement;
                multiSelDataType = InquiryTypeCache.MultiSelectionInquiryData;

                if (inquiryElementType == null || multiSelDataType == null)
                {
                    MCMSettings.DebugLog("Occupation MultiSelection types not found (InquiryElement=" + (inquiryElementType != null) + ", MultiSelData=" + (multiSelDataType != null) + ")");
                    return false;
                }

                // Find ShowMultiSelectionInquiry — try InformationManager first, then all assemblies
                showMethod = MultiSelectionMethodCache.Find(multiSelDataType);

                if (showMethod == null)
                {
                    MCMSettings.DebugLog("Occupation ShowMultiSelectionInquiry method not found on any type");
                    return false;
                }

                // Find InquiryElement constructor using shared helper
                var elementCtor = MultiSelectionMethodCache.FindInquiryElementCtor(inquiryElementType, out bool secondParamIsTextObject);
                if (elementCtor == null)
                    return false;

                // Build InquiryElement list
                var elementCtorParams = elementCtor.GetParameters();
                var listType = typeof(List<>).MakeGenericType(inquiryElementType);
                var elements = (System.Collections.IList)Activator.CreateInstance(listType);

                foreach (var occName in validOccupations)
                {
                    elements.Add(MultiSelectionMethodCache.CreateInquiryElement(elementCtor, elementCtorParams, secondParamIsTextObject, occName, occName));
                }

                // Add "Reset to Original" entry if the hero has a custom occupation
                if (hasCustomOcc)
                {
                    elements.Add(MultiSelectionMethodCache.CreateInquiryElement(elementCtor, elementCtorParams, secondParamIsTextObject, "__reset__", Localization.L("occupation_reset_btn")));
                }

                // Build callbacks using Expression trees
                var actionType = typeof(Action<>).MakeGenericType(listType);

                var affHandler = new OccupationSelectionHandler(objectId, hero, occValueMap);
                var affMethodInfo = typeof(OccupationSelectionHandler).GetMethod("OnOccupationSelected");
                if (affMethodInfo == null) return false;
                var affParam = System.Linq.Expressions.Expression.Parameter(listType, "elements");
                var affCall = System.Linq.Expressions.Expression.Call(
                    System.Linq.Expressions.Expression.Constant(affHandler),
                    affMethodInfo,
                    System.Linq.Expressions.Expression.Convert(affParam, typeof(object)));
                var affirmativeDelegate = System.Linq.Expressions.Expression.Lambda(actionType, affCall, affParam).Compile();

                var negHandler = new OccupationSelectionCancelHandler();
                var negMethodInfo = typeof(OccupationSelectionCancelHandler).GetMethod("OnCancel");
                if (negMethodInfo == null) return false;
                var negParam = System.Linq.Expressions.Expression.Parameter(listType, "elements");
                var negCall = System.Linq.Expressions.Expression.Call(
                    System.Linq.Expressions.Expression.Constant(negHandler),
                    negMethodInfo,
                    System.Linq.Expressions.Expression.Convert(negParam, typeof(object)));
                var negativeDelegate = System.Linq.Expressions.Expression.Lambda(actionType, negCall, negParam).Compile();

                // Find MultiSelectionInquiryData constructor — prefer the longest (newest API)
                System.Reflection.ConstructorInfo dataCtor = null;
                foreach (var ctor in multiSelDataType.GetConstructors())
                {
                    var pars = ctor.GetParameters();
                    if (pars.Length >= 8 && (dataCtor == null || pars.Length > dataCtor.GetParameters().Length))
                        dataCtor = ctor;
                }

                if (dataCtor == null)
                {
                    MCMSettings.DebugLog("Occupation MultiSelectionInquiryData constructor not found");
                    return false;
                }

                // Build MultiSelectionInquiryData dynamically based on parameter types
                string title = Localization.L("occupation_edit_title");
                string desc = Localization.L("occupation_list_select_message", currentOccupation);
                string affText = Localization.L("edit_save");
                string negText = Localization.L("edit_cancel");

                object dataObj = MultiSelectionMethodCache.BuildMultiSelectionInquiryData(
                    dataCtor, title, desc, affText, negText,
                    elements, listType, affirmativeDelegate, negativeDelegate);

                // Call ShowMultiSelectionInquiry
                var showParams = showMethod.GetParameters();
                if (showParams.Length == 1)
                    showMethod.Invoke(null, new object[] { dataObj });
                else if (showParams.Length == 2)
                    showMethod.Invoke(null, new object[] { dataObj, false });
                else
                    showMethod.Invoke(null, new object[] { dataObj, false, false });

                MCMSettings.DebugLog("Showed multi-selection occupation list with " + validOccupations.Count + " occupations");
                EncyclopediaNavigationGuard.ScheduleNavigateBack();
                return true;
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TryShowMultiSelectionOccupationList failed: " + ex.ToString());
                return false;
            }
        }

        /// <summary>
        /// Handler for multi-selection occupation list affirmative callback.
        /// </summary>
        private class OccupationSelectionHandler
        {
            private readonly string _objectId;
            private readonly Hero _hero;
            private readonly Dictionary<string, int> _occValueMap;

            public OccupationSelectionHandler(string objectId, Hero hero, Dictionary<string, int> occValueMap)
            {
                _objectId = objectId;
                _hero = hero;
                _occValueMap = occValueMap;
            }

            public void OnOccupationSelected(object selectedElements)
            {
                try
                {
                    var list = selectedElements as System.Collections.IList;
                    if (list == null || list.Count == 0)
                    {
                        MCMSettings.DebugLog("OnOccupationSelected: no items selected");
                        _popupOpen = false;
                        return;
                    }

                    var selected = list[0];
                    string selectedId = MultiSelectionMethodCache.GetInquiryElementId(selected);
                    MCMSettings.DebugLog("OnOccupationSelected: selectedId=" + (selectedId ?? "null"));

                    if (string.IsNullOrEmpty(selectedId))
                    {
                        _popupOpen = false;
                        return;
                    }

                    if (selectedId == "__reset__")
                    {
                        _popupOpen = false;
                        ResetOccupation(_objectId, _hero);
                        return;
                    }

                    _popupOpen = false;

                    if (_occValueMap.TryGetValue(selectedId, out int occValue))
                    {
                        ApplyOccupation(_objectId, _hero, occValue);
                        return;
                    }

                    MCMSettings.DebugLog("Occupation not matched from selection: " + selectedId);
                }
                catch (Exception ex)
                {
                    _popupOpen = false;
                    MCMSettings.DebugLog("OnOccupationSelected failed: " + ex.ToString());
                }
            }
        }

        /// <summary>
        /// Handler for multi-selection occupation list cancel callback.
        /// </summary>
        private class OccupationSelectionCancelHandler
        {
            public void OnCancel(object selectedElements)
            {
                _popupOpen = false;
                MCMSettings.DebugLog("Occupation multi-selection cancelled");
            }
        }

        internal static void ApplyOccupation(string objectId, Hero hero, int occupationValue)
        {
            try
            {
                if (hero.CharacterObject == null)
                {
                    MCMSettings.DebugLog("Cannot set occupation - hero has no CharacterObject");
                    return;
                }

                // NOTE: We intentionally do NOT change the actual CharacterObject.Occupation
                // or Hero.Occupation properties via reflection. Changing them to non-standard
                // values (e.g. "Preacher") causes GetListItems() to exclude the hero from
                // the encyclopedia list entirely, making them unsearchable and invisible.
                // Instead, we only persist the custom value in the behavior and display it
                // via Stats panel overrides on the detail page postfix.

                // Save to persistence
                EncyclopediaEditBehavior.Instance.SetCustomOccupation(objectId, occupationValue);

                string occName = GetFriendlyName(occupationValue);
                MCMSettings.DebugLog("Occupation set to " + occName + " for " + objectId);

                // Refresh the page
                var refresh = EncyclopediaPageTracker.CurrentRefreshAction;
                if (refresh != null) try { refresh(); } catch (Exception ex) { MCMSettings.DebugLog("Patches: ApplyOccupation exception: " + ex.ToString()); }

                bool showConfirm = true;
                try
                {
                    var settings = MCMSettings.Instance;
                    if (settings != null) showConfirm = settings.ShowConfirmationMessages;
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }

                if (showConfirm)
                {
                    InformationManager.DisplayMessage(
                        new InformationMessage(Localization.L("msg_occupation_updated", occName),
                            Colors.Green));
                }

                // Check if hero has existing lore fields — offer to regenerate for new occupation
                try
                {
                    var behavior = EncyclopediaEditBehavior.Instance;
                    if (behavior != null)
                    {
                        bool hasAnyLore = false;
                        foreach (string fieldKey in EncyclopediaEditBehavior.NarrativeFieldKeys)
                        {
                            string val = behavior.GetHeroInfoField(fieldKey, objectId);
                            if (!string.IsNullOrEmpty(val))
                            {
                                hasAnyLore = true;
                                break;
                            }
                        }

                        if (hasAnyLore)
                        {
                            string newOccName = occName;
                            string heroId = objectId;
                            InformationManager.ShowInquiry(
                                new InquiryData(
                                    Localization.L("msg_occupation_regen_lore_title"),
                                    Localization.L("msg_occupation_regen_lore", newOccName),
                                    true, true,
                                    Localization.L("edit_done"),
                                    Localization.L("edit_cancel"),
                                    delegate
                                    {
                                        try
                                        {
                                            foreach (string fieldKey in EncyclopediaEditBehavior.NarrativeFieldKeys)
                                                behavior.SetHeroInfoField(fieldKey, heroId, null);
                                            MCMSettings.DebugLog("Lore fields cleared for " + heroId + " after occupation change to " + newOccName);

                                            var r = EncyclopediaPageTracker.CurrentRefreshAction;
                                            if (r != null) try { r(); } catch (Exception ex) { MCMSettings.DebugLog("Patches: lore refresh failed: " + ex.ToString()); }

                                            InformationManager.DisplayMessage(
                                                new InformationMessage(Localization.L("msg_occupation_lore_updated", newOccName), Colors.Green));
                                        }
                                        catch (Exception ex) { MCMSettings.DebugLog("Patches: lore regeneration failed: " + ex.ToString()); }
                                    },
                                    null),
                                false, false);
                        }
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: lore regen check failed: " + ex.ToString()); }

                // Auto-clean orphaned entries after change
                try { EncyclopediaEditBehavior.Instance.PurgeOrphanedCustomEntries(); }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Failed to set occupation: " + ex.ToString());
                InformationManager.DisplayMessage(
                    new InformationMessage(Localization.L("msg_occupation_invalid"), Colors.Red));
            }
        }

        /// <summary>
        /// Resets a hero's occupation back to the original value and removes custom occupation data.
        /// </summary>
        internal static void ResetOccupation(string objectId, Hero hero)
        {
            try
            {
                var behavior = EncyclopediaEditBehavior.Instance;
                if (behavior == null) return;

                int origOccValue = behavior.GetOriginalOccupation(objectId);
                if (origOccValue < 0)
                {
                    MCMSettings.DebugLog("No original occupation stored for " + objectId + ", just removing custom data");
                    behavior.RemoveCustomOccupation(objectId);

                    var refresh0 = EncyclopediaPageTracker.CurrentRefreshAction;
                    if (refresh0 != null) try { refresh0(); } catch (Exception ex) { MCMSettings.DebugLog("Patches: ResetOccupation exception: " + ex.ToString()); }

                    InformationManager.DisplayMessage(
                        new InformationMessage(Localization.L("msg_occupation_reset"), Colors.Green));
                    return;
                }

                // Validate original occupation value is still a valid enum
                if (!Enum.IsDefined(typeof(Occupation), origOccValue))
                {
                    MCMSettings.DebugLog("WARNING: Original occupation value " + origOccValue + " is no longer valid for " + objectId);
                    InformationManager.DisplayMessage(
                        new InformationMessage(Localization.L("msg_occupation_original_missing", origOccValue.ToString()), Colors.Yellow));
                    behavior.RemoveCustomOccupation(objectId);

                    var refresh1 = EncyclopediaPageTracker.CurrentRefreshAction;
                    if (refresh1 != null) try { refresh1(); } catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                    return;
                }

                {
                    var occupation = (Occupation)origOccValue;
                    var flags = System.Reflection.BindingFlags.Instance
                              | System.Reflection.BindingFlags.Public
                              | System.Reflection.BindingFlags.NonPublic;

                    // Primary: set on CharacterObject (what the game reads from)
                    if (hero.CharacterObject != null)
                    {
                        var occProp = hero.CharacterObject.GetType().GetProperty("Occupation", flags);
                        if (occProp != null && occProp.CanWrite)
                        {
                            occProp.SetValue(hero.CharacterObject, occupation);
                        }
                        else
                        {
                            var occField = hero.CharacterObject.GetType().GetField("_occupation", flags)
                                        ?? hero.CharacterObject.GetType().GetField("<Occupation>k__BackingField", flags);
                            if (occField != null)
                                occField.SetValue(hero.CharacterObject, occupation);
                            else
                            {
                                foreach (var field in hero.CharacterObject.GetType().GetFields(flags))
                                {
                                    if (field.FieldType == typeof(Occupation))
                                    {
                                        field.SetValue(hero.CharacterObject, occupation);
                                        break;
                                    }
                                }
                            }
                        }
                    }

                    // Secondary: also set on Hero directly
                    try
                    {
                        var heroOccProp = typeof(Hero).GetProperty("Occupation", flags);
                        if (heroOccProp != null && heroOccProp.CanWrite)
                            heroOccProp.SetValue(hero, occupation);
                        else
                        {
                            var heroOccField = typeof(Hero).GetField("_occupation", flags)
                                            ?? typeof(Hero).GetField("<Occupation>k__BackingField", flags);
                            if (heroOccField != null && heroOccField.FieldType == typeof(Occupation))
                                heroOccField.SetValue(hero, occupation);
                        }
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                }

                // Remove custom occupation data from persistence
                behavior.RemoveCustomOccupation(objectId);

                string occName = GetFriendlyName(origOccValue);
                MCMSettings.DebugLog("Occupation reset to original (" + occName + ") for " + objectId);

                var refresh = EncyclopediaPageTracker.CurrentRefreshAction;
                if (refresh != null) try { refresh(); } catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }

                // After refresh, the game may not include an Occupation row in Stats for Lord heroes.
                // Inject one so the occupation remains visible after reset.
                try
                {
                    var vm = EncyclopediaPageTracker.CurrentViewModel;
                    if (vm != null)
                    {
                        var infoFlags = System.Reflection.BindingFlags.Instance
                                      | System.Reflection.BindingFlags.Public
                                      | System.Reflection.BindingFlags.NonPublic;
                        System.Collections.IEnumerable statsList = null;
                        foreach (var propName in EncyclopediaPatchHelper.StatsListNamesCommon)
                        {
                            var sProp = vm.GetType().GetProperty(propName, infoFlags);
                            if (sProp != null)
                            {
                                statsList = sProp.GetValue(vm) as System.Collections.IEnumerable;
                                if (statsList != null) break;
                            }
                        }

                        if (statsList != null)
                        {
                            bool hasOccEntry = false;
                            Type itemType = null;
                            foreach (var item in statsList)
                            {
                                if (item == null) continue;
                                if (itemType == null) itemType = item.GetType();
                                var defProp = itemType.GetProperty("Definition", infoFlags);
                                string def = defProp?.GetValue(item)?.ToString();
                                if (def != null && def.IndexOf("Occupation", StringComparison.OrdinalIgnoreCase) >= 0)
                                {
                                    hasOccEntry = true;
                                    break;
                                }
                            }

                            if (!hasOccEntry && itemType != null)
                            {
                                // Find ctor where first two params are strings (may be 2 or 3+ params)
                                System.Reflection.ConstructorInfo ctor = null;
                                foreach (var c in itemType.GetConstructors())
                                {
                                    var ps = c.GetParameters();
                                    if (ps.Length >= 2 && ps[0].ParameterType == typeof(string) && ps[1].ParameterType == typeof(string))
                                    { ctor = c; break; }
                                }
                                if (ctor != null)
                                {
                                    var ctorParams = ctor.GetParameters();
                                    object[] args = new object[ctorParams.Length];
                                    args[0] = "Occupation";
                                    args[1] = occName;
                                    for (int ai = 2; ai < ctorParams.Length; ai++)
                                        args[ai] = ctorParams[ai].ParameterType.IsValueType ? Activator.CreateInstance(ctorParams[ai].ParameterType) : null;

                                    var newItem = ctor.Invoke(args);
                                    var addMethod = statsList.GetType().GetMethod("Add");
                                    if (addMethod != null)
                                    {
                                        addMethod.Invoke(statsList, new[] { newItem });
                                        MCMSettings.DebugLog("Injected Occupation entry into Stats after reset: " + occName);
                                    }
                                }
                            }
                        }
                    }
                }
                catch (Exception statsEx)
                {
                    MCMSettings.DebugLog("Stats injection after reset failed: " + statsEx.Message);
                }

                InformationManager.DisplayMessage(
                    new InformationMessage(Localization.L("msg_occupation_reset"), Colors.Green));

                // Auto-clean orphaned entries after reset
                try { behavior.PurgeOrphanedCustomEntries(); }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Failed to reset occupation: " + ex.ToString());
            }
        }
    }

    // ============================================
    //  Quick Tag Menu (Ctrl+G) — All page types
    // ============================================
    public static class EncyclopediaTagEditPopup
    {
        private static volatile bool _popupOpen = false;
        public static bool IsPopupOpen => _popupOpen;

        // Gauntlet layer for the Quick Tag Menu
        private static GauntletLayer _quickTagLayer;

        // Main-thread action queue (Gauntlet layer ops must run on main thread)
        private static readonly object _queueLock = new object();
        private static Action _pendingAction;

        /// <summary>
        /// Called from OnApplicationTick (main game thread).
        /// Drains any pending Quick Tag Menu action from a background thread.
        /// </summary>
        public static void TickMainThread()
        {
            Action action = null;
            lock (_queueLock)
            {
                action = _pendingAction;
                _pendingAction = null;
            }
            if (action != null)
            {
                try { action(); }
                catch (Exception ex)
                {
                    MCMSettings.DebugLog("QuickTagMenu.TickMainThread error: " + ex.ToString());
                }
            }
        }

        /// <summary>
        /// Schedules Close() to run on the main game thread (next OnApplicationTick).
        /// Safe to call from any thread. Used when the encyclopedia is closed
        /// while the Quick Tag Menu layer might still be attached.
        /// </summary>
        public static void ScheduleClose()
        {
            lock (_queueLock)
            {
                _pendingAction = () => ReleasePopup();
            }
        }

        private static void ReleasePopup()
        {
            _popupOpen = false;
            CloseQuickTagLayer();
            EncyclopediaInputBlocker.Unblock();
            // Dismiss any game inquiry popup that may still be open (from manual text input)
            TryHideInquiry();
        }

        private static void TryHideInquiry()
        {
            try { InformationManager.HideInquiry(); } catch (Exception ex) { MCMSettings.DebugLog("Patches: TryHideInquiry exception: " + ex.ToString()); }
        }

        private static void CloseQuickTagLayer()
        {
            if (_quickTagLayer != null)
            {
                try
                {
                    _quickTagLayer.InputRestrictions.ResetInputRestrictions();
                    var topScreen = ScreenManager.TopScreen;
                    topScreen?.RemoveLayer(_quickTagLayer);
                    ScreenManager.TryLoseFocus(_quickTagLayer);
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: CloseQuickTagLayer exception: " + ex.ToString()); }
                _quickTagLayer = null;
            }
        }

        public static void TryOpen()
        {
            if (_popupOpen) return;
            if (EncyclopediaEditBehavior.Instance == null) return;
            if (string.IsNullOrEmpty(EncyclopediaPageTracker.CurrentObjectId)) return;

            try
            {
                var settings = MCMSettings.Instance;
                if (settings != null && !settings.EnableTagEditing) return;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: TryOpen exception: " + ex.ToString()); }

            string objectId = EncyclopediaPageTracker.CurrentObjectId;
            string currentTags = EncyclopediaEditBehavior.Instance.GetTags(objectId) ?? "";
            var allUniqueTags = EncyclopediaEditBehavior.Instance.GetAllUniqueTags();

            // Schedule on main thread (caller may be on timer thread)
            lock (_queueLock)
            {
                _pendingAction = () => ShowQuickTagMenu(objectId, currentTags, allUniqueTags);
            }
        }

        /// <summary>
        /// Returns the set of individual tags currently applied to the entry.
        /// </summary>
        private static HashSet<string> ParseCurrentTags(string currentTags)
        {
            var set = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            if (string.IsNullOrEmpty(currentTags)) return set;
            foreach (var part in currentTags.Split(','))
            {
                string tag = part.Trim();
                if (!string.IsNullOrEmpty(tag))
                    set.Add(tag);
            }
            return set;
        }

        /// <summary>
        /// Shows the Quick Tag Menu using the native MultiSelectionInquiry dialog
        /// (same approach as Ctrl+E hero edit picker). Each tag is a selectable item;
        /// currently-applied tags are pre-selected. On confirm, selected tags are saved.
        /// Falls back to manual text input if MultiSelectionInquiry is unavailable.
        /// </summary>
        private static void ShowQuickTagMenu(string objectId, string currentTags, List<string> allUniqueTags)
        {
            _popupOpen = true;
            EncyclopediaInputBlocker.Block();

            var currentSet = ParseCurrentTags(currentTags);

            // ── Build ordered tag list (grouped by category) ──
            // Built-in groups: Diplomacy, Military, Economy, Family, Status
            var builtInGroups = new[]
            {
                new { Group = "Diplomacy", Tags = new[] { "Ally", "Enemy", "Rival", "Friend", "Trusted", "Hostile", "Traitor" } },
                new { Group = "Military",  Tags = new[] { "Target", "Spy", "Warlord", "Raid Leader", "Good Commander", "Dangerous", "Assassination Target" } },
                new { Group = "Economy",   Tags = new[] { "Trade Hub", "Rich", "Ransom Target" } },
                new { Group = "Vassalage", Tags = new[] { "Future Vassal", "Recruit", "Claimant", "Governor", "Future Governor" } },
                new { Group = "Family",    Tags = new[] { "Marriage Candidate", "Family" } },
                new { Group = "Status",    Tags = new[] { "Prisoner", "Dead", "Wanted", "Honorable", "Dishonorable" } },
            };

            // Merge user-defined categories with built-in groups
            var tagGroups = new List<KeyValuePair<string, string[]>>();
            foreach (var g in builtInGroups)
                tagGroups.Add(new KeyValuePair<string, string[]>(g.Group, g.Tags));

            // Add user-defined categories
            try
            {
                var userCategories = EncyclopediaEditBehavior.Instance.GetAllTagCategories();
                foreach (var kvp in userCategories)
                {
                    // Don't duplicate built-in categories
                    bool isBuiltIn = false;
                    foreach (var g in builtInGroups)
                    {
                        if (string.Equals(g.Group, kvp.Key, StringComparison.OrdinalIgnoreCase))
                        { isBuiltIn = true; break; }
                    }
                    if (isBuiltIn) continue;

                    var tags = kvp.Value.Split(',');
                    var tagList = new List<string>();
                    foreach (var t in tags)
                    {
                        string trimmed = t.Trim();
                        if (!string.IsNullOrEmpty(trimmed)) tagList.Add(trimmed);
                    }
                    if (tagList.Count > 0)
                        tagGroups.Add(new KeyValuePair<string, string[]>(kvp.Key, tagList.ToArray()));
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }

            // Collect all preset tags across groups
            var presetSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var group in tagGroups)
                foreach (var tag in group.Value)
                    presetSet.Add(tag);

            var tagUsage = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            foreach (var tag in presetSet)
                tagUsage[tag] = EncyclopediaEditBehavior.Instance.GetTagUsageCount(tag);
            foreach (var tag in allUniqueTags)
            {
                if (!tagUsage.ContainsKey(tag))
                    tagUsage[tag] = EncyclopediaEditBehavior.Instance.GetTagUsageCount(tag);
            }

            // Build ordered preset list: group order, then by usage within each group
            var presetList = new List<string>();
            foreach (var group in tagGroups)
            {
                var groupTags = new List<string>(group.Value);
                groupTags.Sort((a, b) => (tagUsage.ContainsKey(b) ? tagUsage[b] : 0).CompareTo(tagUsage.ContainsKey(a) ? tagUsage[a] : 0));
                presetList.AddRange(groupTags);
            }

            var userTags = new List<string>();
            foreach (var tag in allUniqueTags)
            {
                if (!presetSet.Contains(tag))
                    userTags.Add(tag);
            }
            userTags.Sort((a, b) => (tagUsage.ContainsKey(b) ? tagUsage[b] : 0).CompareTo(tagUsage.ContainsKey(a) ? tagUsage[a] : 0));

            // ── Try native MultiSelectionInquiry (same as Ctrl+E) ──
            try
            {
                // Round 4 finding N-C2: cached scan replaces inline assembly walk.
                Type inquiryElementType = InquiryTypeCache.InquiryElement;
                Type multiSelDataType = InquiryTypeCache.MultiSelectionInquiryData;

                if (inquiryElementType == null || multiSelDataType == null)
                {
                    MCMSettings.DebugLog("QuickTagMenu: MultiSelection types not found, falling back to manual input");
                    _popupOpen = false;
                    EncyclopediaInputBlocker.Unblock();
                    ShowManualTagInput(objectId, currentTags);
                    return;
                }

                var showMethod = MultiSelectionMethodCache.Find(multiSelDataType);
                if (showMethod == null)
                {
                    MCMSettings.DebugLog("QuickTagMenu: ShowMultiSelectionInquiry not found, falling back to manual input");
                    _popupOpen = false;
                    EncyclopediaInputBlocker.Unblock();
                    ShowManualTagInput(objectId, currentTags);
                    return;
                }

                var elementCtor = MultiSelectionMethodCache.FindInquiryElementCtor(inquiryElementType, out bool secondParamIsTextObject);
                if (elementCtor == null)
                {
                    MCMSettings.DebugLog("QuickTagMenu: InquiryElement ctor not found, falling back to manual input");
                    _popupOpen = false;
                    EncyclopediaInputBlocker.Unblock();
                    ShowManualTagInput(objectId, currentTags);
                    return;
                }

                var elementCtorParams = elementCtor.GetParameters();
                var listType = typeof(List<>).MakeGenericType(inquiryElementType);
                var elements = (System.Collections.IList)Activator.CreateInstance(listType);

                // Build tag elements — preset tags first, then user tags
                // Pre-select tags that are currently applied; show usage count
                foreach (var tag in presetList)
                {
                    bool isApplied = currentSet.Contains(tag);
                    int count = tagUsage.ContainsKey(tag) ? tagUsage[tag] : 0;
                    string countSuffix = count > 0 ? " (" + count + ")" : "";
                    string label = (isApplied ? "\u2713 " : "") + tag + countSuffix;
                    elements.Add(MultiSelectionMethodCache.CreateInquiryElement(
                        elementCtor, elementCtorParams, secondParamIsTextObject,
                        tag, label));
                }
                foreach (var tag in userTags)
                {
                    bool isApplied = currentSet.Contains(tag);
                    int count = tagUsage.ContainsKey(tag) ? tagUsage[tag] : 0;
                    string countSuffix = count > 0 ? " (" + count + ")" : "";
                    string label = (isApplied ? "\u2713 " : "") + tag + countSuffix;
                    elements.Add(MultiSelectionMethodCache.CreateInquiryElement(
                        elementCtor, elementCtorParams, secondParamIsTextObject,
                        tag, label));
                }

                // Build callbacks using Expression trees (same pattern as hero edit picker)
                var actionType = typeof(Action<>).MakeGenericType(listType);

                // Confirm handler — toggles selected tags
                var handler = new TagSelectionHandler(objectId, currentSet);
                var tagAffMethodInfo = typeof(TagSelectionHandler).GetMethod("OnSelected");
                if (tagAffMethodInfo == null) return;
                var affParam = System.Linq.Expressions.Expression.Parameter(listType, "elements");
                var affCall = System.Linq.Expressions.Expression.Call(
                    System.Linq.Expressions.Expression.Constant(handler),
                    tagAffMethodInfo,
                    System.Linq.Expressions.Expression.Convert(affParam, typeof(object)));
                var affirmativeDelegate = System.Linq.Expressions.Expression.Lambda(actionType, affCall, affParam).Compile();

                // Cancel handler
                var tagNegMethodInfo = typeof(TagSelectionHandler).GetMethod("OnCancel");
                if (tagNegMethodInfo == null) return;
                var negParam = System.Linq.Expressions.Expression.Parameter(listType, "elements");
                var negBody = System.Linq.Expressions.Expression.Call(
                    System.Linq.Expressions.Expression.Constant(handler),
                    tagNegMethodInfo,
                    System.Linq.Expressions.Expression.Convert(negParam, typeof(object)));
                var negativeDelegate = System.Linq.Expressions.Expression.Lambda(actionType, negBody, negParam).Compile();

                // Find MultiSelectionInquiryData constructor
                System.Reflection.ConstructorInfo dataCtor = null;
                foreach (var ctor in multiSelDataType.GetConstructors())
                {
                    var pars = ctor.GetParameters();
                    if (pars.Length >= 8 && (dataCtor == null || pars.Length > dataCtor.GetParameters().Length))
                        dataCtor = ctor;
                }
                if (dataCtor == null)
                {
                    MCMSettings.DebugLog("QuickTagMenu: MultiSelectionInquiryData ctor not found, falling back to manual input");
                    _popupOpen = false;
                    EncyclopediaInputBlocker.Unblock();
                    ShowManualTagInput(objectId, currentTags);
                    return;
                }

                string title = Localization.L("tag_edit_title");
                string currentDisplay = string.IsNullOrEmpty(currentTags)
                    ? Localization.L("tag_picker_desc_none")
                    : Localization.L("tag_picker_desc", currentTags);

                object dataObj = MultiSelectionMethodCache.BuildMultiSelectionInquiryData(
                    dataCtor, title, currentDisplay,
                    Localization.L("edit_done"), Localization.L("edit_cancel"),
                    elements, listType, affirmativeDelegate, negativeDelegate);

                var showParams = showMethod.GetParameters();
                if (showParams.Length == 1)
                    showMethod.Invoke(null, new object[] { dataObj });
                else if (showParams.Length == 2)
                    showMethod.Invoke(null, new object[] { dataObj, false });
                else
                    showMethod.Invoke(null, new object[] { dataObj, false, false });

                MCMSettings.DebugLog("Showed Quick Tag Menu via MultiSelectionInquiry for " + objectId + " ("
                    + elements.Count + " items, " + currentSet.Count + " applied)");

                EncyclopediaNavigationGuard.ScheduleNavigateBack();
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("QuickTagMenu MultiSelection failed: " + ex.ToString() + ", falling back to manual input");
                _popupOpen = false;
                EncyclopediaInputBlocker.Unblock();
                ShowManualTagInput(objectId, currentTags);
            }
        }

        /// <summary>
        /// Handler for the tag selection multi-selection callback.
        /// Toggles selected tags on the entry.
        /// </summary>
        private class TagSelectionHandler
        {
            private readonly string _objectId;
            private readonly HashSet<string> _previousTags;

            public TagSelectionHandler(string objectId, HashSet<string> previousTags)
            {
                _objectId = objectId;
                _previousTags = previousTags;
            }

            public void OnSelected(object selectedElements)
            {
                try
                {
                    var newTags = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

                    // Add all tags that were selected in the dialog
                    if (selectedElements is System.Collections.IList list)
                    {
                        foreach (var elem in list)
                        {
                            string id = MultiSelectionMethodCache.GetInquiryElementId(elem);
                            if (!string.IsNullOrEmpty(id))
                                newTags.Add(id);
                        }
                    }

                    string normalized = newTags.Count > 0
                        ? NormalizeTags(string.Join(", ", newTags))
                        : null;
                    EncyclopediaEditBehavior.Instance.SetTags(_objectId, normalized);

                    MCMSettings.DebugLog("Tags saved for " + _objectId + ": " + (normalized ?? "(cleared)"));
                    ShowTagMessage(normalized);
                    EncyclopediaPageTracker.CurrentRefreshAction?.Invoke();

                    // Offer to add a note to any of the selected tags
                    if (newTags.Count > 0)
                    {
                        _popupOpen = false;
                        EncyclopediaInputBlocker.Unblock();
                        PromptForTagNote(_objectId, new List<string>(newTags));
                        return; // PromptForTagNote handles _popupOpen
                    }
                }
                catch (Exception ex)
                {
                    MCMSettings.DebugLog("TagSelectionHandler.OnSelected error: " + ex.ToString());
                }
                finally
                {
                    _popupOpen = false;
                    EncyclopediaInputBlocker.Unblock();
                }
            }

            public void OnCancel(object elements)
            {
                _popupOpen = false;
                EncyclopediaInputBlocker.Unblock();
                MCMSettings.DebugLog("Quick Tag Menu cancelled");
            }
        }

        private static void ShowTagMessage(string normalized)
        {
            bool showMsg = true;
            try
            {
                var s = MCMSettings.Instance;
                if (s != null) showMsg = s.ShowConfirmationMessages;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: ShowTagMessage exception: " + ex.ToString()); }

            if (showMsg)
            {
                string msg = string.IsNullOrEmpty(normalized)
                    ? Localization.L("msg_tags_cleared")
                    : Localization.L("msg_tags_updated", normalized);
                InformationManager.DisplayMessage(
                    new InformationMessage(msg, Colors.Green));
            }
        }

        /// <summary>
        /// Shows the manual text input popup for entering tags directly.
        /// </summary>
        internal static void ShowManualTagInput(string objectId, string currentTags)
        {
            string title = Localization.L("tag_edit_title");
            string description = Localization.L("tag_edit_message", currentTags);

            var inquiryData = new TextInquiryData(
                title, description, true, true,
                Localization.L("edit_done"), Localization.L("edit_cancel"),
                delegate (string newTags)
                {
                    try
                    {
                        // Normalize: trim whitespace, remove empty entries, deduplicate
                        string normalized = NormalizeTags(newTags);
                        EncyclopediaEditBehavior.Instance.SetTags(objectId, normalized);

                        MCMSettings.DebugLog("Tags saved for " + objectId + ": " + (normalized ?? "(cleared)"));
                        ShowTagMessage(normalized);

                        // Refresh the page to show updated tags
                        EncyclopediaPageTracker.CurrentRefreshAction?.Invoke();
                    }
                    catch (Exception ex)
                    {
                        MCMSettings.DebugLog("Tag save error: " + ex.ToString());
                    }
                    finally
                    {
                        ReleasePopup();
                    }
                },
                delegate
                {
                    ReleasePopup();
                },
                false, null);

            EEInquiry.Show(inquiryData, false, false);

            // Re-navigate back since ShowTextInquiry causes encyclopedia to navigate to Home
            EncyclopediaNavigationGuard.ScheduleNavigateBack();

            MCMSettings.DebugLog("Showed manual tag input for " + objectId + " (current tags: " + currentTags + ")");
        }

        /// <summary>
        /// Shows a text input to rename a tag globally across all entries.
        /// Format: "oldTag > newTag"
        /// </summary>
        private static void ShowRenameTagInput()
        {
            string title = Localization.L("tag_edit_title");
            string description = Localization.L("tag_rename_prompt");

            var inquiryData = new TextInquiryData(
                title, description, true, true,
                Localization.L("edit_done"), Localization.L("edit_cancel"),
                delegate (string input)
                {
                    try
                    {
                        if (!string.IsNullOrWhiteSpace(input) && input.Contains(">"))
                        {
                            var parts = input.Split(new[] { '>' }, 2);
                            string oldTag = parts[0].Trim();
                            string newTag = parts[1].Trim();
                            if (!string.IsNullOrEmpty(oldTag) && !string.IsNullOrEmpty(newTag))
                            {
                                int count = EncyclopediaEditBehavior.Instance.RenameTagGlobal(oldTag, newTag);
                                InformationManager.DisplayMessage(
                                    new InformationMessage(
                                        Localization.L("tag_renamed_global", oldTag, newTag, count),
                                        Colors.Green));
                                EncyclopediaPageTracker.CurrentRefreshAction?.Invoke();
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        MCMSettings.DebugLog("Tag rename error: " + ex.ToString());
                    }
                    finally
                    {
                        ReleasePopup();
                    }
                },
                delegate { ReleasePopup(); },
                false, null);

            EEInquiry.Show(inquiryData, false, false);
            EncyclopediaNavigationGuard.ScheduleNavigateBack();
        }

        /// <summary>
        /// Shows a text input to remove a tag globally from all entries.
        /// </summary>
        private static void ShowRemoveTagGlobalInput()
        {
            string title = Localization.L("tag_edit_title");
            string description = Localization.L("tag_remove_prompt");

            var inquiryData = new TextInquiryData(
                title, description, true, true,
                Localization.L("edit_done"), Localization.L("edit_cancel"),
                delegate (string input)
                {
                    try
                    {
                        string tag = input?.Trim();
                        if (!string.IsNullOrEmpty(tag))
                        {
                            int count = EncyclopediaEditBehavior.Instance.RemoveTagGlobal(tag);
                            InformationManager.DisplayMessage(
                                new InformationMessage(
                                    Localization.L("tag_removed_global", tag, count),
                                    Colors.Green));
                            EncyclopediaPageTracker.CurrentRefreshAction?.Invoke();
                        }
                    }
                    catch (Exception ex)
                    {
                        MCMSettings.DebugLog("Tag remove global error: " + ex.ToString());
                    }
                    finally
                    {
                        ReleasePopup();
                    }
                },
                delegate { ReleasePopup(); },
                false, null);

            EEInquiry.Show(inquiryData, false, false);
            EncyclopediaNavigationGuard.ScheduleNavigateBack();
        }

        /// <summary>
        /// After tag selection, offers to add or delete a note on one of the selected tags.
        /// If existing notes exist, shows "Add/Edit Note" and "Delete Note" buttons.
        /// If no notes exist, shows "Add Note" and "Cancel" buttons.
        /// </summary>
        private static void PromptForTagNote(string objectId, List<string> tags)
        {
            try
            {
                var behavior = EncyclopediaEditBehavior.Instance;
                if (behavior == null) return;

                var existingNotes = behavior.GetAllTagNotes(objectId);
                string notesDisplay = "";
                if (existingNotes.Count > 0)
                {
                    var notesDisplaySb = new System.Text.StringBuilder("\n\nExisting notes:");
                    foreach (var kvp in existingNotes)
                        notesDisplaySb.Append("\n  ").Append(kvp.Key).Append(": ").Append(kvp.Value);
                    notesDisplay = notesDisplaySb.ToString();
                }

                bool hasNotes = existingNotes.Count > 0;

                InformationManager.ShowInquiry(new InquiryData(
                    Localization.L("tag_note_title"),
                    Localization.L("tag_note_prompt") + notesDisplay,
                    true, true,
                    Localization.L("tag_note_yes"),
                    hasNotes ? Localization.L("tag_note_delete") : Localization.L("edit_cancel"),
                    () =>
                    {
                        // Add/Edit note flow
                        ShowTagNoteInput(objectId, tags, behavior);
                    },
                    () =>
                    {
                        if (hasNotes)
                        {
                            // Delete note flow
                            ShowDeleteTagNotePrompt(objectId, tags, behavior, existingNotes);
                        }
                    }), false, false);
                EncyclopediaNavigationGuard.ScheduleNavigateBack();
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("PromptForTagNote error: " + ex.ToString());
            }
        }

        /// <summary>
        /// Shows the text input for adding/editing a tag note.
        /// </summary>
        private static void ShowTagNoteInput(string objectId, List<string> tags, EncyclopediaEditBehavior behavior)
        {
            string tagList = string.Join(", ", tags);
            string currentNote = "";
            if (tags.Count == 1)
            {
                currentNote = behavior.GetTagNote(objectId, tags[0]) ?? "";
            }

            EEInquiry.Show(new TextInquiryData(
                Localization.L("tag_note_title"),
                Localization.L("tag_note_input", tagList, currentNote),
                true, true,
                Localization.L("edit_done"), Localization.L("edit_cancel"),
                delegate(string input)
                {
                    try
                    {
                        if (!string.IsNullOrWhiteSpace(input))
                        {
                            string targetTag = tags[0];
                            string note = input.Trim();

                            int colonIdx = input.IndexOf(':');
                            if (colonIdx > 0 && colonIdx < input.Length)
                            {
                                string possibleTag = input.Substring(0, colonIdx).Trim();
                                foreach (var t in tags)
                                {
                                    if (string.Equals(t, possibleTag, StringComparison.OrdinalIgnoreCase))
                                    {
                                        targetTag = t;
                                        note = colonIdx + 1 < input.Length ? input.Substring(colonIdx + 1).Trim() : "";
                                        break;
                                    }
                                }
                            }

                            behavior.SetTagNote(objectId, targetTag, note);
                            InformationManager.DisplayMessage(
                                new InformationMessage(
                                    Localization.L("tag_note_saved", targetTag, note),
                                    Colors.Green));
                            EncyclopediaPageTracker.CurrentRefreshAction?.Invoke();
                        }
                    }
                    catch (Exception ex)
                    {
                        MCMSettings.DebugLog("Tag note save error: " + ex.ToString());
                    }
                },
                delegate { },
                false, null), false, false);
            EncyclopediaNavigationGuard.ScheduleNavigateBack();
        }

        /// <summary>
        /// Shows a confirmation dialog to delete a tag note.
        /// If multiple notes exist, asks which one to delete via text input.
        /// </summary>
        private static void ShowDeleteTagNotePrompt(string objectId, List<string> tags,
            EncyclopediaEditBehavior behavior, Dictionary<string, string> existingNotes)
        {
            try
            {
                if (existingNotes.Count == 1)
                {
                    // Only one note — confirm deletion directly
                    var noteEntry = existingNotes.GetEnumerator();
                    noteEntry.MoveNext();
                    string noteTag = noteEntry.Current.Key;
                    string noteText = noteEntry.Current.Value;

                    InformationManager.ShowInquiry(new InquiryData(
                        Localization.L("tag_note_title"),
                        Localization.L("tag_note_delete_confirm", noteTag, noteText),
                        true, true,
                        Localization.L("tag_note_delete"), Localization.L("edit_cancel"),
                        () =>
                        {
                            behavior.SetTagNote(objectId, noteTag, null);
                            InformationManager.DisplayMessage(
                                new InformationMessage(
                                    Localization.L("tag_note_deleted", noteTag),
                                    Colors.Yellow));
                            EncyclopediaPageTracker.CurrentRefreshAction?.Invoke();
                            PromptAlsoRemoveTag(objectId, noteTag, behavior);
                        },
                        () => { }), false, false);
                    EncyclopediaNavigationGuard.ScheduleNavigateBack();
                }
                else
                {
                    // Multiple notes — ask which to delete
                    var notesListSb = new System.Text.StringBuilder();
                    foreach (var kvp in existingNotes)
                        notesListSb.Append("\n  ").Append(kvp.Key).Append(": ").Append(kvp.Value);
                    string notesList = notesListSb.ToString();

                    EEInquiry.Show(new TextInquiryData(
                        Localization.L("tag_note_title"),
                        Localization.L("tag_note_delete_which") + notesList,
                        true, true,
                        Localization.L("tag_note_delete"), Localization.L("edit_cancel"),
                        delegate(string input)
                        {
                            try
                            {
                                if (!string.IsNullOrWhiteSpace(input))
                                {
                                    string tagToDelete = input.Trim();
                                    // Find matching note (case-insensitive)
                                    string matchedTag = null;
                                    foreach (var kvp in existingNotes)
                                    {
                                        if (string.Equals(kvp.Key, tagToDelete, StringComparison.OrdinalIgnoreCase))
                                        {
                                            matchedTag = kvp.Key;
                                            break;
                                        }
                                    }

                                    if (matchedTag != null)
                                    {
                                        behavior.SetTagNote(objectId, matchedTag, null);
                                        InformationManager.DisplayMessage(
                                            new InformationMessage(
                                                Localization.L("tag_note_deleted", matchedTag),
                                                Colors.Yellow));
                                        EncyclopediaPageTracker.CurrentRefreshAction?.Invoke();
                                        PromptAlsoRemoveTag(objectId, matchedTag, behavior);
                                    }
                                    else
                                    {
                                        InformationManager.DisplayMessage(
                                            new InformationMessage(
                                                "No note found for tag '" + tagToDelete + "'.",
                                                Colors.Red));
                                    }
                                }
                            }
                            catch (Exception ex)
                            {
                                MCMSettings.DebugLog("Tag note delete error: " + ex.ToString());
                            }
                        },
                        delegate { },
                        false, null), false, false);
                    EncyclopediaNavigationGuard.ScheduleNavigateBack();
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("ShowDeleteTagNotePrompt error: " + ex.ToString());
            }
        }

        /// <summary>
        /// After deleting a tag note, offers to also remove the tag itself from the entry.
        /// Only prompts if the tag is still present on the object.
        /// </summary>
        private static void PromptAlsoRemoveTag(string objectId, string tagName, EncyclopediaEditBehavior behavior)
        {
            try
            {
                string currentTags = behavior.GetTags(objectId);
                if (string.IsNullOrEmpty(currentTags)) return;

                // Check if the tag is still present
                bool tagPresent = false;
                foreach (var part in currentTags.Split(','))
                {
                    if (string.Equals(part.Trim(), tagName, StringComparison.OrdinalIgnoreCase))
                    {
                        tagPresent = true;
                        break;
                    }
                }
                if (!tagPresent) return;

                InformationManager.ShowInquiry(new InquiryData(
                    Localization.L("tag_note_title"),
                    Localization.L("tag_note_also_remove_tag", tagName),
                    true, true,
                    Localization.L("tag_note_delete"), Localization.L("edit_cancel"),
                    () =>
                    {
                        string updated = EncyclopediaEditBehavior.RemoveTagFromString(currentTags, tagName);
                        behavior.SetTags(objectId, updated);
                        InformationManager.DisplayMessage(
                            new InformationMessage(
                                Localization.L("tag_note_tag_removed", tagName),
                                Colors.Yellow));
                        EncyclopediaPageTracker.CurrentRefreshAction?.Invoke();
                    },
                    () => { }), false, false);
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("PromptAlsoRemoveTag error: " + ex.ToString());
            }
        }

        /// <summary>
        /// Normalizes a tag string: trims whitespace, removes empty entries, deduplicates.
        /// Returns null if no valid tags remain.
        /// </summary>
        internal static string NormalizeTags(string input)
        {
            if (string.IsNullOrWhiteSpace(input))
                return null;

            var parts = input.Split(',');
            var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var result = new List<string>();

            foreach (var part in parts)
            {
                string tag = part.Trim();
                if (!string.IsNullOrEmpty(tag) && seen.Add(tag.ToLowerInvariant()))
                    result.Add(tag);
            }

            return result.Count > 0 ? string.Join(", ", result) : null;
        }
    }

    // ============================================
    //  Prevent game from reverting NPC clan banners
    // ============================================
    /// <summary>
    /// Harmony PREFIX patch on Clan.UpdateBannerColorsAccordingToKingdom.
    /// The game calls this method periodically (e.g. on kingdom join/leave, save load)
    /// to reset clan banner colors to match the kingdom's palette. This silently
    /// overwrites any custom banners we've set via the mod.
    ///
    /// Strategy: If we have a stored custom banner code for any hero in this clan,
    /// or for the clan itself, or for any settlement owned by this clan,
    /// skip the game's method entirely (return false) to prevent reversion.
    /// </summary>
    public static class ClanBannerReversionPatch
    {
        /// <summary>
        /// Called by SubModuleClassEntry to manually patch UpdateBannerColorsAccordingToKingdom.
        /// We use manual patching because the method may not exist in all game versions.
        /// </summary>
        public static void TryPatch(HarmonyLib.Harmony harmony)
        {
            try
            {
                var flags = System.Reflection.BindingFlags.Instance
                          | System.Reflection.BindingFlags.Public
                          | System.Reflection.BindingFlags.NonPublic;

                var targetMethod = typeof(Clan).GetMethod("UpdateBannerColorsAccordingToKingdom", flags);
                if (targetMethod == null)
                {
                    MCMSettings.DebugLog("ClanBannerReversionPatch: UpdateBannerColorsAccordingToKingdom not found on Clan");
                    return;
                }

                var prefix = typeof(ClanBannerReversionPatch).GetMethod("Prefix",
                    System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public);
                if (prefix == null)
                {
                    MCMSettings.DebugLog("ClanBannerReversionPatch: Prefix method not found via reflection");
                    return;
                }

                harmony.Patch(targetMethod, prefix: new HarmonyMethod(prefix));
                MCMSettings.DebugLog("ClanBannerReversionPatch: Successfully patched Clan.UpdateBannerColorsAccordingToKingdom");
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("ClanBannerReversionPatch: Patch failed - " + ex.ToString());
            }
        }

        /// <summary>
        /// Harmony PREFIX: returns false to skip the original method if the clan
        /// has a custom banner set by our mod.
        /// </summary>
        public static bool Prefix(Clan __instance)
        {
            try
            {
                var behavior = EncyclopediaEditBehavior.Instance;
                if (behavior == null) return true; // no mod data, let game proceed

                // Check if any hero in this clan has a custom banner code stored
                foreach (var hero in __instance.Heroes)
                {
                    if (hero != null && behavior.HasCustomBannerCode(hero.StringId))
                    {
                        MCMSettings.DebugLog("ClanBannerReversionPatch: Blocked UpdateBannerColorsAccordingToKingdom for "
                            + __instance.Name + " (hero " + hero.StringId + " has custom banner)");
                        return false; // Skip the original method
                    }
                }

                // Also check if the clan itself has a custom banner code
                if (behavior.HasCustomBannerCode(__instance.StringId))
                {
                    MCMSettings.DebugLog("ClanBannerReversionPatch: Blocked UpdateBannerColorsAccordingToKingdom for "
                        + __instance.Name + " (clan has custom banner)");
                    return false;
                }

                // Also check if any settlement owned by this clan has a custom banner code
                try
                {
                    foreach (var settlement in __instance.Settlements)
                    {
                        if (settlement != null && behavior.HasCustomBannerCode(settlement.StringId))
                        {
                            MCMSettings.DebugLog("ClanBannerReversionPatch: Blocked UpdateBannerColorsAccordingToKingdom for "
                                + __instance.Name + " (settlement " + settlement.StringId + " has custom banner)");
                            return false;
                        }
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("ClanBannerReversionPatch.Prefix error: " + ex.ToString());
            }
            return true; // No custom banner, let game proceed normally
        }
    }

    // ============================================
    //  Banner/Flag edit popup logic
    // ============================================
    public static class EncyclopediaBannerEditPopup
    {
        private static volatile bool _popupOpen = false;
        public static bool IsPopupOpen => _popupOpen;

        // Deferred map visual refresh: store party bases that need banner visual refresh
        // after encyclopedia closes (visual calls are no-ops during encyclopedia overlay)
        private static readonly System.Collections.Generic.List<object> _pendingVisualRefreshParties
            = new System.Collections.Generic.List<object>();
        private static Clan _pendingVisualRefreshClan = null;
        private static string _pendingVisualRefreshBannerCode = null;

        // Main-thread refresh: the visual rebuild MUST run on the main game thread.
        // The timer thread sets this countdown; OnApplicationTick decrements and executes at 0.
        private static int _mainThreadRefreshCountdown = -1;

        // ── Clipboard reading (Win32 P/Invoke) — bypasses text input character limit ──
        [DllImport("user32.dll")]
        private static extern bool OpenClipboard(IntPtr hWndNewOwner);
        [DllImport("user32.dll")]
        private static extern bool CloseClipboard();
        [DllImport("user32.dll")]
        private static extern IntPtr GetClipboardData(uint uFormat);
        [DllImport("kernel32.dll")]
        private static extern IntPtr GlobalLock(IntPtr hMem);
        [DllImport("kernel32.dll")]
        private static extern bool GlobalUnlock(IntPtr hMem);
        private const uint CF_UNICODETEXT = 13;

        // Watchdog spam reduction: only log the first re-apply per objectId, then silently fix
        private static readonly HashSet<string> _watchdogAlreadyLogged = new HashSet<string>();

        private static string GetClipboardText()
        {
            string result = null;

            // Method 1: TaleWorlds.InputSystem.Input.GetClipboardText()
            // This is the most reliable approach since it uses the game engine's own clipboard API,
            // which properly handles threading and window focus.
            try
            {
                Type inputType = null;
                foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                {
                    try
                    {
                        foreach (var t in asm.GetTypes())
                        {
                            if (t.FullName == "TaleWorlds.InputSystem.Input")
                            {
                                inputType = t;
                                break;
                            }
                        }
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: GetClipboardText exception: " + ex.ToString()); }
                    if (inputType != null) break;
                }

                if (inputType != null)
                {
                    var method = inputType.GetMethod("GetClipboardText",
                        System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public);
                    if (method != null)
                    {
                        result = method.Invoke(null, null) as string;
                        if (!string.IsNullOrEmpty(result))
                        {
                            MCMSettings.DebugLog("Clipboard: Got " + result.Length + " chars via TaleWorlds.InputSystem.Input");
                            return result;
                        }
                        MCMSettings.DebugLog("Clipboard: TaleWorlds.InputSystem returned empty");
                    }
                    else
                    {
                        MCMSettings.DebugLog("Clipboard: GetClipboardText method not found on Input class");
                    }
                }
                else
                {
                    MCMSettings.DebugLog("Clipboard: TaleWorlds.InputSystem.Input type not found");
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Clipboard: TaleWorlds.InputSystem failed - " + ex.ToString());
            }

            // Method 2: Win32 P/Invoke (fallback for game versions without Input.GetClipboardText)
            try
            {
                if (!OpenClipboard(IntPtr.Zero))
                {
                    MCMSettings.DebugLog("Clipboard: OpenClipboard(IntPtr.Zero) failed");
                }
                else
                {
                    try
                    {
                        IntPtr handle = GetClipboardData(CF_UNICODETEXT);
                        if (handle == IntPtr.Zero)
                        {
                            MCMSettings.DebugLog("Clipboard: GetClipboardData returned null handle");
                        }
                        else
                        {
                            IntPtr pointer = GlobalLock(handle);
                            if (pointer == IntPtr.Zero)
                            {
                                MCMSettings.DebugLog("Clipboard: GlobalLock failed");
                            }
                            else
                            {
                                try
                                {
                                    result = Marshal.PtrToStringUni(pointer);
                                    if (!string.IsNullOrEmpty(result))
                                    {
                                        MCMSettings.DebugLog("Clipboard: Got " + result.Length + " chars via P/Invoke");
                                        return result;
                                    }
                                    MCMSettings.DebugLog("Clipboard: P/Invoke returned empty string");
                                }
                                finally
                                {
                                    GlobalUnlock(handle);
                                }
                            }
                        }
                    }
                    finally
                    {
                        CloseClipboard();
                    }
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Clipboard: P/Invoke failed - " + ex.ToString());
            }

            // Method 3: File-based import (most reliable fallback — no clipboard issues).
            // User can save banner code to "banner_import.txt" in the mod's DLL folder.
            try
            {
                string modDir = System.IO.Path.GetDirectoryName(
                    typeof(EncyclopediaBannerEditPopup).Assembly.Location);
                string importFile = System.IO.Path.Combine(modDir, "banner_import.txt");
                if (System.IO.File.Exists(importFile))
                {
                    string content = System.IO.File.ReadAllText(importFile).Trim();
                    if (!string.IsNullOrEmpty(content))
                    {
                        MCMSettings.DebugLog("Clipboard: Got " + content.Length + " chars from banner_import.txt");
                        return content;
                    }
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Clipboard: File import failed - " + ex.ToString());
            }

            MCMSettings.DebugLog("Clipboard: All methods returned empty");
            return null;
        }

        private static bool LooksLikeBannerCode(string text)
        {
            if (string.IsNullOrEmpty(text)) return false;
            if (!char.IsDigit(text[0])) return false;
            if (!text.Contains(".")) return false;
            var parts = text.Split('.');
            if (parts.Length < 10) return false;
            // Validate ALL segments are numeric, not just the first 5.
            // The Banner constructor can crash the game engine (native crash, not a
            // managed exception) if given non-numeric text. Checking only the first 5
            // segments allowed strings like "1.2.3.4.5.abc.def.ghi.jkl.mnop" to pass
            // validation and reach the Banner constructor, crashing the game.
            for (int i = 0; i < parts.Length; i++)
            {
                int val;
                if (!int.TryParse(parts[i].Trim(), out val)) return false;
            }
            return true;
        }

        /// <summary>
        /// Called from OnApplicationTick (main thread). Checks if a deferred visual refresh
        /// is pending and executes it after a short frame delay.
        /// </summary>
        public static void TickMainThreadRefresh()
        {
            if (_mainThreadRefreshCountdown < 0) return;

            if (_mainThreadRefreshCountdown > 0)
            {
                _mainThreadRefreshCountdown--;
                return;
            }

            // Countdown reached 0 — execute on this (main) thread
            _mainThreadRefreshCountdown = -1;
            MCMSettings.DebugLog("Main-thread refresh executing (OnApplicationTick)");
            try
            {
                ExecutePendingVisualRefresh();
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Main-thread refresh error: " + ex.ToString());
            }
        }

        /// <summary>
        /// Called from the timer thread when encyclopedia close is detected.
        /// Schedules the visual refresh to run on the main thread after a few frames.
        /// </summary>
        public static void ScheduleMainThreadRefresh()
        {
            if (_pendingVisualRefreshParties.Count == 0) return;
            // Wait ~10 frames to ensure the map render loop is fully active
            _mainThreadRefreshCountdown = 10;
            MCMSettings.DebugLog("Scheduled main-thread visual refresh (10 frame delay)");
        }

        /// <summary>
        /// Called on the MAIN GAME THREAD via OnApplicationTick.
        /// Executes deferred visual refresh for banner changes.
        ///
        /// Strategy: The banner data on Clan/Party objects is already correct
        /// (updated during the edit). We only need to:
        ///   1. Clear the cached _bannerVisual so it regenerates from new data
        ///   2. Mark the party visual as dirty so the game rebuilds it
        ///
        /// IMPORTANT: Do NOT call BannerlordTableauManager.ClearManager() or
        /// TextureProviderFactory.RefreshProviderTypes() here — these destroy
        /// game-wide tableau/texture state and cause crashes when entering
        /// settlements or other scenes that need tableau rendering.
        /// </summary>
        public static void ExecutePendingVisualRefresh()
        {
            if (_pendingVisualRefreshParties.Count == 0) return;

            var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public
                      | System.Reflection.BindingFlags.NonPublic;
            var staticFlags = System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public
                            | System.Reflection.BindingFlags.NonPublic;

            MCMSettings.DebugLog("=== Executing deferred visual refresh ===");
            MCMSettings.DebugLog("Pending parties: " + _pendingVisualRefreshParties.Count
                + " for clan: " + (_pendingVisualRefreshClan?.Name?.ToString() ?? "null"));

            // Step 1: Clear Banner._bannerVisual on the clan banner so it regenerates
            if (_pendingVisualRefreshClan?.Banner != null)
            {
                try
                {
                    var bannerVisualField = typeof(Banner).GetField("_bannerVisual", flags);
                    if (bannerVisualField != null)
                    {
                        bannerVisualField.SetValue(_pendingVisualRefreshClan.Banner, null);
                        MCMSettings.DebugLog("Cleared _bannerVisual cache");
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: ExecutePendingVisualRefresh exception: " + ex.ToString()); }
            }

            // Find PartyVisualManager type and instance — used by Steps 2 and 4
            Type pvmType = null;
            object pvmInstance = null;

            // Step 2: Force full visual rebuild via PartyVisualManager to update 2D badge icon.
            // RemovePartyVisualForParty + AddNewPartyVisualForParty destroys the old visual and creates
            // a fresh one that reads the current (new) banner for its 2D icon texture.
            // IMPORTANT: This must run BEFORE SetVisualAsDirty, because Remove+Add destroys the
            // old visual (and its dirty flag). SetVisualAsDirty must target the NEW visual.
            try
            {
                // Find PartyVisualManager type in loaded assemblies.
                // The actual class name is MobilePartyVisualManager (or NavalMobilePartyVisualManager
                // with NavalDLC). Prefer the Naval variant if present, fall back to base.
                Type pvmFallback = null;
                foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                {
                    try
                    {
                        foreach (var t in asm.GetTypes())
                        {
                            if (t.Name.EndsWith("PartyVisualManager"))
                            {
                                if (t.Name.StartsWith("Naval"))
                                    pvmType = t; // Prefer Naval variant
                                else if (pvmFallback == null)
                                    pvmFallback = t;
                            }
                        }
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                }
                if (pvmType == null) pvmType = pvmFallback;

                if (pvmType != null)
                {
                    MCMSettings.DebugLog("Found PartyVisualManager: " + pvmType.FullName);

                    // Get the singleton instance
                    pvmInstance = null;
                    foreach (var name in new[] { "Current", "Instance", "_current", "_instance" })
                    {
                        try
                        {
                            var prop = pvmType.GetProperty(name, staticFlags);
                            if (prop != null) { pvmInstance = prop.GetValue(null); if (pvmInstance != null) break; }
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                        try
                        {
                            var field = pvmType.GetField(name, staticFlags);
                            if (field != null) { pvmInstance = field.GetValue(null); if (pvmInstance != null) break; }
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                    }

                    if (pvmInstance != null)
                    {
                        MCMSettings.DebugLog("Found PartyVisualManager instance");

                        // Look for remove+add methods for full visual rebuild
                        // Note: the actual method name is "RemovePartyVisualForParty" (not "RemovePartyVisual")
                        var removeMethod = pvmType.GetMethod("RemovePartyVisualForParty", flags)
                                        ?? pvmType.GetMethod("RemovePartyVisual", flags);
                        var addMethod = pvmType.GetMethod("AddNewPartyVisualForParty", flags);

                        if (removeMethod != null && addMethod != null)
                        {
                            // Log full parameter signatures for both methods
                            var removeParams = removeMethod.GetParameters();
                            var addParams = addMethod.GetParameters();
                            var removeParamType = removeParams.Length > 0 ? removeParams[0].ParameterType : null;

                            var removeSigSb = new System.Text.StringBuilder(removeMethod.Name).Append("(");
                            for (int i = 0; i < removeParams.Length; i++)
                            {
                                if (i > 0) removeSigSb.Append(", ");
                                removeSigSb.Append(removeParams[i].ParameterType.Name).Append(" ").Append(removeParams[i].Name);
                            }
                            removeSigSb.Append(")");
                            string removeSig = removeSigSb.ToString();

                            var addSigSb = new System.Text.StringBuilder("AddNewPartyVisualForParty(");
                            for (int i = 0; i < addParams.Length; i++)
                            {
                                if (i > 0) addSigSb.Append(", ");
                                addSigSb.Append(addParams[i].ParameterType.Name).Append(" ").Append(addParams[i].Name);
                            }
                            addSigSb.Append(")");
                            string addSig = addSigSb.ToString();

                            MCMSettings.DebugLog("Found " + removeSig);
                            MCMSettings.DebugLog("Found " + addSig);

                            int rebuilt = 0;
                            foreach (var pb in _pendingVisualRefreshParties)
                            {
                                try
                                {
                                    var partyBase = pb as PartyBase;
                                    if (partyBase == null) continue;

                                    // Settlement parties don't have MobileParty — skip for Remove+Add
                                    if (partyBase.MobileParty == null) continue;

                                    bool isMainParty = false;
                                    try { isMainParty = partyBase.MobileParty == MobileParty.MainParty; } catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }

                                    // Build argument arrays matching actual parameter counts.
                                    // NavalDLC overrides may add extra parameters beyond the base MobileParty arg.
                                    // Pass null/default for any extra parameters.
                                    object primaryArg = (removeParamType != null && removeParamType == typeof(MobileParty))
                                        ? (object)partyBase.MobileParty
                                        : (object)partyBase;

                                    object[] removeArgs = new object[removeParams.Length];
                                    removeArgs[0] = primaryArg;
                                    // Fill extra params with null/default
                                    for (int i = 1; i < removeParams.Length; i++)
                                    {
                                        var pt = removeParams[i].ParameterType;
                                        removeArgs[i] = pt.IsValueType ? Activator.CreateInstance(pt) : null;
                                    }

                                    object[] addArgs = new object[addParams.Length];
                                    // First param of Add is also the party
                                    if (addParams.Length > 0)
                                    {
                                        var addFirstType = addParams[0].ParameterType;
                                        addArgs[0] = (addFirstType == typeof(MobileParty))
                                            ? (object)partyBase.MobileParty
                                            : (object)partyBase;
                                    }
                                    for (int i = 1; i < addParams.Length; i++)
                                    {
                                        var pt = addParams[i].ParameterType;
                                        addArgs[i] = pt.IsValueType ? Activator.CreateInstance(pt) : null;
                                    }

                                    removeMethod.Invoke(pvmInstance, removeArgs);
                                    addMethod.Invoke(pvmInstance, addArgs);
                                    rebuilt++;
                                    if (isMainParty)
                                        MCMSettings.DebugLog("  Main party Remove+Add succeeded");
                                }
                                catch (Exception ex)
                                {
                                    MCMSettings.DebugLog("  Visual rebuild error: " + (ex.InnerException?.Message ?? ex.Message));
                                }
                            }
                            MCMSettings.DebugLog("Rebuilt " + rebuilt + " party visuals via PartyVisualManager");
                        }
                        else
                        {
                            MCMSettings.DebugLog("RemovePartyVisualForParty/RemovePartyVisual or AddNewPartyVisualForParty not found, dumping methods:");
                            foreach (var m in pvmType.GetMethods(flags | staticFlags))
                            {
                                if (m.Name.Contains("Visual") || m.Name.Contains("Party") || m.Name.Contains("Banner")
                                    || m.Name.Contains("Remove") || m.Name.Contains("Add") || m.Name.Contains("Refresh"))
                                    MCMSettings.DebugLog("  Method: " + m.Name + "(" + m.GetParameters().Length + " params)");
                            }
                        }
                    }
                    else
                    {
                        MCMSettings.DebugLog("PartyVisualManager instance not found, dumping static members:");
                        foreach (var m in pvmType.GetFields(staticFlags))
                            MCMSettings.DebugLog("  Static field: " + m.Name + " (" + m.FieldType.Name + ")");
                        foreach (var m in pvmType.GetProperties(staticFlags))
                            MCMSettings.DebugLog("  Static prop: " + m.Name + " (" + m.PropertyType.Name + ")");
                    }
                }
                else
                {
                    MCMSettings.DebugLog("PartyVisualManager type not found in loaded assemblies");
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("PartyVisualManager rebuild failed: " + (ex.InnerException?.Message ?? ex.Message));
            }

            // Step 3: Mark each party as dirty so the game rebuilds the 3D flag visual.
            // This MUST run AFTER PartyVisualManager rebuild (Step 2), because Remove+Add
            // creates a new visual object — the dirty flag must be set on the NEW visual.
            // NOTE: This applies to BOTH mobile parties AND settlement parties.
            // Uses SetMapIconAsDirty() on party Visuals (KingdomColor mod pattern) with
            // fallback to PartyBase.SetVisualAsDirty().
            foreach (var pb in _pendingVisualRefreshParties)
            {
                try
                {
                    var partyBase = pb as PartyBase;
                    if (partyBase == null) continue;

                    string partyName = "unknown";
                    try
                    {
                        if (partyBase.MobileParty != null)
                            partyName = partyBase.MobileParty.Name?.ToString() ?? "mobile";
                        else if (partyBase.Settlement != null)
                            partyName = partyBase.Settlement.Name?.ToString() ?? "settlement";
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }

                    MCMSettings.DebugLog("  Processing: " + partyName
                        + (partyBase.MobileParty != null ? " [mobile]" : " [settlement]"));

                    SetMapIconAsDirtyOnParty(partyBase, flags);
                    MCMSettings.DebugLog("  SetMapIconAsDirty/SetVisualAsDirty on " + partyName);
                }
                catch (Exception ex)
                {
                    MCMSettings.DebugLog("  Deferred refresh error: " + (ex.InnerException?.Message ?? ex.Message));
                }
            }

            // Step 4: Refresh party visuals via MobileParty.Party.Visuals (IPartyVisual) interface.
            // The Visuals property lives on MobileParty (not PartyBase). For settlements, access
            // via Settlement.Party.MobileParty or directly on the PartyVisualManager.
            // This is critical for the MAIN (player) party whose visual can't be removed/recreated
            // by PartyVisualManager. We reinitialize its visual directly via OnStartup(partyBase).
            try
            {
                int step4Null = 0;
                int step4Processed = 0;
                foreach (var pb in _pendingVisualRefreshParties)
                {
                    var partyBase = pb as PartyBase;
                    if (partyBase == null) continue;

                    // The Visuals property is on MobileParty, not PartyBase.
                    // Try multiple paths to find it.
                    object visual = null;
                    string foundVia = null;

                    // Path 1: MobileParty.Visuals (most common for mobile parties)
                    if (partyBase.MobileParty != null)
                    {
                        try
                        {
                            var visualsProp = partyBase.MobileParty.GetType().GetProperty("Visuals", flags);
                            visual = visualsProp?.GetValue(partyBase.MobileParty);
                            if (visual != null) foundVia = "MobileParty.Visuals";
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                    }

                    // Path 2: Try PartyBase itself (in case game version differs)
                    if (visual == null)
                    {
                        try
                        {
                            var visualsProp = partyBase.GetType().GetProperty("Visuals", flags);
                            visual = visualsProp?.GetValue(partyBase);
                            if (visual != null) foundVia = "PartyBase.Visuals";
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                    }

                    // Path 3: Try via PartyVisualManager accessor methods
                    if (visual == null && pvmType != null && pvmInstance != null)
                    {
                        try
                        {
                            foreach (var methodName in new[] { "GetPartyVisualForParty", "GetVisualForParty",
                                                               "GetPartyVisual" })
                            {
                                var getMethod = pvmType.GetMethod(methodName, flags);
                                if (getMethod != null && getMethod.GetParameters().Length == 1)
                                {
                                    var paramType = getMethod.GetParameters()[0].ParameterType;
                                    object arg = paramType == typeof(MobileParty) && partyBase.MobileParty != null
                                        ? (object)partyBase.MobileParty : (object)partyBase;
                                    visual = getMethod.Invoke(pvmInstance, new object[] { arg });
                                    if (visual != null)
                                    {
                                        foundVia = "PVM." + methodName;
                                        break;
                                    }
                                }
                            }
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                    }

                    // Path 4: Search PVM internal dictionary fields for the party visual.
                    // MobilePartyVisualManager stores visuals in a Dictionary<MobileParty, *>.
                    if (visual == null && pvmType != null && pvmInstance != null && partyBase.MobileParty != null)
                    {
                        try
                        {
                            // Search all fields on PVM hierarchy for Dictionary<MobileParty, *>
                            var searchType = pvmType;
                            while (searchType != null && visual == null)
                            {
                                foreach (var field in searchType.GetFields(flags))
                                {
                                    if (!field.FieldType.IsGenericType) continue;
                                    var genDef = field.FieldType.GetGenericTypeDefinition();
                                    if (genDef != typeof(Dictionary<,>)) continue;
                                    var keyType = field.FieldType.GetGenericArguments()[0];
                                    if (keyType != typeof(MobileParty)) continue;

                                    var dict = field.GetValue(pvmInstance);
                                    if (dict == null) continue;

                                    var containsKey = field.FieldType.GetMethod("ContainsKey");
                                    if (containsKey != null && (bool)containsKey.Invoke(dict, new object[] { partyBase.MobileParty }))
                                    {
                                        var indexer = field.FieldType.GetProperty("Item");
                                        var entry = indexer?.GetValue(dict, new object[] { partyBase.MobileParty });
                                        if (entry != null)
                                        {
                                            // The entry might be the visual directly, or a wrapper/tracker.
                                            // Check if it implements IPartyVisual or has a Visual property.
                                            var entryVisualProp = entry.GetType().GetProperty("Visual", flags)
                                                               ?? entry.GetType().GetProperty("PartyVisual", flags);
                                            if (entryVisualProp != null)
                                            {
                                                visual = entryVisualProp.GetValue(entry);
                                                foundVia = "PVM." + field.Name + "[].Visual";
                                            }
                                            else
                                            {
                                                // Entry itself might be the visual
                                                visual = entry;
                                                foundVia = "PVM." + field.Name + "[]";
                                            }
                                        }
                                    }
                                    if (visual != null) break;
                                }
                                searchType = searchType.BaseType;
                            }
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                    }

                    if (visual == null)
                    {
                        step4Null++;
                        string name = "?";
                        try
                        {
                            if (partyBase.MobileParty != null)
                                name = partyBase.MobileParty.Name?.ToString() ?? "mobile";
                            else if (partyBase.Settlement != null)
                                name = partyBase.Settlement.Name?.ToString() ?? "settlement";
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                        if (step4Null <= 3)
                            MCMSettings.DebugLog("  Step4: Visuals is null for " + name);

                        continue;
                    }

                    step4Processed++;
                    bool isMainParty = false;
                    try { isMainParty = partyBase.MobileParty == MobileParty.MainParty; } catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                    bool isSettlement = partyBase.Settlement != null && partyBase.MobileParty == null;

                    string tag = isMainParty ? " [MAIN PARTY]" : (isSettlement ? " [SETTLEMENT]" : "");
                    if (step4Processed <= 3)
                        MCMSettings.DebugLog("  Step4: found visual via " + foundVia + " type=" + visual.GetType().Name + tag);

                    // Try OnStartup(PartyBase) — reinitializes the entire visual including banner.
                    // This is the primary fix for the main party whose visual can't be Remove+Add'd.
                    try
                    {
                        var onStartup = visual.GetType().GetMethod("OnStartup", flags);
                        if (onStartup != null && onStartup.GetParameters().Length == 1)
                        {
                            onStartup.Invoke(visual, new object[] { partyBase });
                            MCMSettings.DebugLog("  Called OnStartup(partyBase) on " + visual.GetType().Name + tag);
                        }
                    }
                    catch (Exception ex)
                    {
                        MCMSettings.DebugLog("  OnStartup error: " + (ex.InnerException?.Message ?? ex.Message));
                    }

                    // Try zero-param methods as secondary approach
                    foreach (var methodName in new[] { "OnBannerChanged", "RefreshBanner", "SetMapIconAsDirty",
                                                       "RefreshPartyIcon" })
                    {
                        var method = visual.GetType().GetMethod(methodName, flags);
                        if (method != null && method.GetParameters().Length == 0)
                        {
                            try
                            {
                                method.Invoke(visual, null);
                                MCMSettings.DebugLog("  Called " + methodName + " on " + visual.GetType().Name + tag);
                            }
                            catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                        }
                    }

                }
                MCMSettings.DebugLog("Step4 summary: " + step4Processed + " processed, " + step4Null + " had null Visuals");
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("PartyVisual method refresh failed: " + (ex.InnerException?.Message ?? ex.Message));
            }

            // Step 5: Settlement-specific visual refresh.
            // Settlements render banner icons differently from mobile parties. They have
            // SettlementComponent objects and their own visual hierarchy. Try calling refresh
            // methods on Settlement objects directly.
            try
            {
                foreach (var pb in _pendingVisualRefreshParties)
                {
                    var partyBase = pb as PartyBase;
                    if (partyBase?.Settlement == null) continue;

                    var settlement = partyBase.Settlement;
                    string settleName = settlement.Name?.ToString() ?? "unknown";
                    MCMSettings.DebugLog("  Settlement refresh: " + settleName
                        + " (IsTown=" + settlement.IsTown + ", IsCastle=" + settlement.IsCastle
                        + ", IsVillage=" + settlement.IsVillage + ")");

                    // Try calling methods on Settlement itself
                    foreach (var methodName in new[] { "OnVisualChanged", "OnPartyVisualDirty",
                                                       "RefreshVisuals", "OnBannerChanged" })
                    {
                        var method = settlement.GetType().GetMethod(methodName, flags);
                        if (method != null && method.GetParameters().Length == 0)
                        {
                            try
                            {
                                method.Invoke(settlement, null);
                                MCMSettings.DebugLog("  Called " + methodName + " on Settlement " + settleName);
                            }
                            catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                        }
                    }

                    // Try refreshing via SettlementComponent
                    try
                    {
                        var compProp = settlement.GetType().GetProperty("SettlementComponent", flags);
                        if (compProp != null)
                        {
                            var comp = compProp.GetValue(settlement);
                            if (comp != null)
                            {
                                foreach (var methodName in new[] { "OnVisualChanged", "RefreshVisuals",
                                                                   "OnBannerChanged", "OnInit" })
                                {
                                    var method = comp.GetType().GetMethod(methodName, flags);
                                    if (method != null && method.GetParameters().Length == 0)
                                    {
                                        try
                                        {
                                            method.Invoke(comp, null);
                                            MCMSettings.DebugLog("  Called " + methodName
                                                + " on SettlementComponent " + comp.GetType().Name);
                                        }
                                        catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                                    }
                                }
                            }
                        }
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }

                    // Try accessing and refreshing the settlement's GateBanner / BannerVisual
                    try
                    {
                        foreach (var propName in new[] { "GateBanner", "Banner", "SettlementVisual" })
                        {
                            var prop = settlement.GetType().GetProperty(propName, flags);
                            if (prop != null && prop.CanRead)
                            {
                                var val = prop.GetValue(settlement);
                                if (val != null)
                                {
                                    MCMSettings.DebugLog("  Settlement." + propName + " = " + val.GetType().Name);
                                }
                            }
                        }
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Settlement visual refresh failed: " + (ex.InnerException?.Message ?? ex.Message));
            }

            // Step 6: Refresh settlement nameplate VMs on the campaign map via UIExtenderEx mixin.
            // The banner icon next to settlement names on the map is rendered by the nameplate
            // UI system — a set of VMs that each have a banner ImageIdentifier. These are
            // NOT refreshed by SetVisualAsDirty. The SettlementNameplateMixin tracks all
            // SettlementNameplateVM instances and can refresh their banner ImageIdentifiers.
            if (_pendingVisualRefreshClan != null)
            {
                try
                {
                    int nameplateCount = SettlementNameplateMixin.RefreshBannersForClan(
                        _pendingVisualRefreshClan, _pendingVisualRefreshBannerCode);
                    MCMSettings.DebugLog("Step6 UIExtenderEx: refreshed " + nameplateCount + " settlement nameplates");
                }
                catch (Exception ex)
                {
                    MCMSettings.DebugLog("Step6 UIExtenderEx mixin failed: " + (ex.InnerException?.Message ?? ex.Message));
                }

                // Fallback: also try the reflection-based approach via screen layers
                try
                {
                    RefreshSettlementNameplateBanners(_pendingVisualRefreshClan, _pendingVisualRefreshBannerCode, flags, staticFlags);
                }
                catch (Exception ex)
                {
                    MCMSettings.DebugLog("Step6 reflection fallback failed: " + (ex.InnerException?.Message ?? ex.Message));
                }
            }

            _pendingVisualRefreshParties.Clear();
            _pendingVisualRefreshClan = null;
            _pendingVisualRefreshBannerCode = null;
            MCMSettings.DebugLog("=== Deferred visual refresh complete ===");
        }


        /// <summary>
        /// Finds and refreshes settlement nameplate VMs on the campaign map so their
        /// banner icons update to the current clan banner. The nameplates are managed
        /// by the MapScreen's screen layers and use ImageIdentifier VMs for banners.
        /// </summary>
        private static void RefreshSettlementNameplateBanners(Clan targetClan, string bannerCode,
            System.Reflection.BindingFlags flags, System.Reflection.BindingFlags staticFlags)
        {
            MCMSettings.DebugLog("Step6: Refreshing settlement nameplate banners for " + targetClan.Name);

            // Strategy 1: Find SettlementNameplatesVM or similar type that holds nameplate VMs
            // and contains references to individual settlement nameplate VMs with banner ImageIdentifiers.
            var topScreen = ScreenManager.TopScreen;
            if (topScreen == null)
            {
                MCMSettings.DebugLog("Step6: TopScreen is null");
                return;
            }

            // Look through screen layers for any DataSource (VM) that contains settlement nameplates.
            // The DataSource property on a GauntletLayer holds the root ViewModel that drives the UI.
            int refreshedNameplates = 0;
            foreach (var layer in topScreen.Layers)
            {
                try
                {
                    // Get the DataSource (ViewModel) from the layer
                    var dsProp = layer.GetType().GetProperty("DataSource", flags);
                    if (dsProp == null) continue;

                    var ds = dsProp.GetValue(layer);
                    if (ds == null) continue;

                    // Search for properties that contain settlement nameplate collections
                    // Common patterns: Nameplates, SettlementNameplates, etc.
                    foreach (var prop in ds.GetType().GetProperties(flags))
                    {
                        try
                        {
                            bool isNameplateProp = prop.Name.IndexOf("Nameplate", StringComparison.OrdinalIgnoreCase) >= 0
                                || prop.Name.IndexOf("Settlement", StringComparison.OrdinalIgnoreCase) >= 0;
                            if (!isNameplateProp) continue;

                            var val = prop.GetValue(ds);
                            if (val == null) continue;

                            // If it's an enumerable, iterate through and update banner ImageIdentifiers
                            if (val is System.Collections.IEnumerable enumerable)
                            {
                                refreshedNameplates += UpdateNameplateImageIdentifiers(
                                    enumerable, targetClan, bannerCode, flags);
                            }
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                    }

                    // Also search fields (some VMs store collections in backing fields)
                    foreach (var field in ds.GetType().GetFields(flags))
                    {
                        try
                        {
                            bool isNameplateField = field.Name.IndexOf("Nameplate", StringComparison.OrdinalIgnoreCase) >= 0
                                || field.Name.IndexOf("nameplate", StringComparison.OrdinalIgnoreCase) >= 0;
                            if (!isNameplateField) continue;

                            var val = field.GetValue(ds);
                            if (val == null) continue;

                            if (val is System.Collections.IEnumerable enumerable)
                            {
                                refreshedNameplates += UpdateNameplateImageIdentifiers(
                                    enumerable, targetClan, bannerCode, flags);
                            }
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                    }

                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
            }

            MCMSettings.DebugLog("Step6: Updated " + refreshedNameplates + " settlement nameplate banners");
        }

        /// <summary>
        /// Iterates through a collection of nameplate VMs and updates banner ImageIdentifiers
        /// for settlements belonging to the target clan.
        /// </summary>
        private static int UpdateNameplateImageIdentifiers(
            System.Collections.IEnumerable nameplates, Clan targetClan, string bannerCode,
            System.Reflection.BindingFlags flags)
        {
            int updated = 0;

            // Create a fresh Banner from stored code to avoid stale clan.Banner
            Banner freshBanner = null;
            if (!string.IsNullOrEmpty(bannerCode))
            {
                try { freshBanner = new Banner(bannerCode); }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: UpdateNameplateImageIdentifiers exception: " + ex.ToString()); }
            }
            if (freshBanner == null)
                freshBanner = targetClan.Banner;

            foreach (var item in nameplates)
            {
                if (item == null) continue;

                try
                {
                    // Check if this nameplate belongs to the target clan
                    // Try Settlement property first
                    Settlement settlement = null;
                    try
                    {
                        var settlementProp = item.GetType().GetProperty("Settlement", flags);
                        settlement = settlementProp?.GetValue(item) as Settlement;
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }

                    if (settlement == null)
                    {
                        // Try other property names
                        foreach (var propName in new[] { "Obj", "SettlementObj" })
                        {
                            try
                            {
                                var prop = item.GetType().GetProperty(propName, flags);
                                settlement = prop?.GetValue(item) as Settlement;
                                if (settlement != null) break;
                            }
                            catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                        }
                    }

                    if (settlement == null || settlement.OwnerClan != targetClan) continue;

                    // Found a nameplate for one of our settlements. Update its banner ImageIdentifier.
                    bool thisUpdated = false;

                    // Look for ImageIdentifier / Banner properties
                    foreach (var propName in new[] { "ImageIdentifier", "BannerImageIdentifier",
                                                     "Faction", "Banner", "ClanBanner" })
                    {
                        try
                        {
                            var prop = item.GetType().GetProperty(propName, flags);
                            if (prop == null || !prop.CanRead) continue;

                            var propVal = prop.GetValue(item);
                            if (propVal == null) continue;

                            // If it's a Faction sub-VM with its own ImageIdentifier
                            if (propName == "Faction")
                            {
                                var imgProp = propVal.GetType().GetProperty("ImageIdentifier", flags);
                                if (imgProp != null && imgProp.CanWrite)
                                {
                                    var imgType = imgProp.PropertyType;
                                    var ctor = imgType.GetConstructor(new[] { typeof(Banner) })
                                            ?? imgType.GetConstructor(new[] { typeof(Banner), typeof(bool) });
                                    if (ctor != null)
                                    {
                                        var args = ctor.GetParameters().Length == 1
                                            ? new object[] { freshBanner }
                                            : new object[] { freshBanner, true };
                                        var newImg = ctor.Invoke(args);
                                        imgProp.SetValue(propVal, newImg);
                                        thisUpdated = true;
                                        MCMSettings.DebugLog("    Updated " + propName + ".ImageIdentifier on "
                                            + settlement.Name);
                                    }
                                }
                                continue;
                            }

                            // Direct ImageIdentifier property (BannerImageIdentifierVM)
                            if (prop.CanWrite && propVal.GetType().Name.Contains("ImageIdentifier"))
                            {
                                var imgType = propVal.GetType();
                                var ctor = imgType.GetConstructor(new[] { typeof(Banner) })
                                        ?? imgType.GetConstructor(new[] { typeof(Banner), typeof(bool) });
                                if (ctor != null)
                                {
                                    var args = ctor.GetParameters().Length == 1
                                        ? new object[] { freshBanner }
                                        : new object[] { freshBanner, true };
                                    var newImg = ctor.Invoke(args);
                                    prop.SetValue(item, newImg);
                                    thisUpdated = true;
                                    MCMSettings.DebugLog("    Updated " + propName + " on " + settlement.Name);
                                }
                            }
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                    }

                    // Also try calling refresh/notification methods on the nameplate VM
                    foreach (var methodName in new[] { "RefreshValues", "RefreshBinding",
                                                       "OnPropertyChanged" })
                    {
                        try
                        {
                            if (methodName == "OnPropertyChanged")
                            {
                                // Fire property changed for banner-related props
                                var opc = item.GetType().GetMethod("OnPropertyChanged",
                                    flags, null, new[] { typeof(string) }, null);
                                if (opc != null)
                                {
                                    opc.Invoke(item, new object[] { "ImageIdentifier" });
                                    opc.Invoke(item, new object[] { "Faction" });
                                    opc.Invoke(item, new object[] { "Banner" });
                                }
                            }
                            else
                            {
                                var m = item.GetType().GetMethod(methodName, flags);
                                if (m != null && m.GetParameters().Length == 0)
                                {
                                    m.Invoke(item, null);
                                    MCMSettings.DebugLog("    Called " + methodName + " on nameplate for "
                                        + settlement.Name);
                                }
                            }
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                    }

                    if (thisUpdated) updated++;
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
            }

            return updated;
        }

        /// <summary>
        /// Calls SetMapIconAsDirty() on a PartyBase's Visuals object (IPartyVisual).
        /// This is the correct way to invalidate campaign map icons for BOTH mobile
        /// parties AND settlements (pattern from KingdomColor mod).
        /// Falls back to SetVisualAsDirty() on PartyBase if SetMapIconAsDirty is not found.
        /// </summary>
        private static void SetMapIconAsDirtyOnParty(PartyBase party, System.Reflection.BindingFlags flags)
        {
            // Try to find the party visual and call SetMapIconAsDirty on it.
            // The Visuals property is on MobileParty, not PartyBase.
            object visual = null;

            // Path 1: MobileParty.Visuals (for mobile parties)
            if (party.MobileParty != null)
            {
                try
                {
                    var visualsProp = party.MobileParty.GetType().GetProperty("Visuals", flags);
                    visual = visualsProp?.GetValue(party.MobileParty);
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: SetMapIconAsDirtyOnParty exception: " + ex.ToString()); }
            }

            // Path 2: Try PartyBase.Visuals (fallback)
            if (visual == null)
            {
                try
                {
                    var visualsProp = party.GetType().GetProperty("Visuals", flags);
                    visual = visualsProp?.GetValue(party);
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: SetMapIconAsDirtyOnParty exception: " + ex.ToString()); }
            }

            // Call SetMapIconAsDirty if we found a visual
            if (visual != null)
            {
                try
                {
                    var setDirtyMethod = visual.GetType().GetMethod("SetMapIconAsDirty", flags);
                    if (setDirtyMethod != null && setDirtyMethod.GetParameters().Length == 0)
                    {
                        setDirtyMethod.Invoke(visual, null);
                        return;
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
            }

            // Fallback: PartyBase.SetVisualAsDirty()
            try
            {
                var setDirty = party.GetType().GetMethod("SetVisualAsDirty", flags);
                if (setDirty != null) setDirty.Invoke(party, null);
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
        }

        // ── Banner Watchdog ──────────────────────────────────────
        // Periodically checks if the game has overwritten custom banners
        // (e.g., kingdom color reset in 1.3.13) and re-applies them.

        private static int _watchdogFrameCounter = 0;
        private const int WATCHDOG_INTERVAL_FRAMES = 300; // ~5 seconds at 60fps

        // Deferred full banner re-apply after save load
        private static int _reapplyDelayFrames = -1;

        // Secondary visual-only refresh after save load (longer delay to ensure visuals are ready)
        private static int _postLoadVisualRefreshFrames = -1;

        /// <summary>
        /// Called from OnApplicationTick. Periodically checks custom banners
        /// and re-applies any that have been silently overwritten by the game.
        /// Also handles one-time full banner re-apply after save load.
        /// </summary>
        public static void TickBannerWatchdog()
        {
            // Handle deferred full re-apply after save load
            if (_reapplyDelayFrames > 0)
            {
                _reapplyDelayFrames--;
                return;
            }
            if (_reapplyDelayFrames == 0)
            {
                _reapplyDelayFrames = -1;
                ReapplyAllCustomBannersOnLoad();
                // Schedule a secondary visual-only refresh with a longer delay
                // to ensure the campaign map visual system is fully initialized
                _postLoadVisualRefreshFrames = 300; // ~5 seconds after initial re-apply
                return;
            }

            // Handle secondary visual-only refresh after save load
            if (_postLoadVisualRefreshFrames > 0)
            {
                _postLoadVisualRefreshFrames--;
            }
            if (_postLoadVisualRefreshFrames == 0)
            {
                _postLoadVisualRefreshFrames = -1;
                RefreshAllCustomBannerVisuals();
            }

            // Check if a full re-apply was requested (set by SyncData after loading save)
            if (EncyclopediaEditBehavior.NeedsBannerReapply)
            {
                EncyclopediaEditBehavior.NeedsBannerReapply = false;
                _reapplyDelayFrames = 120; // Wait ~2 seconds for game to fully initialize
                MCMSettings.DebugLog("Banner re-apply scheduled (120 frame delay)");
                return;
            }

            _watchdogFrameCounter++;
            if (_watchdogFrameCounter < WATCHDOG_INTERVAL_FRAMES) return;
            _watchdogFrameCounter = 0;

            try
            {
                // Check if the setting is enabled
                var settings = MCMSettings.Instance;
                if (settings != null && !settings.PreventKingdomColorOverwrites) return;

                var behavior = EncyclopediaEditBehavior.Instance;
                if (behavior == null) return;

                // Check all stored custom banner codes
                var flags = System.Reflection.BindingFlags.Instance
                          | System.Reflection.BindingFlags.Public
                          | System.Reflection.BindingFlags.NonPublic;

                // Access the _customBannerCodes dictionary via reflection
                var codesField = typeof(EncyclopediaEditBehavior).GetField("_customBannerCodes", flags);
                if (codesField == null) return;

                var codes = codesField.GetValue(behavior) as Dictionary<string, string>;
                if (codes == null || codes.Count == 0) return;

                foreach (var kvp in codes)
                {
                    // Skip "origbanner_" prefix keys — those are backup originals
                    if (kvp.Key.StartsWith("origbanner_")) continue;
                    if (string.IsNullOrEmpty(kvp.Value)) continue;

                    string objectId = kvp.Key;
                    string expectedCode = kvp.Value;

                    try
                    {
                        // Find the clan this banner belongs to
                        Clan targetClan = null;

                        // Try as hero first
                        var hero = Hero.FindFirst(h => h.StringId == objectId);
                        if (hero?.Clan != null)
                        {
                            targetClan = hero.Clan;
                        }
                        else
                        {
                            // Try as clan
                            targetClan = Clan.FindFirst(c => c.StringId == objectId);
                        }

                        if (targetClan?.Banner == null) continue;

                        // Check if the banner still matches
                        string currentCode = targetClan.Banner.Serialize();
                        if (currentCode == expectedCode)
                        {
                            // Banner matches — clear the "already logged" flag so we
                            // log again if it gets overwritten in the future
                            _watchdogAlreadyLogged.Remove(objectId);
                            continue;
                        }

                        // Banner was overwritten! Re-apply.
                        // Only log the first detection to avoid spamming every 5 seconds.
                        if (!_watchdogAlreadyLogged.Contains(objectId))
                        {
                            _watchdogAlreadyLogged.Add(objectId);
                            MCMSettings.DebugLog("Watchdog: Banner overwritten for " + objectId
                                + " (clan=" + targetClan.Name + "), re-applying. Suppressing future logs for this banner.");
                        }

                        // Round 4 finding N-C1: malformed banner code can throw inside Deserialize;
                        // wrap to keep the watchdog patch from propagating exceptions and to keep
                        // Deserialize+cache-clear atomic (no clear if Deserialize throws).
                        try
                        {
                            targetClan.Banner.Deserialize(expectedCode);

                            // Clear the banner visual cache so it regenerates
                            var bannerVisualField = typeof(Banner).GetField("_bannerVisual", flags);
                            if (bannerVisualField != null)
                                bannerVisualField.SetValue(targetClan.Banner, null);
                        }
                        catch (Exception bex)
                        {
                            MCMSettings.DebugLog("Watchdog: Banner.Deserialize failed for " + objectId + ": " + bex.ToString());
                        }

                        // Mark all parties belonging to this clan as visually dirty
                        // so the campaign map redraws their banner icons.
                        // Use party.Party.Visuals?.SetMapIconAsDirty() which works for
                        // BOTH mobile parties AND settlements (from KingdomColor mod pattern).
                        try
                        {
                            foreach (var mp in MobileParty.All)
                            {
                                try
                                {
                                    bool belongs = false;
                                    try { belongs = mp.ActualClan == targetClan; } catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                                    if (!belongs)
                                        try { belongs = mp.Party?.Owner?.Clan == targetClan; } catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }

                                    if (belongs && mp.Party != null)
                                    {
                                        SetMapIconAsDirtyOnParty(mp.Party, flags);
                                    }
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                            }

                            // Also mark settlement parties as dirty
                            foreach (var settlement in Settlement.All)
                            {
                                try
                                {
                                    if (settlement.OwnerClan == targetClan && settlement.Party != null)
                                    {
                                        SetMapIconAsDirtyOnParty(settlement.Party, flags);
                                    }
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                            }
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
        }

        /// <summary>
        /// Re-applies all custom banners after a save game is loaded.
        /// Creates new Banner objects (instead of Deserialize) to properly invalidate
        /// the rendering cache which is keyed by object identity.
        /// </summary>
        private static void ReapplyAllCustomBannersOnLoad()
        {
            try
            {
                var behavior = EncyclopediaEditBehavior.Instance;
                if (behavior == null) return;

                var flags = System.Reflection.BindingFlags.Instance
                          | System.Reflection.BindingFlags.Public
                          | System.Reflection.BindingFlags.NonPublic;

                var codesField = typeof(EncyclopediaEditBehavior).GetField("_customBannerCodes", flags);
                if (codesField == null) return;

                var codes = codesField.GetValue(behavior) as Dictionary<string, string>;
                if (codes == null || codes.Count == 0) return;

                int applied = 0;

                foreach (var kvp in codes)
                {
                    if (kvp.Key.StartsWith("origbanner_")) continue;
                    if (string.IsNullOrEmpty(kvp.Value)) continue;

                    string objectId = kvp.Key;
                    string bannerCode = kvp.Value;

                    try
                    {
                        Clan targetClan = null;

                        // Try as hero
                        var hero = Hero.FindFirst(h => h.StringId == objectId);
                        if (hero?.Clan != null)
                            targetClan = hero.Clan;

                        // Try as clan
                        if (targetClan == null)
                            targetClan = Clan.FindFirst(c => c.StringId == objectId);

                        // Try as settlement (e.g., castle_N4, town_N3)
                        if (targetClan == null)
                        {
                            foreach (var s in Settlement.All)
                            {
                                if (s.StringId == objectId)
                                {
                                    targetClan = s.OwnerClan;
                                    if (targetClan != null)
                                        MCMSettings.DebugLog("Banner re-apply: matched settlement " + s.Name + " → clan " + targetClan.Name);
                                    break;
                                }
                            }
                        }

                        // Try as kingdom
                        if (targetClan == null)
                        {
                            foreach (var k in Kingdom.All)
                            {
                                if (k.StringId == objectId && k.Banner != null)
                                {
                                    ReplaceBannerOnObject(k, bannerCode, flags);
                                    applied++;
                                    break;
                                }
                            }
                            continue;
                        }

                        if (targetClan?.Banner == null) continue;

                        ReplaceBannerOnObject(targetClan, bannerCode, flags);

                        // Mark all parties belonging to this clan as dirty
                        foreach (var mp in MobileParty.All)
                        {
                            try
                            {
                                bool belongs = false;
                                try { belongs = mp.ActualClan == targetClan; } catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                                if (!belongs)
                                    try { belongs = mp.Party?.Owner?.Clan == targetClan; } catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }

                                if (belongs && mp.Party != null)
                                {
                                    SetMapIconAsDirtyOnParty(mp.Party, flags);
                                }
                            }
                            catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                        }

                        // Also mark settlement parties as dirty
                        try
                        {
                            foreach (var settlement in Settlement.All)
                            {
                                try
                                {
                                    if (settlement.OwnerClan == targetClan && settlement.Party != null)
                                        SetMapIconAsDirtyOnParty(settlement.Party, flags);
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                            }
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }

                        applied++;
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                }

                MCMSettings.DebugLog("Re-applied " + applied + " custom banner(s) after save load");
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Banner re-apply on load failed: " + ex.ToString());
            }
        }

        /// <summary>
        /// Secondary visual-only refresh: re-applies banner data and marks all parties
        /// with custom banners as visually dirty. Called with a longer delay after save load
        /// to ensure the campaign map visual system is fully initialized.
        /// </summary>
        private static void RefreshAllCustomBannerVisuals()
        {
            try
            {
                var behavior = EncyclopediaEditBehavior.Instance;
                if (behavior == null) return;

                var flags = System.Reflection.BindingFlags.Instance
                          | System.Reflection.BindingFlags.Public
                          | System.Reflection.BindingFlags.NonPublic;

                var codesField = typeof(EncyclopediaEditBehavior).GetField("_customBannerCodes", flags);
                if (codesField == null) return;

                var codes = codesField.GetValue(behavior) as Dictionary<string, string>;
                if (codes == null || codes.Count == 0) return;

                int refreshed = 0;

                // Collect all clans with custom banners
                var affectedClans = new HashSet<Clan>();

                foreach (var kvp in codes)
                {
                    if (kvp.Key.StartsWith("origbanner_")) continue;
                    if (string.IsNullOrEmpty(kvp.Value)) continue;

                    try
                    {
                        string objectId = kvp.Key;
                        string expectedCode = kvp.Value;
                        Clan targetClan = null;

                        var hero = Hero.FindFirst(h => h.StringId == objectId);
                        if (hero?.Clan != null)
                            targetClan = hero.Clan;

                        if (targetClan == null)
                            targetClan = Clan.FindFirst(c => c.StringId == objectId);

                        // Try as settlement (e.g., castle_N4, town_N3)
                        if (targetClan == null)
                        {
                            foreach (var s in Settlement.All)
                            {
                                if (s.StringId == objectId)
                                {
                                    targetClan = s.OwnerClan;
                                    break;
                                }
                            }
                        }

                        if (targetClan?.Banner == null) continue;

                        // Re-apply if the game has overwritten since the initial re-apply
                        string currentCode = targetClan.Banner.Serialize();
                        if (currentCode != expectedCode)
                        {
                            targetClan.Banner.Deserialize(expectedCode);
                            var bvField = typeof(Banner).GetField("_bannerVisual", flags);
                            if (bvField != null) bvField.SetValue(targetClan.Banner, null);
                        }

                        affectedClans.Add(targetClan);
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                }

                // Mark all parties belonging to affected clans as visually dirty
                // Uses SetMapIconAsDirty on Visuals (KingdomColor pattern) for reliable refresh
                foreach (var mp in MobileParty.All)
                {
                    try
                    {
                        Clan partyClan = null;
                        try { partyClan = mp.ActualClan; } catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                        if (partyClan == null)
                            try { partyClan = mp.Party?.Owner?.Clan; } catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }

                        if (partyClan != null && affectedClans.Contains(partyClan) && mp.Party != null)
                        {
                            SetMapIconAsDirtyOnParty(mp.Party, flags);
                            refreshed++;
                        }
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                }

                // Also mark settlement parties as visually dirty
                foreach (var settlement in Settlement.All)
                {
                    try
                    {
                        if (settlement.OwnerClan != null && affectedClans.Contains(settlement.OwnerClan)
                            && settlement.Party != null)
                        {
                            SetMapIconAsDirtyOnParty(settlement.Party, flags);
                            refreshed++;
                        }
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                }

                MCMSettings.DebugLog("Post-load visual refresh: marked " + refreshed + " party visuals as dirty (incl. settlements)");
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Post-load visual refresh failed: " + ex.ToString());
            }
        }

        /// <summary>
        /// Creates a new Banner object and replaces it on the target (Clan or Kingdom)
        /// via property setter or backing field reflection.
        /// </summary>
        private static void ReplaceBannerOnObject(object target, string bannerCode, System.Reflection.BindingFlags flags)
        {
            // Round 4 finding N-C1: malformed banner code can throw in the Banner ctor.
            Banner newBanner;
            try { newBanner = new Banner(bannerCode); }
            catch (Exception bex)
            {
                MCMSettings.DebugLog("ReplaceBannerOnObject: Banner ctor failed for code='"
                    + bannerCode + "': " + bex.ToString());
                return;
            }
            bool replaced = false;

            // Try property setter
            var bannerProp = target.GetType().GetProperty("Banner", flags);
            if (bannerProp != null && bannerProp.CanWrite)
            {
                bannerProp.SetValue(target, newBanner);
                replaced = true;
            }

            // Try backing fields
            if (!replaced)
            {
                foreach (var fn in new[] { "_banner", "<Banner>k__BackingField", "m_banner", "banner" })
                {
                    var field = target.GetType().GetField(fn, flags);
                    if (field != null && field.FieldType == typeof(Banner))
                    {
                        field.SetValue(target, newBanner);
                        replaced = true;
                        break;
                    }
                }
            }

            // Search all Banner-typed fields
            if (!replaced)
            {
                foreach (var field in target.GetType().GetFields(flags))
                {
                    if (field.FieldType == typeof(Banner))
                    {
                        field.SetValue(target, newBanner);
                        replaced = true;
                        break;
                    }
                }
            }

            // Last resort: Deserialize into existing + clear visual cache
            if (!replaced)
            {
                var existingBanner = bannerProp?.GetValue(target) as Banner;
                if (existingBanner != null)
                {
                    // Round 4 finding N-C1: keep Deserialize+cache-clear atomic.
                    try
                    {
                        existingBanner.Deserialize(bannerCode);
                        var bvField = typeof(Banner).GetField("_bannerVisual", flags);
                        if (bvField != null) bvField.SetValue(existingBanner, null);
                    }
                    catch (Exception bex)
                    {
                        MCMSettings.DebugLog("ReplaceBannerOnObject: last-resort Deserialize failed for code='"
                            + bannerCode + "': " + bex.ToString());
                    }
                }
            }
        }

        public static void TryOpen()
        {
            if (_popupOpen) return;
            if (EncyclopediaEditBehavior.Instance == null) return;
            if (string.IsNullOrEmpty(EncyclopediaPageTracker.CurrentObjectId)) return;

            // Check MCM setting
            try
            {
                var settings = MCMSettings.Instance;
                if (settings != null && !settings.EnableBannerEditing) return;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: TryOpen exception: " + ex.ToString()); }

            EncyclopediaInputBlocker.Block();
            string objectId = EncyclopediaPageTracker.CurrentObjectId;
            string pageType = EncyclopediaPageTracker.CurrentPageType;

            // Get the current banner code for this entity
            string currentCode = EncyclopediaEditBehavior.Instance.GetCustomBannerCode(objectId);
            if (string.IsNullOrEmpty(currentCode))
            {
                currentCode = GetCurrentBannerCode(objectId, pageType);
            }

            // Store original banner code for reset support
            if (EncyclopediaEditBehavior.Instance != null)
            {
                try
                {
                    string origCode = GetCurrentBannerCode(objectId, pageType);
                    EncyclopediaEditBehavior.Instance.StoreOriginalBannerCode(objectId, origCode);
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
            }

            _popupOpen = true;

            MCMSettings.DebugLog("Opening banner edit popup for " + objectId + " (type=" + pageType + ")");

            // Check clipboard/file for a banner code first (bypasses text input character limit).
            // Complex banners from bannerlord.party can have 10,000+ characters which the
            // game's text input dialog truncates, showing a broken banner.
            string clipboardText = null;
            try { clipboardText = GetClipboardText()?.Trim(); } catch (Exception ex)
            {
                MCMSettings.DebugLog("GetClipboardText exception: " + ex.ToString());
            }

            MCMSettings.DebugLog("Clipboard result: " + (clipboardText == null ? "null" : clipboardText.Length + " chars")
                + ", looks like banner: " + LooksLikeBannerCode(clipboardText));

            if (!string.IsNullOrEmpty(clipboardText) && LooksLikeBannerCode(clipboardText))
            {
                string preview = clipboardText.Length > 60
                    ? clipboardText.Substring(0, 60) + "... (" + clipboardText.Length + " chars)"
                    : clipboardText;

                InformationManager.ShowInquiry(
                    new InquiryData(
                        Localization.L("banner_paste_title"),
                        Localization.L("banner_paste_desc", clipboardText.Length, preview),
                        true,
                        true,
                        Localization.L("banner_paste_apply"),
                        Localization.L("banner_paste_manual"),
                        delegate()
                        {
                            OnBannerCodeConfirmed(objectId, pageType, clipboardText);
                        },
                        delegate()
                        {
                            // User wants to type manually — fall through to text input
                            ShowBannerTextInput(objectId, pageType, currentCode);
                        }
                    ),
                    false);
                return;
            }

            // No clipboard/file banner code found — show text input dialog.
            // Note: For very long banner codes, the text input may truncate.
            // As a workaround, save the code to banner_import.txt in the mod's DLL folder.
            if (clipboardText == null || !LooksLikeBannerCode(clipboardText))
            {
                MCMSettings.DebugLog("No banner code in clipboard/file. Falling back to text input. "
                    + "For long codes, save to banner_import.txt in mod DLL folder.");
            }
            ShowBannerTextInput(objectId, pageType, currentCode);
        }

        private static void ShowBannerTextInput(string objectId, string pageType, string currentCode)
        {
            EEInquiry.Show(
                new TextInquiryData(
                    Localization.L("banner_edit_title"),
                    currentCode ?? "",
                    true,
                    true,
                    Localization.L("edit_save"),
                    Localization.L("edit_cancel"),
                    delegate (string newCode)
                    {
                        OnBannerCodeConfirmed(objectId, pageType, newCode);
                    },
                    delegate
                    {
                        _popupOpen = false;
                        EncyclopediaInputBlocker.Unblock();
                        MCMSettings.DebugLog("Banner edit cancelled for " + objectId);
                    },
                    false,
                    null
                ),
                false,
                false);

            EncyclopediaNavigationGuard.ScheduleNavigateBack();
        }

        private static void OnBannerCodeConfirmed(string objectId, string pageType, string newCode)
        {
            _popupOpen = false;
            EncyclopediaInputBlocker.Unblock();

            string trimmed = newCode?.Trim();
            string activeBannerCode = null;
            if (string.IsNullOrEmpty(trimmed))
            {
                // Clear custom banner — restore original
                EncyclopediaEditBehavior.Instance.SetCustomBannerCode(objectId, null);
                string origCode = EncyclopediaEditBehavior.Instance.GetOriginalBannerCode(objectId);
                if (!string.IsNullOrEmpty(origCode))
                {
                    ApplyBannerCode(objectId, pageType, origCode);
                    activeBannerCode = origCode;
                }
            }
            else
            {
                // Validate banner code format before passing to Banner constructor.
                // The Banner constructor can crash the game engine (not just throw)
                // if given non-numeric text like regular words or sentences.
                // This is a native crash that try/catch CANNOT intercept, so we must
                // reject any non-numeric content before it reaches the constructor.
                if (!LooksLikeBannerCode(trimmed))
                {
                    InformationManager.DisplayMessage(
                        new InformationMessage(Localization.L("msg_banner_invalid"), Colors.Red));
                    return;
                }

                // Double-check: ensure every character is a digit, dot, minus sign, or whitespace.
                // This guards against edge cases that LooksLikeBannerCode might miss.
                foreach (char c in trimmed)
                {
                    if (!char.IsDigit(c) && c != '.' && c != '-' && !char.IsWhiteSpace(c))
                    {
                        InformationManager.DisplayMessage(
                            new InformationMessage(Localization.L("msg_banner_invalid"), Colors.Red));
                        return;
                    }
                }

                try
                {
                    new Banner(trimmed);
                }
                catch (Exception ex)
                {
                    MCMSettings.DebugLog("Patches: Banner validation exception: " + ex.ToString());
                    InformationManager.DisplayMessage(
                        new InformationMessage(Localization.L("msg_banner_invalid"), Colors.Red));
                    return;
                }

                MCMSettings.DebugLog("Storing banner code: " + trimmed.Length + " chars, "
                    + trimmed.Split('.').Length + " segments (first 80: " + trimmed.Substring(0, Math.Min(80, trimmed.Length)) + ")");
                EncyclopediaEditBehavior.Instance.SetCustomBannerCode(objectId, trimmed);
                ApplyBannerCode(objectId, pageType, trimmed);
                activeBannerCode = trimmed;

                // Verify the stored code matches what we just set
                string verifyCode = EncyclopediaEditBehavior.Instance.GetCustomBannerCode(objectId);
                MCMSettings.DebugLog("Verify stored code: " + (verifyCode?.Length ?? 0) + " chars, matches: " + (verifyCode == trimmed));
            }

            MCMSettings.DebugLog("Banner saved for " + objectId + " (" + (trimmed?.Length ?? 0) + " chars)");

            // Clear watchdog suppression so it re-logs if the game overwrites this new code
            _watchdogAlreadyLogged.Remove(objectId);

            bool showConfirm = true;
            try
            {
                var settings = MCMSettings.Instance;
                if (settings != null) showConfirm = settings.ShowConfirmationMessages;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }

            if (showConfirm)
            {
                InformationManager.DisplayMessage(
                    new InformationMessage(Localization.L("msg_banner_updated"), Colors.Green));
                InformationManager.DisplayMessage(
                    new InformationMessage(Localization.L("msg_banner_scene_hint"),
                        new Color(1f, 0.9f, 0.2f)));
            }
            // Map nameplate banner can't be refreshed mid-game (Gauntlet widget limitation)
            try
            {
                InformationManager.DisplayMessage(new InformationMessage(
                    "Map banner will update after saving & reloading, or pressing Esc \u2192 Options \u2192 Back.",
                    TaleWorlds.Library.Colors.Gray));
            }
            catch { }

            // Refresh the page to show the updated banner
            EncyclopediaPatchHelper._isApplyingBanner = true;
            try
            {
                var refresh = EncyclopediaPageTracker.CurrentRefreshAction;
                if (refresh != null)
                {
                    try { refresh(); } catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                }
            }
            finally
            {
                EncyclopediaPatchHelper._isApplyingBanner = false;
            }

            ForceRefreshBannerVisual(pageType, activeBannerCode);

            try
            {
                var updateTs = EncyclopediaPageTracker.CurrentUpdateTimestampAction;
                if (updateTs != null) updateTs();
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
        }

        /// <summary>
        /// Gets the current (game-state) banner code for the given entity.
        /// </summary>
        private static string GetCurrentBannerCode(string objectId, string pageType)
        {
            try
            {
                if (pageType == "Hero")
                {
                    var hero = EncyclopediaPageTracker.CurrentHero;
                    if (hero?.Clan?.Banner != null)
                        return hero.Clan.Banner.Serialize();
                }
                else if (pageType == "Clan")
                {
                    var clan = Clan.FindFirst(c => c.StringId == objectId);
                    if (clan?.Banner != null)
                        return clan.Banner.Serialize();
                }
                else if (pageType == "Kingdom")
                {
                    foreach (var k in Kingdom.All)
                    {
                        if (k.StringId == objectId && k.Banner != null)
                            return k.Banner.Serialize();
                    }
                }
                else if (pageType == "Settlement")
                {
                    var settlement = Settlement.Find(objectId);
                    if (settlement?.OwnerClan?.Banner != null)
                        return settlement.OwnerClan.Banner.Serialize();
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
            return null;
        }

        /// <summary>
        /// Applies a banner code to the game object.
        /// </summary>
        public static void ApplyBannerCode(string objectId, string pageType, string bannerCode)
        {
            try
            {
                // Create a completely new Banner object — do NOT reuse the existing one.
                // The game's rendering pipeline caches banner textures by object identity,
                // so Deserialize() on the existing Banner won't invalidate the visual cache.
                // Round 4 finding N-C1: malformed banner code can throw in the Banner ctor.
                Banner newBanner;
                try { newBanner = new Banner(bannerCode); }
                catch (Exception bex)
                {
                    MCMSettings.DebugLog("ApplyBannerToTarget: Banner ctor failed for code='"
                        + bannerCode + "': " + bex.ToString());
                    return;
                }

                var flags = System.Reflection.BindingFlags.Instance
                          | System.Reflection.BindingFlags.Public
                          | System.Reflection.BindingFlags.NonPublic;

                object targetObj = null; // The object that owns the Banner (Clan, Kingdom, etc.)

                if (pageType == "Hero")
                {
                    var hero = EncyclopediaPageTracker.CurrentHero;
                    targetObj = hero?.Clan;
                }
                else if (pageType == "Clan")
                {
                    targetObj = Clan.FindFirst(c => c.StringId == objectId);
                }
                else if (pageType == "Kingdom")
                {
                    foreach (var k in Kingdom.All)
                    {
                        if (k.StringId == objectId)
                        {
                            targetObj = k;
                            break;
                        }
                    }
                }
                else if (pageType == "Settlement")
                {
                    var settlement = Settlement.Find(objectId);
                    targetObj = settlement?.OwnerClan;
                }

                if (targetObj == null)
                {
                    MCMSettings.DebugLog("ApplyBannerCode: target object not found for " + pageType + " " + objectId);
                    return;
                }

                // Try to REPLACE the Banner object entirely (not just modify in-place)
                bool replaced = false;

                // Try setting via property setter first
                var bannerProp = targetObj.GetType().GetProperty("Banner", flags);
                if (bannerProp != null && bannerProp.CanWrite)
                {
                    bannerProp.SetValue(targetObj, newBanner);
                    replaced = true;
                    MCMSettings.DebugLog("Replaced Banner via property setter on " + targetObj.GetType().Name);
                }

                // Try setting via backing field if property is read-only
                if (!replaced)
                {
                    // Common backing field names: _banner, <Banner>k__BackingField, m_banner
                    string[] fieldNames = { "_banner", "<Banner>k__BackingField", "m_banner", "banner" };
                    foreach (var fieldName in fieldNames)
                    {
                        var field = targetObj.GetType().GetField(fieldName, flags);
                        if (field != null && field.FieldType == typeof(Banner))
                        {
                            field.SetValue(targetObj, newBanner);
                            replaced = true;
                            MCMSettings.DebugLog("Replaced Banner via field '" + fieldName + "' on " + targetObj.GetType().Name);
                            break;
                        }
                    }
                }

                // If we still couldn't replace, search ALL fields of type Banner
                if (!replaced)
                {
                    foreach (var field in targetObj.GetType().GetFields(flags))
                    {
                        if (field.FieldType == typeof(Banner))
                        {
                            field.SetValue(targetObj, newBanner);
                            replaced = true;
                            MCMSettings.DebugLog("Replaced Banner via field '" + field.Name + "' on " + targetObj.GetType().Name);
                            break;
                        }
                    }
                }

                // Last resort: Deserialize into existing Banner (old approach)
                if (!replaced)
                {
                    if (bannerProp != null && bannerProp.CanRead)
                    {
                        var existingBanner = bannerProp.GetValue(targetObj) as Banner;
                        if (existingBanner != null)
                        {
                            // Round 4 finding N-C1: malformed code can throw inside Deserialize.
                            try
                            {
                                existingBanner.Deserialize(bannerCode);
                                MCMSettings.DebugLog("Fallback: Deserialized into existing Banner (no setter/field found)");
                            }
                            catch (Exception bex)
                            {
                                MCMSettings.DebugLog("Fallback Deserialize failed for code='" + bannerCode + "': " + bex.ToString());
                            }
                        }
                    }
                }

                // Verify and ensure the stored Banner has the right data.
                // The Clan.Banner setter may create a copy (storedBanner != newBanner).
                // In that case, also Deserialize into the copy so the data is correct.
                Banner storedBanner = bannerProp?.GetValue(targetObj) as Banner;
                if (storedBanner != null)
                {
                    bool sameObject = object.ReferenceEquals(storedBanner, newBanner);
                    MCMSettings.DebugLog("Applied banner to " + pageType + " " + objectId + " (replaced=" + replaced + ")");
                    MCMSettings.DebugLog("  Stored: " + storedBanner.Serialize());
                    MCMSettings.DebugLog("  Same object as newBanner: " + sameObject);

                    // If the setter created a copy, Deserialize our code into the actual stored banner
                    // so the game's internal reference has the correct data
                    if (!sameObject)
                    {
                        // Round 4 finding N-C1: malformed code can throw in Deserialize.
                        try
                        {
                            storedBanner.Deserialize(bannerCode);
                            // Clear the visual cache on the stored banner
                            try
                            {
                                var bvField = typeof(Banner).GetField("_bannerVisual", flags);
                                if (bvField != null) bvField.SetValue(storedBanner, null);
                            }
                            catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                            MCMSettings.DebugLog("  Also deserialized into stored Banner copy + cleared visual cache");
                        }
                        catch (Exception bex)
                        {
                            MCMSettings.DebugLog("  storedBanner.Deserialize failed for code='" + bannerCode + "': " + bex.ToString());
                        }
                    }
                }

                // Mark party/settlement visuals dirty so the campaign map shows the new banner.
                // Note: Do NOT call ClearBannerTextureCache() / ClearManager() here.
                // That destroys game-wide tableau state and causes crashes on settlement entry.
                // Pass the bannerCode so the deferred refresh can create fresh Banner objects
                // from the stored code rather than reading from clan.Banner (which the game may revert).
                RefreshMapBannerVisuals(pageType, objectId, bannerCode);
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Failed to apply banner: " + ex.ToString());
                InformationManager.DisplayMessage(
                    new InformationMessage(Localization.L("msg_banner_invalid"), Colors.Red));
            }
        }

        /// <summary>
        /// Clears the engine's banner texture cache so that changed banners render fresh.
        /// Uses BannerlordTableauManager.ClearManager() and TextureProviderFactory.RefreshProviderTypes().
        /// </summary>
        private static void ClearBannerTextureCache()
        {
            var staticFlags = System.Reflection.BindingFlags.Static
                            | System.Reflection.BindingFlags.Public
                            | System.Reflection.BindingFlags.NonPublic;

            // Strategy 1: BannerlordTableauManager.ClearManager()
            try
            {
                Type btmType = null;
                foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                {
                    try
                    {
                        foreach (var t in asm.GetTypes())
                        {
                            if (t.Name == "BannerlordTableauManager")
                            {
                                btmType = t;
                                break;
                            }
                        }
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: ClearBannerTextureCache exception: " + ex.ToString()); }
                    if (btmType != null) break;
                }

                if (btmType != null)
                {
                    var clearMethod = btmType.GetMethod("ClearManager", staticFlags);
                    if (clearMethod != null && clearMethod.GetParameters().Length == 0)
                    {
                        clearMethod.Invoke(null, null);
                        MCMSettings.DebugLog("Called BannerlordTableauManager.ClearManager()");
                    }
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("BannerlordTableauManager.ClearManager failed: " + (ex.InnerException?.Message ?? ex.Message));
            }

            // Strategy 2: TextureProviderFactory.RefreshProviderTypes()
            try
            {
                Type tpfType = null;
                foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                {
                    try
                    {
                        foreach (var t in asm.GetTypes())
                        {
                            if (t.Name == "TextureProviderFactory")
                            {
                                tpfType = t;
                                break;
                            }
                        }
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                    if (tpfType != null) break;
                }

                if (tpfType != null)
                {
                    var refreshMethod = tpfType.GetMethod("RefreshProviderTypes", staticFlags);
                    if (refreshMethod != null && refreshMethod.GetParameters().Length == 0)
                    {
                        refreshMethod.Invoke(null, null);
                        MCMSettings.DebugLog("Called TextureProviderFactory.RefreshProviderTypes()");
                    }
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TextureProviderFactory.RefreshProviderTypes failed: " + (ex.InnerException?.Message ?? ex.Message));
            }
        }

        /// <summary>
        /// Force-refreshes the banner visual (ImageIdentifierVM) on the current encyclopedia ViewModel.
        public static void ForceRefreshBannerVisual(string pageType, string bannerCode = null)
        {
            try
            {
                var vm = EncyclopediaPageTracker.CurrentViewModel;
                if (vm == null)
                {
                    MCMSettings.DebugLog("ForceRefreshBannerVisual: CurrentViewModel is null");
                    return;
                }

                var flags = System.Reflection.BindingFlags.Instance
                          | System.Reflection.BindingFlags.Public
                          | System.Reflection.BindingFlags.NonPublic;

                // Create a fresh Banner from the stored code. This avoids reading from
                // clan.Banner which the game may revert for NPC clans within milliseconds.
                Banner banner = null;
                if (!string.IsNullOrEmpty(bannerCode))
                {
                    try
                    {
                        banner = new Banner(bannerCode);
                        MCMSettings.DebugLog("ForceRefreshBannerVisual: created fresh Banner from stored code");
                    }
                    catch (Exception ex)
                    {
                        MCMSettings.DebugLog("ForceRefreshBannerVisual: failed to create Banner from stored code: " + ex.ToString());
                    }
                }

                // Fallback: read from clan.Banner
                if (banner == null)
                {
                    if (pageType == "Hero")
                        banner = EncyclopediaPageTracker.CurrentHero?.Clan?.Banner;
                    else if (pageType == "Clan")
                        banner = ((vm as EncyclopediaClanPageVM)?.Obj as Clan)?.Banner;
                    else if (pageType == "Kingdom")
                        banner = ((vm as EncyclopediaFactionPageVM)?.Obj as Kingdom)?.Banner;
                    else if (pageType == "Settlement")
                        banner = ((vm as EncyclopediaSettlementPageVM)?.Obj as Settlement)?.OwnerClan?.Banner;

                    if (banner != null)
                    {
                        string serialized = banner.Serialize() ?? "";
                        MCMSettings.DebugLog("ForceRefreshBannerVisual: using clan.Banner fallback (code="
                            + (serialized.Length > 40 ? serialized.Substring(0, 40) : serialized) + "...)");
                    }
                }

                if (banner == null)
                {
                    MCMSettings.DebugLog("ForceRefreshBannerVisual: banner is null for " + pageType);
                    return;
                }

                // Strategy 1: Directly update banner properties on the Faction sub-VM.
                // Dump EncyclopediaFactionVM properties once so we know all available bindings.
                int updated = 0;
                try
                {
                    var factionProp = vm.GetType().GetProperty("Faction", flags);
                    if (factionProp != null && factionProp.CanRead)
                    {
                        var factionVM = factionProp.GetValue(vm);
                        if (factionVM != null)
                        {
                            // Update ALL ImageIdentifier-like properties on the Faction VM
                            // (not just "ImageIdentifier" — there may be others like "Banner")
                            foreach (var fProp in factionVM.GetType().GetProperties(flags))
                            {
                                if (!fProp.CanWrite || !fProp.CanRead) continue;
                                if (!fProp.PropertyType.Name.Contains("ImageIdentifier")) continue;

                                try
                                {
                                    var imgType = fProp.PropertyType;
                                    var ctor = imgType.GetConstructor(new[] { typeof(Banner) })
                                            ?? imgType.GetConstructor(new[] { typeof(Banner), typeof(bool) });
                                    if (ctor != null)
                                    {
                                        var args = ctor.GetParameters().Length == 1
                                            ? new object[] { banner }
                                            : new object[] { banner, true };
                                        var newImgVM = ctor.Invoke(args);
                                        fProp.SetValue(factionVM, newImgVM);
                                        updated++;
                                        MCMSettings.DebugLog("Updated Faction." + fProp.Name
                                            + " (type=" + imgType.Name + ")");

                                        // Fire property change on Faction VM
                                        try
                                        {
                                            var onPropChanged = factionVM.GetType().GetMethod("OnPropertyChanged",
                                                flags, null, new[] { typeof(string) }, null);
                                            onPropChanged?.Invoke(factionVM, new object[] { fProp.Name });
                                            MCMSettings.DebugLog("Fired OnPropertyChanged('" + fProp.Name
                                                + "') on Faction VM");
                                        }
                                        catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                                    }
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                            }

                            // Fire property change on page VM to rebind entire Faction sub-tree
                            if (updated > 0)
                            {
                                try
                                {
                                    var onPropChanged = vm.GetType().GetMethod("OnPropertyChanged",
                                        flags, null, new[] { typeof(string) }, null);
                                    onPropChanged?.Invoke(vm, new object[] { "Faction" });
                                    MCMSettings.DebugLog("Fired OnPropertyChanged('Faction') on page VM");
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                            }

                            // (ImageIdentifier properties already handled by comprehensive loop above)
                        }
                    }
                }
                catch (Exception ex)
                {
                    MCMSettings.DebugLog("BannerImageIdentifierVM update failed: " + (ex.InnerException?.Message ?? ex.Message));
                }

                // Strategy 2: If direct VM update didn't work, force page re-navigation
                if (updated == 0)
                {
                    MCMSettings.DebugLog("Direct VM update failed, attempting page re-navigation...");
                    try
                    {
                        var campaign = Campaign.Current;
                        if (campaign != null)
                        {
                            var encMgr = campaign.EncyclopediaManager;
                            if (encMgr != null)
                            {
                                var goToLink = encMgr.GetType().GetMethod("GoToLink",
                                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public,
                                    null, new[] { typeof(string) }, null);

                                if (goToLink != null)
                                {
                                    string link = null;
                                    if (pageType == "Hero")
                                        link = "Encyclopedia/Hero/" + EncyclopediaPageTracker.CurrentObjectId;
                                    else if (pageType == "Clan")
                                        link = "Encyclopedia/Clan/" + EncyclopediaPageTracker.CurrentObjectId;
                                    else if (pageType == "Kingdom")
                                        link = "Encyclopedia/Kingdom/" + EncyclopediaPageTracker.CurrentObjectId;
                                    else if (pageType == "Settlement")
                                        link = "Encyclopedia/Settlement/" + EncyclopediaPageTracker.CurrentObjectId;

                                    if (link != null)
                                    {
                                        MCMSettings.DebugLog("Re-navigating to: " + link);
                                        goToLink.Invoke(encMgr, new object[] { link });
                                        MCMSettings.DebugLog("Page re-navigation complete");
                                    }
                                }
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        MCMSettings.DebugLog("Page re-navigation failed: " + (ex.InnerException?.Message ?? ex.Message));
                    }
                }

                MCMSettings.DebugLog("ForceRefreshBannerVisual updated " + updated + " properties");
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("ForceRefreshBannerVisual failed: " + ex.ToString());
            }
        }

        /// <summary>
        /// Forces the campaign map to redraw party/settlement banners after a banner change.
        ///
        /// Strategy (layered, each step adds resilience):
        ///   1. Clear Banner._bannerVisual cache so the next access regenerates the visual.
        ///   2. PartyBase.SetVisualAsDirty() — tells PartyVisualManager.OnTick to rebuild.
        ///   3. Access PartyVisualManager (SandBox.View.Map) via reflection and call
        ///      RemovePartyVisualForParty + AddNewPartyVisualForParty to force full rebuild.
        /// </summary>
        public static void RefreshMapBannerVisuals(string pageType, string objectId, string bannerCode = null)
        {
            try
            {
                Clan targetClan = null;

                if (pageType == "Hero")
                {
                    targetClan = EncyclopediaPageTracker.CurrentHero?.Clan;
                }
                else if (pageType == "Clan")
                {
                    targetClan = Clan.FindFirst(c => c.StringId == objectId);
                }
                else if (pageType == "Kingdom")
                {
                    // Kingdom banner is cosmetic on the encyclopedia; map parties use clan banners
                    return;
                }
                else if (pageType == "Settlement")
                {
                    var settlement = Settlement.Find(objectId);
                    targetClan = settlement?.OwnerClan;
                }

                if (targetClan == null) return;

                var flags = System.Reflection.BindingFlags.Instance
                          | System.Reflection.BindingFlags.Public
                          | System.Reflection.BindingFlags.NonPublic;
                // Step 1: Clear the Banner's internal _bannerVisual cache
                try
                {
                    var bannerVisualField = typeof(Banner).GetField("_bannerVisual", flags);
                    if (bannerVisualField != null)
                    {
                        bannerVisualField.SetValue(targetClan.Banner, null);
                        MCMSettings.DebugLog("Cleared _bannerVisual cache on clan banner");
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }

                // Collect all PartyBase objects belonging to this clan
                var clanParties = new System.Collections.Generic.List<object>();
                foreach (var mobileParty in MobileParty.All)
                {
                    try
                    {
                        bool belongs = false;
                        try { belongs = mobileParty.ActualClan == targetClan; } catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                        if (!belongs)
                        {
                            try { belongs = mobileParty.Party?.Owner?.Clan == targetClan; } catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                        }
                        if (belongs && mobileParty.Party != null)
                            clanParties.Add(mobileParty.Party);
                    }
                    catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                }
                try
                {
                    foreach (var settlement in Settlement.All)
                    {
                        try
                        {
                            if (settlement.OwnerClan == targetClan && settlement.Party != null)
                                clanParties.Add(settlement.Party);
                        }
                        catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }
                    }
                }
                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }

                MCMSettings.DebugLog("Found " + clanParties.Count + " parties for " + targetClan.Name);

                // Step 2: Store parties for DEFERRED visual refresh on encyclopedia close.
                // CRITICAL: Do NOT call SetVisualAsDirty, RefreshPartyIcon, or any visual methods
                // while the encyclopedia is open. The game's tick loop runs during the overlay and
                // will CONSUME the dirty flag (ValidateIsDirty -> RefreshPartyIcon no-op -> OnVisualsUpdated
                // clears the flag) without actually refreshing. The visual must be refreshed AFTER
                // the encyclopedia closes and the map render loop is fully active.
                _pendingVisualRefreshClan = targetClan;
                _pendingVisualRefreshBannerCode = bannerCode;
                _pendingVisualRefreshParties.Clear();
                foreach (var pb in clanParties)
                {
                    _pendingVisualRefreshParties.Add(pb);
                }
                MCMSettings.DebugLog("Queued " + clanParties.Count + " parties for deferred visual refresh on encyclopedia close"
                    + (bannerCode != null ? " (bannerCode stored)" : " (no bannerCode)"));

                MCMSettings.DebugLog("RefreshMapBannerVisuals complete for " + targetClan.Name);
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("RefreshMapBannerVisuals failed: " + ex.ToString());
            }
        }
    }

    // ============================================
    //  Journal Entry Popup (Ctrl+J) — All page types
    // ============================================
    public static class EncyclopediaJournalPopup
    {
        private static volatile bool _popupOpen = false;
        public static bool IsPopupOpen => _popupOpen;

        private static void ReleasePopup()
        {
            _popupOpen = false;
            EncyclopediaInputBlocker.Unblock();
        }

        public static void TryOpen()
        {
            if (_popupOpen) return;
            if (EncyclopediaEditBehavior.Instance == null) return;
            if (string.IsNullOrEmpty(EncyclopediaPageTracker.CurrentObjectId)) return;

            try
            {
                var settings = MCMSettings.Instance;
                if (settings != null && !settings.EnableJournal) return;
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: TryOpen exception: " + ex.ToString()); }

            EncyclopediaInputBlocker.Block();
            _popupOpen = true;

            string objectId = EncyclopediaPageTracker.CurrentObjectId;
            bool hasEntries = EncyclopediaEditBehavior.Instance.HasJournal(objectId);

            if (hasEntries)
                ShowJournalMenu(objectId);
            else
                ShowAddEntry(objectId);
        }

        private static void ShowJournalMenu(string objectId)
        {
            try
            {
                InformationManager.ShowInquiry(
                    new InquiryData(
                        Localization.L("journal_section_header"),
                        Localization.L("journal_add_message", GetDatePreview()),
                        true, true,
                        Localization.L("journal_add_title"),
                        Localization.L("journal_manage_entries"),
                        () =>
                        {
                            ReleasePopup();
                            ShowAddEntry(objectId);
                        },
                        () =>
                        {
                            ReleasePopup();
                            ShowDeleteEntry(objectId);
                        }),
                    true, false);
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Journal menu error: " + ex.ToString());
                ReleasePopup();
            }
        }

        private static void ShowDeleteEntry(string objectId)
        {
            EncyclopediaInputBlocker.Block();
            _popupOpen = true;

            try
            {
                var entries = EncyclopediaEditBehavior.Instance.GetJournalEntries(objectId);
                if (entries.Count == 0)
                {
                    ReleasePopup();
                    return;
                }

                // Build numbered list of entries
                var sb = new System.Text.StringBuilder();
                for (int i = 0; i < entries.Count; i++)
                {
                    sb.Append((i + 1).ToString());
                    sb.Append(". ");
                    string text = entries[i].Text;
                    if (text.Length > 50)
                        text = text.Substring(0, 47) + "...";
                    sb.Append(text);
                    if (!string.IsNullOrEmpty(entries[i].Date))
                    {
                        sb.Append(" (");
                        sb.Append(entries[i].Date);
                        sb.Append(")");
                    }
                    sb.Append("\n");
                }

                EEInquiry.Show(
                    new TextInquiryData(
                        Localization.L("journal_delete_title"),
                        Localization.L("journal_delete_message", sb.ToString()),
                        true, true,
                        Localization.L("journal_clear_confirm"),
                        Localization.L("edit_cancel"),
                        input =>
                        {
                            if (int.TryParse(input?.Trim(), out int num) && num >= 1 && num <= entries.Count)
                            {
                                EncyclopediaEditBehavior.Instance.RemoveJournalEntry(objectId, num - 1);

                                bool showConfirm = true;
                                try
                                {
                                    var s = MCMSettings.Instance;
                                    if (s != null) showConfirm = s.ShowConfirmationMessages;
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: operation exception: " + ex.ToString()); }

                                if (showConfirm)
                                {
                                    InformationManager.DisplayMessage(new InformationMessage(
                                        Localization.L("msg_journal_deleted"),
                                        new Color(0.2f, 0.8f, 0.2f)));
                                }

                                if (PeerRegistry.Has("EE-ChronicleNoters"))
                                    JournalSectionInjector.ScheduleRefresh(objectId);
                            }
                            else if (string.Equals(input?.Trim(), "all", StringComparison.OrdinalIgnoreCase))
                            {
                                ReleasePopup();
                                ShowClearConfirmation(objectId);
                                return;
                            }
                            ReleasePopup();
                        },
                        () => { ReleasePopup(); }),
                    true, false);
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Journal delete entry error: " + ex.ToString());
                ReleasePopup();
            }
        }

        private static void ShowClearConfirmation(string objectId)
        {
            EncyclopediaInputBlocker.Block();
            _popupOpen = true;

            try
            {
                InformationManager.ShowInquiry(
                    new InquiryData(
                        Localization.L("journal_clear_title"),
                        Localization.L("journal_clear_message"),
                        true, true,
                        Localization.L("journal_clear_confirm"),
                        Localization.L("edit_cancel"),
                        () =>
                        {
                            EncyclopediaEditBehavior.Instance.ClearJournal(objectId);
                            InformationManager.DisplayMessage(new InformationMessage(
                                Localization.L("msg_journal_cleared"),
                                new Color(0.2f, 0.8f, 0.2f)));
                            if (PeerRegistry.Has("EE-ChronicleNoters"))
                                JournalSectionInjector.ScheduleRefresh(objectId);
                            ReleasePopup();
                        },
                        () => { ReleasePopup(); }),
                    true, false);
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Journal clear confirm error: " + ex.ToString());
                ReleasePopup();
            }
        }

        private static void ShowAddEntry(string objectId)
        {
            EncyclopediaInputBlocker.Block();
            _popupOpen = true;

            try
            {
                if (!TryShowCategoryPicker(objectId))
                {
                    // Fallback: skip category, go straight to text input
                    MCMSettings.DebugLog("Journal: category picker unavailable, skipping to text input");
                    ReleasePopup();
                    ShowAddEntryText(objectId, "");
                }
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Journal category select error: " + ex.ToString());
                ReleasePopup();
            }
        }

        /// <summary>
        /// Shows a clickable category picker (War, Politics, Family, Other) using
        /// the native ShowMultiSelectionInquiry UI — same approach as the tag picker.
        /// </summary>
        private static bool TryShowCategoryPicker(string objectId)
        {
            try
            {
                // Find InquiryElement and MultiSelectionInquiryData types
                Type inquiryElementType = null;
                Type multiSelDataType = null;

                // Round 4 finding N-C2: cached scan replaces inline assembly walk.
                inquiryElementType = InquiryTypeCache.InquiryElement;
                multiSelDataType = InquiryTypeCache.MultiSelectionInquiryData;

                if (inquiryElementType == null || multiSelDataType == null)
                {
                    MCMSettings.DebugLog("Journal category picker: MultiSelection types not found");
                    return false;
                }

                var showMethod = MultiSelectionMethodCache.Find(multiSelDataType);
                if (showMethod == null)
                {
                    MCMSettings.DebugLog("Journal category picker: ShowMultiSelectionInquiry not found");
                    return false;
                }

                var elementCtor = MultiSelectionMethodCache.FindInquiryElementCtor(inquiryElementType, out bool secondParamIsTextObject);
                if (elementCtor == null)
                    return false;

                var elementCtorParams = elementCtor.GetParameters();
                var listType = typeof(List<>).MakeGenericType(inquiryElementType);
                var elements = (System.Collections.IList)Activator.CreateInstance(listType);

                // Add the four category options
                string[][] categories = new string[][]
                {
                    new[] { "war",      "\u2694 War" },
                    new[] { "politics", "\u265B Politics" },
                    new[] { "family",   "\u2665 Family" },
                    new[] { "other",    "Other" }
                };

                foreach (var cat in categories)
                {
                    elements.Add(MultiSelectionMethodCache.CreateInquiryElement(
                        elementCtor, elementCtorParams, secondParamIsTextObject,
                        cat[0], cat[1]));
                }

                // Build callbacks
                var actionType = typeof(Action<>).MakeGenericType(listType);

                // Affirmative handler — extract selected category and proceed to text input
                var handler = new JournalCategoryHandler(objectId);
                var journalAffMethodInfo = typeof(JournalCategoryHandler).GetMethod("OnCategorySelected");
                if (journalAffMethodInfo == null) return false;
                var affParam = System.Linq.Expressions.Expression.Parameter(listType, "elements");
                var affCall = System.Linq.Expressions.Expression.Call(
                    System.Linq.Expressions.Expression.Constant(handler),
                    journalAffMethodInfo,
                    System.Linq.Expressions.Expression.Convert(affParam, typeof(object)));
                var affirmativeDelegate = System.Linq.Expressions.Expression.Lambda(actionType, affCall, affParam).Compile();

                // Negative handler — cancel
                var journalNegMethodInfo = typeof(EncyclopediaJournalPopup).GetMethod("OnCategoryPickerCancelled",
                        System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic);
                if (journalNegMethodInfo == null) return false;
                var negParam = System.Linq.Expressions.Expression.Parameter(listType, "elements");
                var negBody = System.Linq.Expressions.Expression.Call(journalNegMethodInfo);
                var negativeDelegate = System.Linq.Expressions.Expression.Lambda(actionType, negBody, negParam).Compile();

                // Find MultiSelectionInquiryData constructor
                System.Reflection.ConstructorInfo dataCtor = null;
                foreach (var ctor in multiSelDataType.GetConstructors())
                {
                    var pars = ctor.GetParameters();
                    if (pars.Length >= 8 && (dataCtor == null || pars.Length > dataCtor.GetParameters().Length))
                        dataCtor = ctor;
                }

                if (dataCtor == null)
                {
                    MCMSettings.DebugLog("Journal category picker: MultiSelectionInquiryData ctor not found");
                    return false;
                }

                object dataObj = MultiSelectionMethodCache.BuildMultiSelectionInquiryData(
                    dataCtor,
                    Localization.L("journal_category_title"),
                    Localization.L("journal_category_message"),
                    Localization.L("edit_done"), Localization.L("edit_cancel"),
                    elements, listType, affirmativeDelegate, negativeDelegate);

                var showParams = showMethod.GetParameters();
                if (showParams.Length == 1)
                    showMethod.Invoke(null, new object[] { dataObj });
                else if (showParams.Length == 2)
                    showMethod.Invoke(null, new object[] { dataObj, false });
                else
                    showMethod.Invoke(null, new object[] { dataObj, false, false });

                EncyclopediaNavigationGuard.ScheduleNavigateBack();

                MCMSettings.DebugLog("Showed journal category picker for " + objectId);
                return true;
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("TryShowCategoryPicker failed: " + ex.ToString());
                return false;
            }
        }

        private static void OnCategoryPickerCancelled()
        {
            ReleasePopup();
        }

        /// <summary>
        /// Handles the selected category from the journal category picker.
        /// </summary>
        private class JournalCategoryHandler
        {
            private readonly string _objectId;

            public JournalCategoryHandler(string objectId) { _objectId = objectId; }

            public void OnCategorySelected(object selectedElements)
            {
                try
                {
                    ReleasePopup();

                    var list = selectedElements as System.Collections.IList;
                    if (list == null || list.Count == 0)
                    {
                        // No selection — go to text input with no category
                        ShowAddEntryText(_objectId, "");
                        return;
                    }

                    string selectedId = MultiSelectionMethodCache.GetInquiryElementId(list[0]);
                    string categoryTag = "";
                    switch (selectedId)
                    {
                        case "war":      categoryTag = "[War] "; break;
                        case "politics": categoryTag = "[Politics] "; break;
                        case "family":   categoryTag = "[Family] "; break;
                        case "other":    categoryTag = ""; break;
                    }

                    MCMSettings.DebugLog("Journal category selected: " + (selectedId ?? "null") + " -> tag: '" + categoryTag + "'");
                    ShowAddEntryText(_objectId, categoryTag);
                }
                catch (Exception ex)
                {
                    MCMSettings.DebugLog("OnCategorySelected error: " + ex.ToString());
                    ReleasePopup();
                }
            }
        }

        private static void ShowAddEntryText(string objectId, string categoryTag)
        {
            EncyclopediaInputBlocker.Block();
            _popupOpen = true;

            string datePreview = GetDatePreview();

            try
            {
                EEInquiry.Show(
                    new TextInquiryData(
                        Localization.L("journal_add_title"),
                        Localization.L("journal_add_message", datePreview),
                        true, true,
                        Localization.L("edit_save"),
                        Localization.L("edit_cancel"),
                        text =>
                        {
                            if (!string.IsNullOrWhiteSpace(text))
                            {
                                string fullText = categoryTag + text;
                                EncyclopediaEditBehavior.Instance.AddJournalEntry(objectId, fullText);

                                bool showConfirm = true;
                                try
                                {
                                    var s = MCMSettings.Instance;
                                    if (s != null) showConfirm = s.ShowConfirmationMessages;
                                }
                                catch (Exception ex) { MCMSettings.DebugLog("Patches: ShowAddEntryText exception: " + ex.ToString()); }

                                if (showConfirm)
                                {
                                    InformationManager.DisplayMessage(new InformationMessage(
                                        Localization.L("msg_journal_added"),
                                        new Color(0.2f, 0.8f, 0.2f)));
                                }

                                if (PeerRegistry.Has("EE-ChronicleNoters"))
                                    JournalSectionInjector.ScheduleRefresh(objectId);
                            }
                            ReleasePopup();
                        },
                        () => { ReleasePopup(); }),
                    true, false);
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("Journal add entry error: " + ex.ToString());
                ReleasePopup();
            }
        }

        private static string GetDatePreview()
        {
            try { return EncyclopediaEditBehavior.GetCurrentGameDateString(); }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: GetDatePreview exception: " + ex.ToString()); return "Unknown Date"; }
        }
    }

    /// <summary>
    /// Runtime Harmony patch on GauntletMapEncyclopediaView to capture the GauntletLayer
    /// when the encyclopedia opens. This replaces fragile text-matching ("Friends"/"Enemies"/"Info")
    /// and eliminates retry loops in LoreSection/TagWidget/TimestampOverlay.
    /// </summary>
    public static class EncyclopediaLayerCapturePatch
    {
        private static bool _patched;
        private static System.Reflection.FieldInfo _layerField;
        private static Type _encManagerType;

        public static void TryPatch(object encManager)
        {
            if (_patched) return;
            try
            {
                var encType = encManager.GetType();
                _encManagerType = encType;
                var flags = System.Reflection.BindingFlags.Instance
                          | System.Reflection.BindingFlags.Public
                          | System.Reflection.BindingFlags.NonPublic;
                var declaredFlags = flags | System.Reflection.BindingFlags.DeclaredOnly;

                // Cache the layer field for use in the postfix.
                // Search by known names first, then scan for ANY GauntletLayer field.
                var searchType = encType;
                while (searchType != null && searchType != typeof(object))
                {
                    _layerField = searchType.GetField("<Layer>k__BackingField", flags);
                    if (_layerField == null)
                        _layerField = searchType.GetField("_layer", flags);
                    if (_layerField == null)
                        _layerField = searchType.GetField("_gauntletLayer", flags);
                    if (_layerField == null)
                        _layerField = searchType.GetField("_encyclopediaLayer", flags);
                    if (_layerField != null) break;
                    searchType = searchType.BaseType;
                }

                // If no named field found, scan all fields for one of type GauntletLayer
                if (_layerField == null)
                {
                    searchType = encType;
                    while (searchType != null && searchType != typeof(object))
                    {
                        foreach (var f in searchType.GetFields(declaredFlags))
                        {
                            if (typeof(GauntletLayer).IsAssignableFrom(f.FieldType))
                            {
                                _layerField = f;
                                break;
                            }
                        }
                        if (_layerField != null) break;
                        searchType = searchType.BaseType;
                    }
                }

                // Log what we found (or didn't) — don't return early, the Harmony patches
                // on CreateLayout/OnTick are still useful even without a layer field because
                // the injectors now cache EncyclopediaLayerRef when they find the layer
                // via content matching.
                if (_layerField != null)
                {
                    MCMSettings.DebugLog("EncyclopediaLayerCapture: found layer field '"
                        + _layerField.Name + "' on " + _layerField.DeclaringType.Name
                        + ", manager type=" + encType.FullName);
                }
                else
                {
                    MCMSettings.DebugLog("EncyclopediaLayerCapture: no layer field found on "
                        + encType.Name + " — relying on content-match caching");
                }

                var harmony = new HarmonyLib.Harmony("com.editableencyclopedia.patch");
                var postfix = typeof(EncyclopediaLayerCapturePatch).GetMethod("CaptureLayerPostfix",
                    System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public);
                if (postfix == null)
                {
                    MCMSettings.DebugLog("EncyclopediaLayerCapture: CaptureLayerPostfix method not found via reflection");
                    return;
                }

                int patched = 0;

                // Log all declared methods on the exact encyclopedia type for diagnostics
                var allDeclared = encType.GetMethods(declaredFlags);
                MCMSettings.DebugLog("EncyclopediaLayerCapture: " + encType.Name + " declares "
                    + allDeclared.Length + " methods: "
                    + string.Join(", ", Array.ConvertAll(allDeclared, m => m.Name)));

                // Strategy: patch methods DECLARED on the encyclopedia type that run
                // when the encyclopedia opens or every frame.
                // Known declared methods: CreateLayout, OnTick, ExecuteLink, OnFinalize,
                //                         CloseEncyclopedia, GetTutorialContext
                //
                // CreateLayout: creates the GauntletLayer — postfix captures it immediately.
                // OnTick: runs every frame — captures the layer on the first tick where
                //         it's non-null (handles the case where we patched after CreateLayout
                //         already ran for the current session).
                string[] candidateNames = {
                    "CreateLayout",
                    "OpenEncyclopedia", "ShowEncyclopediaPanel",
                    "OpenEncyclopediaPage", "ActivateEncyclopedia",
                    "OnActivate", "Initialize", "OnInitialize",
                };

                foreach (string name in candidateNames)
                {
                    var method = encType.GetMethod(name, declaredFlags);
                    if (method != null)
                    {
                        try
                        {
                            harmony.Patch(method, postfix: new HarmonyLib.HarmonyMethod(postfix));
                            MCMSettings.DebugLog("EncyclopediaLayerCapture: patched "
                                + encType.Name + "." + name + "()");
                            patched++;
                        }
                        catch (Exception ex)
                        {
                            MCMSettings.DebugLog("EncyclopediaLayerCapture: failed to patch "
                                + name + ": " + ex.ToString());
                        }
                    }
                }

                // Also patch OnTick — it runs every frame and will capture the layer
                // on the first frame where it's non-null. This is critical for the
                // first encyclopedia open (CreateLayout already ran before we patched).
                var onTickPostfix = typeof(EncyclopediaLayerCapturePatch).GetMethod("OnTickCapturePostfix",
                    System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public);
                var onTick = encType.GetMethod("OnTick", declaredFlags);
                if (onTick != null && onTickPostfix != null)
                {
                    try
                    {
                        harmony.Patch(onTick, postfix: new HarmonyLib.HarmonyMethod(onTickPostfix));
                        MCMSettings.DebugLog("EncyclopediaLayerCapture: patched "
                            + encType.Name + ".OnTick() for per-frame capture");
                        patched++;
                    }
                    catch (Exception ex)
                    {
                        MCMSettings.DebugLog("EncyclopediaLayerCapture: failed to patch OnTick: " + ex.ToString());
                    }
                }

                // Patch ExecuteLink with prefix+postfix to bracket page transitions.
                // The prefix sets a "in page transition" flag that suppresses false close detection,
                // and the postfix clears it. This prevents the IsEncyclopediaOpen field's brief
                // false toggle during page navigation from triggering the close debounce.
                var executeLinkMethod = encType.GetMethod("ExecuteLink", declaredFlags);
                if (executeLinkMethod != null)
                {
                    try
                    {
                        var elPrefix = typeof(EncyclopediaLayerCapturePatch).GetMethod("ExecuteLinkPrefix",
                            System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public);
                        var elPostfix = typeof(EncyclopediaLayerCapturePatch).GetMethod("ExecuteLinkPostfix",
                            System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public);
                        var elFinalizer = typeof(EncyclopediaLayerCapturePatch).GetMethod("ExecuteLinkFinalizer",
                            System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public);
                        if (elPrefix == null || elPostfix == null || elFinalizer == null)
                        {
                            MCMSettings.DebugLog("EncyclopediaLayerCapture: ExecuteLink patch methods not found via reflection");
                        }
                        else
                        {
                            harmony.Patch(executeLinkMethod,
                                prefix: new HarmonyLib.HarmonyMethod(elPrefix),
                                postfix: new HarmonyLib.HarmonyMethod(elPostfix),
                                finalizer: new HarmonyLib.HarmonyMethod(elFinalizer));
                            MCMSettings.DebugLog("EncyclopediaLayerCapture: patched "
                                + encType.Name + ".ExecuteLink() for transition tracking");
                            patched++;
                        }
                    }
                    catch (Exception ex)
                    {
                        MCMSettings.DebugLog("EncyclopediaLayerCapture: failed to patch ExecuteLink: " + ex.ToString());
                    }
                }

                if (patched == 0)
                    MCMSettings.DebugLog("EncyclopediaLayerCapture: WARNING — no methods found to patch on " + encType.Name);
                else
                    MCMSettings.DebugLog("EncyclopediaLayerCapture: patched " + patched + " method(s)");

                _patched = true;
            }
            catch (Exception ex)
            {
                MCMSettings.DebugLog("EncyclopediaLayerCapture: error: " + ex.ToString());
            }
        }

        /// <summary>
        /// Harmony prefix on ExecuteLink — sets the page transition flag to suppress
        /// false close detection during the brief IsEncyclopediaOpen toggle.
        /// </summary>
        public static void ExecuteLinkPrefix(object __instance)
        {
            if (_encManagerType == null) return;
            if (!_encManagerType.IsAssignableFrom(__instance.GetType())) return;
            var cachedManager = EncyclopediaPageTracker.EncyclopediaManagerRef;
            if (cachedManager != null && !object.ReferenceEquals(__instance, cachedManager)) return;
            EncyclopediaPageTracker.BeginPageTransition();
        }

        /// <summary>
        /// Harmony postfix on ExecuteLink — clears the page transition flag.
        /// Note: Harmony postfixes may not run if the method throws. The 3-second
        /// auto-expiry in IsInPageTransition handles that case as a safety net.
        /// </summary>
        public static void ExecuteLinkPostfix(object __instance)
        {
            if (_encManagerType == null) return;
            if (!_encManagerType.IsAssignableFrom(__instance.GetType())) return;
            var cachedManager = EncyclopediaPageTracker.EncyclopediaManagerRef;
            if (cachedManager != null && !object.ReferenceEquals(__instance, cachedManager)) return;
            EncyclopediaPageTracker.EndPageTransition();
        }

        /// <summary>
        /// Harmony finalizer on ExecuteLink — ensures the transition flag is cleared
        /// even when the method throws an exception (postfixes may be skipped on throw).
        /// </summary>
        public static Exception ExecuteLinkFinalizer(Exception __exception, object __instance)
        {
            if (__exception != null)
            {
                // Clear transition flag on exception
                EncyclopediaPageTracker.EndPageTransition();
            }
            return __exception; // re-throw the original exception
        }

        /// <summary>
        /// Harmony postfix that runs after CreateLayout or similar methods.
        /// Captures the GauntletLayer reference from the manager instance.
        /// Only captures when __instance is the actual encyclopedia manager.
        /// </summary>
        public static void CaptureLayerPostfix(object __instance)
        {
            TryCaptureLayer(__instance, "CaptureLayerPostfix");
        }

        /// <summary>
        /// Harmony postfix on OnTick — captures the layer on the first frame where
        /// it's non-null. Only logs once to avoid per-frame log spam.
        /// </summary>
        public static void OnTickCapturePostfix(object __instance)
        {
            // Skip if we already have a layer reference (avoid per-frame work)
            if (EncyclopediaPageTracker.EncyclopediaLayerRef != null) return;
            TryCaptureLayer(__instance, "OnTick");
        }

        private static void TryCaptureLayer(object instance, string source)
        {
            try
            {
                if (_layerField == null || _encManagerType == null) return;

                // Identity check: only capture from the actual encyclopedia manager instance.
                if (!_encManagerType.IsAssignableFrom(instance.GetType())) return;

                // Also verify this is THE cached encyclopedia manager
                var cachedManager = EncyclopediaPageTracker.EncyclopediaManagerRef;
                if (cachedManager != null && !object.ReferenceEquals(instance, cachedManager)) return;

                var layer = _layerField.GetValue(instance);
                if (layer is GauntletLayer gl)
                {
                    int desc = LoreSectionInjector.CountDescendants(
                        LoreSectionInjector.GetLayerRootWidget(gl));
                    EncyclopediaPageTracker.EncyclopediaLayerRef = gl;
                    MCMSettings.DebugLog("EncyclopediaLayerCapture: captured layer via " + source
                        + " (descendants=" + desc + ")");
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog("Patches: TryCaptureLayer exception: " + ex.ToString()); }
        }
    }

    /// <summary>
    /// Harmony postfix patch on SettlementNameplateVM.RefreshValues().
    /// After the game sets the nameplate Name from Settlement.Name, override it
    /// with the custom name if one exists. This fires during nameplate construction,
    /// camera movement, and any UI refresh — guaranteeing the custom name is always shown.
    /// </summary>
    [HarmonyPatch(typeof(SandBox.ViewModelCollection.Nameplate.SettlementNameplateVM), "RefreshValues")]
    public static class SettlementNameplateRefreshPatch
    {
        [ThreadStatic] private static bool _logged;

        /// <summary>
        /// Prefix: set Settlement.Name TextObject in-place BEFORE RefreshValues reads it.
        /// This way when RefreshValues does Name = Settlement.Name.ToString(), it gets our custom name.
        /// </summary>
        public static void Prefix(SandBox.ViewModelCollection.Nameplate.SettlementNameplateVM __instance)
        {
            try
            {
                var behavior = EncyclopediaEditBehavior.Instance;
                if (behavior == null) return;

                var settlementProp = __instance.GetType().GetProperty("Settlement",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic);
                if (settlementProp == null) return;

                var settlement = settlementProp.GetValue(__instance) as TaleWorlds.CampaignSystem.Settlements.Settlement;
                if (settlement == null) return;

                string customName = behavior.GetCustomName(settlement.StringId);
                if (string.IsNullOrEmpty(customName)) return;

                string oldName = __instance.Name;
                __instance.Name = customName;
                if (!_logged)
                {
                    _logged = true;
                    MCMSettings.DebugLog("NameplatePatch: RefreshValues postfix fired, \"" + oldName + "\" -> \"" + customName + "\" for " + settlement.StringId);
                }
            }
            catch (Exception ex) { MCMSettings.DebugLog("NameplatePatch error: " + ex.ToString()); }
        }
    }

    // RefreshDynamicProperties patch removed — per-frame TextObject modification
    // caused instability. Settlement nameplate names update on save+reload only.
    // Mid-game rename shows info message directing player to save+reload or open Options.
}
